INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('1', '这个标志是何含义？', '4', '小型车车道', '小型车专用车道', '多乘员车辆专用车道', '机动车车道', '此为机动车车道，比多乘员车辆专用车道少俩人。', 'https://images.juheapi.com/jztk/c1c2subject1/1.jpg'),
('2', '这个标志是何含义？', '1', '线形诱导标志', '合流诱导标志', '分流诱导标志', '转弯诱导标志', '线型诱导标线型诱导标志，用于引导车辆驾驶人改变行驶方向，促使安全运行。视需要设于易肇事之弯道路段，小半径匝道曲线或中央隔离设施及渠化设施的端部。线形诱导标的颜色规定为：指示性线形诱导标一般道路为蓝底白图案,高速公路为绿底白图案，用以提供一般性行驶指示;警告性线形诱导标为红底白图案，可使车辆驾驶人提高警觉，并准备防范应变之措施。', 'https://images.juheapi.com/jztk/c1c2subject1/2.jpg'),
('3', '这个标志是何含义？', '1', '车道数变少', '合流处', '应急车道', '向左变道', '三车道变成二车道故车道数变少，选A。', 'https://images.juheapi.com/jztk/c1c2subject1/3.jpg'),
('4', '这个标志是何含义？', '2', '禁止自行车通行车道', '非机动车车道', '自行车专用车道', '停放自行车路段', '此图为非机动车车道，别误以为自行车专用车道，没有自行车专用车道这一说。', 'https://images.juheapi.com/jztk/c1c2subject1/4.jpg'),
('5', '这个标志是何含义？', '3', '停车让行', '单行路', '会车先行', '对向先行', '表示会车先行，此标志设在车道以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/5.jpg'),
('6', '这个标志是何含义？', '4', '右转车道', '掉头车道', '左转车道', '直行车道', '表示只准一切车辆直行。此标志设在直行的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/6.jpg'),
('7', '这个标志是何含义？', '2', '减速慢行', '注意危险', '拥堵路段', '事故多发路段', '注意危险：用以促使车辆驾驶员谨慎慢行。', 'https://images.juheapi.com/jztk/c1c2subject1/7.jpg'),
('8', '这个标志是何含义？', '2', '车道方向预告', '交叉路口预告', '分道信息预告', '分岔处预告', '此为交叉路口预告，记住吧。', 'https://images.juheapi.com/jztk/c1c2subject1/8.jpg'),
('9', '这个标志是何含义？', '2', '距有人看守铁路道口50米', '距无人看守铁路道口100米', '距有人看守铁路道口100米', '距无人看守铁路道口50米', '一道红线是50米，二道100米。', 'https://images.juheapi.com/jztk/c1c2subject1/9.jpg'),
('10', '这个标志是何含义？', '2', '分向行驶车道', '掉头和左转合用车道', '禁止左转和掉头车道', '直行和左转合用车道', '左转和掉头合并在一个标志里，你应该能看到的。', 'https://images.juheapi.com/jztk/c1c2subject1/10.jpg'),
('11', '这个标志是何含义？', '3', '省道编号', '国道编号', '县道编号', '乡道编号', '乡道是白底Y字开头的，县道是白底X开头的，省道是黄底的，国道是红底的。', 'https://images.juheapi.com/jztk/c1c2subject1/11.jpg'),
('12', '这个标志是何含义？', '4', '前方40米减速', '最低时速40公里', '限制40吨轴重', '限制最高时速40公里', '限制最高时速40公里：表示该标志至前方限制速度标志的路段内，机动车行驶速度不得超过标志所示数值。此标志设在需要限制车辆速度的路段的起点。以图为例：限制行驶时速不得超过40公里。', 'https://images.juheapi.com/jztk/c1c2subject1/12.jpg'),
('13', '这个标志是何含义？', '4', '十字交叉路口预告', '互通立体交叉预告', 'Y型交叉路口预告', '环行交叉路口预告', '环形交叉口是在几条相交道路的平面交叉口中央设置一个半径较大的中心岛，使所有经过交叉口的直行和左转车辆都绕着中心岛作逆时针方向行驶，在其行驶过程中将车流的冲突点变  为交织点，从而保证交叉口的行车安全，提高交叉口的通行能力。', 'https://images.juheapi.com/jztk/c1c2subject1/13.jpg'),
('14', '这个标志是何含义？', '3', '专用停车场', '露天停车场', '室内停车场', '内部停车场', '你看那个P字上边还有个遮挡，说明是室内的，如果没有上边那个遮挡就是露天停车场。', 'https://images.juheapi.com/jztk/c1c2subject1/14.jpg'),
('15', '这个标志是何含义？', '4', '道路流量监测', '减速拍照区', '全路段抓拍', '交通监控设备', '交通监控设备标志属于指路标志，蓝底、白图形、白边框、蓝色衬边。用于告知机动车驾驶人该区域设置有固定式交通监控设备。', 'https://images.juheapi.com/jztk/c1c2subject1/15.jpg'),
('16', '这个标志是何含义？', '4', '靠道路左侧停车', '左侧是下坡路段', '只准向左转弯', '靠左侧道路行驶', '靠左侧道路行驶：表示只准一切车辆靠左侧道路行驶。此标志设在车辆必须靠左侧行驶的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/16.jpg'),
('17', '这个标志是何含义？', '2', '大型客车专用车道', '公交线路专用车道', '快速公交系统专用车道', '多乘员车辆专用车道', '此为公交线路专用车道，与快速公交系统专用车道的区别是少了“快速公交”四个字。', 'https://images.juheapi.com/jztk/c1c2subject1/17.jpg'),
('18', '这个标志是何含义？', '4', '小型汽车专用车道', '机动车专用车道', '出租汽车专用车道', '多乘员车辆专用车道', '此标志为多乘员车辆专用车道，比机动车专用车道标志上的小车多了2个小人，所以它是多乘员车辆专用车道。', 'https://images.juheapi.com/jztk/c1c2subject1/18.jpg'),
('19', '这个标志是何含义？', '1', '休息区', '服务区', '停车场', '观景台', '这个是休息区，服务区是有加油，通车，吃饭的组合标志，停车场就是一个P，图中没有加油站和吃饭的，所以它只是一个休息区。', 'https://images.juheapi.com/jztk/c1c2subject1/19.jpg'),
('20', '这个标志是何含义？', '2', '直行和掉头合用车道', '直行和左转合用车道', '直行和右转车道', '分向行驶车道', '表示只准一切车辆直行和向左转弯。此标志设在车辆必须直行和向左转弯的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/20.jpg'),
('21', '这个标志是何含义？', '4', '平面交叉路口', '环行平面交叉', '注意交互式道路', '注意分离式道路', '注意分离式道路：用以警告车辆驾驶人注意前方平面交叉的被交道路是分离式道路。', 'https://images.juheapi.com/jztk/c1c2subject1/21.jpg'),
('22', '这个标志是何含义？', '1', '丁字交叉路口预告', '道路分叉处预告', 'Y型交叉路口预告', '十字交叉路口预告', '你看它长的多像丁字。', 'https://images.juheapi.com/jztk/c1c2subject1/22.jpg'),
('23', '这个标志是何含义？', '1', '地点距离', '行驶路线', '终点地名', '行驶方向', '你看那个地点名和KM公里多明显，所以本题的答案是地点距离。如果有箭头的一半是行驶方向。', 'https://images.juheapi.com/jztk/c1c2subject1/23.jpg'),
('24', '指示标志的作用是什么？', '4', '告知方向信息', '警告前方危险', '限制车辆、行人通行', '指示车辆、行人行进', '指示标志是交通标志中主要标志的一种，用以指示车辆和行人按规定方向、地点行驶。 指示标志的颜色为蓝底、白色图案；形状分为圆形、长方形和正方形。', NULL),
('25', '这个标志是何含义？', '2', '塌方路段', '施工路段', '前方工厂', '道路堵塞', '施工路段：用以告示前方道路施工，车辆应减速慢行或绕道行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/25.jpg'),
('26', '这个标志是何含义？', '3', '注意危险', '右侧绕行', '左侧绕行', '单向通行', '左侧绕行：用以告示前方道路有障碍物，车辆应按标志指示减速慢行，左侧绕行通过。', 'https://images.juheapi.com/jztk/c1c2subject1/26.jpg'),
('27', '这个标志是何含义？', '3', '直行和左转车道', '直行和辅路出口车道', '直行和右转合用车道', '分向行驶车道', '表示只准一切车辆直行和向右转弯。此标志设在车辆必须直行和向右转弯）的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/27.jpg'),
('28', '这个标志是何含义？', '4', '限制宽度为3.5米', '解除3.5米限高', '限制车距为3.5米', '限制高度为3.5米', '限制高度为3.5米：表示禁止装载高度超过标志所示数值的车辆通行。此标志设在最大允许高度受限制的地方。 以图为例：装载高度不得超过3.5米。', 'https://images.juheapi.com/jztk/c1c2subject1/28.jpg'),
('29', '这个标志是何含义？', '1', '禁止通行', '减速行驶', '限时进入', '禁止驶入', '禁止通行：表示禁止一切车辆和行人通行。此标志设在禁止通行的道路入口处。', 'https://images.juheapi.com/jztk/c1c2subject1/29.jpg'),
('30', '这个标志是何含义？', '2', '十字交叉路口预告', '互通式立体交叉预告', 'Y型交叉路口预告', '环行交叉路口预告', '互通式立体交叉：路线交叉中的一种重要类型。交叉道路之间立体交叉并以匝道相互连通以实现交通转换的交叉。', 'https://images.juheapi.com/jztk/c1c2subject1/30.jpg'),
('31', '这个标志是何含义？', '2', '右侧是下坡路段', '靠右侧道路行驶', '靠道路右侧停车', '只准向右转弯', '靠右侧道路行驶：表示只准一切车辆靠右侧道路行驶。此标志设在车辆必须靠右侧行驶的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/31.jpg'),
('32', '这个标志是何含义？', '4', '禁止变道', '禁止左转', '禁止直行', '禁止掉头', '禁止掉头：表示前方路口禁止一切车辆掉头。此标志设在禁止掉头的路口前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/32.jpg'),
('33', '这个标志是何含义？', '3', '注意双向行驶', '靠两侧行驶', '注意潮汐车道', '可变车道', '“潮汐车道”是指根据早晚交通流量不同情况，对有条件的道路，试点开辟潮汐车道，通过车道灯的指示方向变化，控制主干道车道行驶方向，来调整车道数。', 'https://images.juheapi.com/jztk/c1c2subject1/33.jpg'),
('34', '这个标志是何含义？', '2', '直行和向左转弯', '直行和向右转弯', '禁止直行和向右转弯', '只准向左和向右转弯', '直行和向右转弯：表示只准一切车辆直行和向右转弯。此标志设在车辆必须直行和向右转弯）的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/34.jpg'),
('35', '这个标志是何含义？', '2', '禁止直行和向左变道', '禁止直行和向左转弯', '允许直行和向左变道', '禁止直行和向右转弯', '禁止直行和向左转弯：表示前方路口禁止一切车辆直行和向左转弯。此标志设在禁止直行和向左转弯的路口前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/35.jpg'),
('36', '这个标志是何含义？', '1', '观景台', '停车场', '休息区', '停车位', '观景台那三个字多明显，你再不选它，叫它情何以堪。', 'https://images.juheapi.com/jztk/c1c2subject1/36.jpg'),
('37', '这属于哪一类标志？', '1', '指路标志', '指示标志', '禁令标志', '警告标志', '他是指方向的故为指路标志。', 'https://images.juheapi.com/jztk/c1c2subject1/37.jpg'),
('38', '这个标志是何含义？', '4', '乡道编号', '县道编号', '省道编号', '国道编号', '乡道是白底Y字开头的，县道是白底X开头的，省道是黄底的，国道是红底的。', 'https://images.juheapi.com/jztk/c1c2subject1/38.jpg'),
('39', '这个标志是何含义？', '1', '距无人看守铁路道口150米', '距无人看守铁路道口100米', '距有人看守铁路道口100米', '距有人看守铁路道口150米', '一道红线是50米，三道150米。', 'https://images.juheapi.com/jztk/c1c2subject1/39.jpg'),
('40', '这个标志是何含义？', '2', '两侧街道', '干路先行', '停车让行', '单行路', '表示干路先行，此标志设在车道以前适当位置。答题技巧：记住哥一句话，谁粗谁先行。', 'https://images.juheapi.com/jztk/c1c2subject1/40.jpg'),
('41', '这个标志是何含义？', '1', '向右转弯', '单行路', '只准直行', '直行车道', '向右转弯：表示只准一切车辆向右转弯。此标志设在车辆必须向右转弯的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/41.jpg'),
('42', '这个标志是何含义？', '4', '允许临时停车', '允许长时停车', '禁止长时停车', '禁止停放车辆', '禁止停放车辆：表示在限定的范围内，禁止一切车辆临时或长时停放。此标志设在禁止车辆停放的地方。禁止车辆停放的时间、车种和范围可用辅助标志说明。', 'https://images.juheapi.com/jztk/c1c2subject1/42.jpg'),
('43', '这个标志是何含义？', '4', '左转行驶车道', '直线行驶车道', '右转行驶车道', '分向行驶车道', '同向多车道的公路一般都设计了分向行驶车道，正常行驶过程中可以变更车道，当你行驶至路口时要变换到你要行驶的车道。例如要左转弯时要提前变更车道至左转弯车道；要右转弯时要提前变更车道至右转弯车道，不能占用他人行车道，以最大限度的保障通行。', 'https://images.juheapi.com/jztk/c1c2subject1/43.jpg'),
('44', '这个标志是何含义？', '3', '有人看守铁路道口', '无人看守铁路道口', '多股铁路与道路相交', '注意避让火车', '多股铁路与道路相交，则应在铁路道口标志上方设置叉形符号。叉形符号交叉点到警告标志三角形顶点的距离为40cm。', 'https://images.juheapi.com/jztk/c1c2subject1/44.jpg'),
('45', '这个标志是何含义？', '3', '禁止向右转弯', '禁止掉头', '禁止直行', '禁止向左转弯', '禁止直行：表示前方路口禁止一切车辆直行。此标志设在禁止直行的路口前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/45.jpg'),
('46', '这个标志是何含义？', '2', '禁止临时停车', '禁止长时停车', '禁止停放车辆', '允许长时停车', '禁止长时停车：禁止车辆长时停放，临时停放不受限制。禁止车辆停放的时间、车种和范围可用辅助标志说明。', 'https://images.juheapi.com/jztk/c1c2subject1/46.jpg'),
('47', '这个标志是何含义？', '3', '隧道减速', '隧道开远光灯', '隧道开灯', '隧道开示宽灯', '这个应该能看懂吧？很明显那个小车开灯的效果。', 'https://images.juheapi.com/jztk/c1c2subject1/47.jpg'),
('48', '驾驶机动车在前方路口不能右转弯。', '2', '正确', '错误', '', '', '如果路口只有圆形的红黄绿灯，那么不管是红灯亮还是绿灯亮都可以右转弯，如果路口是箭头形状，那么向右转的箭头没亮绿灯就不能走了，黄灯也不能走。所以，这题注意看灯的形状。', 'https://images.juheapi.com/jztk/c1c2subject1/48.jpg'),
('49', '这个标志是何含义？', '4', 'Y型交叉口', '主路让行', '注意分流', '注意合流', '黄底为警告标志，所以排除A和B，图很明显的为合流标志，所以选D', 'https://images.juheapi.com/jztk/c1c2subject1/49.jpg'),
('50', '这个标志是何含义？', '1', '事故易发路段', '施工路段', '减速慢行路段', '拥堵路段', '事故易发路段：此标志设在交通事故易发路段以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/50.jpg'),
('51', '这个标志是何含义？', '2', '两侧通行', '右侧通行', '左侧通行', '不准通行', '用于引导行车方向，提示道路使用者前方线形变化，注意谨慎驾驶。设于中央隔离设施端部、渠化设施的端部、桥头等。答题技巧：∧表示俩侧通行，/这个方向的表示左侧通行，这个方向表示右侧通行。交通指路标志大全：http://www.jszks.com/onepage/16752.html', 'https://images.juheapi.com/jztk/c1c2subject1/51.jpg'),
('52', '这个标志是何含义？', '1', '掉头', '倒车', '左转', '绕行', '允许掉头标志', 'https://images.juheapi.com/jztk/c1c2subject1/52.jpg'),
('53', '禁令标志的作用是什么？', '3', '指示车辆行进', '警告前方危险', '禁止或限制行为', '告知方向信息', '禁令标志是交通标志中主要标志的一种，对车辆加以禁止或限制的标志，如禁止通行、禁止停车、禁止左转弯、禁止鸣喇叭、限制速度、限制重量等。', NULL),
('54', '驾驶机动车在这种情况下可以右转弯。', '2', '正确', '错误', '', '', '根据《中华人民共和国道路交通安全法》的相关规定；红灯亮时（满屏灯）右转弯车辆在不影响其他车辆、行人的通行条件下第一台车可以通行，第一台车如等候信号停止时第二台车不可以从前车的左或右侧绕行，<b>但是箭头灯红灯亮时右转弯车辆是绝对不可以通行的，必须要等绿红亮时通行。</b> 
<br/>图片中显示的是箭头灯，并且右转箭头灯是红灯，根据规定，机动车在图中这种情况下是不能右转弯的。题目描述有误，因此本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/54.jpg'),
('55', '这个标志是何含义？', '1', '停车让行', '不准临时停车', '不准车辆驶入', '不准长时间停车', '停车让行：表示车辆必须在停止线以外停车了望，确认安全后，才准许通行。停车让行标志在下列情况下设置：(1)与交通流量较大的干路平交的支路路口；(2)无人看守的铁路道口；(3)其他需要设置的地方。', 'https://images.juheapi.com/jztk/c1c2subject1/55.jpg'),
('56', '这个标志是何含义？', '2', '直行和向右转弯', '直行和向左转弯', '禁止直行和向左转弯', '只准向右和向左转弯', '直行和向左转弯：表示只准一切车辆直行和向左转弯。此标志设在车辆必须直行和向左转弯的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/56.jpg'),
('57', '这个标志是何含义？', '4', '40米减速行驶路段', '最低时速40公里', '最高时速40公里', '解除时速40公里限制', '解除时速40公里限制：表示限制速度路段结束。此标志设在限制车辆速度路段的重点。', 'https://images.juheapi.com/jztk/c1c2subject1/57.jpg'),
('58', '这个标志是何含义？', '4', '右侧通行', '左侧通行', '向右行驶', '环岛行驶', '环岛行驶：表示只准车辆靠右环行。此标志设在环岛面向路口来车方向适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/58.jpg'),
('59', '红色圆圈内标线含义是什么？', '3', '临时停靠站', '大客车停靠站', '公交车停靠站', '应急停车带', '都写了公交站了，不许选错了', 'https://images.juheapi.com/jztk/c1c2subject1/59.jpg'),
('60', '这个标志是何含义？', '2', '车多路段', '慢行', '拥堵路段', '施工路段', '慢行：此标志设在前方需要减速慢行的路段以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/60.jpg'),
('61', '这个标志是何含义？', '1', '有人看守铁路道口', '多股铁路与道路相交', '立交式的铁路道口', '无人看守铁路道口', '有火车形状的，为无人看守的铁路口，此图为有人看守的铁路口。', 'https://images.juheapi.com/jztk/c1c2subject1/61.jpg'),
('62', '这个标志是何含义？', '3', '路面低洼', '驼峰桥', '路面不平', '路面高突', '路面不平：用以提醒车辆驾驶人减速慢行。设在路面颠簸路段或桥头跳车较严重的地点以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/62.jpg'),
('63', '这个标志是何含义？', '3', '不准小型车通行', '只准小型车行驶', '机动车行驶', '禁止小型车行驶', '看到小汽车你应该想到的是机动车行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/63.jpg'),
('64', '这个标志是何含义？', '3', '环行交叉路口预告', '十字交叉路口预告', 'Y型交叉路口预告', '丁字交叉路口预告', '俩个箭头加上你来的道路形成一个Y字。', 'https://images.juheapi.com/jztk/c1c2subject1/64.jpg'),
('65', '这个路面标记是何含义？', '1', '非机动车道', '摩托车专用道', '电瓶车专用道', '自行车专用道', '这是非机动车（就是不烧油的）不要把四轮的开到他们的道上', 'https://images.juheapi.com/jztk/c1c2subject1/65.jpg'),
('66', '这个标志是何含义？', '1', '易滑路段', '急转弯路', '试车路段', '曲线路段', '易滑路段：此标志设在路面的摩擦系数不能满足相应行驶速度下要求紧急刹车距离的路段前适当位置。行驶至此路段必须减速慢行。', 'https://images.juheapi.com/jztk/c1c2subject1/66.jpg'),
('67', '这个标志是何含义？', '1', '两侧通行', '不准通行', '左侧通行', '右侧通行', '用于引导行车方向，提示道路使用者前方线形变化，注意谨慎驾驶。设于中央隔离设施端部、渠化设施的端部、桥头等。∧表示俩侧通行，/这个方向的表示左侧通行，这个方向表示右侧通行。交通指路标志大全：http://www.jszks.com/onepage/16752.html', 'https://images.juheapi.com/jztk/c1c2subject1/67.jpg'),
('68', '这个标志是何含义？', '1', '隧道出口距离', '隧道入口距离', '隧道跟车距离', '隧道总长度', '用于指示到前方隧道出口的距离。设在长度超过3 000 m的特长隧道内，从距离隧道出口2 000m处开始每500 m设置一块，直至隧道出口。该标志一般设置在隧道侧壁上。不要纠结选D，正确答案就是A，牢记吧。交通指路标志大全：http://www.jszks.com/onepage/16752.html', 'https://images.juheapi.com/jztk/c1c2subject1/68.jpg'),
('69', '这个标志是何含义？', '3', '高速公路右侧出口预告', '高速公路下一出口预告', '高速公路地点、方向预告', '高速公路左侧出口预告', '高速公路地点、方向预告：用于指示高速公路或城市快速路两个行驶方向，设在驶入高速公路或城市快速路的匝道分岔点处。在目的地信息之上，可增加前往高速公路的编号信息。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/69.jpg'),
('70', '这个标志是何含义？', '3', '高速公路下一出口预告', '高速公路右侧出口预告', '高速公路左侧出口预告', '高速公路目的地预告', '高速公路左侧出口预告：用于预告前方出口，在距离高速公路或城市快速路减速车道的渐变段起点处。出口预告标志应同时附着出口编号标志。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/70.jpg'),
('71', '这个标志是何含义？', '1', '掉头车道', '绕行车道', '分向车道', '左转车道', '常识题。', 'https://images.juheapi.com/jztk/c1c2subject1/71.jpg'),
('72', '机动车号牌损毁，机动车所有人要向登记地车辆管理所申请补领、换领。', '1', '正确', '错误', '', '', '机动车号牌、行驶证灭失、丢失或者损毁的，机动车所有人应当向登记地车辆管理所申请补领、换领。申请时，机动车所有人应当填写申请表并提交身份证明。', NULL),
('73', '绿灯亮表示前方路口允许机动车通行。', '1', '正确', '错误', '', '', '红灯停，绿灯行。', NULL),
('74', '路面上的白色标线是何含义？', '2', '道路施工提示标线', '车行道横向减速标线', '车行道纵向减速标线', '车道变少提示标线', '<p><img src=http://nimg.cysq.com/yxlimg/20a43532.jpg>
<br/>横向减速标线
<br/><img src=http://nimg.cysq.com/yxlimg/2ec73df9.jpg>
<br/>纵向减速标线</p>', 'https://images.juheapi.com/jztk/c1c2subject1/74.jpg'),
('75', '这个标志是何含义？', '4', '高速公路报警电话', '高速公路公用电话', '高速公路紧急电话', '高速公路救援电话', '高速公路救援电话：用于指示救援电话号码，没有设置紧急电话的高速公路上应设置救援电话标志。标志上号码为示例。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/75.jpg'),
('76', '这个标志是何含义？', '4', '大型客车专用车道', '多乘员车专用车道', '公交车专用车道', 'BRT车辆专用车道', '此图为BRT车辆专用车道，与公交车专用车道的区别是多了“快速公交”四个字。', 'https://images.juheapi.com/jztk/c1c2subject1/76.jpg'),
('77', '这个标志是何含义？', '3', '傍山险路', '悬崖路段', '注意落石', '危险路段', '注意落石：此标志设在左侧有落石危险的傍山路段之前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/77.jpg'),
('78', '驾驶机动车不按照规定避让校车的，一次记6分。', '1', '正确', '错误', '', '', '根据规定，驾驶机动车不按照规定避让校车的，一次记6分 。', NULL),
('79', '路面上的黄色填充标线是何含义？', '3', '接近移动障碍物标线', '远离狭窄路面标线', '接近障碍物标线', '接近狭窄路面标线', '双黄线就是警告注意越界，“打叉的物体”就是不可移动障碍物。因此选接近障碍物标线。', 'https://images.juheapi.com/jztk/c1c2subject1/79.jpg'),
('80', '路面上导向箭头是何含义？', '3', '指示前方道路是Y型交叉口', '指示前方道路是分离式道路', '指示前方道路仅可左右转弯', '指示前方道路需向左右合流', '可以左转也可以右转，三叉路口', 'https://images.juheapi.com/jztk/c1c2subject1/80.jpg')
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('81', '这个标志是何含义？', '4', '高速公路救援电话号码', '高速公路服务电话号码', '高速公路报警电话号码', '高速公路交通广播频率', '高速公路交通广播频率：用以指示收听高速公路或城市快速路交通信息广播的频率，可在适当地点设置，根据需要可重复设置。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/81.jpg'),
('82', '这个标志是何含义？', '4', '会车时停车让右侧车先行', '右侧道路禁止车通行', '前方是双向通行路段', '会车时停车让对方车先行', '会车时停车让对方车先行：表示车辆会车时，必须停车让对方车先行。设置在会车有困难的狭窄路段的一端或由于某种原因只能开放一条车道作双向通行路段的一端。', 'https://images.juheapi.com/jztk/c1c2subject1/82.jpg'),
('83', '这个标志是何含义？', '1', '高速公路停车区预告', '高速公路避险处预告', '高速公路停车场预告', '高速公路服务区预告', '高速公路停车区是有茶杯的，高速公路停车场是只有一个P。', 'https://images.juheapi.com/jztk/c1c2subject1/83.jpg'),
('84', '醉酒驾驶机动车在道路上行驶会受到什么处罚？', '3', '处管制，并处罚金', '处2年以上徒刑', '处拘役，并处罚金', '处2年以下徒刑', '按照《道路交通安全法》规定：醉酒驾驶机动车辆，吊销驾照，5年内不得重新获取驾照，经过判决后处以拘役，并处罚金。', NULL),
('85', '这个标志是何含义？', '3', '禁止鸣高音喇叭', '禁止鸣低音喇叭', '应当鸣喇叭', '禁止鸣喇叭', '表示机动车行至该标志处必须鸣喇叭。此标志设在公路的急转弯处、陡坡等视线不良路段的起点。', 'https://images.juheapi.com/jztk/c1c2subject1/85.jpg'),
('86', '这个标志是何含义？', '4', '左转让行', '直行单行路', '向右单行路', '向左单行路', '表示一切车辆向左单向行驶。此标志设在单行路的路口和入口处的适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/86.jpg'),
('87', '这个路面标记是何含义？', '4', '平均速度为100公里/小时', '最低限速为100公里/小时', '解除100公里/小时限速', '最高限速为100公里/小时', '黄色是警示你别超了，一越你就黄了', 'https://images.juheapi.com/jztk/c1c2subject1/87.jpg'),
('88', '这个标志是何含义？', '2', '禁止向左转弯', '向左和向右转弯', '禁止向左右转弯', '禁止向右转弯', '向左和向右转弯：表示只准一切车辆向左和向右转弯。此标志设在车辆必须向左和向右转弯的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/88.jpg'),
('89', '路缘石上的黄色实线是何含义？', '4', '仅允许上下人员', '仅允许装卸货物', '禁止长时间停车', '禁止停放车辆', '黄色实线表示禁止停放车辆，黄色虚线表示禁止长时间停车。题目图片是黄色实线，因此表示禁止停放车辆。选项D正确，答案选D。', 'https://images.juheapi.com/jztk/c1c2subject1/89.jpg'),
('90', '这个标志是何含义？', '2', '路面不平', '路面高突', '路面低洼', '驼峰桥', '路面高突：用以提醒车辆驾驶人减速慢行。设在路面突然高突以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/90.jpg'),
('91', '这个标志是何含义？', '4', '露天停车场', '紧急停车带', '停车位', '错车道', '错车道指的是在单车道道路上，可通视的一定距离内，供车辆交错避让用的一段加宽车道。', 'https://images.juheapi.com/jztk/c1c2subject1/91.jpg'),
('92', '图中圈内黄色虚线是什么标线？', '2', '非机动车引导线', '路口导向线', '车道连接线', '小型车转弯线', '黄色虚线 划于路段中时，用以分隔同向行驶的交通流或作为行车安全距离识别线；划于路口时，用以引导车辆行进。
<br/>例如：当我方车道上的车辆与对面道路上的车同时左转弯时，一律需要在线内行驶，保证有足够的安全距离。', 'https://images.juheapi.com/jztk/c1c2subject1/92.jpg'),
('93', '这个标志是何含义？', '3', '直行和左转弯行驶', '直行和右转弯行驶', '立体交叉直行和右转弯行驶', '立体交叉直行和左转弯行驶', '立体交叉直行和右转弯行驶：表示车辆在立交处可以直行和按图示路线右转弯行驶。此标志设在立交右转弯出口处适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/93.jpg'),
('94', '指示标线的作用是什么？', '2', '禁止通行', '指示通行', '限制通行', '警告提醒', '指示标线是指示通行的，具体的红色标志表示禁止、限制；黄色标志表示警告。', NULL),
('95', '这个标志是何含义？', '1', '十字交叉路口', '环行交叉路口', 'T型交叉路口', 'Y型交叉路口', '十字交叉路口：除了基本形十字路口外，还有部分变异的十字路口，如：五路交叉路口、变形十字路口、变形五路交叉路口等。五路以上的路口均按十字路口对待。', 'https://images.juheapi.com/jztk/c1c2subject1/95.jpg'),
('96', '图中圈内白色虚线是什么标线？', '4', '小型车转弯线', '车道连接线', '非机动车引导线', '路口导向线', '白色虚线划于路段中时，用以分隔同向行驶的交通流或作为行车安全距离识别线；划于路口时，用以引导车辆行进。', 'https://images.juheapi.com/jztk/c1c2subject1/96.jpg'),
('97', '路面上白色虚线和三角地带标线组成的是什么标线？', '1', '道路入口标线', '可跨越式分道线', '道路入口减速线', '道路出口标线', '<p><img src=http://tp.mnks.cn/tp_303.jpg>
<br/>道路出口标线
<br/><img src=http://tp.mnks.cn/tp_304.jpg>
<br/>道路入口标线</p>', 'https://images.juheapi.com/jztk/c1c2subject1/97.jpg'),
('98', '驾驶人违反交通运输管理法规发生重大事故后，逃逸或者有其他特别恶劣情节的，处7年以上有期徒刑。', '2', '正确', '错误', '', '', '《刑法》第一百三十三条规定：
<br/>1、违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；
<br/>2、<b>交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；</b>
<br/>3、因逃逸致人死亡的，处七年以上有期徒刑。
<br/>根据规定， 题目中的情况应该判处 <b>[ 三年以上七年以下有期徒刑 ]</b> ，并非七年以上有期徒刑。题目描述错误，因此答案为错。', NULL),
('99', '路中心白色实线是何含义？', '2', '单侧可跨越同向车道分界线', '禁止跨越同向车行道分界线', '双侧可跨越同向车道分界线', '禁止跨越对向车行道分界线', '图中两车道明显为同方向，而且实线不能压，因此路中心白色实线是禁止跨越同向车行道分界线。', 'https://images.juheapi.com/jztk/c1c2subject1/99.jpg'),
('100', '这个地面标记是什么标线？', '1', '人行横道预告', '交叉路口预告', '减速让行预告', '停车让行预告', '这种标线在到达人行横道前的道路30-50米处设置，它的作用是用来提示驾驶员，前方已接近人行横道，应减速慢行，并须注意行人横过马路。', 'https://images.juheapi.com/jztk/c1c2subject1/100.jpg'),
('101', '使用其他机动车号牌、行驶证的一次记3分。', '2', '正确', '错误', '', '', '机动车驾驶人有下列违法行为之一，一次记12分：<br/>（一）驾驶与准驾车型不符的机动车的；<br/>（二）饮酒后驾驶机动车的；<br/>（三）驾驶营运客车（不包括公共汽车）、校车载人超过核定人数20％以上的；<br/>（四）造成交通事故后逃逸，尚不构成犯罪的；<br/>（五）上道路行驶的机动车未悬挂机动车号牌的，或者故意遮挡、污损、不按规定安装机动车号牌的；<br/><b>（六）使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的；</b><br/>（七）驾驶机动车在高速公路上倒车、逆行、穿越中央分隔带掉头的；<br/>（八）驾驶营运客车在高速公路车道内停车的；<br/>（九）驾驶中型以上载客载货汽车、校车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速20％以上或者在高速公路、城市快速路以外的道路上行驶超过规定时速50％以上，以及驾驶其他机动车行驶超过规定时速50%以上的；<br/>（十）连续驾驶中型以上载客汽车、危险物品运输车辆超过4小时未停车休息或者停车休息时间少于20分钟的；', NULL),
('102', '雾天对安全行车的主要影响是什么？', '3', '发动机易熄火', '易发生侧滑', '能见度低，视线不清', '行驶阻力增大', '雾天的能见度很低，容易造成视野不良。而易发生侧滑的应该是滑溜的路面，雾天与行驶阻力大和发动机熄火并无直接关联。因此本题选D', NULL),
('103', '这个路面数字标记是何含义？', '3', '保持车距标记', '最小间距标记', '速度限制标记', '道路编号标记', '<p><img src=http://tp.mnks.cn/tp_321.jpg>
<br/>限制速度
<br/><img src=http://tp.mnks.cn/tp_322.jpg>
<br/>限制最高速度
<br/><img src=http://tp.mnks.cn/tp_323.jpg>
<br/>限制最低速度</p>', 'https://images.juheapi.com/jztk/c1c2subject1/103.jpg'),
('104', '这个路口允许车辆怎样行驶？', '1', '直行或向右转弯', '向左转弯', '直行或向左转弯', '向左、向右转弯', '请看灯，直行和右转灯是绿的。', 'https://images.juheapi.com/jztk/c1c2subject1/104.jpg'),
('105', '遇到这种情况时怎样行驶？', '4', '加速进入两侧车道行驶', '进入右侧车道行驶', '减速进入两侧车道行驶', '禁止车辆在两侧车道通行', '两侧车道都是红灯，都不可以通行，所以是禁止车辆在两侧车道通行。', 'https://images.juheapi.com/jztk/c1c2subject1/105.jpg'),
('106', '这个标志是何含义？', '1', '高速公路右侧出口预告', '高速公路目的地预告', '高速公路左侧出口预告', '高速公路下一出口预告', '高速公路右侧出口预告：用于预告前方出口，设置在距离高速公路或城市快速路减速车道的渐变段起点处。出口预告标志应同时附着出口编号标志。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/106.jpg'),
('107', '这个标志是何含义？', '2', '向左单行路', '向右单行路', '直行单行路', '右转让行', '表示一切车辆向右单向行驶。此标志设在单行路的路口和入口处的适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/107.jpg'),
('108', '驾驶机动车发生财产损失交通事故后，当事人对事实及成因无争议移动车辆时需要对现场拍照或者标划停车位置。', '1', '正确', '错误', '', '', '《道路交通事故处理程序规定》第十三条：机动车与机动车、机动车与非机动车发生财产损失事故，当事人对事实及成因无争议的，可以自行协商处理损害赔偿事宜。<b>车辆可以移动的，当事人应当在确保安全的原则下对现场拍照或者标划事故车辆现场位置后，立即撤离现场，将车辆移至不妨碍交通的地点，再进行协商。</b>非机动车与非机动车或者行人发生财产损失事故，基本事实及成因清楚的，当事人应当先撤离现场，再协商处理损害赔偿事宜。', NULL),
('109', '交通警察对未放置保险标志上道路行驶的车辆可依法扣留行驶证。', '2', '正确', '错误', '', '', '《道路交通安全法》第九十五条：<b>上道路行驶的机动车未悬挂机动车号牌，未放置检验合格标志、保险标志，或者未随车携带行驶证、驾驶证的，公安机关交通管理部门应当扣留机动车，通知当事人提供相应的牌证、标志或者补办相应手续，并可以依照本法第九十条的规定予以处罚。</b>当事人提供相应的牌证、标志或者补办相应手续的，应当及时退还机动车。故意遮挡、污损或者不按规定安装机动车号牌的，依照本法第九十条的规定予以处罚。
<br/>根据规定，对于不放置保险标志上路的处罚，扣留的是机动车，并不会扣留行驶证。因此题目描述有误，本题答案应为错误。', NULL),
('110', '这辆红色轿车可以在该车道行驶。', '2', '正确', '错误', '', '', '中间红灯表示中间车道禁行。因此红色轿车不可以在该车道行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/110.jpg'),
('111', '路中白色虚线是什么标线？', '4', '禁止跨越对向车道中心线', '限制跨越对向车道中心线', '单向行驶车道分界中心线', '可跨越同向车道中心线', '白色表示同向两车道之间的标线，虚线可跨越超车。', 'https://images.juheapi.com/jztk/c1c2subject1/111.jpg'),
('112', '路右侧车行道边缘白色虚线是什么含义？', '1', '车辆可临时越线行驶', '车辆禁止越线行驶', '应急车道分界线', '人行横道分界线', '<p><img src=http://tp.mnks.cn/tp_292.jpg>
<br/>禁止跨越白色实线
<br/><img src=http://tp.mnks.cn/tp_293.jpg>
<br/>允许跨越白色虚线</p>', 'https://images.juheapi.com/jztk/c1c2subject1/112.jpg'),
('113', '这个标志是何含义？', '2', 'Y型交叉路口', 'T型交叉路口', '十字交叉路口', '环行交叉路口', 'T型交叉路口：丁字形标志原则上设在与交叉口形状相符的道路上。右侧丁字路口，此标志设在进入T字路口以前的适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/113.jpg'),
('114', '路两侧的车行道边缘白色实线是什么含义？', '2', '车辆可临时跨越', '禁止车辆跨越', '机动车可临时跨越', '非机动车可临时跨越', '<p><img src=http://tp.mnks.cn/tp_292.jpg><br/>禁止跨越白色实线</p><p><img src=http://tp.mnks.cn/tp_293.jpg><br/>允许跨越白色虚线</p>', 'https://images.juheapi.com/jztk/c1c2subject1/114.jpg'),
('115', '这个路口允许车辆怎样行驶？', '3', '直行或向右转弯', '向右转弯', '向左转弯', '直行', '左转的灯是绿色，所以可以向左转弯。', 'https://images.juheapi.com/jztk/c1c2subject1/115.jpg'),
('116', '冰雪道路对安全行车的主要影响是什么？', '4', '电器设备易受潮短路', '能见度降低，视野模糊', '行驶阻力增大', '制动性能差，方向易跑偏', '冰雪道路，因汽车轮胎与路面的摩擦系数减小、附着力大大降低，汽车驱动轮很容易打滑或空转，尤其是上坡、起步、停车时还会出现后溜车的现象；车辆在行驶中如果突然加速或减速，很容易造成侧滑及方向跑偏现象；遇情况紧急制动时，制动距离会大大延长。', NULL),
('117', '图中圈内的白色折线是什么标线？', '1', '车距确认线', '减速行驶线', '车速确认线', '路口减速线', '白色平行粗实线，用以提供车辆驾驶人保持行车安全距离的参考，与车距确认标志配合使用。设在常发生超车、易肇事或其他有需要路段。高速公路车距确认标线作用为，见此标线时，驾驶人应与前车保持行车安全距离，避免发生交通事故。', 'https://images.juheapi.com/jztk/c1c2subject1/117.jpg'),
('118', '图中路口中央黄色路面标记是什么标线？', '3', '中心圈', '导流线', '网状线', '停车区', '路面黄色网状线表示严格禁止一切车辆长时或临时停车，防止交通阻塞。当黄色网状线前方有车辆停驶时，后车必须在黄色网状线外等候，直到确认黄色网状线前方有足够空间停驶本车时，方可驶过黄色网状线。 另有黄色网状线是施画在重要国家机关、军队、大型企事业单位和公交枢纽门前，确保车辆进出时不致被门前拥堵车辆堵住的措施。网状线是黄色线，停车时禁止占用。', 'https://images.juheapi.com/jztk/c1c2subject1/118.jpg'),
('119', '这个标志是何含义？', '1', '堤坝路', '临崖路', '傍水路', '易滑路', '堤坝路：用以提醒车辆驾驶人小心驾驶，设在沿水库、湖泊、河流等堤坝道路以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/119.jpg'),
('120', '水淹路面影响行车安全，不易通行的原因是什么？', '2', '路面附着力增大', '无法观察到暗坑和凸起的路面', '能见度低，视野模糊', '日光反射阻挡视线', '因为水淹没了路面，所以看不清是暗坑和凸起的路面。', NULL),
('121', '夜间行车，驾驶人视距变短，影响观察，同时注意力高度集中，易产生疲劳。', '1', '正确', '错误', '', '', '高度集中注意力，比较费神，时间久了就会疲倦。', NULL),
('122', '这个导向箭头是何含义？', '4', '指示前方可左转或掉头', '指示前方可直行或左转', '指示前方直行向左变道', '指示前方可直行或掉头', '直行或者掉头都可以', 'https://images.juheapi.com/jztk/c1c2subject1/122.jpg'),
('123', '图中圈内两条黄色虚线间的区域是何含义？', '4', '营运客车专用车道', '大客车专用车道', '出租车专用车道', '公交专用车道', '黄色虚线中的车道里有写字，黄色虚线是想突出引动驾驶员注意的，因此本题是公交专用车道。', 'https://images.juheapi.com/jztk/c1c2subject1/123.jpg'),
('124', '这个标志是何含义？', '4', '减速让行', '潮汐车道', '分离式道路', '双向交通', '双向交通：用以提醒车辆驾驶人注意会车。设在由双向分离行驶，因某种原因出现临时性或永久性的不分离双向行驶的路段，或由单向行驶进人双向行驶的路段以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/124.jpg'),
('125', '这个标志是何含义？', '1', '人行横道', '学生通道', '注意行人', '儿童通道', '表示该处为专供行人横穿马路的通道。此标志设在人行横道的两侧。', 'https://images.juheapi.com/jztk/c1c2subject1/125.jpg'),
('126', '这个标志预告什么？', '4', '高速公路服务区预告', '高速公路避险处预告', '高速公路客车站预告', '高速公路停车场预告', '<p><img src=http://tp.mnks.cn/tp_283.jpg>
<br/>高速公路停车区
<br/><img src=http://tp.mnks.cn/tp_284.jpg>
<br/>高速公路停车场
<br/><img src=http://tp.mnks.cn/tp_282.jpg>
<br/>高速公路服务区预告</p>', 'https://images.juheapi.com/jztk/c1c2subject1/126.jpg'),
('127', '驾驶人记分没有达到满分，有罚款尚未缴纳的，记分转入下一记分周期。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第二十四条：机动车驾驶人在一个记分周期内记分未达到12分，所处罚款已经缴纳的，记分予以清除；记分虽未达到12分，但尚有罚款未缴纳的，记分转入下一记分周期。', NULL),
('128', '黄灯持续闪烁，表示机动车可以加速通过。', '2', '正确', '错误', '', '', '黄灯持续闪烁，表明已经越过停止线的车辆可以行使，没越过停止线的车辆要停车等待，机动车不能加速通过。', NULL),
('129', '使用伪造、变造的机动车号牌一次记几分？', '3', '2分', '3分', '12分', '6分', '《公安部令第123号》规定，使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的，一次记12分 。', NULL),
('130', '这一组交通警察手势是什么信号？', '4', '减速慢行信号', '靠边停车信号', '停止信号', '右转弯信号', '手势题详解：http://www.jszks.com/onepage/16203.html', 'https://images.juheapi.com/jztk/c1c2subject1/130.jpg'),
('131', '这个标志是何含义？', '3', '省道编号', '县道编号', '乡道编号', '国道编号', '乡道是白底Y字开头的，县道是白底X开头的，省道是黄底的，国道是红底的。', 'https://images.juheapi.com/jztk/c1c2subject1/131.jpg'),
('132', '这一组交通警察手势是什么信号？', '4', '右转弯信号', '减速慢行信号', '靠边停车信号', '变道信号', '手势题详解：http://www.jszks.com/onepage/16203.html', 'https://images.juheapi.com/jztk/c1c2subject1/132.jpg'),
('133', '这个标志是何含义？', '4', '向右变道', '分流处', '路面变宽', '车道数增加', '俩个车道变成三个，表示车道数增加。', 'https://images.juheapi.com/jztk/c1c2subject1/133.jpg'),
('134', '这个导向箭头是何含义？', '3', '指示向左变道', '指示前方直行', '指示前方左转弯', '指示前方右转弯', '请记住了哦，不难的吧', 'https://images.juheapi.com/jztk/c1c2subject1/134.jpg'),
('135', '这个标志是何含义？', '4', '国界', '边防', '边界', '海关', '海关那俩个大字那么清晰你再不选D，D得有多伤心。', 'https://images.juheapi.com/jztk/c1c2subject1/135.jpg'),
('136', '驾驶机动车在铁路道口看到这种信号灯时怎样行驶？', '2', '在火车到来前通过', '不得越过停止线', '边观察边缓慢通过', '不换挡加速通过', '在铁路道口，红灯已亮，表示可能有火车驶来，此时绝对禁止通行，不得越过停止线。', 'https://images.juheapi.com/jztk/c1c2subject1/136.jpg'),
('137', '这个标志是何含义？', '1', '立体交叉直行和左转弯行驶', '立体交叉直行和右转弯行驶', '直行和左转弯行驶', '直行和右转弯行驶', '立体交叉直行和左转弯行驶：表示车辆在立交处可以直行和按图示路线左转弯行驶。此标志设在立交左转弯出口处适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/137.jpg'),
('138', '这个导向箭头是何含义？', '3', '指示向左变道', '指示前方直行', '指示前方掉头', '指示前方右转', '请记住了 so easy!!', 'https://images.juheapi.com/jztk/c1c2subject1/138.jpg'),
('139', '夜间道路环境对安全行车的主要影响是什么？', '3', '驾驶人体力下降', '驾驶人易产生冲动、幻觉', '能见度低、不利于观察道路交通情况', '路面复杂多变', '<b>夜间行车视线差，在没有照明的路段，驾驶人视线普遍受到影响，不能清楚看到前方事物，或者不能看清和判断前方事物的距离，尤其是在会车的情况下，由于受对向车辆灯光的影响，会产生视觉的盲点，导致看不清或看不见前方事物，夜间特大道路交通事故明显高于白天。</b>夜间行车由于不能见到道路两旁的景观，对驾驶员兴奋性刺激物小，因此最易产生驾驶疲劳，如稍有感觉就应振作精神或停车休息片刻。因此本题选A。', NULL),
('140', '这个标志是何含义？', '3', '内部停车场', '专用停车场', '露天停车场', '室内停车场', '如果P字上边没有遮挡就是露天停车场。', 'https://images.juheapi.com/jztk/c1c2subject1/140.jpg'),
('141', '这个标志是何含义？', '2', '直行车道', '只准直行', '单行路', '禁止直行', '只准直行：表示只准一切车辆直行。此标志设在直行的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/141.jpg'),
('142', '这个标志是何含义？', '1', '驼峰桥', '路面高突', '路面低洼', '不平路面', '驼峰桥：用以提醒车辆驾驶人谨慎驾驶。设在拱度很大，影响视距的驼峰桥以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/142.jpg'),
('143', '这个标志是何含义？', '3', '禁止在路口掉头', '禁止向左向右变道', '禁止向左向右转弯', '禁止车辆直行', '禁止向左向右转弯：表示前方路口禁止一切车辆向左向右转弯。此标志设在禁止向左向右转弯的路口前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/143.jpg'),
('144', '这个标志提示哪种车型禁止通行？', '2', '各种车辆', '小型客车', '中型客车', '小型货车', '此标志表示禁止小型客车驶入。轿车属于小型客车。', 'https://images.juheapi.com/jztk/c1c2subject1/144.jpg'),
('145', '这个标志是何含义？', '1', '最低限速50公里/小时', '高度限速50公里/小时', '水平高度50米', '海拔高度50米', '表示机动车驶入前方道路之最低时速限制。此标志设在高速公路或其他道路限速路段的起点。高度限速标志是白底红字。', 'https://images.juheapi.com/jztk/c1c2subject1/145.jpg'),
('146', '这个标志是何含义？', '1', '避险车道', '应急车道', '路肩', '急弯道', '避险车道是指在长陡下坡路段行车道外侧增设的供速度失控车辆驶离正线安全减速的专用车道。', 'https://images.juheapi.com/jztk/c1c2subject1/146.jpg'),
('147', '这个标志是何含义？', '1', '应急避难场所', '生活服务区', '行人专用通道', '横过道路设施', '你看他的动作时在跑，所以是紧急的情况，所以答案是A。应急避难场所是应对突发公共事件的一项灾民安置措施，是现代化大城市用于民众躲避火灾、爆炸、洪水、地震、疫情等重大突发公共事件的安全避难场所。', 'https://images.juheapi.com/jztk/c1c2subject1/147.jpg'),
('148', '这个标志是何含义？', '3', '禁止车辆掉头', '禁止向左变道', '禁止向左转弯', '禁止驶入左车道', '禁止向左转弯：表示前方路口禁止一切车辆向左转弯。此标志设在禁止向左转弯的路口前适当位置', 'https://images.juheapi.com/jztk/c1c2subject1/148.jpg'),
('149', '这个标志是何含义？', '3', '右转车道', '掉头车道', '左转车道', '分向车道', '表示只准一切车辆向左转弯。此标志设在车辆必须向左转弯的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/149.jpg'),
('150', '初次申领驾驶证的驾驶人在实习期内可以单独驾驶机动车上高速公路行驶。', '2', '正确', '错误', '', '', '《公安部令第123号》第六十五条：<b>驾驶人在实习期内驾驶机动车上高速公路行驶，应当由持相应或者更高准驾车型驾驶证三年以上的驾驶人陪同。</b>其中，驾驶残疾人专用小型自动挡载客汽车的，可以由持有小型自动挡载客汽车以上准驾车型驾驶证的驾驶人陪同。', NULL),
('151', '驾驶人将机动车交给驾驶证被吊销的人驾驶的，交通警察依法扣留驾驶证。', '1', '正确', '错误', '', '', '六种情形下可以扣留驾驶证 新法规定，有下列情形之一的，可以扣留机动车驾驶证： <br/>(一)饮酒、醉酒后驾驶机动车的； <br/>(二)<b>机动车驾驶人将机动车交由未取得机动车驾驶证或者机动车驾驶证被吊销、暂扣的人驾驶的；<br/></b> (三)机动车行驶超过规定时速百分之五十的； <br/>(四)驾驶拼装或者已达到报废标准的机动车的； <br/>(五)发生重大交通事故，构成犯罪的； <br/>(六)在一个记分周期内累积记分达到12分的。', NULL),
('152', '驾驶机动车遇到这种信号灯亮时，如果已越过停止线，可以继续通行。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第三十八条：黄灯亮时，已越过停止线的车辆可以继续通行；未经过停止线的则禁止继续通行。', 'https://images.juheapi.com/jztk/c1c2subject1/152.jpg'),
('153', '驾驶人因服兵役、出国（境）等原因无法办理审验时，延期审验期限最长不超过多长时间？', '1', '3年', '5年', '1年', '2年', '《机动车驾驶证申领和使用规定》第五十条：机动车驾驶人因服兵役、出国（境）等原因，无法在规定时间内办理驾驶证期满换证、提交身体条件证明的，可以向机动车驾驶证核发地车辆管理所申请延期办理，<b>延期期限最长不超过三年</b>。延期期间机动车驾驶人不得驾驶机动车。', NULL),
('154', '这一组交通警察手势是什么信号？', '4', '左转弯待转信号', '靠边停车信号', '减速慢行信号', '左转弯信号', '手势题详解：http://www.jszks.com/onepage/16203.html', 'https://images.juheapi.com/jztk/c1c2subject1/154.jpg'),
('155', '泥泞道路对安全行车的主要影响是什么？', '2', '行驶阻力变小', '车轮极易滑转和侧滑', '能见度低，视野模糊', '路面附着力增大', '泥泞道路，泥土附着在轮胎上，轮胎和地面的摩擦减小，附着力也随之减小，车轮容易发生滑转和侧滑；同时因为道路状况变差，行驶阻力也变大。', NULL),
('156', '路面上的菱形块虚线是何含义？', '2', '道路施工提示标线', '车行道纵向减速标线', '车行道横向减速标线', '车道变少提示标线', '<p><img src=http://nimg.cysq.com/yxlimg/20a43532.jpg>
<br/>横向减速标线
<br/><img src=http://nimg.cysq.com/yxlimg/2ec73df9.jpg>
<br/>纵向减速标线</p>', 'https://images.juheapi.com/jztk/c1c2subject1/156.jpg'),
('157', '行车中突遇对向车辆强行超车，占据自己车道时，可不予避让，迫使对方让路。', '2', '正确', '错误', '', '', '行车要始终记得安全文明驾驶，对方要超车，应及时减速避让。', NULL),
('158', '图中圈内三角填充区域是什么标线？', '3', '停车线', '减速线', '导流线', '网状线', '导流线的形式主要为一个或几个根据路口地形设置的白色V形线或斜纹线区域，表示车辆必须按规定的路线行驶，不得压线或越线行驶。 主要用于过宽、不规则或行驶条件比较复杂的交叉路口,立体交叉的匝道口或其他特殊地点。', 'https://images.juheapi.com/jztk/c1c2subject1/158.jpg'),
('159', '夜间驾驶人对物体的观察明显比白天差，视距会有什么变化？', '4', '不变', '无规律', '变长', '变短', '夜晚，在路上行车，由于车灯作用，看到的是黑色背景中的亮色物体，所以亮色物体偏大，而眼睛依旧以近大远小的感觉判断，故视距减小。', NULL),
('160', '有下列哪种违法行为的机动车驾驶人将被一次记12分？', '4', '机动车驾驶证被暂扣期间驾驶机动车的', '以隐瞒、欺骗手段补领机动车驾驶证的', '驾驶机动车不按照规定避让校车的', '驾驶故意污损号牌的机动车上道路行驶', '《公安部令第123号》规定，上道路行驶的机动车未悬挂机动车号牌的，或者故意遮挡、污损、不按规定安装机动车号牌的，一次记12分 。其余均为6分。', NULL)
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('161', '图中圈内白色横实线是何含义？', '4', '待转线', '减速线', '让行线', '停止线', '<p><img src=http://tp.mnks.cn/tp_332.jpg>
<br/>停止线
<br/><img src=http://tp.mnks.cn/tp_333.jpg>
<br/>停车让行线
<br/><img src=http://tp.mnks.cn/tp_334.jpg>
<br/>减速让行线</p>', 'https://images.juheapi.com/jztk/c1c2subject1/161.jpg'),
('162', '这一组交通警察手势是什么信号？', '3', '左转弯待转信号', '靠边停车信号', '右转弯信号', '减速慢行信号', '手势题详解：http://www.jszks.com/onepage/16203.html', 'https://images.juheapi.com/jztk/c1c2subject1/162.jpg'),
('163', '路中心黄色虚线属于哪一类标线？', '1', '指示标线', '禁止标线', '警告标志', '辅助标线', '根据GB 5768.3-2009《道路交通标志和标线第3部分：道路交通标线》的规定：
<br/>黄色虚线，划于路段中时，用以分隔对向行驶的交通流。
<br/>起到指示的作用，属于指示标线。', 'https://images.juheapi.com/jztk/c1c2subject1/163.jpg'),
('164', '在狭窄的路段会车时，应做到礼让三先：先慢、先让、先停。', '1', '正确', '错误', '', '', '文明驾驶，礼貌让行。', NULL),
('165', '驾驶人有哪种情形，交通警察可依法扣留机动车驾驶证？', '4', '超过规定速度10%', '疲劳后驾驶机动车', '行车中未系安全带', '饮酒后驾驶机动车', '六种情形下可以扣留驾驶证。新法规定，有下列情形之一的，可以扣留机动车驾驶证：<br/> <b> (一)饮酒、醉酒后驾驶机动车的；</b>  <br/>(二)机动车驾驶人将机动车交由未取得机动车驾驶证或者机动车驾驶证被吊销、暂扣的人驾驶的；  <br/>(三)机动车行驶超过规定时速百分之五十的； <br/>(四)驾驶拼装或者已达到报废标准的机动车的；  <br/>(五)发生重大交通事故，构成犯罪的；  <br/>(六)在一个记分周期内累积记分达到12分的。', NULL),
('166', '在铁路道口遇到两个红灯交替闪烁时要停车等待。', '1', '正确', '错误', '', '', '在铁路道口，一个红灯亮或两个红灯闪烁时都是禁止通行的，要停车等待。', 'https://images.juheapi.com/jztk/c1c2subject1/166.jpg'),
('167', '这个标志是何含义？', '1', '旅游区距离', '旅游区方向', '旅游区符号', '旅游区类别', '遇此类标志是指旅游区的距离还有多远（亲不要激动 安全第一 慢行', 'https://images.juheapi.com/jztk/c1c2subject1/167.jpg'),
('168', '伪造、变造或者使用伪造、变造驾驶证的驾驶人构成犯罪的，将依法追究刑事责任。', '1', '正确', '错误', '', '', '《道路交通安全法》第九十六条：伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、驾驶证的，由公安机关交通管理部门予以收缴，扣留该机动车，处十五日以下拘留，并处二千元以上五千元以下罚款；构成犯罪的，依法追究刑事责任。', NULL),
('169', '驾驶证记载的驾驶人信息发生变化的要在多长时间内申请换证？', '1', '30日', '40日', '50日', '60日', '《公安部令第123号》第五十一条：<br/>具有下列情形之一的，机动车驾驶人应当在三十日内到机动车驾驶证核发地车辆管理所申请换证：<br/><b>（一）在车辆管理所管辖区域内，机动车驾驶证记载的机动车驾驶人信息发生变化的；</b><br/>（二）机动车驾驶证损毁无法辨认的。', NULL),
('170', '路面上的黄色标记是何含义？', '3', '禁止掉头', '禁止左转', '禁止右转', '禁止直行', '一个X加上一个右转，加一起就是禁止右转，爆弱了', 'https://images.juheapi.com/jztk/c1c2subject1/170.jpg'),
('171', '路中两条双黄色虚线是什么标线？', '2', '双向分道线', '潮汐车道线', '可跨越分道线', '单向分道线', '路中两条双黄色虚线是潮汐车道线。
<br/>“潮汐车道”是指根据早晚交通流量不同情况，对有条件的道路，试点开辟潮汐车道，通过车道灯的指示方向变化，控制主干道车道行驶方向，来调整车道数，提高车道使用效率。', 'https://images.juheapi.com/jztk/c1c2subject1/171.jpg'),
('172', '驾驶机动车在路口看到这种信号灯亮时，要加速通过。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第三十八条：黄灯亮时，已越过停止线的车辆可以继续通行；未经过停止线的则禁止继续通行。', 'https://images.juheapi.com/jztk/c1c2subject1/172.jpg'),
('173', '行车中遇有前方发生交通事故，需要帮助时，应怎样做？', '3', '尽量绕道躲避', '立即报警，停车观望', '协助保护现场，并立即报警', '加速通过，不予理睬', '维护道路交通安全，人人有责。当他人出了事故，请协助保护现场，并立即报警。', NULL),
('174', '路面上的黄色标记是何含义？', '3', '禁止直行', '允许掉头', '禁止掉头', '禁止转弯', '一个X加上一个向回掉头的标记，加一起就是禁止掉头', 'https://images.juheapi.com/jztk/c1c2subject1/174.jpg'),
('175', '对未按照国家规定投保交强险的车辆，交通警察可依法予以扣留。', '1', '正确', '错误', '', '', '《道路交通安全法》第九十八条：机动车所有人、管理人未按照国家规定投保机动车第三者责任强制保险的，由公安机关交通管理部门扣留车辆至依照规定投保后，并处依照规定投保最低责任限额应缴纳的保险费的二倍罚款。', NULL),
('176', '驾驶机动车在路口遇到这种信号灯禁止通行。', '2', '正确', '错误', '', '', '仔细看图，图中三个圆形灯从左到右分别是红色、黄色、绿灯。此时绿灯亮起，根据“红灯停，绿灯行”的原则，车辆是可以通行的。题目描述错误，本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/176.jpg'),
('177', '路面上的黄色标线是何含义？', '1', '路面宽度渐变标线', '车行道变多标线', '接近障碍物标线', '施工路段提示线', '左下角有一个标志表示路面变窄，所以黄线就是表示路面宽度有变化。', 'https://images.juheapi.com/jztk/c1c2subject1/177.jpg'),
('178', '雨天对安全行车的主要影响是什么？', '1', '路面湿滑，视线受阻', '发动机易熄火', '行驶阻力增大', '电器设备易受潮短路', '雨天路面湿滑，雨水会使视线受阻，所以更要注意行车安全。', NULL),
('179', '驶离高速公路可以从这个位置直接驶入匝道。', '2', '正确', '错误', '', '', '不能压实线直接过去的啊，应该提前换到驶离的车道，在进入匝道。', 'https://images.juheapi.com/jztk/c1c2subject1/179.jpg'),
('180', '这一组交通警察手势是什么信号？', '3', '左转弯待转信号', '靠边停车信号', '左转弯信号', '右转弯信号', '手势题详解：http://www.jszks.com/onepage/16203.html', 'https://images.juheapi.com/jztk/c1c2subject1/180.jpg'),
('181', '驾驶与准驾车型不符的机动车一次记几分？', '4', '2分', '3分', '6分', '12分', '根据公安部《机动车驾驶证申领和使用规定》（附件3：道路交通安全违法行为记分分值），<b>驾驶与准驾车型不符的机动车的，一次应记12分。</b>', NULL),
('182', '驾驶机动车行驶到这个位置时，如果车前轮已越过停止线可以继续通过。', '2', '正确', '错误', '', '', '车全部越过停车线才可以继续通过，红灯时前轮刚过线必须停下来，否则就是闯红灯。', 'https://images.juheapi.com/jztk/c1c2subject1/182.jpg'),
('183', '这个标志是何含义？', '1', '高速公路紧急停车带', '高速公路避让处所', '高速公路客车站', '高速公路停车区', '高速公路紧急停车带：用于指示紧急停车的位置，设在紧急停车带的前端。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/183.jpg'),
('184', '图中圈内两条白色虚线是什么标线？', '2', '交叉路停车线', '左弯待转区线', '掉头引导线', '小型车转弯线', '左弯待转区是专门供左转弯车辆使用的。<br/>当直行信号灯绿灯亮时，左转弯是红灯时，左转弯的车辆可以进入左转弯待转区等候，待左转弯信号灯绿灯亮了，等候在待转区的车辆可以快速通过路口；当直行、左转弯信号灯都是红灯时，车辆是不可以进入左弯待转区的。', 'https://images.juheapi.com/jztk/c1c2subject1/184.jpg'),
('185', '驾驶机动车在这种情况下不能直行和左转弯', '1', '正确', '错误', '', '', '直行和左转都是红灯，所以不能直行和左转。', 'https://images.juheapi.com/jztk/c1c2subject1/185.jpg'),
('186', '驾驶机动车要选择绿色箭头灯亮的车道行驶。', '1', '正确', '错误', '', '', '只有绿灯是表示允许通行，机动车要选择绿色箭头灯亮的车道行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/186.jpg'),
('187', '驶近没有人行横道的交叉路口时，发现有人横穿道路，应怎样做？', '1', '减速或停车让行', '鸣喇叭示意其让道', '立即变道绕过行人', '抢在行人之前通过', '如果没有人行横道，行人就有可能从任何地方走出。遇到行人一定要减速或停车让行，注意行人的安全。', NULL),
('188', '图中圈内白色实线是什么标线？', '1', '导向车道线', '可变导向车道线', '方向引导线', '单向行驶线', '将车流诱导到应行驶的路线的设施的总称。导向车道：大城市主要平交路口两端，引导车辆分道行驶的车道，其分界线用白色单实线，表明进入该车道的车辆不得变更车道或压线行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/188.jpg'),
('189', '路中黄色分界线的作用是什么？', '2', '允许在左侧车道行驶', '分隔对向行驶的交通流', '分隔同向行驶的交通流', '禁止跨越对向行车道', '白色表示同向可跨越车道，黄色表示反向可跨越车道；虚线表示可跨越车道。', 'https://images.juheapi.com/jztk/c1c2subject1/189.jpg'),
('190', '在这条车道行驶的最低车速是多少？', '4', '100公里/小时', '110公里/小时', '60公里/小时', '90公里/小时', '高速路同方向有3条车道，最左侧的为110公里到120公里，中间的为90公里到110公里，最右侧的速度范围为60公里到90公里。', 'https://images.juheapi.com/jztk/c1c2subject1/190.jpg'),
('191', '驾驶人在超车时，前方车辆不减速、不让道，应怎样做？', '2', '紧跟其后，伺机再超', '停止继续超车', '加速继续超越', '连续鸣喇叭加速超越', '行车安全第一，如果继续强制超车，会有发生事故的危险。应该停止继续超车。', NULL),
('192', '驾驶机动车在路口直行遇到这种信号灯应该怎样行驶？', '4', '进入路口等待', '左转弯行驶', '加速直行通过', '不得越过停止线', '亮红灯时，车辆应该在停止线内停车等待。', 'https://images.juheapi.com/jztk/c1c2subject1/192.jpg'),
('193', '图中圈内的白色半圆状标记是什么标线？', '4', '减速行驶线', '车速确认线', '路口减速线', '车距确认线', '白色半圆形车距确认线半球半径为30cm，间隔50m设置，一般在一定路段内连续设置。', 'https://images.juheapi.com/jztk/c1c2subject1/193.jpg'),
('194', '驾驶机动车在路口遇到这种信号灯亮时，要在停止线前停车�望。', '2', '正确', '错误', '', '', '绿灯，赶紧的走你。', 'https://images.juheapi.com/jztk/c1c2subject1/194.jpg'),
('195', '路口最前端的双白实线是什么含义？', '1', '停车让行线', '减速让行线', '左弯待转线', '等候放行线', '<p><img src=http://tp.mnks.cn/tp_332.jpg>
<br/>停止线
<br/><img src=http://tp.mnks.cn/tp_333.jpg>
<br/>停车让行线
<br/><img src=http://tp.mnks.cn/tp_334.jpg>
<br/>减速让行线</p>', 'https://images.juheapi.com/jztk/c1c2subject1/195.jpg'),
('196', '这个标志是何含义？', '3', '旅游区距离', '旅游区类别', '旅游区方向', '旅游区符号', '快到云居寺了，箭头指的是方向', 'https://images.juheapi.com/jztk/c1c2subject1/196.jpg'),
('197', '驾驶人一边驾车，一边打手持电话是违法行为。', '1', '正确', '错误', '', '', '新修订的《机动车驾驶证申领和使用规定》公布后，2013年1月1日起施行，其中规定：驾驶机动车有拨打、接听手持电话等妨碍安全驾驶的行为的一次记2分。并且违反了《道路交通安全法》的相关规定，属于违法行为。', NULL),
('198', '大型客车、牵引车、城市公交车、中型客车、大型货车驾驶人应当每两年提交一次身体条件证明.', '2', '正确', '错误', '', '', '2013年1月1日起施行的公安部123号令，已明确规定，大、中型客货车驾驶人每年参加审验，审验时自己申报身体条件情况', NULL),
('199', '车辆在雨天临时停车时，应开启什么灯？', '2', '前后雾灯', '危险报警闪光灯', '前大灯', '倒车灯', '即使不是在雨天，我们在路边临时停车时，也要开启危险报警闪光灯。', NULL),
('200', '驾驶人在道路上醉酒驾驶机动车的处3年以上有期徒刑。', '2', '正确', '错误', '', '', '醉酒驾驶机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任；5年内不得重新取得机动车驾驶证。
<br/>醉酒驾驶营运机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任；10年内不得重新取得机动车驾驶证，重新取得机动车驾驶证后，不得驾驶营运机动车。
<br/>醉驾不用处3年以上有期徒刑。', NULL),
('201', '已注册登记的小型载客汽车有下列哪种情形，所有人不需要办理变更登记？', '2', '机动车更换发动机', '加装前后防撞装置', '改变车身颜色', '更换车身或者车架', '《道路交通安全法实施条例》第六条：已注册登记的机动车有下列情形之一的，<b>机动车所有人应当向登记该机动车的公安机关交通管理部门申请变更登记</b>： 
<br/><b>(一)改变机动车车身颜色的； 
<br/>(二)更换发动机的； 
<br/>(三)更换车身或者车架的； </b>
<br/>(四)因质量有问题，制造厂更换整车的； 
<br/>(五)营运机动车改为非营运机动车或者非营运机动车改为营运机动车的；
<br/>(六)机动车所有人的住所迁出或者迁入公安机关交通管理部门管辖区域的。
<br/>注意题目说的是 <b>[不需要办理变更登记的]</b> ，结合法规和题目要求，更换发动机、改变车身颜色、更换车身或者车架都需要办理变更登记，而B项加装前后防撞装置是不需要办理变更登记的，因此本题答案选B。', NULL),
('202', '驾驶人驾驶机动车违反道路交通信号灯通行一次记多少分?', '3', '2分', '3分', '6分', '12分', '驾驶机动车违反道路交通信号灯通行的一次记6分。', NULL),
('203', '这个标志是何含义？', '4', '高速公路左侧出口预告', '高速公路目的地预告', '高速公路右侧出口预告', '高速公路下一出口预告', '高速公路下一出口预告：预告下一出口可到达地点。当互通式立体交叉间距大于或等于3 km、小于5 km时，应设置下一出口预告标志，预告下一出口的信息和距离。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/203.jpg'),
('204', '这个标志是何含义？', '2', '高速公路出口', '高速公路起点', '高速公路入口', '高速公路终点', '高速公路起点：设在高速公路或城市快速路的起点。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/204.jpg'),
('205', '会车中遇到对方来车行进有困难需借道时，应怎样做？', '2', '靠右侧加速行驶', '尽量礼让对方先行', '不侵占对方道路，正常行驶', '示意对方停车让行', '如果遇到对方来车行进有困难需借道，请驾驶员尽量礼让对方先行，文明行车。', NULL),
('206', '驾驶机动车在这种情况下不能左转弯。', '1', '正确', '错误', '', '', '有图片可知，左转箭头此时是红灯，红灯禁止通行，因此在这种情况下不能左转弯。题目描述无误，因此本题答案为对。', 'https://images.juheapi.com/jztk/c1c2subject1/206.jpg'),
('207', '车速超过规定时速50%以上的一次记12分。', '1', '正确', '错误', '', '', '《公安部令第123号》规定，驾驶中型以上载客载货汽车、校车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速20％以上或者在高速公路、城市快速路以外的道路上行驶超过规定时速50％以上，以及驾驶其他机动车行驶超过规定时速50%以上的，一次记12分。', NULL),
('208', '一个合格的驾驶人，不仅表现在技术的娴熟上，更重要的是应该具有良好的驾驶行为习惯和道德修养。', '1', '正确', '错误', '', '', '娴熟的技术固然重要，但没有良好的驾驶习惯和道德修养，同样会破坏正常的交通秩序。因此合格驾驶员应该具备良好的驾驶行为习惯和道德修养。', NULL),
('209', '这一组交通警察手势是什么信号？', '1', '直行信号', '转弯信号', '停止信号', '靠边停车信号', '手势题详解：http://www.jszks.com/onepage/16203.html', 'https://images.juheapi.com/jztk/c1c2subject1/209.jpg'),
('210', '这个标志是何含义？', '4', '分道信息预告', '道路分岔处预告', '地点和距离预告', '十字交叉路口预告', '上边有十字能看到吧？', 'https://images.juheapi.com/jztk/c1c2subject1/210.jpg'),
('211', '驾驶机动车发生财产损失交通事故，当事人对事实及成因无争议的可先撤离现场。', '1', '正确', '错误', '', '', '《道路交通事故处理程序规定》第十三条：<b>机动车与机动车、机动车与非机动车发生财产损失事故，当事人对事实及成因无争议的，可以自行协商处理损害赔偿事宜。</b>车辆可以移动的，当事人应当在确保安全的原则下对现场拍照或者标划事故车辆现场位置后，立即撤离现场，将车辆移至不妨碍交通的地点，再进行协商。非机动车与非机动车或者行人发生财产损失事故，基本事实及成因清楚的，当事人应当先撤离现场，再协商处理损害赔偿事宜。', NULL),
('212', '距离交叉路口50米以内的路段不能停车。', '1', '正确', '错误', '', '', '根据《道路安全法实施条例》第六十三条，机动车在道路上临时停车应当遵守下列规定：<br/>（1）在设有禁停标志、标线的路段，在机动车道与非机动车道、人行道之间设有隔离设施的路段以及人行横道、施工地段，不得停车；<br/>（2）<b>交叉路口、</b>铁路道口、急转弯、宽度不足4米的窄路、桥梁、陡坡、隧道以及距离上述地点50米以内的路段，不得停车；<br/>（3）公共汽车站、急救站、加油站、消防栓或者消防队（站）门前以及距离上述地点30米以内的路段，除使用上述设施的以外，不得停车；<br/>（4）车辆停稳前不得开车门和上下人员，开关车门不得妨碍其他车辆和行人通行；<br/>（5）路边停车应当紧靠道路右侧，机动车驾驶人不得离车，上下人员或者装卸物品后，立即驶离；<br/>（6）城市公共汽车不得在站点以外的路段停车上下乘客。<br/>', NULL),
('213', '可以从这个位置直接驶入高速公路行车道。', '2', '正确', '错误', '', '', '应该按照标线行驶，不要乱开。', 'https://images.juheapi.com/jztk/c1c2subject1/213.jpg'),
('214', '遇到这种情况的路口，以下做法正确的是什么？', '2', '沿左侧车道掉头', '该路口不能掉头', '选择中间车道掉头', '在路口内掉头', '此处有禁止掉头的标志，所以是不可以掉头的。', 'https://images.juheapi.com/jztk/c1c2subject1/214.jpg'),
('215', '会车前选择的交会位置不理想时，应怎样做？', '1', '减速、低速会车或停车让行', '向左占道，让对方减速让行', '打开前照灯，示意对方停车让行', '加速选择理想位置', '发现交会位置不理想时，应减速或停车让行，以寻找下一个理想会车位置。', NULL),
('216', '驾驶机动车在铁路道口、桥梁、陡坡、隧道或者容易发生危险的路段不能掉头。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第四十九条第一款：<br/>“机动车在有禁止掉头或者禁止左转弯标志、标线的地点以及在铁路道口、人行横道、桥梁、急弯、陡坡、隧道或者容易发生危险的路段,不得掉头。”', NULL),
('217', '驾驶车辆行至道路急转弯处，应怎样做？', '3', '急剧制动低速通过', '靠弯道外侧行驶', '充分减速并靠右侧行驶', '借对向车道行驶', '安全驾驶，减速慢行。急转弯处切记减速靠右侧慢行，否则不仅容易侧翻，还容易因为视线死角与对向来车发生碰撞。', NULL),
('218', '路缘石上的黄色虚线是何含义？', '4', '禁止临时停车', '禁止上下人员', '禁止装卸货物', '禁止长时停车', '虚线是禁止长时间停车，实线是禁止临时或长时间停车。<br/>图中所示为虚线，所以禁止长时停车，可以临时停车。', 'https://images.juheapi.com/jztk/c1c2subject1/218.jpg'),
('219', '这个标志是何含义？', '4', 'T型路口', '分流路口', '减速通行', '此路不通', '用以指示前方道路为死胡同，无出口、不能通行。该标志为蓝底白色街区红色图案。', 'https://images.juheapi.com/jztk/c1c2subject1/219.jpg'),
('220', '这个标志是何含义？', '3', '高速公路公用电话', '高速公路报警电话', '高速公路紧急电话', '高速公路救援电话', '高速公路紧急电话：用于指示高速公路紧急电话的位置，可单独设置也可设在紧急电话的立柱上或箱体上。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/220.jpg'),
('221', '这个标志是何含义？', '3', '高速公路客车站预告', '高速公路避险处预告', '高速公路服务区预告', '高速公路收费站预告', '高速公路服务区预告：用于预告服务区的位置，设在减速车道起点处。表示一般服务区预告标志。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/221.jpg'),
('222', '发现前方道路堵塞，正确的做法是什么？', '1', '按顺序停车等候', '鸣喇叭示意前方车辆快速行驶', '选择空当逐车超越', '继续穿插绕行', '如果遇到前方拥堵，应该按顺序停车等候。随便加塞或者鸣喇叭都不是文明行车行为。', NULL),
('223', '这个标志是何含义？', '1', '停车领卡', '停车缴费', 'ETC通道', '停车检查', '停车领卡：用以提示停车领卡，设在进入高速公路或城市快速路收费站入口一侧的适当位置。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/223.jpg'),
('224', '在这条车道行驶的最低车速是多少？', '3', '60公里/小时', '90公里/小时', '100公里/小时', '110公里/小时', '高速路同方向有2条车道，左侧车的速度范围为100公里到120公里，右侧车的速度范围为60公里到100公里。', 'https://images.juheapi.com/jztk/c1c2subject1/224.jpg'),
('225', '这样在路边临时停放机动车有什么违法行为？', '3', '停车占用机动车道', '距离路边超过30厘米', '在有禁停标线路段停车', '在非机动车道停车', '图中右侧路边是黄色的禁止停车标线，所以此处是不能停车的。', 'https://images.juheapi.com/jztk/c1c2subject1/225.jpg'),
('226', '这个标志是何含义？', '2', '残疾人出入口', '注意残疾人', '残疾人休息处', '残疾人专用通道', '黄底标志为警告标志，所以是注意残疾人。', 'https://images.juheapi.com/jztk/c1c2subject1/226.jpg'),
('227', '这辆小型载客汽车进入高速公路行车道的行为是正确的。', '2', '正确', '错误', '', '', '这辆车直接驶入了行车道，要先在加速车道，也就是靠右的车道加速后才能驶入，所以错', 'https://images.juheapi.com/jztk/c1c2subject1/227.jpg'),
('228', '这个标志是何含义？', '1', '向右急转弯', '向右绕行', '连续弯路', '向左急转弯', '向右急转弯：向右急弯路标志，设在右急转弯的道路前方适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/228.jpg'),
('229', '在距这段路多少米以内的路段不能停放机动车？', '3', '5米以内', '10米以内', '50米以内', '30米以内', '根据《道路安全法实施条例》第六十三条，机动车在道路上临时停车应当遵守下列规定：
<br/>（1）在设有禁停标志、标线的路段，在机动车道与非机动车道、人行道之间设有隔离设施的路段以及人行横道、施工地段，不得停车；
<br/><b>（2）交叉路口、铁路道口、急转弯、宽度不足4米的窄路、桥梁、陡坡、隧道以及距离上述地点50米以内的路段，不得停车；</b>
<br/>（3）公共汽车站、急救站、加油站、消防栓或者消防队（站）门前以及距离上述地点30米以内的路段，除使用上述设施的以外，不得停车；
<br/>（4）车辆停稳前不得开车门和上下人员，开关车门不得妨碍其他车辆和行人通行；
<br/>（5）路边停车应当紧靠道路右侧，机动车驾驶人不得离车，上下人员或者装卸物品后，立即驶离。
<br/>（6）城市公共汽车不得在站点以外的路段停车上下乘客。', 'https://images.juheapi.com/jztk/c1c2subject1/229.jpg'),
('230', '在标志、标线齐全的高速公路上行车，应当按照什么规定的车道和车速行驶？', '1', '标志或标线', '《道路交通安全法》', '车辆说明书', '地方法规', '根据规定，在标志、标线齐全的路段，应该按标志、标线行驶。', NULL),
('231', '驾驶机动车在路口遇到这种信号灯表示什么意思？', '2', '禁止右转', '路口警示', '准许直行', '加速通过', '路口黄灯持续闪烁，警示驾驶人要注意瞭望，确认安全通过。', 'https://images.juheapi.com/jztk/c1c2subject1/231.jpg'),
('232', '指路标志的作用是什么？', '3', '限制车辆通行', '提示限速信息', '提供方向信息', '警告前方危险', '指路标志是传递道路方向，地点，距离信息的标志。', NULL),
('233', '机动车在道路上发生轻微交通事故且妨碍交通时，不需移动。', '2', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》第七十条：在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜。', NULL),
('234', '在这种路口怎样进行掉头？', '1', '从中心线虚线处掉头', '从右侧车道掉头', '进入路口后掉头', '在人行横道上掉头', '虚线处可掉头，实线是不能压的，所以实线处不能掉头、变道等。因此应该从图中中心线虚线处掉头才对。', 'https://images.juheapi.com/jztk/c1c2subject1/234.jpg'),
('235', '社会车辆距离消防栓或者消防队(站)门前30米以内的路段不能停车。', '1', '正确', '错误', '', '', '根据《道路安全法实施条例》第六十三条，机动车在道路上临时停车应当遵守下列规定：<br/>（1）在设有禁停标志、标线的路段，在机动车道与非机动车道、人行道之间设有隔离设施的路段以及人行横道、施工地段，不得停车；<br/>（2）交叉路口、铁路道口、急转弯、宽度不足4米的窄路、桥梁、陡坡、隧道以及距离上述地点50米以内的路段，不得停车；<br/><b>（3）公共汽车站、急救站、加油站、消防栓或者消防队（站）门前以及距离上述地点30米以内的路段，除使用上述设施的以外，不得停车；</b><br/>（4）车辆停稳前不得开车门和上下人员，开关车门不得妨碍其他车辆和行人通行；<br/>（5）路边停车应当紧靠道路右侧，机动车驾驶人不得离车，上下人员或者装卸物品后，立即驶离；<br/>（6）城市公共汽车不得在站点以外的路段停车上下乘客。<br/>', NULL),
('236', '行车中发现前方道路拥堵时，应怎样做？', '3', '寻找机会超越前车', '从车辆空间穿插通过', '减速停车，依次排队等候', '鸣喇叭催促', '减速停车依次排队，文明驾驶。', NULL),
('237', '机动车行驶中，车上少年儿童可不使用安全带。', '2', '正确', '错误', '', '', '《道路交通安全法》第五十一条：机动车行驶时，驾驶人、乘坐人员应当按规定使用安全带，摩托车驾驶人及乘坐人员应当按规定戴安全头盔。相比较成人，少年儿童自我保护能力更低，更应该系安全带。', NULL),
('238', '这位驾驶人违反法律规定的行为是什么？', '3', '没按规定握转向盘', '座椅角度不对', '没系安全带', '驾驶姿势不正确', '《道路交通安全法》第五十一条：机动车行驶时，驾驶人、乘坐人员应当按规定使用安全带，摩托车驾驶人及乘坐人员应当按规定戴安全头盔。很明显，图中司机没有系安全带，属于违法行为。', 'https://images.juheapi.com/jztk/c1c2subject1/238.jpg'),
('239', '这样临时停放红色轿车有什么违法行为？', '3', '距离路边超过30厘米', '在有禁停标线路段停车', '距离加油站不到30米', '停车占用非机动车道', '图为加油站，规定加油站30米内不得停车。公共汽车站、急救站、加油站、消防栓或者消防队（站）门前以及距离上述地点30米以内的路段，除使用上述设施的车辆以外的车辆，不得停车。', 'https://images.juheapi.com/jztk/c1c2subject1/239.jpg'),
('240', '这个标志是何含义？', '3', '注意行人', '有人行横道', '村庄或集镇', '有小学校', '村庄：用以提醒车辆驾驶人小心驾驶。设在紧靠村庄、集镇且视线不良的路段以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/240.jpg')
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('241', '路中心黄色虚实线是何含义？', '2', '虚线一侧禁止越线', '实线一侧禁止越线', '实线一侧允许越线', '两侧均可越线行驶', '虚线可压，实线不可压。实线一侧禁止越线。', 'https://images.juheapi.com/jztk/c1c2subject1/241.jpg'),
('242', '行车中超越同向行驶的自行车时，应怎样做？', '4', '连续鸣喇叭提醒其让路', '持续鸣喇叭并加速超越', '让自行车先行', '注意观察动态，减速慢行，留有足够的安全距离', '驾驶机动车遇行人和非机动车肯定要减速慢行，否则会容易撞上，但“慢行”相对机动车的快行是慢的，而相对自行车来的速度来说还是比较快的。并且超车必须要确保安全距离（左右距离），防止与自行车相撞。', NULL),
('243', '这个标志是何含义？', '3', '水渠', '桥梁', '隧道', '涵洞', '隧道：用以提醒车辆驾驶人注意慢行。设在双向行驶并且照明不好的隧道口前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/243.jpg'),
('244', '这个标志是何含义？', '1', '高速公路入口预告', '高速公路终点预告', '高速公路起点预告', '高速公路出口预告', '高速公路入口预告：用于指示进入高速公路或城市快速路的入口，设在进入高速公路或城市快速路前的被交道路上适当位置。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/244.jpg'),
('245', '这个标志是何含义？', '4', '非机动车道', '避让非机动车', '禁止非机动车通行', '注意非机动车', '黄底标志为警告标志，自行车优势非机动车所以答案是注意非机动车。', 'https://images.juheapi.com/jztk/c1c2subject1/245.jpg'),
('246', '这个标志是何含义？', '3', '隧道入口', '气象台', '注意横风', '风向标', '注意横风：此标志设在经常有很强的侧风并有必要引起注意的路段前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/246.jpg'),
('247', '这个标志是何含义？', '3', '高速公路收费处', '高速公路检查站', '设有ETC的收费站', '高速公路领卡处', '设有ETC的收费站：用以指示前方收费站。设在高速公路、城市快速路主线上渐变段起点处。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/247.jpg'),
('248', '驾驶小型载客汽车在高速公路上时速低于100公里时的最小跟车距离是多少？', '3', '不得少于20米', '不得少于10米', '不得少于50米', '不得少于30米', '根据《中华人民共和国道路交通安全法实施条例》第八十条 机动车在高速公路上行驶，车速超过每小时100公里时，应当与同车道前车保持100米以上的距离，车速低于每小时100公里时，与同车道前车距离可以适当缩短，但最小距离不得少于50米。', NULL),
('249', '这个标志是何含义？', '3', '两侧通行', '右侧通行', '左侧通行', '不准通行', '用于引导行车方向，提示道路使用者前方线形变化，注意谨慎驾驶。设于中央隔离设施端部、渠化设施的端部、桥头等。答题技巧：∧表示俩侧通行，/这个方向的表示左侧通行，这个方向表示右侧通行。交通指路标志大全：http://www.jszks.com/onepage/16752.html', 'https://images.juheapi.com/jztk/c1c2subject1/249.jpg'),
('250', '这个路面标记是何含义？', '1', '最低限速为80公里/小时', '平均速度为80公里/小时', '最高限速为80公里/小时', '解除80公里/小时限速', '白色为最低限速，黄色为最高限速。', 'https://images.juheapi.com/jztk/c1c2subject1/250.jpg'),
('251', '这个标志是何含义？', '1', '高速公路特殊天气建议速度', '高速公路特殊天气最低速度', '高速公路特殊天气平均速度', '高速公路特殊天气最高速度', '高速公路特殊天气建议速度：用以提醒驾驶员在雨、雪、雾等特殊天气下，以建议速度行驶，和白色半圆状车距确认线配合使用。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/251.jpg'),
('252', '这个标志是何含义？', '2', '堤坝路', '傍山险路', '落石路', '临崖路', '傍山险路：用以提醒车辆驾驶人小心驾驶。设在傍山险路路段以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/252.jpg'),
('253', '这个标志是何含义？', '3', '禁止借道', '禁止变道', '禁止超车', '禁止掉头', '禁止超车：表示该标志至前方解除禁止超车标志的路段内，不准机动车超车。此标志设在禁止超车的起点。', 'https://images.juheapi.com/jztk/c1c2subject1/253.jpg'),
('254', '这个标志是何含义？', '2', '漫水桥', '渡口', '船用码头', '过水路面', '渡口：用以提醒车辆驾驶人谨慎驾驶。设在车辆渡口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/254.jpg'),
('255', '机动车在道路上发生故障，需要停车排除时，驾驶人应该怎么办？', '2', '将车停在道路中间', '将车停到不妨碍交通的地方', '开启近光灯或雾灯', '就地停车排除故障', '机动车在行驶道路上发生故障，应将机动车移至不妨碍交通的地方停放，并要在来车方向的50—100米的地方设置警示标志。', NULL),
('256', '这个标志是何含义？', '3', '高速公路里程编号', '高速公路界牌编号', '高速公路命名编号', '高速公路路段编号', '高速公路命名编号：用于指示高速公路的编号，作为指路标志的路线信息，出现在高速公路、城市快速路、一般道路指路标志版面中。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/256.jpg'),
('257', '这个标志是何含义？', '3', '低速行驶', '注意行人', '步行', '行人先行', '表示该街道只供步行。此标志设在步行街的两端。', 'https://images.juheapi.com/jztk/c1c2subject1/257.jpg'),
('258', '行车中遇到执行紧急任务的消防车、救护车、工程救险车时要及时让行。', '1', '正确', '错误', '', '', '《道路法》第五十三条第1款　警车、消防车、救护车、工程救险车执行紧急任务时，其他车辆和行人应当让行。', NULL),
('259', '驾驶机动车行经城市没有列车通过的铁路道口时允许超车。', '2', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》第四十三条：
<br/>同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：
<br/>（一）前车正在左转弯、掉头、超车的；
<br/>（二）与对面来车有会车可能的；
<br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的；
<br/>（四）行经<b>铁路道口、</b>交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。', NULL),
('260', '在道路上遇到这种情况可以从两侧超车。', '2', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》第四十三条：<br/>同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：<br/>（一）前车正在左转弯、掉头、超车的；<br/>（二）与对面来车有会车可能的；<br/><b>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的；</b><br/>（四）行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。', 'https://images.juheapi.com/jztk/c1c2subject1/260.jpg'),
('261', '在这个路口不能掉头。', '2', '正确', '错误', '', '', '此处有指示掉头的标志，而且虚线是可以临时跨越的，所以是可以掉头的。题目描述有误，因此本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/261.jpg'),
('262', '驾驶机动车在高速公路要按照限速标志标明的车速行驶。', '1', '正确', '错误', '', '', '由于高速公路上车速较快，危险性较高。为了保障安全，一定要严格按照限速标志的车速行驶。', NULL),
('263', '行车中遇儿童时，应怎样做？', '1', '减速慢行，必要时停车避让', '长鸣喇叭催促', '迅速从一侧通过', '加速绕行', '儿童的行动变化性非常大，为了保护儿童安全，一定要减速慢行，必要时停车避让。', NULL),
('264', '驾驶车辆驶入铁路道口前减速降挡，进入道口后应怎样做？', '1', '不能变换挡位', '可以变换挡位', '可换为高挡', '停车观察', '进路口前停车观望，进了就不能换挡，如果换挡不当，就会熄火，非常危险。', NULL),
('265', '驾驶车辆向右变更车道时，应提前开启右转向灯，注意观察，在确保安全的情况下，驶入要变更的车道。', '1', '正确', '错误', '', '', '向右变道时，提前开启右转向灯，是为了提示后车。同时要观察周围情况，具有变道条件时再变更车道。', NULL),
('266', '这辆停在路边的机动车没有违法行为。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第六十条：机动车在道路上发生故障或者发生交通事故，妨碍交通又难以移动的，应当按照规定开启危险报警闪光灯并在车后50米至100米处设置警告标志，夜间还应当同时开启示廓灯和后位灯。警告标志与车的距离不足50米，而且没有开启危险报警闪光灯，存在违法行为。', 'https://images.juheapi.com/jztk/c1c2subject1/266.jpg'),
('267', '车辆在拥挤路段低速行驶时，遇其他车辆强行插队，应怎样做？', '4', '鸣喇叭警告，不得进入', '加速行驶，紧跟前车，不让其进入', '挤靠“加塞”车辆，逼其离开', '主动礼让，确保行车安全', '遇到其他车辆强行插队，如果我们不礼让的话就会有发生事故的风险。做文明司机，主动礼让，确保安全。', NULL),
('268', '饮酒后驾驶机动车的一次记12分。', '1', '正确', '错误', '', '', '根据规定，<b>饮酒驾驶机动车辆，罚款1000元—2000元、记12分并暂扣驾照6个月</b>；饮酒驾驶营运机动车，罚款5000元，记12分，处以15日以下拘留，并且5年内不得重新获得驾照。醉酒驾驶机动车辆，吊销驾照，5年内不得重新获取驾照，经过判决后处以拘役，并处罚金；醉酒驾驶营运机动车辆，吊销驾照，10年内不得重新获取驾照，终生不得驾驶营运车辆，经过判决后处以拘役，并处罚金。
<br/>题目描述正确，因此答案为对。', NULL),
('269', '在一般道路倒车时，若发现有过往车辆通过，应怎样做？', '2', '鸣喇叭示意', '主动停车避让', '加速倒车', '继续倒车', '倒车时视线盲区较大，如果有意外情况无法及时处理。因此一旦后方有车辆通过，为了安全一定要停车避让。', NULL),
('270', '遇到这种情形时，应怎么办？', '1', '停车让行人先行', '从行人前方绕行', '鸣喇叭提醒行人', '从行人后方绕行', '通过人行横道应减速慢行，遇到行人则需停车让行。', 'https://images.juheapi.com/jztk/c1c2subject1/270.jpg'),
('271', '在道路上临时停车不得妨碍其他车辆和行人通行。', '1', '正确', '错误', '', '', '《道路交通安全法》第五十六条：在道路上临时停车的，不得妨碍其他车辆和行人通行。', NULL),
('272', '驾驶车辆在道路上行驶时，应当按照规定的速度安全行驶。', '1', '正确', '错误', '', '', '安全驾驶，请驾驶员按照规定的速度行驶。', NULL),
('273', '驾驶机动车驶离高速公路时，在这个位置怎样行驶？', '1', '驶入减速车道', '继续向前行驶', '车速保持100公里/小时', '车速降到40公里/小时以下', '这是高速路口出口，当要驶离高速路时，要先进入减速车道。正确操作是：提前打开右转向灯，并逐渐降低车速，不能压实线，要越过虚线进入减速车道。', 'https://images.juheapi.com/jztk/c1c2subject1/273.jpg'),
('274', '山区道路车辆进入弯道前，在对面没有来车的情况下，应怎样做？', '4', '可靠弯道外侧行驶', '可短时间借用对方的车道', '可加速沿弯道切线方向通过', '应“减速、鸣喇叭、靠右行”', '在急转弯处，应该减速慢行；鸣喇叭，靠右行，是为了提醒对面来车。总之，安全驾驶为主。', NULL),
('275', '在泥泞路上制动时,车轮易发生侧滑或甩尾，导致交通事故。', '1', '正确', '错误', '', '', '常识题，泥泞路摩擦系数低。', NULL),
('276', '驾驶人在发生交通事故后因抢救伤员变动现场时要标明位置。', '1', '正确', '错误', '', '', '《道路交通安全法》第七十条：在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场；造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。<b>因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。 </b><br/>在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜；不即行撤离现场的，应当迅速报告执勤的交通警察或者公安机关交通管理部门。 在道路上发生交通事故，仅造成轻微财产损失，并且基本事实清楚的，当事人应当先撤离现场再进行协商处理。', NULL),
('277', '驾驶机动车行经市区下列哪种道路时不得超车？', '3', '主要街道', '单向行驶路段', '交通流量大的路段', '单向两条行车道', '《中华人民共和国道路交通安全法》第四十三条：<br/>同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：<br/>（一）前车正在左转弯、掉头、超车的；<br/>（二）与对面来车有会车可能的；<br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的；<br/>（四）行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、<b>市区交通流量大的路段</b>等没有超车条件的。', NULL),
('278', '上道路行驶的机动车故意遮挡、污损、不按规定安装机动车号牌的一次记几分？', '4', '2分', '3分', '6分', '12分', '《公安部令第123号》规定，上道路行驶的机动车未悬挂机动车号牌的，<b>或者故意遮挡、污损、不按规定安装机动车号牌的，一次记12分 。</b>', NULL),
('279', '这样在路边临时停放机动车有什么违法行为？', '1', '在人行横道上停车', '距离路边超过30厘米', '在有禁停标线路段停车', '在非机动车道停车', '图中汽车停在人行横道。规定是：在设有禁停标志、标线的路段，在机动车道与非机动车道、人行道之间设有隔离设施的路段以及人行横道、施工地段，不得停车；', 'https://images.juheapi.com/jztk/c1c2subject1/279.jpg'),
('280', '这个路段可以在非机动车道上临时停车。', '2', '正确', '错误', '', '', '在设有禁停标志、标线的路段，在机动车道与非机动车道、人行道之间设有隔离设施的路段以及人行横道、施工地段，不得停车。', 'https://images.juheapi.com/jztk/c1c2subject1/280.jpg'),
('281', '变更车道时只需开启转向灯，便可迅速转向驶入相应的行车道。', '2', '正确', '错误', '', '', '<b>开转向灯后，要充分观察确认安全后方可使入车道，</b>本题错在“迅速”且没有观察。', NULL),
('282', '同车道行驶的车辆遇前车有下列哪种情形时不得超车？', '3', '正在停车', '减速让行', '正在掉头', '正常行驶', '同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：  ①《《前车正在左转弯、掉头、超车的》》;  ②与对面来车有会车可能的;  ③前车为执行紧急任务的警车、消防车、救护车、工程救险车的;  ④行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。', NULL),
('283', '驾驶机动车在高速公路遇到能见度低于50米的气象条件时，车速不得超过20公里/小时，还应怎么做？', '2', '进入应急车道行驶', '尽快驶离高速公路', '尽快在路边停车', '在路肩低速行驶', '1、能见度小于200米时，开启雾灯、近光灯、示廓灯和前后位灯，车速不得超过每小时60公里，与同车道前车保持100米以上的距离；
<br/>2、能见度小于100米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时40公里，与同车道前车保持50米以上的距离； 　　
<br/><b>3、能见度小于50米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时20公里，并从最近的出口尽快驶离高速公路。</b>', NULL),
('284', '漫水道路行车时，应挂高速档，快速通过。', '2', '正确', '错误', '', '', '不应该挂高速挡，而是要选用低速挡，以保证汽车有足够的驱动力;入水时应平稳，以防溅起的水花落入电器设备，造成电器短路；发动机中速运转，保持车速，中途不得停车、换挡和急转转向盘', NULL),
('285', '夜间车辆通过照明条件良好的路段时，应使用什么灯？', '3', '危险报警闪光灯', '远光灯', '近光灯', '雾灯', '照明条件良好，开启近光就够了。远光会影响前车和前面行人的视线，容易引发危险。', NULL),
('286', '找出这辆故障车有哪种违法行为？', '4', '没有开启危险报警闪光灯', '没有将车停到路边', '没有立即排除故障', '没有设置警告标志', '《道路交通安全法实施条例》第六十条：机动车在道路上发生故障或者发生交通事故，妨碍交通又难以移动的，应当按照规定开启危险报警闪光灯并在车后50米至100米处设置警告标志，夜间还应当同时开启示廓灯和后位灯。', 'https://images.juheapi.com/jztk/c1c2subject1/286.jpg'),
('287', '驾驶人未携带哪种证件驾驶机动车上路，交通警察可依法扣留车辆？', '1', '机动车行驶证', '从业资格证', '居民身份证', '机动车通行证', '《道路交通安全违法行为处理程序规定》第十三条 “有下列情形之一的，因无其他机动车驾驶人代替驾驶、违法行为尚未消除、需要调查或者证据保全等原因不能立即放行的，可以扣留车辆：    （一）未悬挂机动车号牌，未放置检验合格标志、保险标志，或者未携带行驶证、机动车驾驶证的；', NULL),
('288', '在这个位置时怎样使用灯光？', '2', '开启右转向灯', '开启左转向灯', '开启危险报警闪光灯', '开启前照灯', '《道路交通安全法实施条例》第七十九条：机动车从匝道驶入高速公路，<b>应当开启左转向灯</b>，在不妨碍已在高速公路内的机动车正常行驶的情况下驶入车道。', 'https://images.juheapi.com/jztk/c1c2subject1/288.jpg'),
('289', '对未放置检验合格标志上道路行驶的车辆，交通警察可依法予以扣留。', '1', '正确', '错误', '', '', '《道路交通安全法》第九十五条：上道路行驶的机动车未悬挂机动车号牌，<b>未放置检验合格标志、</b>保险标志，或者未随车携带行驶证、驾驶证的，公安机关交通管理部门应当扣留机动车，通知当事人提供相应的牌证、标志或者补办相应手续，并可以依照本法第九十条的规定予以处罚。当事人提供相应的牌证、标志或者补办相应手续的，应当及时退还机动车。故意遮挡、污损或者不按规定安装机动车号牌的，依照本法第九十条的规定予以处罚。', NULL),
('290', '行车中遇列队横过道路的学生时，应怎样做？', '2', '提前加速抢行', '停车让行', '降低车速、缓慢通过', '连续鸣喇叭催促', '列队横过道路的学生，人数多，通行时间长。降低车速还是容易撞上，停车让行更安全。', NULL),
('291', '机动车在夜间道路上发生故障难以移动时要开启危险报警闪光灯、示廓灯、后位灯。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第六十条：机动车在道路上发生故障或者发生交通事故，妨碍交通又难以移动的，应当按照规定开启<b>危险报警闪光灯</b>并在车后50米至100米处设置警告标志，夜间还应当同时开启<b>示廓灯和后位灯</b>。', NULL),
('292', '车辆驶近停在车站的公交车辆时，为预防公交车突然起步或行人从车前穿出，应怎样做？', '1', '减速，保持足够间距，随时准备停车', '保持正常车速行驶', '鸣喇叭提醒，加速通过', '随时准备紧急制动', '遇到行人，减速行驶，随时准备停车。如果紧急制动的话可能会导致后车追尾，所有选择A。', NULL),
('293', '提供虚假材料申领驾驶证的申请人会承担下列哪种法律责任？', '3', '处20元以上200元以下罚款', '取消申领驾驶证资格', '1年内不得再次申领驾驶证', '2年内不能再次申领驾驶证', '修订后的《机动车驾驶证申领和使用规定》第七十八条第一款规定：“隐瞒有关情况或者提供虚假材料申领机动车驾驶证的，申请人在一年内不得再次申领机动车驾驶证。”', NULL),
('294', '造成交通事故后逃逸构成犯罪的人不能申请机动车驾驶证。', '1', '正确', '错误', '', '', '《交通法》第一百零一条 违反道路交通安全法律、法规的规定，发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证。<br/><b>造成交通事故后逃逸的，由公安机关交通管理部门吊销机动车驾驶证，且终生不得重新取得机动车驾驶证。</b>', NULL),
('295', '车辆驶近人行横道时，应怎样做？', '3', '加速通过', '立即停车', '先减速注意观察行人、非机动车动态，确认安全后再通过', '鸣喇叭示意行人让道', '因为行人具有随意性，所以要先减速注意观察行人、非机动车动态，确认安全后再通过。', NULL),
('296', '驾驶机动车需要在路边停车时怎样选择停车地点？', '2', '靠左侧路边逆向停放', '在停车泊位内停放', '在路边随意停放', '在人行道上停放', '一般人行道上是不能停车的，路边也不能随意停车。在路边可以顺向临时停车，但是不能逆向停车。所以最佳停车地点还是停车泊位内。', NULL),
('297', '在道路上超车时，应尽量加大横向距离，必要时可越实线超车。', '2', '正确', '错误', '', '', '实线不能跨越，因此不能越实线超车，本题错误。', NULL),
('298', '距离宽度不足4米的窄路50米以内的路段不能停车。', '1', '正确', '错误', '', '', '根据《道路安全法实施条例》第六十三条，机动车在道路上临时停车应当遵守下列规定：<br/>（1）在设有禁停标志、标线的路段，在机动车道与非机动车道、人行道之间设有隔离设施的路段以及人行横道、施工地段，不得停车；<br/>（2）交叉路口、铁路道口、急转弯、<b>宽度不足4米的窄路、</b>桥梁、陡坡、隧道以及距离上述地点50米以内的路段，不得停车；<br/>（3）公共汽车站、急救站、加油站、消防栓或者消防队（站）门前以及距离上述地点30米以内的路段，除使用上述设施的以外，不得停车；<br/>（4）车辆停稳前不得开车门和上下人员，开关车门不得妨碍其他车辆和行人通行；<br/>（5）路边停车应当紧靠道路右侧，机动车驾驶人不得离车，上下人员或者装卸物品后，立即驶离；<br/>（6）城市公共汽车不得在站点以外的路段停车上下乘客。<br/>', NULL),
('299', '行车中遇到对向来车占道行驶，应怎样做？', '3', '逼对方靠右行驶', '用大灯警示对方', '主动给对方让行', '紧靠道路中心行驶', '记住文明驾驶，礼貌让行。不开赌气车，安全第一。', NULL),
('300', '距离桥梁、陡坡、隧道50米以内的路段不能停车。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第六十三条 机动车在道路上临时停车，应当遵守下列规定：交叉路口、铁路道口、急弯路、宽度不足４米的窄路、桥梁、陡坡、隧道以及距离上述地点50米以内的路段，不得停车。', NULL),
('301', '驾驶车辆在交叉路口前变更车道时，应怎样驶入要变更的车道？', '4', '在路口前实线区内根据需要', '进入路口实线区内', '在路口停止线前', '在虚线区按导向箭头指示', '实线不可跨线行驶，应该在虚线区按导向箭头指示变更车道。', NULL),
('302', '当驾驶车辆行经两侧有行人且有积水的路面时，应怎样做？', '4', '加速通过', '正常行驶', '连续鸣喇叭', '减速慢行', '文明驾驶，减速慢行，防止水溅至行人身上。', NULL),
('303', '行车中遇交通事故受伤者需要抢救时，应怎样做？', '1', '及时将伤者送医院抢救或拨打急救电话', '尽量避开，少惹麻烦', '绕过现场行驶', '借故避开现场', '伤者需要帮助，我们应及时伸出援助之手，及时送伤者去医院或拨打急救电话。', NULL),
('304', '谨慎驾驶的三原则是集中注意力、仔细观察和提前预防。', '1', '正确', '错误', '', '', '黄金原则，牢记，对我们以后驾车是有很大的帮助的。', NULL),
('305', '驾驶车辆变更车道时，应提前开启转向灯，注意观察，保持安全距离，驶入要变更的车道。', '1', '正确', '错误', '', '', '行车变道时，提前开启转向灯，是为了提示后车。同时要观察周围情况，具有变道条件时再变更车道。', NULL),
('306', '打开机动车车门时，不得妨碍其他车辆和行人通行。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第七十七条：乘坐机动车应当遵守下列规定：<br/>(一)不得在机动车道上拦乘机动车;<br/>(二)在机动车道上不得从机动车左侧上下车;<br/><b>(三)开关车门不得妨碍其他车辆和行人通行;</b><br/>(四)机动车行驶中，不得干扰驾驶，不得将身体任何部分伸出车外，不得跳车;<br/>(五)乘坐两轮摩托车应当正向骑坐。', NULL),
('307', '在这段高速公路上行驶的最低车速是多少？', '3', '100公里/小时', '80公里/小时', '60公里/小时', '50公里/小时', '红圈白底限制最高速度，蓝底限制最低速度，此路段最低车速是60公里每小时。', 'https://images.juheapi.com/jztk/c1c2subject1/307.jpg'),
('308', '驾驶人违反交通运输管理法规发生重大事故致人重伤的可能判处3年以下徒刑或拘役。', '1', '正确', '错误', '', '', '刑法第一百三十三条规定：违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；因逃逸致人死亡的，处七年以上有期徒刑。', NULL),
('309', '上道路行驶的机动车有哪种情形交通警察可依法扣留车辆？', '1', '未放置检验合格标志', '未携带身份证', '未放置城市环保标志', '未携带机动车登记证书', '未放置检验合格标志，未悬挂机动车号牌，未放置保险标志的，未携带机动车行驶证的都是可依法扣留车辆的。', NULL),
('310', '这个标志是何含义？', '1', '连续下坡', '下陡坡', '上陡坡', '连续上坡', '连续下坡：用以提醒车辆驾驶人小心驾驶。当连续下坡总长大于3 km后，应重复设置。', 'https://images.juheapi.com/jztk/c1c2subject1/310.jpg'),
('311', '驾驶人在道路上驾驶机动车追逐竞驶，情节恶劣的处3年以下有期徒刑。', '2', '正确', '错误', '', '', '道路上驾驶机动车追逐竞驶，情节恶劣的，或者在道路上醉酒驾驶机动车的，处拘役，并处罚金。不用判刑。', NULL),
('312', '行车中遇到正在进行作业的道路养护车辆、工程作业车时要注意避让。', '1', '正确', '错误', '', '', '按照规定，行车途中遇到正在进行作业的道路养护车辆、工程作业车时要注意避让。', NULL),
('313', '驾驶小型汽车下陡坡时允许熄火滑行。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第六十二条：驾驶机动车不得在下陡坡时熄火或者空挡滑行。', NULL),
('314', '在堵车的交叉路口绿灯亮时，车辆应怎样做？', '2', '可直接驶入交叉路口', '不能驶入交叉路口', '可借对向车道通过路口', '在保证安全的情况下驶入交叉路口', '前方堵车，这时进入交叉路口只能更堵。因此堵车时即便绿灯亮了，也不要驶入路口内。', NULL),
('315', '机动车发生财产损失交通事故，对应当自行撤离现场而未撤离造成交通堵塞的，可以对驾驶人处以200元罚款。', '1', '正确', '错误', '', '', '《道路交通事故处理程序规定》第十三条：对应当自行撤离现场而未撤离的，交通警察应当责令当事人撤离现场；造成交通堵塞的，对驾驶人处以200元罚款；驾驶人有其他道路交通安全违法行为的，依法一并处罚。', NULL),
('316', '这个标志是何含义？', '4', '堤坝路', '上陡坡', '连续上坡', '下陡坡', '下陡坡：用以提醒车辆驾驶人小心驾驶。', 'https://images.juheapi.com/jztk/c1c2subject1/316.jpg'),
('317', '这个标志是何含义？', '1', '注意行人', '注意儿童', '学校区域', '人行横道', '注意行人：用以警告车辆驾驶人减速慢行，注意行人。设在行人密集，或不易被驾驶员发现的人行横道线以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/317.jpg'),
('318', '女驾驶人穿高跟鞋驾驶车辆，不利于安全行车。', '1', '正确', '错误', '', '', '穿高跟鞋踩制动踏板，会受力不均，同时也不能正确感知是否将制动踩到底，容易造成事故。', NULL),
('319', '不要在驾驶室的前后窗范围内悬挂和放置妨碍驾驶人视线的物品。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第六十二条：驾驶机动车不得在机动车驾驶室的前后窗范围内悬挂、放置妨碍驾驶人视线的物品。', NULL),
('320', '车辆临时靠边停车后准备起步时，应先怎样做？', '4', '加油起步', '鸣喇叭', '提高发动机转速', '观察周围交通情况', '起步时要先观察路况，小心驾驶，安全第一。', NULL)
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('321', '驾驶人违反交通运输管理法规发生重大事故后，因逃逸致人死亡的，处多少年有期徒刑？', '4', '2年以下', '3年以下', '7年以下', '7年以上', '《中华人民共和国刑法》第一百三十三条：
<br/>违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；
<br/>交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；
<br/><b>因逃逸致人死亡的，处七年以上有期徒刑。</b>
<br/>在道路上驾驶机动车追逐竞驶，情节恶劣的，或者在道路上醉酒驾驶机动车的，处拘役，并处罚金。
<br/>有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。', NULL),
('322', '在道路与铁路道口遇到一个红灯亮时要尽快通过道口。', '2', '正确', '错误', '', '', '车辆通过设有交通信号的铁路道口时，必须遵守下列规定： 1）两个红灯交替闪烁或红灯稳定亮时，表示火车接近道口，禁止通行； 2）红灯熄灭白灯亮时，表示道口开通，准许车辆通行； 3）当红灯和白灯同时熄灭时，表示停电或者设备发生故障，道口信号无效，在这种情况下，必须听从道口看守人员和道口安全管理人员的指挥，在道口前减速或者停车，确认安全无误后迅速通行。凡遇到道口栏杆（栏门）关闭、音响器发出报警、道口信号显示红色灯光或者道口看守人员示意火车即将通过等任意一种情况时，车辆严禁抢行，必须依次停在停止线外，没有停止线的，停在距最外钢轨的5米以外，并且不得影响栏杆或者栏门的关闭。', 'https://images.juheapi.com/jztk/c1c2subject1/322.jpg'),
('323', '冰雪道路行车，由于积雪对光线的反射，极易造成驾驶人目眩而产生错觉。', '1', '正确', '错误', '', '', '因为太阳光通过冰的折射到人的眼睛里，冰在太阳光下就好像是一面镜子。所以会容易目眩而产生幻觉。', NULL),
('324', '上道路行驶的机动车有哪种情形交通警察可依法扣留车辆？', '4', '未携带机动车登记证书', '未携带保险合同', '未放置城市环保标志', '未放置保险标志', '未放置检验合格标志，未悬挂机动车号牌，未放置保险标志的，未携带机动车行驶证的都是可依法扣留车辆的。', NULL),
('325', '路口黄灯持续闪烁，警示驾驶人要注意�望，确认安全通过。', '1', '正确', '错误', '', '', '路口黄灯持续闪烁，警示驾驶人要注意�望，确认安全通过。', NULL),
('326', '这一组交通警察手势是什么信号？', '2', '左转弯信号', '左转弯待转信号', '减速慢行信号', '右转弯信号', '手势题详解：http://www.jszks.com/onepage/16203.html', 'https://images.juheapi.com/jztk/c1c2subject1/326.jpg'),
('327', '道路最左侧白色虚线区域是何含义？', '1', '多乘员车辆专用车道', '小型客车专用车道', '未载客出租车专用车道', '大型客车专用车道', '图上有字，“多乘员专用”，因此本题是多乘员车辆专用车道', 'https://images.juheapi.com/jztk/c1c2subject1/327.jpg'),
('328', '路口最前端的双白虚线是什么含义？', '3', '等候放行线', '停车让行线', '减速让行线', '左弯待转线', '<p><img src=http://tp.mnks.cn/tp_332.jpg><br/>停止线</p><p><img src=http://tp.mnks.cn/tp_333.jpg><br/>停车让行线</p><p><img src=http://tp.mnks.cn/tp_334.jpg><br/>减速让行线</p>', 'https://images.juheapi.com/jztk/c1c2subject1/328.jpg'),
('329', '这一组交通警察手势是什么信号？', '4', '右转弯信号', '靠边停车信号', '左转弯信号', '停止信号', '手势题详解：http://www.jszks.com/onepage/16203.html', 'https://images.juheapi.com/jztk/c1c2subject1/329.jpg'),
('330', '行车中在道路情况良好的条件下可以观看车载视频。', '2', '正确', '错误', '', '', '《实施条例》第六十二条，驾驶机动车不得有下列行为：
<br/>(一)在车门、车厢没有关好时行车；
<br/>(二)在机动车驾驶室的前后窗范围内悬挂、放置妨碍驾驶人视线的物品；
<br/><b>(三)拨打接听手持电话、观看电视等妨碍安全驾驶的行为；</b>
<br/>(四)下陡坡时熄火或者空挡滑行；
<br/>(五)向道路上抛撒物品；
<br/>(六)驾驶摩托车手离车把或者在车把上悬挂物品；
<br/>(七)连续驾驶机动车超过4小时未停车休息或者停车休息时间少于20分钟；
<br/>(八)在禁止鸣喇叭的区域或者路段鸣喇叭。', NULL),
('331', '驾驶人有使用其他车辆检验合格标志嫌疑的，交通警察可依法扣留车辆。', '1', '正确', '错误', '', '', '《道路交通安全违法行为处理程序规定》第二十五条规定，有下列情形之一的，依法扣留车辆：有伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、检验合格标志、 保险标志、驾驶证或者<b>使用其他车辆的机动车登记证书、号牌、行驶证、检验合格标志、保险标志嫌疑的。</b>', NULL),
('332', '驾驶人因服兵役、出国（境）等原因延期审验期间不得驾驶机动车。', '1', '正确', '错误', '', '', '第六十三条  机动车驾驶人因服兵役、出国（境）等原因，无法在规定时间内办理驾驶证期满换证、审验、提交身体条件证明的，可以向机动车驾驶证核发地车辆管理所申请延期办理。申请时应当填写申请表，并提交机动车驾驶人的身份证明、机动车驾驶证和延期事由证明。<br/>延期期限最长不超过三年。【延期期间机动车驾驶人不得驾驶机动车】。', NULL),
('333', '对使用其他车辆号牌、行驶证的车辆，交通警察可依法予以扣留。', '1', '正确', '错误', '', '', '《道路交通安全法》第九十六条：使用其他车辆的机动车登记证书、号牌、行驶证、检验合格标志、保险标志的，由公安机关交通管理部门予以收缴，扣留该机动车，处二千元以上五千元以下罚款。', NULL),
('334', '冰雪路行车时应注意什么？', '1', '制动距离延长', '抗滑能力变大', '制动性能没有变化', '路面附着力增大', '车辆在冰雪路面上行驶，<b>因汽车轮胎与路面的摩擦系数减小、附着力大大降低，</b>所以遇有冰雪路面，车辆在行驶中最重要的是车辆制动问题，要采取点刹、并和前后车保持车距离。遇情况紧急制动时，制动距离会大大延长。', NULL),
('335', '道路交通违法行为累积记分周期是多长时间？', '2', '14个月', '12个月', '6个月', '10个月', '《公安部令第123号》第五十五条：道路交通安全违法行为累积记分周期（即记分周期）为12个月，满分为12分，从机动车驾驶证初次领取之日起计算。', NULL),
('336', '驾驶人有使用其他车辆号牌、行驶证嫌疑的，交通警察可依法扣留车辆。', '1', '正确', '错误', '', '', '《道路交通安全违法行为处理程序规定》第二十五条规定，有下列情形之一的，依法扣留车辆：有伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、检验合格标志、 保险标志、驾驶证或者<b>使用其他车辆的机动车登记证书、号牌、行驶证、检验合格标志、保险标志嫌疑</b>的。', NULL),
('337', '进入减速车道时怎样使用灯光？', '4', '开启危险报警闪光灯', '开启前照灯', '开启左转向灯', '开启右转向灯', '减速车道在右侧，应该开启右转向灯提醒后车注意减速避让，然后从虚线处进入减速车道。', 'https://images.juheapi.com/jztk/c1c2subject1/337.jpg'),
('338', '在道路上跟车行驶时，跟车距离不是主要的，只须保持与前车相等的速度，即可防止发生追尾事故。', '2', '正确', '错误', '', '', '跟车时，与前车保持相同的速度，只能让两车间的距离保持不变，并不能保证安全。而保持足够的安全距离，才能有效防止追尾的发生。', NULL),
('339', '驾驶机动车时可以向道路上抛撒物品。', '2', '正确', '错误', '', '', '《实施条例》第六十二条，驾驶机动车不得有下列行为：
<br/>(一)在车门、车厢没有关好时行车；
<br/>(二)在机动车驾驶室的前后窗范围内悬挂、放置妨碍驾驶人视线的物品；
<br/>(三)拨打接听手持电话、观看电视等妨碍安全驾驶的行为；
<br/>(四)下陡坡时熄火或者空挡滑行；
<br/><b>(五)向道路上抛撒物品；</b>
<br/>(六)驾驶摩托车手离车把或者在车把上悬挂物品；
<br/>(七)连续驾驶机动车超过4小时未停车休息或者停车休息时间少于20分钟；
<br/>(八)在禁止鸣喇叭的区域或者路段鸣喇叭。', NULL),
('340', '驾驶人驾驶有达到报废标准嫌疑机动车上路的，交通警察依法予以拘留。', '2', '正确', '错误', '', '', '1、根据《中华人民共和国道路交通安全法》规定，驾驶拼装的机动车或者已达到报废标准的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废。对驾驶前款所列机动车上道路行驶的驾驶人，处200元以上2000元以下罚款，并吊销机动车驾驶证。
<br/>2、题目中表述的是“达到报废标准嫌疑机动车”，并未确定为已经报废，按规定无须处罚。
<br/>因此，题目所说的“交通警察依法予以拘留”是不正确的，本题答案应为错误。', NULL),
('341', '道路交通事故中，机动车无号牌、检验合格标志、保险标志时，要保护现场并立即报警。', '1', '正确', '错误', '', '', '《道路交通事故处理程序规定》 第八条 道路交通事故有下列情形之一的，当事人应当保护现场并立即报警： 　　<br/>（一）造成人员死亡、受伤的； 　　<br/>（二）发生财产损失事故，当事人对事实或者成因有争议的，以及虽然对事实或者成因无争议，但协商损害赔偿未达成协议的； 　　<br/>（三）<b>机动车无号牌、无检验合格标志、无保险标志的；</b> 　　<br/>（四）载运爆炸物品、易燃易爆化学物品以及毒害性、放射性、腐蚀性、传染病病源体等危险物品车辆的； 　　<br/>（五）碰撞建筑物、公共设施或者其他设施的；　　<br/>（六）驾驶人无有效机动车驾驶证的； 　　<br/>（七）驾驶人有饮酒、服用国家管制的精神药品或者麻醉药品嫌疑的； 　　<br/>（八）当事人不能自行移动车辆的。 　　<br/>发生财产损失事故，并具有前款第二项至第五项情形之一，车辆可以移动的，当事人可以在报警后，在确保安全的原则下对现场拍照或者标划停车位置，将车辆移至不妨碍交通的地点等候处理。', NULL),
('342', '对有使用伪造或变造检验合格标志嫌疑的车辆，交通警察只进行罚款处罚。', '2', '正确', '错误', '', '', '根据《中华人民共和国道路交通安全法》第九十六条规定：<br/><b>伪造、变造或者使用伪造、变造的检验合格标志、保险标志的，由公安机关交通管理部门予以收缴，扣留该机动车，处十日以下拘留，并处一千元以上三千元以下罚款；构成犯罪的，依法追究刑事责任。</b><br/>使用其他车辆的机动车登记证书、号牌、行驶证、检验合格标志、保险标志的，由公安机关交通管理部门予以收缴，扣留该机动车，处二千元以上五千元以下罚款。 当事人提供相应的合法证明或者补办相应手续的，应当及时退还机动车。', NULL),
('343', '道路交通安全违法行为累积记分一个周期满分为12分。', '1', '正确', '错误', '', '', '《公安部令第123号》第五十五条：<br/>道路交通安全违法行为累积记分周期（即记分周期）为12个月，满分为12分，从机动车驾驶证初次领取之日起计算。', NULL),
('344', '这个标志是何含义？', '3', '下陡坡', '连续上坡', '上陡坡', '堤坝路', '上陡坡：用以提醒车辆驾驶人小心驾驶。', 'https://images.juheapi.com/jztk/c1c2subject1/344.jpg'),
('345', '下雨后路面湿滑，车辆行驶中紧急制动时，容易导致什么？', '1', '发生侧滑、引发交通事故', '因视线模糊而撞车', '不被其他车辆驾驶人发现', '引起发动机熄火', '<b>下雨时路面潮湿，轮胎与路面之间的滑动摩擦因素小，相应的摩擦力也要变小。</b>所以紧急制动时，汽车轮胎停止滚动，而向前滑动。或者说滑动摩擦力不能有效减慢汽车速度，导致汽车还要向前滑出很大段距离。因此天雨路滑，宜减速行驶。', NULL),
('346', '遇到这种情形时要停车避让行人。', '1', '正确', '错误', '', '', '根据《道路交通安全法》第四十七条，机动车行经没有交通信号的道路时，遇行人横过道路，应当避让。', 'https://images.juheapi.com/jztk/c1c2subject1/346.jpg'),
('347', '驾驶机动车在道路上追逐竞驶，情节恶劣，会受到什么处罚？', '4', '处6个月徒刑', '处1年以上徒刑', '处管制，并处罚金', '处拘役，并处罚金', '根据《中华人民共和国刑法修正案（八）》规定“在道路上驾驶机动车追逐竞驶，情节恶劣的，或者在道路上醉酒驾驶机动车的，处拘役，并处罚金”。', NULL),
('348', '驾驶机动车在道路上发生交通事故要立即将车移到路边。', '2', '正确', '错误', '', '', '《道路交通安全法》第七十条：<b>在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场；</b>造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜；不即行撤离现场的，应当迅速报告执勤的交通警察或者公安机关交通管理部门。在道路上发生交通事故，仅造成轻微财产损失，并且基本事实清楚的，当事人应当先撤离现场再进行协商处理。', NULL),
('349', '上道路行驶的机动车有哪种情形交通警察可依法扣留车辆？', '1', '未悬挂机动车号牌', '未携带身份证', '未携带保险合同', '未放置城市环保标志', '未放置检验合格标志，未悬挂机动车号牌，未放置保险标志的，未携带机动车行驶证的都是可依法扣留车辆的。', NULL),
('350', '驾驶人将机动车交由什么样的人驾驶的，交通警察可依法扣留机动车驾驶证？', '3', '实习期驾驶人', '取得驾驶证的人', '驾驶证被吊销的人', '驾驶证记分达到6分的人', '六种情形下可以扣留驾驶证 新法规定，有下列情形之一的，可以扣留机动车驾驶证： (一)饮酒、醉酒后驾驶机动车的；<b>(二)机动车驾驶人将机动车交由未取得机动车驾驶证或者机动车驾驶证被吊销、暂扣的人驾驶的；</b> (三)机动车行驶超过规定时速百分之五十的； (四)驾驶拼装或者已达到报废标准的机动车的； (五)发生重大交通事故，构成犯罪的； (六)在一个记分周期内累积记分达到12分的。', NULL),
('351', '驾驶人违反交通运输管理法规发生重大事故致人死亡且逃逸的，处多少年有期徒刑？', '3', '7年以上', '3年以下', '3年以上7年以下', '10年以上', '《中华人民共和国刑法》第一百三十三条：
<br/>1、违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；
<br/>2、<b>交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；</b>
<br/>3、因逃逸致人死亡的，处七年以上有期徒刑。
<br/>
<br/>题干中所说“发生重大事故致人死亡且逃逸的”，可理解为：先发生事故致人死亡，然后逃逸（先死后逃）。结合法规，题干所描述的情况属于情节特别恶劣的交通肇事行为，并且在肇事后逃逸，因此应该处“3年以上7年以下有期徒刑”，所以选C。
<br/>
<br/>【拓展延伸】
<br/>如果肇事司机逃逸前，因交通事故已致人死亡了，死因可归结到交通事故上；
<br/>但若肇事司机逃逸后，人再死亡，死因则变成交通事故+因逃逸致其救治不及时，属于罪加一等，因此处罚更加严重。
<br/>
<br/>有个口诀可以教给大家：
<br/>先死后逃，3年以上7年以下；
<br/>先逃后死，7年以上。', NULL),
('352', '驾驶人违反交通运输管理法规发生重大事故后，因逃逸致人死亡的，处3年以上7年以下有期徒刑。', '2', '正确', '错误', '', '', '发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；<b>因逃逸致人死亡的，处七年以上有期徒刑。</b>', NULL),
('353', '小型汽车驾驶人发生交通事故造成人员死亡，承担同等以上责任未被吊销驾驶证的，应当在记分周期结束后30日内接受审验。', '1', '正确', '错误', '', '', '《机动车驾驶证申领和使用规定》（公安部令第123号）第六十条：<br/>小型汽车驾驶人发生交通事故造成人员死亡承担同等以上责任未被吊销机动车驾驶证的，应当在本记分周期结束后三十日内到公安机关交通管理部门接受审验。', NULL),
('354', '夜间驾驶车辆遇自行车对向驶来时，应怎样做？', '3', '连续变换远、近光灯', '不断鸣喇叭', '使用近光灯，减速或停车避让', '使用远光灯', '文明驾驶，礼貌让行。交替使用远近光灯可能会使对方看不清，所以最好的是减速或者停车避让。', NULL),
('355', '高速公路因发生事故造成堵塞时，可在右侧紧急停车带或路肩行驶。', '2', '正确', '错误', '', '', '紧急停车带：一般用于高速公路发生车祸等事故以后，警车、救护车、消防车等救援车辆的紧急通行车道，其他车辆除特殊情况下，严禁占用该车道行驶或长时间停车。', NULL),
('356', '对发生道路交通事故需要收集证据的事故车，交通警察可以依法扣留。', '1', '正确', '错误', '', '', '《道路交通安全违法行为处理程序规定》第二十五条规定，有下列情形之一的，依法扣留车辆：对发生道路交通事故，因收集证据需要的，可以依法扣留事故车辆。', NULL),
('357', '驾驶人违反交通运输管理法规发生重大事故使公私财产遭受重大损失的可能处3年以下徒刑或拘役。', '1', '正确', '错误', '', '', '《中华人民共和国刑法》第一百三十三条：违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役。', NULL),
('358', '这辆小轿车不能在这个位置停车。', '1', '正确', '错误', '', '', '人行横道禁止停车，因为会阻碍行人走路。', 'https://images.juheapi.com/jztk/c1c2subject1/358.jpg'),
('359', '3年内有下列哪种行为的人不得申请机动车驾驶证？', '4', '注射胰岛素', '酒醉经历', '吸烟成瘾', '注射毒品', '《机动车驾驶证申领和使用规定》第十二条：三年内有吸食、注射毒品行为或者解除强制隔离戒毒措施未满三年，或者长期服用依赖性精神药品成瘾尚未戒除的，不得申请机动车驾驶证。', NULL),
('360', '驾驶人未携带哪种证件驾驶机动车上路，交通警察可依法扣留车辆？', '1', '机动车驾驶证', '居民身份证', '机动车通行证', '从业资格证', '《道路交通安全违法行为处理程序规定》第十三条 “有下列情形之一的，因无其他机动车驾驶人代替驾驶、违法行为尚未消除、需要调查或者证据保全等原因不能立即放行的，可以扣留车辆：    （一）未悬挂机动车号牌，未放置检验合格标志、保险标志，或者未携带行驶证、机动车驾驶证的；', NULL),
('361', '对有伪造或变造号牌、行驶证嫌疑的车辆，交通警察可依法予以扣留', '1', '正确', '错误', '', '', '这个没有问题。', NULL),
('362', '车辆在路边起步后应尽快提速，并向左迅速转向驶入正常行驶道路。', '2', '正确', '错误', '', '', '需要先观察，安全才能开过去，不是一起步就迅速进入行驶道行驶，万一后面有车是很危险的，所以“迅速”是错的。', NULL),
('363', '发生交通事故造成人员受伤时，要保护现场并立即报警。', '1', '正确', '错误', '', '', '《道路交通事故处理程序规定》 第八条 道路交通事故有下列情形之一的，<b>当事人应当保护现场并立即报警：</b> 　　
<br/><b>（一）造成人员死亡、受伤的； </b>　　
<br/>（二）发生财产损失事故，当事人对事实或者成因有争议的，以及虽然对事实或者成因无争议，但协商损害赔偿未达成协议的； 　　
<br/>（三）机动车无号牌、无检验合格标志、无保险标志的； 　　
<br/>（四）载运爆炸物品、易燃易爆化学物品以及毒害性、放射性、腐蚀性、传染病病源体等危险物品车辆的； 　　
<br/>（五）碰撞建筑物、公共设施或者其他设施的；　　
<br/>（六）驾驶人无有效机动车驾驶证的； 　　
<br/>（七）驾驶人有饮酒、服用国家管制的精神药品或者麻醉药品嫌疑的； 　　
<br/>（八）当事人不能自行移动车辆的。 　　
<br/>发生财产损失事故，并具有前款第二项至第五项情形之一，车辆可以移动的，当事人可以在报警后，在确保安全的原则下对现场拍照或者标划停车位置，将车辆移至不妨碍交通的地点等候处理。', NULL),
('364', '图中圈内的锯齿状白色实线是什么标线？', '3', '导向车道线', '方向引导线', '可变导向车道线', '单向行驶线', '可变导向车道的意思就是进入该车道后有不止一个车道走向，如有的路口情况允许右转和直行（即右转和直行合并为一个车道），或者调头和左转合并为一个车道（一般用于左侧车道）。可变导向车道有着灵活性，不同于普通的车道指示线，普通的车道只要进入车道直行就是直行，左转就是左转。一般这样的车道设在交通比较复杂的路段。', 'https://images.juheapi.com/jztk/c1c2subject1/364.jpg'),
('365', '夜间行车，驾驶人的视野受限，很难观察到灯光照射区域以外的交通情况，因此要减速行驶。', '1', '正确', '错误', '', '', '晚上开车的时候受到光线暗的局限，相对观察事物的距离也就受到局限，所以视距比较短，因此很难观察到灯光照射区域以外的交通情况。为了安全考虑，减速行驶是必须的。', NULL),
('366', '车辆起步前，驾驶人应对车辆周围交通情况进行观察，确认安全时再开始起步。', '1', '正确', '错误', '', '', '起步前的第一步就是驾驶员要先观察车周围，确认安全时再开始起步。因此本题是对的。', NULL),
('367', '在交叉路口遇到这种情况享有优先通行权。', '2', '正确', '错误', '', '', '右转让左转。', 'https://images.juheapi.com/jztk/c1c2subject1/367.jpg'),
('368', '通过经常发生塌方、泥石流的山区地段，避免停车。', '1', '正确', '错误', '', '', '经常发生塌方、泥石流的都属于危险地段，所以能尽快离开就尽快离开，避免停车。', NULL),
('369', '驾驶机动车在车道减少的路口，遇到前方车辆依次停车或缓慢行驶时怎么办？', '3', '从前车右侧路肩进入路口', '从有空隙一侧进入路口', '每车道一辆依次交替驶入路口', '向左变道穿插进入路口', '《道路交通安全法实施条例》第五十三条：机动车在车道减少的路口、路段，遇有前方机动车停车排队等候或者缓慢行驶的，应当每车道一辆依次交替驶入车道减少后的路口、路段。', NULL),
('370', '这个标志是何含义？', '1', '注意野生动物', '注意牲畜', '动物公园', '开放的牧区', '这个是头鹿啊，是野生动物啊。', 'https://images.juheapi.com/jztk/c1c2subject1/370.jpg'),
('371', '立交桥上一般都是单向行驶，车辆不必减速行驶。', '2', '正确', '错误', '', '', '立交桥上车多，弯多，路窄，考虑到安全问题，还是要减速行驶。', NULL),
('372', '机动车在高速公路行驶，下列做法正确的是？', '1', '非紧急情况时不得在应急车道行驶或者停车', '可在减速车道或加速车道上超车、停车', '可在紧急停车带停车装卸货物', '可在路肩停车上下人员', '紧急车道只能在紧急情况下才能使用，非紧急情况不得占用。', NULL),
('373', '车辆在高速公路行驶时，可以仅凭感觉确认车速。', '2', '正确', '错误', '', '', '不仅是在高速行车中，任何时候都不能凭感觉去确认车速。要通过速度表确认。', NULL),
('374', '这个导向箭头是何含义？', '4', '指示禁行', '指示车道', '指示合流', '指示直行', '亲，直行哦~~', 'https://images.juheapi.com/jztk/c1c2subject1/374.jpg'),
('375', '驾驶车辆通过人行横道线时，应注意礼让行人。', '1', '正确', '错误', '', '', '安全第一，文明驾驶，礼貌让行。', NULL),
('376', '变更车道时，应开启转向灯，迅速驶入侧方车道。', '2', '正确', '错误', '', '', '<b>开启转向灯后，应该充分观察确认安全后再驶入。</b>本题错在“迅速”两字，且没有观察。', NULL),
('377', '车辆行至交叉路口，遇有转弯的车辆抢行，应怎样做？', '3', '提高车速抢先通过', '鸣喇叭抢先通过', '停车避让', '保持正常车速行驶', '如果遇有转弯的车辆抢行，一定要文明驾驶，礼貌让行。', NULL),
('378', '驾驶机动车遇有前方交叉路口交通阻塞时怎么办？', '2', '可借对向车道通过', '依次停在路口外等候', '从前车两侧穿插通过', '进入路口内等候', '《中华人民共和国道路交通安全法实施条例》第五十三条：<br/>机动车遇有前方交叉路口交通阻塞时，应当依次停在路口以外等候，不得进入路口。 所以应该选A。', NULL),
('379', '在冰雪道路上行车时，车辆的稳定性降低，加速过急时车轮极易空转或溜滑。', '1', '正确', '错误', '', '', '冰雪道路，轮胎与地面的摩擦力较小，吸附力较低，只要一加速，就比较容易打滑或者溜空。', NULL),
('380', '车辆在高速公路上行车，可以频繁地变更车道。', '2', '正确', '错误', '', '', '车辆在高速公路上行车，可以变更车道，但不可以“频繁”的变更车道。', NULL),
('381', '掉头过程中，应严格控制车速，仔细观察道路前后方情况，确认安全后方可前进或倒车。', '1', '正确', '错误', '', '', '掉头过程中，要控制好车速，仔细观察周围情况。这样能最大程度的避免掉头中发生事故。', NULL),
('382', '驾驶机动车不能进入红色叉形灯或者红色箭头灯亮的车道。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第四十条规定： 红色叉形灯或者箭头灯亮时，禁止本车道车辆通行。', NULL),
('383', '车辆转弯时应沿道路右侧行驶，不要侵占对方的车道，做到“左转转大弯，右转转小弯”。', '1', '正确', '错误', '', '', '由于<b>我国规定机动车要靠右行驶，无论在十字路口，弯路都是各行其路，所以左转弧度大，右转弧度就小。</b>右转转小弯左转转大弯，就能最大程度避免与对方来车发生碰撞。', NULL),
('384', '车辆驶离高速公路时，应当经减速车道减速后进入匝道。', '1', '正确', '错误', '', '', '下高速公路时必须在减速车道减速至60码以下才能出高速公路。', NULL),
('385', '驾驶小型载客汽车在高速公路行驶的最低车速为90公里/小时。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第七十八条：高速公路应当标明车道的行驶速度，最高车速不得超过每小时120公里，最低车速不得低于每小时60公里。', NULL),
('386', '行车中遇抢救伤员的救护车从本车道逆向驶来时，应怎样做？', '1', '靠边减速或停车让行', '占用其他车道行驶', '加速变更车道避让', '在原车道内继续行驶', '遇到正在执行任务的特种车辆，应当靠边减速或停车让行，为其让路。', NULL),
('387', '车辆通过凹凸路面时，应怎样做？', '4', '依靠惯性加速冲过', '挂空挡滑行驶过', '保持原速通过', '低速缓慢平稳通过', '遇到凹凸不平的路面，要减速缓慢通过，安全第一。', NULL),
('388', '车辆行至交叉路口时，左转弯车辆在任何时段都可以进入左弯待转区。', '2', '正确', '错误', '', '', '直行车辆放行时才可进入左转待转区。你到路口观察一下就明白了！', NULL),
('389', '驾驶小型载客汽车在高速公路上时速超过100公里时的跟车距离是多少？', '3', '保持50米以上', '保持60米以上', '保持100米以上', '保持80米以上', '《道路交通安全法实施条例》第八十条：机动车在高速公路上行驶，车速超过每小时100公里时，应当与同车道前车保持100米以上的距离，车速低于每小时100公里时，与同车道前车距离可以适当缩短，但最小距离不得少于50米。', NULL),
('390', '驾驶车辆通过无人看守的铁路道口时，应怎样做？', '3', '减速通过', '匀速通过', '一停、二看、三通过', '加速通过', '一停，是停在未到铁道前，不是停在铁路上，二看，是在铁道前观察是否有火车要经过，三通过，才是安全通过。', NULL),
('391', '遇到这种情况时，要加速从红车前变更车道。', '2', '正确', '错误', '', '', '图中车辆按照道路提示需要向左变道，所以需要减速或者停车等待左侧车道直行车辆通行完毕后变道，而不可能是加速。', 'https://images.juheapi.com/jztk/c1c2subject1/391.jpg'),
('392', '通过隧道时，不得超车。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》 第四十三条 同车道行驶的机动车，……有下列情形之一的，不得超车： <br/>（一）前车正在左转弯、掉头、超车的； <br/>（二）与对面来车有会车可能的； <br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的； <br/>（四）<b>行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。</b>', NULL),
('393', '驾驶机动车通过漫水路时要加速行驶。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第六十四条：机动车行经漫水路或者漫水桥时，应当停车察明水情，确认安全后，低速通过。', NULL),
('394', '行驶在高速公路上遇大雾视线受阻时，应当立即紧急制动停车。', '2', '正确', '错误', '', '', '<b>错在“紧急制动”上，要逐渐减速停车，</b>大雾天气视线不佳，紧急制动容易发生追尾事故，要逐渐减速停车。并且要开启危险警示灯以及雾灯。', NULL),
('395', '遇到前方车辆缓慢行驶时怎样行驶？', '1', '依次排队行驶', '占对向车道超越', '从右侧借道超越', '从两侧随意超越', '图中明显看出前方车辆较为拥堵，应该依次排队行驶，此时超车的话，容易造成交通事故。其次，左边是黄实线，不能越线超车。', 'https://images.juheapi.com/jztk/c1c2subject1/395.jpg'),
('396', '驾驶人持超过有效期的驾驶证可以在1年内驾驶机动车。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第二十八条：机动车驾驶人在机动车驾驶证丢失、损毁、超过有效期或者被依法扣留、暂扣期间以及记分达到12分的，不得驾驶机动车。', NULL),
('397', '行车中遇有非机动车准备绕过停放的车辆时，应怎样做？', '2', '鸣喇叭示意其让道', '让其先行', '紧随其后鸣喇叭', '加速绕过', '文明驾驶，礼貌让行。', NULL),
('398', '行车中超越右侧停放的车辆时，为预防其突然起步或开启车门，应怎样做？', '4', '加速通过', '长鸣喇叭', '保持正常速度行驶', '预留出横向安全距离，减速行驶', '留出安全距离、并减速，万一右侧车辆启动才有足够的空间和时间避让。', NULL),
('399', '在路口直行时,遇这种情形如何通行？', '3', '开启危险报警闪光灯通行', '直接加速直行通过', '让右方道路车辆先行', '让左方道路车辆先行', '右方的车直行，左方的车左转，左转让直行。', 'https://images.juheapi.com/jztk/c1c2subject1/399.jpg'),
('400', '驾驶机动车在没有中心线的城市道路上，最高速度不能超过每小时50公里。', '2', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第四十五条：<br/>机动车在道路上行驶不得超过限速标志、标线标明的速度。在没有限速标志、标线的道路上，机动车不得超过下列最高行驶速度：<br/><b>(一)没有道路中心线的道路，城市道路为每小时30公里，公路为每小时40公里。</b><br/>(二)同方向只有1条机动车道的道路，城市道路为每小时50公里，公路为每小时70公里。', NULL)
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('401', '这个标志是何含义？', '3', '人行横道灯', '注意行人', '注意信号灯', '交叉路口', '注意信号灯：用以警告车辆驾驶人注意前方路段设有信号灯，应依信号灯指示行车。', 'https://images.juheapi.com/jztk/c1c2subject1/401.jpg'),
('402', '行车中，遇非机动车抢行时，应怎样做？', '3', '加速通过', '鸣喇叭警告', '减速让行', '临近时突然加速', '文明驾驶，礼貌让行，注意非机动车的安全。', NULL),
('403', '车辆上坡行驶，要提前观察路况、坡道长度，及时减挡使车辆保持充足的动力。', '1', '正确', '错误', '', '', '提前观察路况可以增加行车时的预见性，及时减档保持充足的动力才能顺利上坡。低档速度慢，但是动力足，才能保证不熄火，顺利上坡。', NULL),
('404', '驾驶的车辆正在被其他车辆超越时，应怎样做？', '4', '靠道路中心行驶', '加速让路', '继续加速行驶', '减速，靠右侧行驶', '超车从左边，如果我们正在被其他车辆超车，应该靠右边减速让行。安全第一。', NULL),
('405', '在山区道路遇对向来车时，应怎样会车？', '4', '紧靠道路中心', '不减速', '加速', '减速或停车让行', '山区道路比较复杂，容易出事故，为了安全，会车时要减速或者停车让行。', NULL),
('406', '在这种情况下可以借右侧公交车道超车。', '2', '正确', '错误', '', '', '超车只能从左侧超车，并且车道内已经注明“公交车专用车道”，则此车道为公交车专用，其他车辆一般情况下不准占用。仅当发生事故、正常道路封闭有标示注明允许借用或者交警指示等特殊情况允许借道行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/406.jpg'),
('407', '驾驶机动车遇到这种桥时首先怎样办？', '3', '保持匀速通过', '尽快加速通过', '停车察明水情', '低速缓慢通过', '《道路交通安全法实施条例》第六十四条：机动车行经漫水路或者漫水桥时，应当停车察明水情，确认安全后，低速通过。', 'https://images.juheapi.com/jztk/c1c2subject1/407.jpg'),
('408', '车辆在山区道路行车下陡坡时，不得超车。', '1', '正确', '错误', '', '', '《道路交通安全法》规定，在陡坡上不得超车，掉头。', NULL),
('409', '在这条车道行驶的最高车速是多少？', '2', '100公里/小时', '90公里/小时', '120公里/小时', '110公里/小时', '高速公路上同方向有2条车道的，左侧车道的最低车速为每小时100公里。但是图中最高限度标志为90公里/小时，所以应根据标志来选择90公里/小时。', 'https://images.juheapi.com/jztk/c1c2subject1/409.jpg'),
('410', '机动车在道路上发生故障难以移动时要在车后50米以内设置警告标志。', '2', '正确', '错误', '', '', '机动车在道路上发生故障或者发生交通事故，妨碍交通又难以移动的，应当按照规定开启危险报警闪光灯并在车后50米至100米处设置警告标志，夜间还应当同时开启示廓灯和后位灯。 所以不是在50米内，应该是50米以外100米内。扩展提示：高速公路上要在车后150米外设置警告标志。', NULL),
('411', '驾驶机动车行经下列哪种路段不得超车？', '3', '主要街道', '高架路', '人行横道', '环城高速', '《中华人民共和国道路交通安全法》第四十三条：<br/>同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：<br/>（一）前车正在左转弯、掉头、超车的；<br/>（二）与对面来车有会车可能的；<br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的；<br/>（四）行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、<b>人行横道、</b>市区交通流量大的路段等没有超车条件的。', NULL),
('412', '遇有浓雾或特大雾天能见度过低，行车困难时，应怎样做？', '4', '开启前照灯，继续行驶', '开启示廓灯、雾灯，靠右行驶', '开启危险报警闪光灯，继续行驶', '开启危险报警闪光灯和雾灯，选择安全地点停车', '浓雾或特大雾天，能见度过低，此时开车属于十分危险的行为，一定要开启危险报警闪光灯和雾灯，选择安全地点停车。', NULL),
('413', '驾驶人出现下列哪种情况，不得驾驶机动车？', '3', '记分达到10分', '记分达到6分', '驾驶证丢失、损毁', '驾驶证接近有效期', '驾驶证是证明驾驶员驾驶资格的重要凭证，<b>驾驶证损毁，丢失，就相当于是无证驾驶，所以在此期间驾驶员是不能驾驶车辆的。</b>驾驶证接近有效期，应该去交通管理所去换证。驾驶证累积记分达到12分的，应该重新进行理论考试，考试通过，才能重新领回驾照。
<br/>因此本题答案应为A。', NULL),
('414', '机动车在道路边临时停车时，应怎样做？', '1', '不得逆向或并列停放', '只要出去方便，可随意停放', '可逆向停放', '可并列停放', '在路边临时停车时应遵循“不影响正常交通”的原则，因此除了要靠路边之外，还要尽可能留出空间便于其他车辆通行，因此不得逆向或并列停放。', NULL),
('415', '雨天路面湿滑，车辆制动距离增大，行车中尽量使用紧急制动减速。', '2', '正确', '错误', '', '', '因为路面比较滑，如果紧急制动（急刹车）容易造成车辆失控，最好不要紧急制动。', NULL),
('416', '遇到这种情况不能超车。', '1', '正确', '错误', '', '', '前车正在超车时，后面的车此时超车的话，肯定会导致两车相撞的，所以应该放弃超车。', 'https://images.juheapi.com/jztk/c1c2subject1/416.jpg'),
('417', '在高速公路上遇分流交通管制时，可不驶出高速公路，就地靠边停靠等待管制结束后继续前行。', '2', '正确', '错误', '', '', '高速公路上不能随便靠边停车，以免造成更大的堵塞。', NULL),
('418', '驾驶机动车在夜间超车时怎样使用灯光？', '4', '关闭前大灯', '开启远光灯', '开启雾灯', '变换远、近光灯', '《实施条例》第四十七条规定：机动车超车时，应当提前开启左转向灯、<b>变换使用远、近光灯或者鸣喇叭</b>。夜间视线不佳，应该变换使用远、近光灯提醒其他车辆。', NULL),
('419', '车辆在雪天临时停车时，应开启什么灯？', '4', '前后雾灯', '倒车灯', '前大灯', '危险报警闪光灯', '一般情况下，我们在路边临时停车，均需开启危险报警闪光灯。', NULL),
('420', '在交叉路口遇到这种情况时，要在红灯亮以前加速通过路口。', '2', '正确', '错误', '', '', '黄灯亮了，车身没越过白色停止线，所以要停车等待。', 'https://images.juheapi.com/jztk/c1c2subject1/420.jpg'),
('421', '驾驶机动车在下列哪种路段不得超车？', '4', '山区道路', '城市高架路', '城市快速路', '窄桥、弯道', '《中华人民共和国道路交通安全法》第四十三条：
<br/>同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：
<br/>（一）前车正在左转弯、掉头、超车的；
<br/>（二）与对面来车有会车可能的；
<br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的；
<br/>（四）行经铁路道口、交叉路口、<b>窄桥、弯道、</b>陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。', NULL),
('422', '行车中需要借道绕过前方障碍物，但对向来车已接近障碍物时，应怎样做？', '4', '加速提前抢过', '鸣喇叭示意对向车辆让道', '迅速占用车道，迫使对向来车停车让道', '降低速度或停车，让对向来车优先通行', '请注意看题干“对向来车已接近障碍物时”，对方的车更接近障碍物，文明礼让，对向来车优先通行。', NULL),
('423', '行经这种交通标线的路段要加速行驶。', '2', '正确', '错误', '', '', '要减速通过，白色的菱形标志就是提醒你前方接近人行横道，所以要减速防止撞到行人。', 'https://images.juheapi.com/jztk/c1c2subject1/423.jpg'),
('424', '这种情况超车时，从前车的哪一侧超越？', '3', '左右两侧均可超越', '从前车的右侧超越', '从前车的左侧超越', '从无障碍一侧超越', '超车只能从左侧超越。因为驾驶员在左边，左边超车，驾驶员能观察到相对行驶车道有无来车。而右方超车驾驶员是看不到前方是否来车或速度慢的车辆。', 'https://images.juheapi.com/jztk/c1c2subject1/424.jpg'),
('425', '遇到这种情况的路段，可以进入网状线区域内停车等候。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第五十三条：机动车在遇有前方机动车停车排队等候或者缓慢行驶时，应当依次排队，不得从前方车辆两侧穿插或者超越行驶，不得在人行横道、网状线区域内停车等候。', 'https://images.juheapi.com/jztk/c1c2subject1/425.jpg'),
('426', '进入左侧道路超车，无法保证与正常行驶前车的横向安全间距时，应怎样做？', '2', '谨慎超越', '放弃超车', '并行一段距离后再超越', '加速超越', '没有超车条件，放弃超车是最安全的行为。', NULL),
('427', '在路口这个位置时可以加速通过路口。', '2', '正确', '错误', '', '', '这是红灯信号，应该禁止通过，应停车等待绿灯，再通过。
<br/>题目描述有误，本题答案应为错误。', 'https://images.juheapi.com/jztk/c1c2subject1/427.jpg'),
('428', '车辆在山区道路跟车行驶时，应怎样做？', '1', '适当加大安全距离', '紧随前车之后', '适当减小安全距离', '尽可能寻找超车机会', '山区道路行车，要加大安全距离，发生事故时，有反应时间和反应距离。', NULL),
('429', '车辆通过学校和小区应注意观察标志标线，低速行驶，不要鸣喇叭。', '1', '正确', '错误', '', '', '<b>学校区域和居民区通常禁止鸣笛，减少噪音，</b>以免影响居民生活和学生学习。同时，这些地方人流量大，要时时留意交通状况，减速慢行。', NULL),
('430', '在高速公路上行驶感觉疲劳时，应立即停车休息。', '2', '正确', '错误', '', '', '在高速公路上行驶感觉疲困时，应该找到最近的服务区停车休息，高速不可随便停车。', NULL),
('431', '驾驶机动车在没有交通信号的路口要尽快通过。', '2', '正确', '错误', '', '', '《道路交通安全法》第四十四条：通过没有交通信号灯、交通标志、交通标线或者交通警察指挥的交叉路口时，应当减速慢行，并让行人和优先通过的车辆先行。', NULL),
('432', '车辆在较窄的山路上行驶时，如果靠山体的一方不让行，应怎样做？', '3', '鸣喇叭催其让行', '保持正常车速行驶', '提前减速或停车避让', '向左占道，谨慎驶过', '如果靠山体的一方不让行，为了保障行车安全，一定要提前减速或停车避让。', NULL),
('433', '这个路口允许车辆怎样行驶？', '2', '直行', '向右转弯', '向左转弯', '直行或向左转弯', '右转的灯是绿的，所以只能向右转弯。', 'https://images.juheapi.com/jztk/c1c2subject1/433.jpg'),
('434', '驾驶人吸食或注射毒品后驾驶机动车的，一经查获，其驾驶证将被注销。', '1', '', '', '', '', '严禁机动车驾驶员酒驾或者毒驾，驾驶人吸食或注射毒品后驾驶机动车的，一经查获，将注销其驾驶证。', NULL),
('435', '夜间行车中，前方出现弯道时，灯光照射会发生怎样的变化？', '2', '离开路面', '由路中移到路侧', '距离不变', '由高变低', '车辆在平面路上行驶，灯光距离不变；在出现一般的弯道，灯光由路中移动到路侧；上坡时，灯光由高变低；出现急弯或大坑时，灯光离开路面。', NULL),
('436', '有下列哪种违法行为的机动车驾驶人将被一次记6分？', '1', '驾驶机动车违反道路交通信号灯', '未取得校车驾驶资格驾驶校车', '驾驶与准驾车型不符的机动车', '饮酒后驾驶机动车', '《公安部令第123号》规定，驾驶机动车违反道路交通信号灯通行的，一次记6分 。', NULL),
('437', '驾驶人行车中看到注意儿童标志的时候，应怎样做？', '4', '加速行驶', '绕道行驶', '保持正常车速行驶', '谨慎选择行车速度', '看见儿童标志，需谨慎驾驶，避免伤及儿童。', NULL),
('438', '在这种路段如何行驶？', '4', '占对方道路转弯', '在弯道中心转弯', '加速鸣喇叭通过', '减速鸣喇叭示意', '《道路交通安全法实施条例》第五十九条规定：机动车在夜间通过急弯、坡路、拱桥、人行横道或者没有交通信号灯控制的路口时，应当交替使用远近光灯示意。<b>机动车驶近急弯、坡道顶端等影响安全视距的路段以及超车或者遇有紧急情况时，应当减速慢行，并鸣喇叭示意。</b>
<br/>因此，本题答案应为A。', 'https://images.juheapi.com/jztk/c1c2subject1/438.jpg'),
('439', '驾驶机动车通过没有交通信号的交叉路口怎样行驶？', '1', '减速慢行', '加速通过', '大型车先行', '左侧车辆先行', '交叉路口的车流量本来就比较大，在没有交通信号的交叉路口，更应该减速慢行，同时注意观察周围情况，确认可以通过后再通过。', NULL),
('440', '这是什么操纵装置？', '2', '空调开关', '点火开关', '雨刷开关', '灯光开关', '这个是点火装置没错。灯光开关在左手边，雨刷开关在右手边。', 'https://images.juheapi.com/jztk/c1c2subject1/440.jpg'),
('441', '高速公路上行车，如果因疏忽驶过出口，应怎样做？', '4', '立即停车', '在原地掉头', '在原地倒车驶回', '继续向前行驶，寻找下一个出口', '高速公路行车不可掉头、不可倒车，错过出口，只能继续行驶，寻找下个出口。', NULL),
('442', '遇有这种排队等候的情形怎么做？', '3', '从左侧跨越实线超越', '从两侧随意超越', '依次排队等候', '从右侧借道超越', '前方拥堵，请耐心等候。', 'https://images.juheapi.com/jztk/c1c2subject1/442.jpg'),
('443', '车辆行至急转弯处时，应减速并靠右侧行驶，防止与越过弯道中心线的对方车辆相撞。', '1', '正确', '错误', '', '', '通过急弯靠右行驶，给对向来车流出足够的行车空间，慢行能在遇到突发状况时有足够的反应时间。', NULL),
('444', '这个导向箭头是何含义？', '2', '指示直行或掉头', '指示直行或左转弯', '指示直行或向左变道', '指示向左转弯或掉头', '左或者直行', 'https://images.juheapi.com/jztk/c1c2subject1/444.jpg'),
('445', '在这种环境下通过路口如何使用灯光？', '3', '关闭远光灯', '使用危险报警闪光灯', '交替使用远近光灯', '使用远光灯', '《道路交通安全法实施条例》第五十九条：机动车在夜间通过急弯、坡路、拱桥、人行横道或者没有交通信号灯控制的路口时，应当交替使用远近光灯示意。
<br/>因此，本题答案应为D。', 'https://images.juheapi.com/jztk/c1c2subject1/445.jpg'),
('446', '这两辆车发生追尾的主要原因是什么？', '4', '前车采取制动时没看后视镜', '前车采取制动过急', '后车超车时距离前车太近', '后车未与前车保持安全距离', '因为有人行横道线，所以司机应该知道要提前减速，速度降得低了，后车要刹车就应该应该不会再追尾了。追尾都是后车的责任，因为没有保持足有的安全距离。', 'https://images.juheapi.com/jztk/c1c2subject1/446.jpg'),
('447', '造成交通事故后逃逸，尚不构成犯罪的一次记几分？', '3', '3分', '2分', '12分', '6分', '《公安部令第123号》附件2，造成交通事故后逃逸，尚不构成犯罪的，一次记12分 。', NULL),
('448', '驾驶机动车在泥泞道路行驶时，最高速度不能超过多少？', '4', '15公里/小时', '20公里/小时', '40公里/小时', '30公里/小时', '机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 <br/>（一）进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；　　 <br/>（二）掉头、转弯、下陡坡时；　　 <br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 <br/>（四）在冰雪、<b>泥泞</b>的道路上行驶时；', NULL),
('449', '机动车在高速公路上发生故障时，在来车方向50至100米处设置警告标志。', '2', '正确', '错误', '', '', '《道路交通安全法》第六十八条：机动车在高速公路上发生故障时，应当依照本法第五十二条的有关规定办理；警告标志应当设置在故障车来车方向150米以外，车上人员应当迅速转移到右侧路肩上或者应急车道内，并且迅速报警。', NULL),
('450', '车辆长时间停放时，应选择停车场停车。', '1', '正确', '错误', '', '', '路边只能临时停车，要长时间停车，应该选择停车场。以免妨碍其他车辆通行。', NULL),
('451', '夜间行车，要尽量避免超车，确需超车时，可变换远近光灯向前车示意。', '1', '正确', '错误', '', '', '只要在确保安全和不违规的情况下都可以超车。<b>变换远近灯光是为了提醒前方车辆的注意，</b>虽然只是一个动作，但对于保证安全来说却是很重要的。', NULL),
('452', '在这段道路上一定要减少鸣喇叭的频率。', '2', '正确', '错误', '', '', '右侧的标志是禁止鸣喇叭，不是“减少”，而是绝对不能鸣喇叭。', 'https://images.juheapi.com/jztk/c1c2subject1/452.jpg'),
('453', '机动车驾驶人违法驾驶造成重大交通事故构成犯罪的，依法追究什么责任？', '1', '刑事责任', '民事责任', '直接责任', '经济责任', '根据《道路交通安全法》第一百零一条规定：<b>违反道路交通安全法律、法规规定，发生重大交通事故，构成犯罪的，依法追究刑事责任，

并由公安机关交通管理部门吊销机动车驾驶证。</b>', NULL),
('454', '这个标志是何含义？', '1', '注意牲畜', '注意野生动物', '野生动物保护区', '大型畜牧场', '这个是头牛，是牲畜。', 'https://images.juheapi.com/jztk/c1c2subject1/454.jpg'),
('455', '下列哪种证件是驾驶机动车上路行驶应当随车携带？', '2', '机动车保险单', '机动车行驶证', '出厂合格证明', '机动车登记证', '《道路交通安全法》第十一条：驾驶机动车上道路行驶，应当悬挂机动车号牌，放置检验合格标志、保险标志，<b>并随车携带机动车行驶证。</b>因此本题答案应为C。', NULL),
('456', '车辆在高速公路匝道上可以停车。', '2', '正确', '错误', '', '', '按照规定：驶入确定匝道后，迅速提高车速，但不得超过规定速度，<b>在匝道上，不准超车、掉头、停车、和倒车。</b>', NULL),
('457', '车辆驶入匝道后，迅速将车速提高到每小时60公里以上。', '2', '正确', '错误', '', '', '应该是从匝道进入高速公路加速车道，在加速车道里迅速将车速提高到每小时60公里以上，而不是匝道。', NULL),
('458', '机动车发生财产损失交通事故，对应当自行撤离现场而未撤离的，交通警察不可以责令当事人撤离现场。', '2', '正确', '错误', '', '', '《道路交通事故处理程序规定》第十三条：<b>对应当自行撤离现场而未撤离的，交通警察应当责令当事人撤离现场；</b>造成交通堵塞的，对驾驶人处以200元罚款；驾驶人有其他道路交通安全违法行为的，依法一并处罚。', NULL),
('459', '雾天行车时，应及时开启什么灯？', '3', '倒车灯', '近光灯', '雾灯', '远光灯', '雾天行车应开启雾灯和危险报警闪光灯，本题选C。', NULL),
('460', '点火开关在ON位置，车用电器不能使用。', '2', '正确', '错误', '', '', 'LOCK-----（锁止），ACC------------ (断电)
<br/>ON--------（通电），START--------（起动）
<br/>点火开关在ON位置，车用电器是可以使用的。', 'https://images.juheapi.com/jztk/c1c2subject1/460.jpg'),
('461', '驾驶机动车通过窄路、窄桥时的最高速度不能超过每小时30公里。', '1', '正确', '错误', '', '', '机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 <br/>（一）进出非机动车道，通过铁路道口、急弯路、<b>窄路、窄桥时；</b>　　 <br/>（二）掉头、转弯、下陡坡时；　　 <br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 <br/>（四）在冰雪、泥泞的道路上行驶时。', NULL),
('462', '这是什么踏板？', '1', '离合器踏板', '制动踏板', '驻车制动器', '加速踏板', '这个不知如何解释，记住吧，亲，你会开车以后这个东东用的频率是相当高的。', 'https://images.juheapi.com/jztk/c1c2subject1/462.jpg'),
('463', '机动车仪表板上（如图所示）亮表示启用地板及前风窗玻璃吹风。', '1', '正确', '错误', '', '', '扇型的是前风窗，曲线向上表示前风窗玻璃吹风。箭头向下是地板出风。所以本题是对的。', 'https://images.juheapi.com/jztk/c1c2subject1/463.jpeg'),
('464', '连续降雨天气，山区公路可能会出现路肩疏松和堤坡坍塌现象，行车时应选择道路中间坚实的路面，避免靠近路边行驶。', '1', '正确', '错误', '', '', '山区公路连续降雨，如果开外侧，容易掉下悬崖，如果开内侧容易被塌方和落石砸到。<b>选择在道路中间行驶，不仅能最大程度避免意外情况的发生，当对面有车过来时，驾驶员也能第一时间观察到做出合适的应对。</b>', NULL),
('465', '驾驶车辆进入高速公路加速车道后，应尽快将车速提高到每小时多少公里以上？', '2', '50', '60', '30', '40', '高速公路加速车道最低行驶速度60公里每小时！ 《道路交通安全法实施条例》第78条规定：<b>“高速公路最高车速不得超过每小时120公里，最低车速不得低于每小时60公里。”</b>', NULL),
('466', '在路口右转弯遇同车道前车等候放行信号时如何行驶？', '1', '依次停车等候', '鸣喇叭让前车让路', '从右侧占道转弯', '从前车左侧转弯', '《道路交通安全法实施条例》第五十一条：机动车通过有交通信号灯控制的交叉路口，应当按照下列规定通行，向右转弯遇有同车道前车正在等候放行信号时，依次停车等候。', NULL),
('467', '这个标志的含义是指示此处设有室内停车场', '2', '正确', '错误', '', '', '你看那个P字上边没有遮挡，说明是露天停车场，如果P字上边有遮挡就是室内停车场了。', 'https://images.juheapi.com/jztk/c1c2subject1/467.jpg'),
('468', '车辆不得在高速公路匝道上倒车。', '1', '正确', '错误', '', '', '按照规定：驶入确定匝道后，迅速提高车速，但不得超过规定速度，在匝道上，不准超车、掉头、停车、和倒车。', NULL),
('469', '这是什么踏板？', '1', '加速踏板', '离合器踏板', '驻车制动器', '制动踏板', '加速踏板俗称油门，控制车速的。', 'https://images.juheapi.com/jztk/c1c2subject1/469.jpg'),
('470', '驾驶人在驾驶证丢失后3个月内还可以驾驶机动车。', '2', '正确', '错误', '', '', '机动车驾驶人在机动车驾驶证丢失后，不得驾驶机动车。如果驾驶人在驾驶证丢失期间开车上路，其行为虽不按“未取得机动车驾驶证”处理，但仍要受到法律的制裁，即依照“未随车携带驾驶证”的情况进行处罚。
<br/>题目描述有误，因此本题答案应为错误。', NULL),
('471', '车辆涉水后，应保持低速行驶，怎样操作制动踏板，以恢复制动效果？', '4', '持续重踏', '间断重踏', '持续轻踏', '间断轻踏', '采用间断轻踏摩擦刹车片来加热蒸发水分，恢复制动', NULL),
('472', '饮酒后驾驶机动车一次记几分？', '4', '3分', '2分', '6分', '12分', '道路交通安全违法行为记分分值：
<br/>　　一、机动车驾驶人有下列违法行为之一，<b>一次记12分：</b>
<br/>　　（一）驾驶与准驾车型不符的机动车的；
<br/>　　<b>（二）饮酒后驾驶机动车的；</b>
<br/>　　（三）驾驶营运客车（不包括公共汽车）、校车载人超过核定人数20%以上的；
<br/>　　（四）造成交通事故后逃逸，尚不构成犯罪的；
<br/>　　（五）上道路行驶的机动车未悬挂机动车号牌的，或者故意遮挡、污损、不按规定安装机动车号牌的；
<br/>　　（六）使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的；
<br/>　　（七）驾驶机动车在高速公路上倒车、逆行、穿越中央分隔带掉头的；
<br/>　　（八）驾驶营运客车在高速公路车道内停车的；
<br/>　　（九）驾驶中型以上载客载货汽车、校车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速20%以上或者在高速公路、城市快速路以外的道路上行驶超过规定时速50%以上，以及驾驶其他机动车行驶超过规定时速50%以上的；
<br/>　　（十）连续驾驶中型以上载客汽车、危险物品运输车辆超过4小时未停车休息或者停车休息时间少于20分钟的；
<br/>　　（十一）未取得校车驾驶资格驾驶校车的。
<br/>　', NULL),
('473', '在这种情况下可加速通过交叉路口。', '2', '正确', '错误', '', '', '当黄灯亮起，车身在停止线里边的，应停车等待。而且，通过交叉路口一般都要减速，确认安全再通过。
<br/>题目描述有误，本题答案应为错误。', 'https://images.juheapi.com/jztk/c1c2subject1/473.jpg'),
('474', '机动车在高速公路上发生交通事故无法正常行驶时，用救援车、清障车拖曳、牵引。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》第六十八条： 机动车在高速公路上发生故障或者交通事故，无法正常行驶的，应当由救援车、清障车拖曳、牵引。 所以本题是正确的。', NULL),
('475', '驾驶机动车在道路上向左变更车道时如何使用灯光？', '3', '提前开启右转向灯', '不用开启转向灯', '提前开启左转向灯', '提前开启近光灯', '《道路交通安全法实施条例》第五十七条,机动车应当按照下列规定使用转向灯：
<br/><b>(一)向左转弯、向左变更车道、准备超车、驶离停车地点或者掉头时，应当提前开启左转向灯；</b>
<br/> (二)向右转弯、向右变更车道、超车完毕驶回原车道、靠路边停车时，应当提前开启右转向灯。
<br/>根据规定，向左变更车道应该<b>提前开启左转向灯</b>，选项C符合规定，因此本题答案为C。', NULL),
('476', '驾驶人在观察后方无来车的情况下，未开转向灯就变更车道也是合理的。', '2', '正确', '错误', '', '', '这是错误的行车方法，<b>不论在何种情况下变更车道或者转弯，都必须开启转向灯，安全第一。</b>', NULL),
('477', '这是什么操纵装置？', '4', '倒车灯开关', '刮水器开关', '危险报警闪光灯开关', '灯光、信号组合开关', '左手边控制灯光、信号组合开关，右手边控制刮水器开关。', 'https://images.juheapi.com/jztk/c1c2subject1/477.jpg'),
('478', '车辆在冰雪路面紧急制动易产生侧滑，应低速行驶，可利用发动机制动进行减速。', '1', '正确', '错误', '', '', '发动机制动有三个显著特点：一是由于差速器的作用，可将制动力矩平均地分配在左右车轮上，减少侧滑、甩尾的可能性；二是有效地减少脚制动的使用频率，避免因长时间使用制动器，导致制动器摩擦片的温度升高，使制动力下降，甚至失去作用；<b>三是车速始终被限定在一定范围内，有利于及时降速或停车，确保行车安全。</b>
<br/>因此在冰雪路面上，应该尽可能选择发动机制动减速。', NULL),
('479', '上路行驶的机动车未放置检验合格标志的, 交通警察可依法扣留机动车。', '1', '正确', '错误', '', '', '没有问题，记住吧。', NULL),
('480', '上路行驶的机动车未随车携带身份证的，交通警察可依法扣留机动车。', '2', '正确', '错误', '', '', '《道路交通安全法》第九十五条规定：上道路行驶的机动车未悬挂机动车号牌，未放置检验合格标志、保险标志，或者未随车携带行驶证、驾驶证的，公安机关交通管理部门应当扣留机动车。
<br/>不携带身份证的话，是不会被扣留车辆的。', NULL)
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('481', '机动车驾驶人初次申领驾驶证后的实习期是多长时间？', '3', '18个月', '16个月', '12个月', '6个月', '《公安部令第123号》第六十四条规定：机动车驾驶人初次申请机动车驾驶证和增加准驾车型后的12个月为实习期。', NULL),
('482', '机动车仪表板上（如图所示）一直亮表示什么？', '4', '安全气囊处于工作状态', '安全带没有系好', '防抱死制动系统故障', '安全气囊处于故障状态', '圆球表示安全气囊，黄色表示处于故障状态。所以该标志亮就表示安全气囊出现故障。', 'https://images.juheapi.com/jztk/c1c2subject1/482.jpeg'),
('483', '机动车在发生碰撞时，安全带可以减轻驾乘人员伤害。', '1', '正确', '错误', '', '', '安全带加上安全气囊的双重保护才能充分发挥作用。', NULL),
('484', '机动车仪表板上（如图所示）亮，表示行车制动系统可能出现故障。', '1', '正确', '错误', '', '', '圆圈里面是“P” 表示驻车制动器处于制动状态，即手刹没松开，但是车辆没有发生故障。<br/>里面是“！” 表示制动系统异常或故障。', 'https://images.juheapi.com/jztk/c1c2subject1/484.jpeg'),
('485', '驾驶这种机动车上路行驶没有违法行为。', '2', '正确', '错误', '', '', '《公安部令第123号》规定，上道路行驶的机动车未悬挂机动车号牌的，或者<b>故意遮挡、污损</b>、不按规定安装机动车号牌的，一次记12分 。图中车辆很明显遮挡住了车号牌，属于违法行为。本题表述有误，因此本题答案应为错误。', 'https://images.juheapi.com/jztk/c1c2subject1/485.jpg'),
('486', '这个标志的含义是表示车辆会车时，对方车辆应停车让行。', '2', '正确', '错误', '', '', '此为<b>会车让行标志</b>，表示车辆会车时，面对标志的车辆必须停车让对方车辆先行。题目描述有误，因此本题答案为错。
<br/>
<br/>【拓展延伸】
<br/><p><img src=http://tp.mnks.cn/tp_176.jpg>
<br/>停车让行</p><p><img src=http://tp.mnks.cn/tp_178.jpg>
<br/>会车让行</p><p><img src=http://tp.mnks.cn/tp_219.jpg>
<br/>会车先行</p>', 'https://images.juheapi.com/jztk/c1c2subject1/486.jpg'),
('487', '在没有中心线的道路上发现后车发出超车信号时，如果条件许可如何行驶？', '3', '保持原状态行驶', '加速行驶', '降速靠右让路', '迅速停车让行', '如果迅速停车的话，会很容易追尾，降速靠右让路是因为超车规定要在左侧超越。安全文明驾驶原则，后车条件许可超车，前车那就减速靠右行驶。', NULL),
('488', '拼装的机动车只要认为安全就可以上路行驶。', '2', '正确', '错误', '', '', '《道路交通安全法》第一百条规定：驾驶拼装的机动车或者已达到报废标准的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废，处200元以上2000元以下罚款，并吊销机动车驾驶证。
<br/>无论司机认为拼装车是否安全，都不能开上路，一旦开上路就是违法行为。本题描述有误，因此本题答案应为错误。', NULL),
('489', '对驾驶拼装机动车上路行驶的驾驶人，会受到下列哪种处罚？', '2', '依法追究刑事责任', '处200以上2000元以下罚款', '吊销机动车行驶证', '处15日以下拘留', '根据《中华人民共和国道路交通安全法》规定，驾驶拼装的机动车或者已达到报废标准的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废。<b>对驾驶前款所列机动车上道路行驶的驾驶人，处200元以上2000元以下罚款，并吊销机动车驾驶证。</b>选项中只有C项符合规定，因此本题答案为C。
<br/>
<br/>【拓展延伸】
<br/>本题很多学员容易选择“D、吊销机动车行驶证”，注意上面的法规说明是［<b>吊销驾驶证</b>］不是“行驶证”。', NULL),
('490', '未取得驾驶证的学员在道路上学习驾驶技能，下列哪种做法是正确的？', '1', '使用所学车型的教练车由教练员随车指导', '使用所学车型的教练车单独驾驶学习', '使用所学车型的教练车由非教练员的驾驶人随车指导', '使用私家车由教练员随车指导', '《公安部令第123号》规定：未取得驾驶证的学员在道路上学习驾驶技能，使用所学车型的教练车由教练员随车指导。', NULL),
('491', '对违法驾驶发生重大交通事故且构成犯罪的，不追究其刑事责任。', '2', '正确', '错误', '', '', '《道路交通安全法》第一百零一条规定：违反道路交通安全法律、法规的规定，发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证。', NULL),
('492', '机动车仪表板上（如图所示)亮，提示两侧车门未关闭。', '1', '正确', '错误', '', '', '看标志两侧的门是打开的状态，如果该灯亮了，就是提醒司机车门是打开的状态。', 'https://images.juheapi.com/jztk/c1c2subject1/492.jpeg'),
('493', '驾驶人在行车中经过积水路面时，应怎样做？', '1', '减速慢行', '保持正常车速通过', '空挡滑行通过', '加速通过', '行车中经过积水路面时，应特别留意减速慢行；<b>加速或保持正常车速通过，溅起的水花会冲击前挡风玻璃，阻挡驾驶员的视线，</b>无法观察前方情况，极易导致车辆失控或交通事故。另外，驾驶车辆行经两侧有行人或非机动车行驶且有积水的路面时，更应减速慢行，<b>以免泥水飞溅到行人或非机动车驾驶员身上。</b>', NULL),
('494', '旋转开关这一档控制机动车哪个部位？', '2', '近光灯', '前后雾灯', '远光灯', '左右转向灯', '此处为雾灯的控制。下边的控制前雾灯，上边的控制后雾灯。', 'https://images.juheapi.com/jztk/c1c2subject1/494.jpg'),
('495', '驾驶机动车在冰雪道路行驶时，最高速度不能超过多少？', '3', '50公里/小时', '40公里/小时', '30公里/小时', '20公里/小时', '机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 <br/>（一）进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；　　 <br/>（二）掉头、转弯、下陡坡时；　　 <br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 <br/>（四）在<b>冰雪</b>、泥泞的道路上行驶时；', NULL),
('496', '开启危险报警闪光灯时，（如图所示）闪烁。', '1', '正确', '错误', '', '', '此标记为危险报警闪烁灯的标记，开启危险报警闪烁灯，此标志闪烁。', 'https://images.juheapi.com/jztk/c1c2subject1/496.jpeg'),
('497', '这辆在高速公路上临时停放的故障车，警告标志应该设置在车后多远处？', '1', '150米以外', '50～150米', '50米以内', '50～100米', '《道路交通安全法》第六十八条：机动车在高速公路上发生故障时，应当依照本法第五十二条的有关规定办理；但是，警告标志应当设置在故障车来车方向一百五十米以外，车上人员应当迅速转移到右侧路肩上或者应急车道内，并且迅速报警。', 'https://images.juheapi.com/jztk/c1c2subject1/497.jpg'),
('498', '机动车在紧急制动时ABS系统会起到什么作用？', '4', '切断动力输出', '自动控制方向', '减轻制动惯性', '防止车轮抱死', 'ABS防抱死系统；车轮不卡死、硬化路面制动时间短平稳、可以用力踩制动、系统自动张合8次/每秒。', 'https://images.juheapi.com/jztk/c1c2subject1/498.jpg'),
('499', '夜间驾驶人对事物的观察能力明显比白天差，视距变短。', '1', '正确', '错误', '', '', '白天开车的时候由于光线比较充足，所以观察事物的范围比较广，观察事物的视线距离相对也就比较大，<b>而在晚上受到光线暗的局限，相对观察事物的距离也就受到局限，所以视距比较短。</b>', NULL),
('500', '机动车仪表板上（如图所示）亮表示什么？', '4', '迎面出风', '空气外循环', '风窗玻璃除霜', '空气内循环', '此为空气内循环，当箭头是从车外进来的就是空气外循环。', 'https://images.juheapi.com/jztk/c1c2subject1/500.jpeg'),
('501', '机动车行驶证灭失、丢失，机动车所有人要向登记地车辆管理所申请补领、换领。', '1', '正确', '错误', '', '', '机动车号牌、行驶证灭失、丢失或者损毁的，机动车所有人应当向登记地车辆管理所申请补领、换领。申请时，机动车所有人应当填写申请表并提交身份证明。', NULL),
('502', '驾驶拼装机动车上路行驶的驾驶人，除按规定接受罚款外，还要受到哪种处理？', '2', '暂扣驾驶证', '吊销驾驶证', '追究刑事责任', '处10日以下拘留', '根据《中华人民共和国道路交通安全法》的规定，对驾驶拼装的机动车或已达到报废标准的机动车上路行驶的驾驶人，处200元以上2000元以下罚款，并吊销机动车驾驶证，对车辆予以收缴，强制报废。', NULL),
('503', '在山区冰雪道路上行车，遇有前车正在爬坡时，后车应怎样做？', '3', '低速爬坡', '紧随其后爬坡', '选择适当地点停车，等前车通过后再爬坡', '迅速超越前车', '冰雪路面很滑，正在爬坡的车可能会后溜，最安全的做法是选择安全地点停车，等前车通过后再爬坡。这样能避免发生意外事故时两车相撞的可能。', NULL),
('504', '机动车仪表板上（如图所示）亮时表示什么？', '3', '已开启前雾灯', '已开启前照灯近光', '已开启前照灯远光', '已开启后雾灯', '远光灯的灯光走向是直的。近光灯的灯光走向是朝下的。', 'https://images.juheapi.com/jztk/c1c2subject1/504.jpeg'),
('505', '浓雾天气能见度低，开启远光灯会提高能见度。', '2', '正确', '错误', '', '', '不能开启远光灯，因浓雾会反射灯光。应开启雾灯。', NULL),
('506', '机动车仪表板上（如图所示）亮表示什么？', '3', '驻车制动解除', '行车制动器失效', '制动系统出现异常', '制动踏板没回位', '可能出现故障仪表板上的图标才会亮。', 'https://images.juheapi.com/jztk/c1c2subject1/506.jpeg'),
('507', '驾驶机动车在道路上违反道路交通安全法的行为，属于什么行为？', '4', '过失行为', '违规行为', '违章行为', '违法行为', '题干中明确表述“违反道路交通安全法”，因此该行为属于违法行为。', NULL),
('508', '驾驶机动车在道路上超车时可以不使用转向灯。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例实施条例》第五十七条 机动车应当按照下列规定使用转向灯：<b>（一）向左转弯、向左变更车道、准备超车、驶离停车地点或者掉头时，应当提前开启左转向灯；</b>（二）向右转弯、向右变更车道、超车完毕驶回原车道、靠路边停车时，应当提前开启右转向灯。
<br/>超车必须使用转向灯，否则极易造成严重的交通事故。题目描述有误，本题答案应为错误。', NULL),
('509', '车辆应靠高速公路右侧的路肩上行驶。', '2', '正确', '错误', '', '', '路肩通常是让有事故的车辆停靠维修的，如果车辆没有问题的话不能在路肩上行驶。', NULL),
('510', '危险报警闪光灯可用于下列什么场合？', '3', '遇到道路拥堵时', '在道路上跟车行驶时', '机动车发生故障停车时', '引领后车行驶时', '危险报警闪光灯是一种提醒其他车辆与行人注意本车发生了特殊情况的信号灯。因此当机动车发生故障停车时，可以使用危险报警闪光灯。', NULL),
('511', '装有ABS系统的机动车在冰雪路面上会最大限度缩短制动距离。', '2', '正确', '错误', '', '', '我们要知道，采用ABS系统的机动车，可以在滚动、抱死两种状态中间不断切换，让轮胎尽量保持最大静摩擦力，也能让轮胎防滑部分充分发挥效用。
<br/>ABS系统的作用不是缩短制动距离，题目描述有误，因此本题答案错误。', NULL),
('512', '（如图所示）这个符号的开关控制什么装置？', '4', '前风窗玻璃除霜', '后风窗玻璃刮水器', '后风窗玻璃除霜', '前风窗玻璃刮水器', '此为前风窗玻璃刮水器。关于如何区分前风窗玻璃刮水器及洗涤器和后风窗玻璃刮水器及洗涤器，你只需记住一点半弧形的图标是前风窗，四四方方的图标就是后风窗。', 'https://images.juheapi.com/jztk/c1c2subject1/512.jpeg'),
('513', '夜间行车，遇对面来车未关闭远光灯时，应减速行驶，以防两车灯光的交汇处有行人通过时发生事故。', '1', '正确', '错误', '', '', '灯光刺行人眼看不清会发生事故。因此本题是对的。', NULL),
('514', '这是什么踏板？', '3', '离合器踏板', '加速踏板', '制动踏板', '驻车制动器', '制动踏板俗称刹车。', 'https://images.juheapi.com/jztk/c1c2subject1/514.jpg'),
('515', '开启前照灯近光时仪表板上（如图所示）亮起。', '2', '正确', '错误', '', '', '<p><img src=http://tp.mnks.cn/tp_387.jpg>
<br/>前照远光灯</p>
<br/><p><img src=http://tp.mnks.cn/tp_388.jpg>
<br/>前照近光灯</p>', 'https://images.juheapi.com/jztk/c1c2subject1/515.jpeg'),
('516', '夜间通过无交通信号灯控制的交叉路口时，不得变换远、近光灯。', '2', '正确', '错误', '', '', '换远近光灯是为了让来车认识到前方有车，应注意减速慢行注意安全。', NULL),
('517', '驾驶机动车通过急弯路时，最高速度不能超过多少？', '2', '20公里/小时', '30公里/小时', '40公里/小时', '50公里/小时', '机动车行驶中遇有下列情形之一的，<b>最高行驶速度不得超过每小时30公里</b>，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 
<br/>（一）进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；　　 
<br/>（二）掉头、转弯、下陡坡时；　　 
<br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 
<br/>（四）在冰雪、泥泞的道路上行驶时；', NULL),
('518', '这是什么操纵装置？', '3', '驻车制动器操纵杆', '节气门操纵杆', '变速器操纵杆', '离合器操纵杆', '变速器操纵杆也就是换挡的，当我们速度越开越快的时候也要对应上相应的档位，故此为变速器操纵杆。', 'https://images.juheapi.com/jztk/c1c2subject1/518.jpg'),
('519', '雾天行车多使用喇叭可引起对方注意；听到对方车辆鸣喇叭，也应鸣喇叭回应。', '1', '正确', '错误', '', '', '雾天视线不佳，喇叭可当做一种信号和其他车辆交流，有利于安全行车。', NULL),
('520', '机动车仪表板上（如图所示）亮表示什么？', '1', '后雾灯打开', '前照灯近光打开', '前照灯远光打开', '前雾灯打开', '前雾灯朝左，后雾灯朝右。', 'https://images.juheapi.com/jztk/c1c2subject1/520.jpeg'),
('521', '驾驶机动车通过铁路道口时，最高速度不能超过多少？', '3', '15公里/小时', '20公里/小时', '30公里/小时', '40公里/小时', '机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 
<br/>（一）进出非机动车道，<b>通过铁路道口</b>、急弯路、窄路、窄桥时；　　 
<br/>（二）掉头、转弯、下陡坡时；　　 
<br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 
<br/>（四）在冰雪、泥泞的道路上行驶时；', NULL),
('522', '未上坡的车辆遇到这种情况让对向下坡车先行。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第四十八条： 在狭窄的坡路，上坡的一方先行；但下坡的一方已行至中途而上坡的一方未上坡时，下坡的一方先行。图中下坡的车已经到了中途，可以先行。', 'https://images.juheapi.com/jztk/c1c2subject1/522.jpg'),
('523', '这个标志的含义是告示前方是塌方路段，车辆应绕道行驶。', '2', '正确', '错误', '', '', '<b>图中是 [施工路段] 标志。</b>用以告示前方道路施工，车辆应减速慢行或绕道行驶。该标志可以作为临时标志支设在施工路段以前适当位置。题目描述有误，因此本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/523.jpg'),
('524', '驾驶机动车在下列哪种情形下不能超越前车？', '2', '前车减速让行', '前车正在左转弯', '前车靠边停车', '前车正在右转弯', '《道路交通安全法》第四十三条： <br/>同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车： <br/><b>（一）前车正在左转弯、掉头、超车的； </b><br/>（二）与对面来车有会车可能的； <br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的； <br/>（四）行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。', NULL),
('525', '机动车发生碰撞时座椅安全带主要作用是什么？', '3', '保护驾乘人员颈部', '保护驾乘人员胸部', '减轻驾乘人员伤害', '保护驾乘人员腰部', '安全带在紧急情况下，可以迅速拉紧把人束缚在座椅上，保证安全。可以减轻对驾乘人员的伤害。', NULL),
('526', '在路口遇有交通信号灯和交通警察指挥不一致时，按照交通信号灯通行。', '2', '正确', '错误', '', '', '《道路交通安全法》第三十八条：车辆、行人应当按照交通信号通行；<b>遇有交通警察现场指挥时，应当按照交通警察的指挥通行；</b>在没有交通信号的道路上，应当在确保安全、畅通的原则下通行。
<br/>题目描述有误，本题答案应为错误。', NULL),
('527', '驾驶机动车在没有中心线的公路上，最高速度不能超过每小时70公里。', '2', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第四十五条：<br/>机动车在道路上行驶不得超过限速标志、标线标明的速度。在没有限速标志、标线的道路上，机动车不得超过下列最高行驶速度：<br/><b>(一)没有道路中心线的道路，城市道路为每小时30公里，公路为每小时40公里；</b><br/>(二)同方向只有1条机动车道的道路，城市道路为每小时50公里，公路为每小时70公里。', NULL),
('528', '这种握转向盘的动作是正确的。', '2', '正确', '错误', '', '', '正确的握法是握住方向盘的两边，分别在10点和4点位置，左手为主右手为辅。题中的握法是驾驶的陋习，是有很大的风险的。', 'https://images.juheapi.com/jztk/c1c2subject1/528.jpg'),
('529', '车辆下坡行驶，要适当控制车速，充分利用发动机进行制动。', '1', '正确', '错误', '', '', '下坡时不能空挡滑行，应充分利用发动机制动。防止下坡时刹车发生打滑，所以应该利用发动机制动。', NULL),
('530', '驾驶有ABS系统的机动车在紧急制动的同时转向可能会发生侧滑。', '1', '正确', '错误', '', '', 'ABS防抱死系统；车轮不卡死、硬化路面制动时间短平稳、可以用力踩制动、系统自动张合8次/每秒。', NULL),
('531', '驾驶机动车在道路上违反道路通行规定应当接受相应的处罚。', '1', '正确', '错误', '', '', '违反道路通行规定应该接受相应处罚，以提高司机的安全行车意识，避免类似情况再次发生。', NULL),
('532', '机动车驾驶人造成事故后逃逸构成犯罪的，吊销驾驶证且多长时间不得重新取得驾驶证？', '4', '5年内', '10年内', '20年内', '终生', '《道路交通安全法》第一百零一条规定：<b>造成交通事故后逃逸的且构成犯罪的，由公安机关交通管理部门吊销机动车驾驶证，且终生不得重新取得机动车驾驶证。</b>上述规定泛指各类交通事故，只要是造成交通事故后逃逸的，就应当由公安机关交通管理部门吊销其机动车驾驶证，并且终身不得重新取得驾驶证，而不论其造成交通事故后果的大小。也就是说，法律规定惩罚的交通肇事逃逸行为，与驾驶人造成交通事故后果的轻重无关；构成犯罪的，依法追究刑事责任。', NULL),
('533', '伪造、变造机动车驾驶证构成犯罪的将被依法追究刑事责任。', '1', '正确', '错误', '', '', '《道路交通安全法》第九十六条：伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、驾驶证的，由公安机关交通管理部门予以收缴，扣留该机动车，处十五日以下拘留，并处二千元以上五千元以下罚款；<b>构成犯罪的，依法追究刑事责任。</b>', NULL),
('534', '准驾车型为小型自动挡汽车的，可以驾驶低速载货汽车。', '2', '正确', '错误', '', '', '小型自动挡汽车（C2）准驾车型：小型、微型自动挡载客汽车以及轻型、微型自动挡载货汽车。', NULL),
('535', '在暴雨天气驾车，刮水器无法刮净雨水时，应怎样做？', '2', '集中注意力谨慎驾驶', '立即减速靠边停车', '以正常速度行驶', '减速行驶', '暴雨天气驾车，刮水器无法刮净雨水的话，司机很难完全看清楚路况，十分危险。为了安全起见，一定要立即减速靠边停车，不能再继续向前行驶。选项C符合要求，因此答案选C。
<br/>
<br/>【拓展延伸】
<br/>发生这种情况后，司机绝不能继续向前开，“A减速行驶”、“B集中注意力谨慎驾驶”、“D以正常速度行驶”都包含了继续行驶的意思，是错误的。
<br/>而很多人会认为C项“立即”是错误的，可以这样理解：<b>立即减速靠边停车≠紧急制动</b>，是说司机意识到危险情况后，立即采取了减速并靠边停车这样的应对措施。是没有问题的，注意审题。', NULL),
('536', '在冰雪路面上行车，必须降低车速、加大安全距离。', '1', '正确', '错误', '', '', '冰雪路面行驶时，路面滑摩擦系数小，制动距离比平时要大。因此要考虑到紧急状况。如果出现紧急情况，需要有足够的制动距离。', NULL),
('537', '安装防抱死制动装置（ABS）的机动车制动时，制动距离会大大缩短，因此不必保持安全车距。', '2', '正确', '错误', '', '', 'ABS防抱死系统；车轮不卡死、硬化路面制动时间短平稳、可以用力踩制动、系统自动张合8次/每秒。', NULL),
('538', '如图所示，A车在此时进入左侧车道是因为进入实线区不得变更车道。', '1', '正确', '错误', '', '', '实线是不能跨越的，虚线可以跨越，如果车辆想要变道，需要在虚线处变道。题目描述无误，因此本题答案为对。', 'https://images.juheapi.com/jztk/c1c2subject1/538.jpg'),
('539', '（如图所示）这个符号的开关控制什么装置？', '3', '两侧车窗玻璃', '电动车门', '车门锁住开锁', '儿童安全锁', '你看那个长的多像一把钥匙，所以是车门锁住开锁。', 'https://images.juheapi.com/jztk/c1c2subject1/539.jpeg'),
('540', '风、雨、雪、雾等复杂气象条件，遇前车速度较低时，应开启前照灯，连续鸣喇叭迅速超越。', '2', '正确', '错误', '', '', '复杂天气下超车十分危险，为了道路安全最好不要超车。应该选择合适地点减速停车。', NULL),
('541', '对未取得驾驶证驾驶机动车的，追究其法律责任。', '1', '正确', '错误', '', '', '《道路交通安全法》第九十九条规定：<b>未取得机动车驾驶证、</b>机动车驾驶证被吊销或者机动车驾驶证被暂扣期间驾驶机动车的，由公安机关交通管理部门处二百元以上二千元以下罚款，可以并处十五日以下拘留。', NULL),
('542', '上下搬动这个开关前风窗玻璃刮水器开始工作。', '1', '正确', '错误', '', '', '正确，这个没问题，左侧的开关是管灯光的，右侧的开关是管雨刷的。', 'https://images.juheapi.com/jztk/c1c2subject1/542.jpg'),
('543', '机动车仪表板上（如图所示）亮表示什么？', '1', '左转向指示灯闪烁', '车前后示宽灯亮起', '车前后位置灯亮起', '右转向指示灯闪烁', '这个没有问题吧。。。老衲也不知如何解释这个题。', 'https://images.juheapi.com/jztk/c1c2subject1/543.jpeg'),
('544', '驾驶机动车上道路行驶,不允许超过限速标志标明的最高时速。', '1', '正确', '错误', '', '', '这个没问题，按照标志行驶不会错。', NULL),
('545', '正面安全气囊与什么配合才能充分发挥保护作用？', '2', '防抱死制动系统', '座椅安全带', '座椅安全头枕', '安全玻璃', '安全气囊和安全带一起使用，起到有效的保护措施，不使用安全带是起不到作用的。', 'https://images.juheapi.com/jztk/c1c2subject1/545.jpg'),
('546', '通过漫水路时要谨慎慢行，不得空挡滑行。', '1', '正确', '错误', '', '', '机动车行经漫水桥路段时，应当停车察明水情，确认安全后，低速通过。空档滑行十分危险。', NULL),
('547', '如图所示，这个标志设置在有人看守的铁路道口，提示驾驶人距有人看守的铁路道口的距离还有100米。', '2', '正确', '错误', '', '', '无人看守的铁道路口：用来警告车辆驾驶人注意慢行或及时停车，设在<b>无人看守</b>的铁道路口以前适当位置。火车头是无人指守，栅栏是有人看守。红色的斜线，一条表示50米，2条100米，3条150米。', 'https://images.juheapi.com/jztk/c1c2subject1/547.jpg'),
('548', '初次申领的机动车驾驶证的有效期为4年。', '2', '正确', '错误', '', '', '根据规定，初次取得驾驶证的有效期是六年，在六年有效期里的每个记分周期未达到12分的换发十年有效期驾驶证，在十年有效期里的每个记分周期未达到12分的换发长期驾驶证。', NULL),
('549', '如图所示，在同向三车道高速公路上行车，车速每小时115公里应在哪条行车道上行驶？', '1', '最左侧行车道', '中间行车道', '最右侧行车道', '哪条都行', '如图上面的绿色标志，左侧限速在100-120，中间是80-100，右侧是60-80，车速每小时115公里，应该在左侧车道。', 'https://images.juheapi.com/jztk/c1c2subject1/549.jpg'),
('550', '如图所示，在这种情况下不能够超车的原因是什么？', '4', '前车速度过快', '我方车速不足以超越前车', '路中心为黄线', '前车正在超车', '按照规定，当前方车辆正在超车时，为了行车安全，驾驶员应该主动放弃超车。而图中蓝色车辆很明显在超车，因此选择D。', 'https://images.juheapi.com/jztk/c1c2subject1/550.jpg'),
('551', '交通肇事致一人以上重伤，负事故全部或者主要责任，并具有下列哪种行为的，构成交通肇事罪?', '3', '未带驾驶证', '未报警', '为逃避法律追究逃离事故现场的', '未抢救受伤人员', '根据规定，交通肇事致一人以上重伤，负事故全部责任或者主要责任，为逃避法律追究逃离事故现场的，以交通肇事罪定罪处罚，在这种情形下不能再认定为“逃逸”。', NULL),
('552', '机动车仪表板上（如图所示）亮时，提醒驾驶人座椅没调整好。', '2', '正确', '错误', '', '', '该指示灯用来显示安全带是否处于锁止状态，当该灯点亮时，说明安全带没有及时的扣紧。有些车型会有相应的提示音。当安全带被及时扣紧后，该指示灯自动熄灭。', 'https://images.juheapi.com/jztk/c1c2subject1/552.jpeg'),
('553', '如图所示，在这种情况下，A车可以向左变更车道。', '2', '正确', '错误', '', '', '变道时不能妨碍在该车道上行驶的车辆（C车）的正常通行，同时两车道有并行车辆（A车和C车）时，变道非常危险。因此A车此时不能向左变更车道。', 'https://images.juheapi.com/jztk/c1c2subject1/553.jpg'),
('554', '记分满12分的驾驶人拒不参加学习和考试的将被公告驾驶证停止使用。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第二十五条：机动车驾驶人记分达到12分，拒不参加公安机关交通管理部门通知的学习，也不接受考试的，由公安机关交通管理部门公告其机动车驾驶证停止使用。', NULL),
('555', '变更车道时只需开启转向灯，并迅速转向驶入相应的车道，以不妨碍同车道机动车正常行驶。', '2', '正确', '错误', '', '', '变更车道，先要打开转向灯，其次要观察周围的环境，确认安全的情况下驶入需要变更的车道。不能迅速驶入。', NULL),
('556', '行车中当车辆前轮爆胎已发生转向时，驾驶人应双手紧握转向盘，尽力控制车辆直线行驶。', '1', '正确', '错误', '', '', '行车中当车辆前轮爆胎已发生转向时：第一步：驾驶人应双手紧握转向盘，尽力控制车辆转回原行驶路线。如果不控制方向，很容易翻车，如果急刹车，也很容翻车。第二步：利用发动机制动减速，打开右转向灯缓慢停靠在路肩上。', NULL),
('557', '这是什么操纵装置？', '4', '转向灯开关', '前照灯开关', '刮水器开关', '除雾器开关', '你看那些曲线，代表的就是雾气。题目扩展：上边的按钮是前挡风除雾，下边的按钮是后挡风除雾。', 'https://images.juheapi.com/jztk/c1c2subject1/557.jpg'),
('558', '驾驶人违反交通运输管理法规发生重大事故使公私财产遭受重大损失，可能会受到什么刑罚？', '2', '处5年以上徒刑', '处3年以下徒刑或者拘役', '处3年以上徒刑', '处3年以上7年以下徒刑', '《刑法》第一百三十三条规定：<b>违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；</b>交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；因逃逸致人死亡的，处七年以上有期徒刑。', NULL),
('559', '机动车仪表板上（如图所示）这个符号表示什么？', '2', '行李舱开启', '发动机舱开启', '燃油箱盖开启', '一侧车门开启', '前盖为发动机舱，后边为行李舱。', 'https://images.juheapi.com/jztk/c1c2subject1/559.jpeg'),
('560', '如图所示，A车具有优先通行权。', '2', '正确', '错误', '', '', '三个先行原则：转弯的机动车让直行的车辆先行，右方道路来车先行，右转弯车让左转弯车先行。', 'https://images.juheapi.com/jztk/c1c2subject1/560.jpg')
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('561', '安全气囊是一种什么装置？', '3', '防抱死制动系统', '电子制动力分配系统', '辅助驾乘人员保护系统', '驾驶人头颈保护系统', '安全气囊，设置在车内前方（正副驾驶位），侧方（车内前排和后排）和车顶三个方向。装有安全气囊系统的容器外部都印有Supplemental Inflatable Restraint System，简称SRS)的字样，直译成中文为“辅助可充气约束系统”。旨在减轻乘员的伤害程度，当发生碰撞事故时，避免乘员发生二次碰撞，或车辆发生翻滚等危险情况下被抛离座位。', NULL),
('562', '如图所示，机动车在这种道路上行驶，在道路中间通行的原因是什么？', '3', '在道路中间通行速度快', '在道路中间通行视线好', '给两侧的非机动车和行人留有充足的通行空间', '防止车辆冲出路外', '没有划分车道的，在遵循右侧通行前提下，混合通行。行人在最右侧通行，非机动车在靠右侧，机动车在中间偏右的位置通行。因为对向来车也是如此，所以对整条路而言，就是机动车在中间，非机动车在两边。给两侧的非机动车和行人留有充足的通行空间，相对来讲更加安全。', 'https://images.juheapi.com/jztk/c1c2subject1/562.jpg'),
('563', '驾驶机动车变更车道为什么要提前开启转向灯？', '4', '提示前车让行', '提示行人让行', '开阔视野，便于观察路面情况', '提示其他车辆我方准备变更车道', '转向灯其实就相当于一个信号，传达自己车辆动向的信息。', NULL),
('564', '仪表显示当前冷却液的温度是90度。', '1', '正确', '错误', '', '', '此仪表盘温度表示的是冷却液的温度。', 'https://images.juheapi.com/jztk/c1c2subject1/564.jpg'),
('565', '机动车驶近急弯、坡道顶端等影响安全视距的路段时，减速慢行并鸣喇叭示意是为了什么？', '2', '提示前车后方车辆准备超车', '提示对向交通参与者我方有来车', '避免行至坡道顶端车辆动力不足', '测试喇叭是否能正常使用', '视线受阻，彼此看不到，所以就要靠喇叭来提醒，路上的行人或者车辆，我方有来车需要注意安全。', NULL),
('566', '机动车仪表板上（如图所示）亮时，提醒发动机需要补充机油。', '2', '正确', '错误', '', '', '这个是燃油液面高度指示灯。图中所示，说明是<b>燃油</b>已到最低液面。', 'https://images.juheapi.com/jztk/c1c2subject1/566.jpeg'),
('567', '驾驶人违反交通运输管理法规发生重大事故致人重伤、死亡，可能会受到什么刑罚？', '1', '处3年以下徒刑或者拘役', '处3年以上7年以下徒刑', '处5年以上徒刑', '处7年以上徒刑', '《刑法》第一百三十三条规定：<b>违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；</b>交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；因逃逸致人死亡的，处七年以上有期徒刑。', NULL),
('568', '如图所示，在前方路口可以掉头。', '2', '正确', '错误', '', '', '根据规定，铁道路口不准掉头、超车。应该停车观察，确认安全后通过铁道。', 'https://images.juheapi.com/jztk/c1c2subject1/568.jpg'),
('569', '非机动车驾驶人、行人故意碰撞机动车造成交通事故的，机动车一方不承担赔偿责任。', '1', '', '', '', '', '《中华人民共和国道路交通安全法》第七十六条：明确规定交通事故的损失是由非机动车驾驶人、行人故意碰撞机动车造成的，机动车一方不承担赔偿责任。', NULL),
('570', '安装防抱死制动装置（ABS）的机动车紧急制动时，可用力踏制动踏板。', '1', '正确', '错误', '', '', 'ABS防抱死系统；车轮不卡死、硬化路面制动时间短平稳、可以用力踩制动、系统自动张合8次/每秒。', NULL),
('571', '这个标志的含义是告示车辆驾驶人应慢行或停车，确保干道车辆优先。', '1', '正确', '错误', '', '', '减速让行，表示车辆应减速让行，告示车辆驾驶人必须慢行或停车，观察干道行车情况，在确保干道车辆优先的前提下，认为安全时方可续行。设于视线良好交叉道路次要道路路口。', 'https://images.juheapi.com/jztk/c1c2subject1/571.jpg'),
('572', '如图所示，当越过停在人行横道前的A车时，B车应减速，准备停车让行。', '1', '正确', '错误', '', '', '如图所示，当A车停在人行横道前，证明此时人行横道上有行人通行。B车应该及时减速，准备停车为行人让行，保障行人安全。', 'https://images.juheapi.com/jztk/c1c2subject1/572.jpg'),
('573', '如图所示，在这种情形下，对方车辆具有先行权。', '1', '正确', '错误', '', '', '在两辆车相对行驶的时候，如果道路一侧有障碍物，那么有障碍物一侧的车辆，避让无障碍物一侧的车辆。', 'https://images.juheapi.com/jztk/c1c2subject1/573.jpg'),
('574', '如图所示，当A车后方有执行任务的救护车驶来时，以下做法正确的是什么？', '3', '立即停车让路', '向左转弯让路', '靠右减速让路', '不必理会，继续行驶', '行车中遇到执行任务的消防车、救护车、工程救险车时要及时让行。', 'https://images.juheapi.com/jztk/c1c2subject1/574.jpg'),
('575', '如图所示，驾驶机动车遇到没有行人通过的人行横道时不用减速慢行。', '2', '正确', '错误', '', '', '《道路交通安全法》规定：驾驶机动车遇到人行横道必须减速让行，必要时停车让行。行人的流动很随意，需要谨慎减速慢行。', 'https://images.juheapi.com/jztk/c1c2subject1/575.jpg'),
('576', '如图所示，在超车过程中，遇对向有来车时要放弃超车是因为什么?', '1', '如继续超车，易与对面机动车发生刮擦、相撞', '前车车速快', '对向来车车速快', '我方车辆提速太慢', '如图所示，对向车道有来车，前方车辆左侧没有足够的安全距离，应放弃超车，避免与对面车辆发生刮擦、相撞。', 'https://images.juheapi.com/jztk/c1c2subject1/576.jpg'),
('577', '如图所示，在这种情况下，会车时必须减速靠右通过。', '1', '正确', '错误', '', '', '如图所示，车道较窄，会车时，为了防止不必要的摩擦，所以要减速靠右行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/577.jpg'),
('578', '初次申领的机动车驾驶证的有效期为多少年？', '3', '3年', '5年', '6年', '12年', '机动车驾驶证有效期首次申领为6年，6年有效期内每个记分周期均未达到12分的，换发10年有效期的机动车驾驶证；在机动车驾驶证的10年有效期内，每个记分周期均未达到12分的，换发长期有效的机动车驾驶证。', NULL),
('579', '怎样通过这样的路口？', '4', '不减速通过', '加速尽快通过', '空挡滑行通过', '减速或停车观察', '右上角的图标为无人看守的铁道路口，驾驶员要减速或者停车确认安全后再通过。', 'https://images.juheapi.com/jztk/c1c2subject1/579.jpg'),
('580', '防抱死制动系统（ABS）在什么情况下可以最大限度发挥制动器效能?', '3', '间歇制动', '持续制动', '紧急制动', '缓踏制动踏板', 'ABS的目的就是为了防止刹车的时候一脚踩死，导致翻车什么的。 不过刹车刹死就比较慢（速度N快的时候），效果等于踩下刹车，再松下刹车，反复几次！', NULL),
('581', '如图所示，在这种情况下只要后方没有来车，可以倒车。', '2', '正确', '错误', '', '', '图上蓝色指标为直行单行道。道路交通安全法实施条例第五十条规定：机动车倒车时，应当察明车后情况，确认安全后倒车。<b>不得在铁路道口、交叉路口、单行路、桥梁、急弯、陡坡或者隧道中倒车。</b>', 'https://images.juheapi.com/jztk/c1c2subject1/581.jpg'),
('582', '初次申领的机动车驾驶证的有效期为6年。', '1', '正确', '错误', '', '', '《机动车驾驶证申领和使用规定》第九条：机动车驾驶证有效期分为六年、十年和长期。<br/>《中华人民共和国道路交通安全法实施条例》：第二十六条 机动车驾驶人在机动车驾驶证的6年有效期内，每个记分周期均未达到12分的，换发10年有效期的机动车驾驶证；在机动车驾驶证的10年有效期内，每个记分周期均未达到12分的，换发长期有效的机动车驾驶证。', NULL),
('583', '驾驶人在机动车驾驶证的6年有效期内，每个记分周期均未达到12分的，换发10年有效期的机动车驾驶证。', '1', '正确', '错误', '', '', '机动车驾驶人在机动车驾驶证的六年有效期内，每个记分周期均未记满12分的，换发十年有效期的机动车驾驶证；在机动车驾驶证的十年有效期内，每个记分周期均未记满12分的，换发长期有效的机动车驾驶证。', NULL),
('584', '如图所示，当您超越右侧车辆时，应该尽快超越，减少并行时间。', '1', '正确', '错误', '', '', '减少并行时间一方面是为了防止与右侧车刮擦，另一方面则是为了防止与对向来车相撞。减少并行，快速超越，这样才能确保超车安全。
<br/>
<br/>【拓展延伸】
<br/>不少学员认为“尽快超越”有问题，担心右侧车辆会在超车时突然向左，会发生事故。但在超车时，被超越车辆更大几率情况应靠右侧让行，而正在进行超车的车辆占用了对向车道，随时有可能驶来车辆，如果不尽快完成超车，很容易发生事故。综上所述，题目描述没有问题。', 'https://images.juheapi.com/jztk/c1c2subject1/584.jpg'),
('585', '当您即将通过交叉路口的时候，才意识到要左转而不是向前，以下说法正确的是什么?', '2', '停在交叉路口，等待安全时左转', '继续向前行驶', '在确保安全的情况下，倒车然后左转', '原地掉头后，右转', '按规定，交叉路口，不可以停车，不可以倒车，只能继续向前行驶。', NULL),
('586', '机动车紧急制动时，ABS系统在提供最大制动力的同时能使车前轮保持转向能力。', '1', '正确', '错误', '', '', 'ABS防抱死系统；车轮不卡死、硬化路面制动时间短平稳、可以用力踩制动、系统自动张合8次/每秒。', NULL),
('587', '驾驶人在核发地车辆管理所管辖区以外居住的，可以向居住地车辆管理所申请换证。', '1', '', '', '', '', '机动车驾驶人户籍迁出原车辆管理所管辖区的，应当向迁入地车辆管理所申请换证。<b>机动车驾驶人在核发地车辆管理所管辖区以外居住的，可以向居住地车辆管理所申请换证。</b>', NULL),
('588', '驾驶机动车前，以下说法错误的是什么？', '4', '调整驾驶座椅，保证踩踏踏板舒适', '调整安全带的松紧与高低', '调整适合驾驶的方向盘位置', '调整安全头枕高度，使头枕正对驾驶人的颈椎', '驾驶机动车前，需要：调整驾驶座椅，保证踩踏踏板舒适；调整安全带的松紧与高低；调整适合驾驶方向盘的位置。<b>安全头枕需要对准后脑勺来保护驾驶员的颈椎。</b>', NULL),
('589', '如图所示，驾驶机动车遇到这种情况能够加速通过，是因为人行横道没有行人通过。', '2', '正确', '错误', '', '', '按规定，<b>驾驶机动车遇到人行横道时必须减速让行，必要时需要停车让行。</b>因为行人有很大的随意性，需要谨慎减速慢行。', 'https://images.juheapi.com/jztk/c1c2subject1/589.jpg'),
('590', '如图所示，A车要在前方掉头行驶，可以在此处变换车道，进入左侧车道准备掉头。', '2', '正确', '错误', '', '', '图中虚线箭头代表的是车辆行驶路线，仔细虚线路径，可以看到变道时压到了白色实线。变道是不能压线的，因此图中A车要在前方掉头行驶，是不能在此处变换车道的。题目描述错误，本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/590.jpg'),
('591', '机动车仪表板上（如图所示）亮时表示什么？', '2', '已开启后雾灯', '已开启前照灯近光', '已开启前照灯远光', '已开启前雾灯', '近光灯的灯光走向是朝下的。远光灯的灯光走向是直的。', 'https://images.juheapi.com/jztk/c1c2subject1/591.jpeg'),
('592', '下列哪个指示灯亮表示车辆在使用远光灯?(图10a. 10b. 10c. 10d)', '4', '10a', '10b', '10c', '10d', '10a：车灯总开关；10b：前后雾灯；10c：驻车制动器处于制动状态；10d：远光灯。', 'https://images.juheapi.com/jztk/c1c2subject1/592.jpg'),
('593', '避免爆胎的错误的做法是什么？', '1', '降低轮胎气压', '定期检查轮胎', '更换有裂纹或有很深损伤的轮胎', '及时清理轮胎沟槽里的异物', '当轮胎气压降低，轮胎与地面的摩擦成倍增加，胎温急剧升高，轮胎变软，强度急剧下降。这种情况下，如果车辆高速行驶，就可能导致爆胎。而如果车辆在低速行驶，也会伤胎，而且潜伏期长，隐蔽性高，危害性更大，会埋下日后爆胎的隐患。因此，降低轮胎气压不仅不能避免爆胎，还会抬高爆胎的风险。根据题意，A符合要求，是避免爆胎的错误做法，答案选A。
<br/>
<br/>【拓展延伸】
<br/>想要避免爆胎，一定要定期检查轮胎，及时清理轮胎沟槽内的异物，及时更换有裂纹或有很深损伤的轮胎。', NULL),
('594', '驾驶机动车变更车道前应仔细观察，目的是判断有无变更车道的条件。', '1', '正确', '错误', '', '', '变更车道时，不得影响其他车辆的正常通行。注意观察是为了确认有无变更车道的条件。如果没有应该停止变更车道，寻找合适时机。条件允许才可以变更车道。', NULL),
('595', '在以下路段不能倒车的是什么？', '4', '交叉路口', '隧道', '急弯', '以上皆是', '第五十条机动车倒车时，应当察明车后情况，确认安全后倒车。不得在铁路道口、交叉路口、单行路、桥梁、急弯、陡坡或者隧道中倒车。', NULL),
('596', '机动车仪表板上（如图所示）亮表示什么？', '4', '防抱死制动系统出现故障', '驻车制动器处于解除状态', '行车制动系统出现故障', '驻车制动器处于制动状态', '驻车制动器处于制动状态，就是手刹没松开。', 'https://images.juheapi.com/jztk/c1c2subject1/596.jpeg'),
('597', '在划有道路中心线的道路上会车时，应做到保持安全车速、不越线行驶。', '1', '正确', '错误', '', '', '在划有道路中心线的道路上，两条车道的行驶方向是不同的。会车时为了避免迎头相撞，应该尽可能的保持安全车速，不越线行驶。', NULL),
('598', '机动车仪表板上（如图所示）亮表示什么？', '2', '空气内循环', '空气外循环', '迎面吹风', '风窗玻璃除霜', '此为空气外循环，当箭头在车内转的时候是空气内循环。', 'https://images.juheapi.com/jztk/c1c2subject1/598.jpeg'),
('599', '如图所示，铁路道口设置这个标志，是提示驾驶人前方路口有单股铁道。', '2', '正确', '错误', '', '', '叉形符号标志表示多股铁道与道路交叉。
<br/>该符号颜色为白底红边。设在铁路道口标志上端。叉形符号交叉点到警告标志三角形顶点的距离为40cm。', 'https://images.juheapi.com/jztk/c1c2subject1/599.jpg'),
('600', '在行驶过程中，机动车驾驶人要注意与前车保持安全距离。', '1', '正确', '错误', '', '', '后车与前车保持安全距离是很重要的，因为安全距离很小的话，在刹车的时候，由于制动距离不够，就会发生碰撞。所以要保持足够的安全距离。', NULL),
('601', '在没有交通信号指示的交叉路口，转弯的机动车让直行的车辆和行人先行。', '1', '正确', '错误', '', '', '车辆通过交叉路口时的通行规定，直行第一、左转弯第二、右转弯第三通行。', NULL),
('602', '驾驶机动车遇到前方低速行驶的洒水车作业时，以下做法错误的是什么？', '4', '注意避让', '若洒水车有指示箭头，在确保安全的情况下按箭头指示方向变更车道', '若洒水车无指示箭头，在确保安全的情况下选择合适的车道变更', '通过洒水车时应急加速通过', '驾驶机动车遇到前方低速行驶的洒水车作业时，需要注意避让。若洒水车有指示箭头，在确保安全的情况下按箭头指示方向变更车道；若洒水车无指示箭头，在确保安全的情况下选择合适的车道变更。不能加速通过。', NULL),
('603', '对驾驶已达到报废标准的机动车上路行驶的驾驶人，会受到下列哪种处罚？', '4', '处20以上200元以下罚款', '追究刑事责任', '处15日以下拘留', '吊销机动车驾驶证', '根据《中华人民共和国道路交通安全法》规定，驾驶拼装的机动车或者已达到报废标准的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废。<b>对驾驶前款所列机动车上道路行驶的驾驶人，处200元以上2000元以下罚款，并吊销机动车驾驶证。</b>因此本题答案为B。', NULL),
('604', '下列哪个指示灯亮表示车辆在使用近光灯?(图9a. 9b. 9c. 9d)', '3', '9a', '9b', '9c', '9d', '9a是车廓灯，9b是前后雾灯，9c是近光灯，9d制动系统出现异常或故障。', 'https://images.juheapi.com/jztk/c1c2subject1/604.jpg'),
('605', '驾驶机动车在高速公路上遇到雨雪天气时，需要降低车速、保持安全距离的原因，以下说法错误的是什么？', '4', '能见度下降，驾驶人难以及时发现前方车辆', '此类天气条件下的道路上，车辆的制动距离变长', '为车辆安全行驶提供足够的安全距离', '降低恶劣天气对车辆造成的损害', '驾驶机动车在高速公路上遇到雨雪天气时能见度下降，驾驶人难以及时发现前方车辆，<b>在此类天气条件下的道路上，车辆的制动距离变长，需要降低车速，为车辆安全行驶提供足够的安全距离。</b>
<br/>而降低车速、保持安全距离，与降低恶劣天气对车辆造成的损害并无直接关系。', NULL),
('606', '如图所示，在这种情况下遇到红灯交替闪烁时，要尽快通过道口。', '2', '正确', '错误', '', '', '红灯交替闪烁，说明此时情况很危险，火车马上就要来了，应该等火车通过后再通过。', 'https://images.juheapi.com/jztk/c1c2subject1/606.jpg'),
('607', '如图所示，A车可以从左侧超越B车。', '2', '', '', '', '', '实线是不能压的，所以A车不具备超车条件，应该放弃。', 'https://images.juheapi.com/jztk/c1c2subject1/607.jpg'),
('608', '这段道路红车所在车道是什么车道？', '1', '快速车道', '慢速车道', '应急车道', '专用车道', '《道路交通安全法实施条例》第四十四条：在道路同方向划有2条以上机动车道的，左侧为快速车道，右侧为慢速车道。红色车在最左侧，所以是在快速车道。', 'https://images.juheapi.com/jztk/c1c2subject1/608.jpg'),
('609', '驾驶机动车正在被其他车辆超越时，被超车辆减速靠右侧行驶的目的是什么?', '2', '以便随时停车', '给该车让出足够的超车空间', '避让行人与非机动车', '提醒其他交通参与者注意避让', '"《道路交通安全法实施条例》第四十七条：机动车超车时，应当提前开启左转向灯、变换使用远、近光灯或者鸣喇叭。在没有道路中心线或者同方向只有1条机动车道的道路上，前车遇后车发出超车信号时，在条件许可的情况下，应当降低速度、靠右让路。后车应当在确认有充足的安全距离后，从前车的左侧超越，在与被超车辆拉开必要的安全距离后，开启右转向灯，驶回原车道。"', NULL),
('610', '驾驶机动车在进出非机动车道时，最高速度不能超过多少？', '4', '40公里/小时', '50公里/小时', '60公里/小时', '30公里/小时', '机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 
<br/>（一）<b>进出非机动车道</b>，通过铁路道口、急弯路、窄路、窄桥时；　　 
<br/>（二）掉头、转弯、下陡坡时；　　 
<br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 
<br/>（四）在冰雪、泥泞的道路上行驶时；', NULL),
('611', '申请人患有精神病的，可以申领机动车驾驶证，但是在发病期间不得驾驶机动车。', '2', '', '', '', '', '《机动车驾驶证申领和使用规定》第十二条有下列情形之一的，不得申请机动车驾驶证：<b>(一)有器质性心脏病、癫痫病、美尼尔氏症、眩晕症、癔病、震颤麻痹、精神病、痴呆以及影响肢体活动的神经系统疾病等妨碍安全驾驶疾病的;</b>(二)三年内有吸食、注射毒品行为或者解除强制隔离戒毒措施未满三年，或者长期服用依赖性精神药品成瘾尚未戒除的;(三)造成交通事故后逃逸构成犯罪的;（四）申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的；(五)醉酒驾驶营运机动车依法被吊销机动车驾驶证未满十年的。', NULL),
('612', '机动车仪表板上（如图所示）亮时，不影响正常行驶。', '2', '正确', '错误', '', '', '图中报警灯是驻车制动器及系统故障指示灯。行车途中该灯亮起，表示制动系统出了问题或故障，机动车不能上路。题目描述错误，因此本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/612.jpeg'),
('613', '驾驶报废机动车上路行驶的驾驶人，除按规定罚款外，还要受到哪种处理？', '4', '收缴驾驶证', '撤销驾驶许可', '强制恢复车况', '吊销驾驶证', '根据《中华人民共和国道路交通安全法》规定，驾驶拼装的机动车或者已达到报废标准的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废。<b>对驾驶前款所列机动车上道路行驶的驾驶人，处200元以上2000元以下罚款，并吊销机动车驾驶证。</b>因此本题答案为D。', NULL),
('614', '如图所示，在这种情况下准备进入环形路口时，为了保证车后车流的通畅，应加速超越红车进入路口。', '2', '正确', '错误', '', '', '在进入环形路口时，不得影响环岛内车辆的正常通行。因此应该按顺序进入环岛，不得加速超越。', 'https://images.juheapi.com/jztk/c1c2subject1/614.jpg'),
('615', '驾驶机动车遇到沙尘、冰雹、雨、雾、结冰等气象条件时应降低行驶速度。', '1', '正确', '错误', '', '', '安全第一，毫无疑问。', NULL),
('616', '如图所示，在这种情况下驶近路口，车辆可以怎么行驶？', '2', '只能直行', '左转或者直行', '左转或右转', '直行或右转', '擦亮眼睛，注意看图！地面图示直行或者左转弯箭头！只有这两种行驶路线！', 'https://images.juheapi.com/jztk/c1c2subject1/616.jpg'),
('617', '雾天行车听到对方鸣喇叭，也应该鸣喇叭回应，以提示对方车辆。', '1', '正确', '错误', '', '', '雾天视线不佳，无法观察周围车况时，喇叭也是车辆间互相提醒的重要工具。要充分利用喇叭提示对方，保障行车安全。', NULL),
('618', '前轮胎爆裂已出现转向时，驾驶人不要过度矫正，应在控制住方向的情况下，应怎样做，使车辆缓慢减速？', '3', '采取紧急制动', '使用驻车制动', '轻踏制动踏板', '迅速踏下制动踏板', '爆胎时不能迅速减速，需慢慢减速。A踩脚刹B拉手刹D踩脚刹都属于迅速减速，此时车子容易发生侧滑。所以要轻踩刹车。', NULL),
('619', '机动车驾驶证补领后，以下说法正确的是什么？', '2', '原驾驶证继续使用', '原驾驶证作废，不得继续使用', '原驾驶证特殊情况下使用', '替换使用', '《机动车驾驶证申领和使用规定》：机动车驾驶人补领机动车驾驶证后，原机动车驾驶证作废，不得继续使用。', NULL),
('620', '饮酒后只要不影响驾驶操作可以短距离驾驶机动车。', '2', '正确', '错误', '', '', '《道路交通安全法》第九十一条：饮酒后驾驶机动车的，处暂扣六个月机动车驾驶证，并处一千元以上二千元以下罚款。对自己对他人负责，只要饮酒就不开车。本题题干描述有误，因此本题答案应为错误。', NULL),
('621', '驾驶机动车在没有道路中心线的狭窄山路怎样会车？', '1', '不靠山体的一方先行', '靠山体的一方先行', '重车让空车先行', '速度慢的先行', '在没有中心隔离设施或者没有中心线的道路上，机动车遇相对方向来车时应当遵守下列规定：
<br/>1)减速靠右行驶，并与其他车辆、行人保持必要的安全距离。
<br/>2)在有障碍的路段，无障碍的一方先行：但有障碍的一方已驶入障碍路段而无障碍的一方未驶入时，有障碍的一方先行。
<br/>3)在狭窄的坡路，上坡的一方先行；但下坡的一方已行至中途而上坡的一方未上坡时，下坡的一方先行。
<br/>4)<b>在狭窄的山路，不靠山体的一方先行。</b>
<br/>5)夜间会车应当在距相对方向来车150m以外改用近光灯，在窄路、窄桥与非机动车会车时应当使用近光灯。', NULL),
('622', '灯光开关在该位置时，前雾灯点亮。', '1', '正确', '错误', '', '', '灯杆上白色圆点对准的是前雾灯标志，因此灯光开关在图中位置时，前雾灯点亮，题目描述正确，因此答案为对。', 'https://images.juheapi.com/jztk/c1c2subject1/622.jpg'),
('623', '车辆后轮胎爆裂，车尾会摇摆不定，驾驶人应双手紧握转向盘，控制车辆保持直线行驶，减速停车。', '1', '正确', '错误', '', '', '<b>爆胎后，首先要控制住方向，保持直线行驶，再减速停车。</b>因为如果突然爆胎，瞬间靠右会导致与后方来车相撞，应该先保持直线行驶，再减速停车。', NULL),
('624', '机动车向左转弯、向左变更车道，驶离停车地点及掉头时，提前开启左转向灯是为了什么？', '3', '提示前车，将要向左变更行驶路线', '提示前车，将要向右变更行驶路线', '提示后车，将要向左变更行驶路线', '提示后车，将要向右变更行驶路线', '开启左转向灯，主要是为了提醒后车，开启左转向灯，当然是向左变更车道了。', NULL),
('625', '人行横道上禁止掉头的原因是什么？', '4', '路段有监控设备', '人行横道禁止停车', '人行横道禁止车辆通行', '避免妨碍行人正常通行，确保行人安全', '人行横道禁止掉头。虽然设有交通隔离护栏路段的人行横道不设禁止掉头交通标志，但规定严禁在人行横道掉头，这主要是为了保护人行横道上行人的安全。', NULL),
('626', '其他车辆不准进入专用车道行驶，其目的是为了不影响专用车的正常通行。', '1', '正确', '错误', '', '', '道路划设专用车道的，在专用车道内，只准许规定的车辆通行，其他车辆不得进入专用车道内行驶。在道路上施划专用车道，为某类车辆提供专门车道通行，这是为缓解交通压力、提高交通通行效率的成功经验和通常做法。', NULL),
('627', '下列哪种标志是驾驶机动车上路行驶应当在车上放置的标志？', '3', '保持车距标志', '提醒危险标志', '检验合格标志', '产品合格标志', '《道路交通安全法》第十一条：驾驶机动车上道路行驶，应当悬挂机动车号牌，<b>放置检验合格标志</b>、保险标志，并随车携带机动车行驶证。因此本题答案应为D。', NULL),
('628', '如图所示，当您车速为95km/h时，您可以在哪条车道内行驶？', '2', '车道A', '车道B', '车道C', '车道D', '看图得知，A车道限速为100~120km/h，B车道限速为80~100km/h，C车道限速为60~80km/h，那么95km/h显而易见是在80~100之间，选B', 'https://images.juheapi.com/jztk/c1c2subject1/628.jpg'),
('629', '超车需从前车左侧超越，以下说法正确的是什么？', '1', '便于观察，有利于安全', '右侧为快速车道', '左侧为慢速车道', '我国实行左侧通行原则', '除了“便于观察，有利于安全”其他选项表述均错。', NULL),
('630', '造成交通事故后逃逸且构成犯罪的驾驶人,将吊销驾驶证且终生不得重新取得驾驶证。', '1', '正确', '错误', '', '', '吊二撤三醉五逃终生，这样就好理解了吧！', NULL),
('631', '如图所示，在这种情况下通过前方路口，应该怎么行驶？', '1', '减速或停车避让行人', '加速通过', '赶在行人前通过', '靠左侧行驶', '前方左侧有行人正在通行，为了保障行人安全，一定要减速或者停车避让行人。', 'https://images.juheapi.com/jztk/c1c2subject1/631.jpg'),
('632', '如图所示，A车在这种情况下应适当减速。', '1', '正确', '错误', '', '', '如图所示，B车要减速转弯，A车也要适当减速，以免两车发生碰撞。', 'https://images.juheapi.com/jztk/c1c2subject1/632.jpg'),
('633', '夜间会车规定150米以内使用近光灯的原因是什么？', '2', '驾驶人的操作习惯行为', '使用远光灯会造成驾驶人出现眩目，易引发危险', '两车之间相互提示', '提示后方车辆', '<b>在夜间会车时开远光灯，容易造成对方驾驶员眼睛出现盲区，</b>这种情况一般可持续四五秒，而这四五秒极有可能酿成车祸。所以，会车150米以内应使用近光灯。', NULL),
('634', '年满20周岁，可以初次申请下列哪种准驾车型？', '1', '大型货车.', '大型客车', '中型客车', '牵引车', '1、申请小型汽车、小型自动挡汽车、残疾人专用小型自动挡载客汽车、轻便摩托车准驾车型的，在18周岁以上、70周岁以下;<br/>2、申请低速载货汽车、三轮汽车、普通三轮摩托车、普通二轮摩托车或者轮式自行机械车准驾车型的，在18周岁以上，60周岁以下;<br/>3、<b>申请城市公交车、大型货车、无轨电车或者有轨电车准驾车型的，在20周岁以上，50周岁以下;</b><br/>4、申请中型客车准驾车型的，在21周岁以上，50周岁以下;<br/>5、申请牵引车准驾车型的，在24周岁以上，50周岁以下;<br/>6、申请大型客车准驾车型的，在26周岁以上，50周岁以下。', NULL),
('635', '在涉水路段跟车行驶时，应当怎样做？', '3', '紧跟其后', '并行通过', '适当增加车距', '超越前车，抢先通过', '涉水路段路滑， 为了避免“水滑”时出现追尾撞车，应该保持安全距离。', NULL),
('636', '驾驶机动车在这种道路上如何通行？', '1', '在道路中间通行', '在道路两边通行', '实行分道通行', '可随意通行', '《道路交通安全法》第三十六条：根据道路条件和通行需要，道路划分为机动车道、非机动车道和人行道的，机动车、非机动车、行人实行分道通行。<b>没有划分机动车道、非机动车道和人行道的，机动车在道路中间通行，非机动车和行人在道路两侧通行。</b>', 'https://images.juheapi.com/jztk/c1c2subject1/636.jpg'),
('637', '这个标志的含义是告示前方道路有障碍物，车辆左侧绕行。', '1', '正确', '错误', '', '', '警告标志：左侧绕行，注意安全。用以告示前方道路有障碍物，车辆应按标志指示减速慢行。设在道路障碍物前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/637.jpg'),
('638', '机动车、非机动车和行人实行分道行驶，是为了规范交通秩序，提高通行效率。', '1', '正确', '错误', '', '', '《道路交通安全法》第三十六条：根据道路条件和通行需要，道路划分为机动车道、非机动车道和人行道的，机动车、非机动车、行人实行分道通行。没有划分机动车道、非机动车道和人行道的，机动车在道路中间通行，非机动车和行人在道路两侧通行。规范交通秩序，提高通行效率。', NULL),
('639', '如图所示，当车辆驶近这样的路口时，以下说法错误的是什么？', '4', '右前方路口视野受阻，如有突然冲出车辆，容易引发事故', '为避免车辆从路口突然冲出引发危险，应适当降低车速', '因为视野受阻，应鸣喇叭提醒侧方道路来车', '本车有优先通行权，可加速通过', '驾驶员在靠近村庄或者集镇时，应该注意观察路况，注意行人。而不是加速通过，故B选项错误。', 'https://images.juheapi.com/jztk/c1c2subject1/639.jpg'),
('640', '如图所示，在这种情况下，驾驶机动车要停车让行。', '1', '正确', '错误', '', '', '图中人行横道此时正有行人通行，为了保障行人安全，必须停车让行。', 'https://images.juheapi.com/jztk/c1c2subject1/640.jpg')
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('641', '如图所示，机动车在这样的城市道路上行驶，最高的行驶速度不得超过50公里/小时。', '2', '正确', '错误', '', '', '《道路交通安全法》规定：没有道路中心线的城市道路最高行驶速度为30km/h。', 'https://images.juheapi.com/jztk/c1c2subject1/641.jpg'),
('642', '灯光开关在该位置时，后雾灯点亮。', '1', '正确', '错误', '', '', '停的位置雾灯是冲右的，此为后雾灯，故正确。', 'https://images.juheapi.com/jztk/c1c2subject1/642.jpg'),
('643', '牵引发生故障的机动车时，最高车速不得超过多少？', '2', '20公里/小时', '30公里/小时', '40公里/小时', '50公里/小时', '道路交通安全法实施条例<br/>第四十六条　机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：<br/>　　（一）进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；<br/>　　（二）掉头、转弯、下陡坡时；<br/>　　（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；<br/>　　（四）在冰雪、泥泞的道路上行驶时；<br/>　　（五）牵引发生故障的机动车时。', NULL),
('644', '公安机关交通管理部门对累积记分达到规定分值的驾驶人怎样处理？', '3', '处15日以下拘留', '终生禁驾', '进行法律法规教育，重新考试', '依法追究刑事责任', '机动车驾驶人<b>在一个记分周期内累积记分达到12分的，</b>公安机关交通管理部门应当扣留其机动车驾驶证。 机动车驾驶人应当在十五日内到机动车驾驶证核发地或者违法行为地公安机关交通管理部门<b>参加为期七日的道路交通安全法律、法规和相关知识学习。</b>机动车驾驶人参加学习后，车辆管理所应当在二十日内对其进行道路交通安全法律、法规和相关知识考试。考试合格的，记分予以清除，发还机动车驾驶证。考试不合格的，继续参加学习和考试。
<br/>因此本题答案应为D。', NULL),
('645', '机动车仪表板上（如图所示）亮时，提醒发动机冷却液可能不足。', '1', '正确', '错误', '', '', '此标志亮起说明发动机水温过高，可能是冷却液不足引起的。', 'https://images.juheapi.com/jztk/c1c2subject1/645.jpeg'),
('646', '如图所示，B车具有优先通行权。', '2', '正确', '错误', '', '', '车辆通过交叉路口时的通行规定，直行第一、左转弯第二、右转弯第三通行。', 'https://images.juheapi.com/jztk/c1c2subject1/646.jpg'),
('647', '将转向灯开关向上提，左转向灯亮。', '2', '正确', '错误', '', '', '向上提：右转向灯亮；
<br/>向下拉：左转向灯亮。
<br/>题目描述及图片显示均错误，因此本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/647.jpg'),
('648', '准驾车型为小型自动挡汽车的，可以驾驶以下哪种车型？', '4', '低速载货汽车', '小型汽车', '二轮摩托车', '轻型自动挡载货汽车', '小型自动挡汽车（C2）准驾车型：小型、微型自动挡载客汽车以及轻型、微型自动挡载货汽车。', NULL),
('649', '当行人出现交通安全违法行为时，车辆可以不给行人让行。', '2', '正确', '错误', '', '', '安全第一，文明驾驶，礼貌让行。无论何时都应该让行。', NULL),
('650', '交叉路口不得倒车的原因是什么？', '1', '交通情况复杂，容易造成交通堵塞甚至引发事故', '交通监控设备多', '交通警察多', '车道数量少', '交叉路口车流最多，情况很复杂，如果倒车极易造车拥堵或易发事故。', NULL),
('651', '交通肇事致一人以上重伤，负事故全部或者主要责任，并具有下列哪种行为的，构成交通肇事罪?', '2', '未带驾驶证', '酒后、吸食毒品后驾驶机动车辆的', '未报警', '未抢救受伤人员', '交通肇事致一人受伤(属于一般事故)，负事故全部或者主要责任，并具有酒后、无证驾驶、严重超载等情形之一的，以交通肇事罪处罚。', NULL),
('652', '这个标志的含义是提醒车辆驾驶人前方是急转弯路段。', '2', '正确', '错误', '', '', '<p><img src=http://tp.mnks.cn/tp_123.jpg>
<br/>向右急弯路
<br/><img src=http://tp.mnks.cn/tp_124.jpg>
<br/>向左急弯路
<br/><img src=http://tp.mnks.cn/tp_142.jpg>
<br/>易滑路段</p>', 'https://images.juheapi.com/jztk/c1c2subject1/652.jpg'),
('653', '机动车驾驶人补领机动车驾驶证后，原机动车驾驶证作废，不得继续使用。', '1', '', '', '', '', '《机动车驾驶证申领和使用规定》：机动车驾驶人补领机动车驾驶证后，原机动车驾驶证作废，不得继续使用。', NULL),
('654', '车在这种条件的道路上，最高速度不能超过每小时50公里。', '2', '正确', '错误', '', '', '冰雪路面最高速度不能超过每小时30公里。', 'https://images.juheapi.com/jztk/c1c2subject1/654.jpg'),
('655', '夜间尾随前车行驶时，后车可以使用远光灯。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第五十八条：“机动车在夜间没有路灯、照明不良或者遇有雾、雨、雪、沙尘、冰雹等低能见度情况下行驶时，应当开启前照灯、示廓灯和后位灯，<b>但同方向行驶的后车与前车近距离行驶时，不得使用远光灯。</b>机动车雾天行驶应当开启雾灯和危险报警闪光灯。”', NULL),
('656', '仪表显示当前发动机转速是6000转/分钟。', '2', '正确', '错误', '', '', '题目中仪表中有KM，这是速度和里程表，表示当前汽车的行驶速度是60公里/小时。', 'https://images.juheapi.com/jztk/c1c2subject1/656.jpg'),
('657', '驾驶机动车在隧道、陡坡等特殊路段不得超车。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》第四十三条：<br/>同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：<br/>（一）前车正在左转弯、掉头、超车的；<br/>（二）与对面来车有会车可能的；<br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的；<br/>（四）行经铁路道口、交叉路口、窄桥、弯道、<b>陡坡、隧道、</b>人行横道、市区交通流量大的路段等没有超车条件的。', NULL),
('658', '路口转弯过程中，持续开启转向灯，主要是因为什么？', '2', '完成转弯动作前，关闭转向灯是习惯动作', '让其他驾驶人知道您正在转弯', '让其他驾驶人知道您正在超车', '完成转弯动作前，关闭转向灯会对车辆造成损害', '路口转弯过程中，持续开启转向灯，是为了提醒别的行人和车辆此车正在转弯，注意安全。直至转弯动作完成后，才能关闭转向灯。', NULL),
('659', '如图所示，车辆在拥挤路段排队行驶时，遇有其他车辆强行穿插行驶，以下说法正确的是什么？', '4', '迅速提高车速不让其穿插', '持续鸣喇叭警告', '迅速左转躲避', '减速或停车让行', '减速停车让行，文明才是王道。', 'https://images.juheapi.com/jztk/c1c2subject1/659.jpg'),
('660', '机动车驾驶人在一个记分周期内累积记分达到12分，拒不参加学习和考试的，将被公安机关交通管理部门公告其驾驶证停止使用。', '1', '', '', '', '', '正确的，所以要及时去处理扣分。', NULL),
('661', '山区道路对安全行车的主要影响是什么？', '2', '交通情况单一', '坡长弯急，视距不足', '车流密度大', '道路标志少', '<b>山区道路的特点是：坡多、路窄、急弯多，不像平原地区视线开阔。</b>最关键的一点是山区道路行驶时不容易掌握周围情况，也就是所谓视距不足。', NULL),
('662', '在这段城市道路上行驶的最高速度不能超过多少？', '2', '40公里/小时', '30公里/小时', '50公里/小时', '70公里/小时', '《中华人民共和国道路交通安全法实施条例》<br/>第四十五条：机动车在道路上行驶不得超过限速标志、标线标明的速度。在没有限速标志、标线的道路上，机动车不得超过下列最高行驶速度：<br/>  <b>(一)没有道路中心线的道路，城市道路为每小时30公里，公路为每小时40公里；</b><br/>  (二)同方向只有1条机动车道的道路，城市道路为每小时50公里，公路为每小时70公里。', 'https://images.juheapi.com/jztk/c1c2subject1/662.jpg'),
('663', '驾驶机动车在雾天行车开启雾灯和危险报警闪光灯。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第五十八条：机动车在夜间没有路灯、照明不良或者遇有雾、雨、雪、沙尘、冰雹等低能见度情况下行驶时，应当开启前照灯、示廓灯和后位灯，但同方向行驶的后车与前车近距离行驶时，不得使用远光灯。<b>机动车雾天行驶应当开启雾灯和危险报警闪光灯。</b>
<br/>因此，本题答案应为正确。', NULL),
('664', '如图所示，在这种情况下通过交叉路口时，不得超车的原因是什么？', '3', '路口有交通监控设备', '路口设有信号灯', '路口内交通情况复杂，易发生交通事故', '机动车速度慢，不足以超越前车', '路口交通情况较为复杂，冒然超车，容易引发交通事故。安全起见，不要在路口超车。', 'https://images.juheapi.com/jztk/c1c2subject1/664.jpg'),
('665', '这个导向箭头是何含义？', '1', '指示直行或右转弯', '指示向右转弯或掉头', '指示直行或向右变道', '指示直行或掉头', '直接或右转，送分题', 'https://images.juheapi.com/jztk/c1c2subject1/665.jpg'),
('666', '遇后车超车时，在条件许可的情况下应减速靠右让路，是为了给后车留出超车空间。', '1', '正确', '错误', '', '', '和谐第一，做题就要假扮圣人，人家要超车就减速靠右给他让出超车的位置。', NULL),
('667', '有这种信号灯的路口允许机动车如何行驶？', '1', '向右转弯', '停车等待', '向左转弯', '直行通过', '图中是箭头指示的交通信号灯，只有右转的灯是绿灯，并且我方车辆在右转车道上，所以只能向右转弯。', 'https://images.juheapi.com/jztk/c1c2subject1/667.jpg'),
('668', '交通肇事致一人以上重伤，负事故全部或者主要责任，并具有下列哪种行为的，构成交通肇事罪?', '3', '未带驾驶证', '未及时报警', '严重超载驾驶的', '未抢救受伤人员', '交通肇事致一人受伤(属于一般事故)，负事故全部或者主要责任，并具有酒后、无证驾驶(这个是没有驾驶证，而不是没带驾驶证)、严重超载等情形之一的，以交通肇事罪处罚。', NULL),
('669', '灯光开关旋转到这个位置时，全车灯光点亮。', '2', '正确', '错误', '', '', '当前旋钮箭头对应的只是示宽灯，不是全车灯光点亮。', 'https://images.juheapi.com/jztk/c1c2subject1/669.jpg'),
('670', '这辆在道路上行驶的机动车有下列哪种违法行为？', '2', '未按规定悬挂号牌', '故意遮挡号牌', '占用非机动车道', '逆向行驶', '《道路交通安全法》第十一条规定：机动车号牌应当按照规定悬挂并保持清晰、完整，不得故意遮挡、污损。 
<br/>观察可知，图中机动车的车号牌被故意遮挡住了。但并没有存在逆向行驶、不悬挂号牌、占用非机动车道这些违法行为，因此本题答案应为C。
<br/>
<br/>【拓展延伸】
<br/>图中黄色虚线，设置在 <b>[ 双向道路 ]</b> 的中间，并非单向车道。图中车辆在对向车道上，并未逆向行驶，注意审图。', 'https://images.juheapi.com/jztk/c1c2subject1/670.jpg'),
('671', '存在以下哪种行为的申请人在一年内不得再次申领机动车驾驶证？', '2', '在考试过程中出现身体不适', '在考试过程中有舞弊行为', '不能按照教学大纲认真练习驾驶技能', '未参加理论培训', '《机动车驾驶证申领和使用规定》第六章第七十八条：隐瞒有关情况或者提供虚假材料申领机动车驾驶证的，申请人在一年内不得再次申领机动车驾驶证。<b>申请人在考试过程中有贿赂、舞弊行为的，取消考试资格，已经通过考试的其他科目成绩无效；申请人在一年内不得再次申领机动车驾驶证。</b>', NULL),
('672', '驾驶机动车在道路上发生交通事故，任何情况下都应标明现场位置后，先行撤离现场。', '2', '', '', '', '', '因为根据《交通安全法》的规定，如果机动车在道路上面发生了事故，那么必须要马上停车保护现场，如果有人员伤亡的情况，驾驶人应该马上去抢救受伤人员。并且报告执勤的交警或交通管理部门。<b>如果因为抢救伤员而而变动了现场的话，就要标明位置。</b>路人或过往的车辆驾驶人或乘客都应该协助帮忙。如果在道路上发生交通事故，没有造成人员伤亡的，当事人没有对事故有任何争议的，可以撤离现场恢复交通次序，双方自行协商处理损害赔偿就行了。如果说有争议的话，那么不要撤离现场，需要马上报个相关的交警来处理。', NULL),
('673', '这个标志的含义是警告车辆驾驶人前方是人行横道。', '2', '正确', '错误', '', '', '图中为注意行人标志，用来警示机动车驾驶人要注意过往行人，谨慎慢行。此标志通常设置在行人密集，或者有人行横道但是不易被发现的区域。提示司机注意行人，而非人行横道。题目描述错误，因此答案为错。
<br/>
<br/><p><img src=http://tp.mnks.cn/tp_216.jpg>
<br/>人行横道
<br/><img src=http://tp.mnks.cn/tp_135.jpg>
<br/>注意行人</p>', 'https://images.juheapi.com/jztk/c1c2subject1/673.jpg'),
('674', '在道路上发生交通事故造成人身伤亡时，要立即抢救受伤人员并迅速报警。', '1', '正确', '错误', '', '', '根据《中华人民共和国道路交通安全法》第七十条的规定：<b>在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场；造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。</b>因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。', NULL),
('675', '如图所示，在这种情况下跟车行驶，不能使用远光灯的原因是什么？', '3', '不利于看清远方的路况', '不利于看清车前的路况', '会影响前车驾驶人的视线', '会影响自己的视线', '当开启远光灯之后，由于远光灯的光束十分集中且亮度较高，前车的司机在看左右后视镜时，往往会受刺眼的强光影响，形成局部的“盲区”甚至短暂“失明”，无法看清车身两侧的路面情况。尤其在需要并线或者转弯时，一个不留神就极其容易发生交通意外。', 'https://images.juheapi.com/jztk/c1c2subject1/675.jpg'),
('676', '申请人有下列哪种行为，三年内不得再次申领机动车驾驶证？', '3', '实习期记满12分，注销驾驶证的', '申请人在考试过程中有舞弊行为的', '申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的', '申请人未能在培训过程中认真练习的', '根据公安部令第123号规定：
<br/>申请人在考试过程中有贿赂、舞弊行为的，取消考试资格，已经通过考试的其他科目成绩无效；申请人在一年内不得再次申领机动车驾驶证。
<br/>申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的，公安机关交通管理部门收缴机动车驾驶证，撤销机动车驾驶许可；申请人在三年内不得再次申领机动车驾驶证。', NULL),
('677', '这个导向箭头是何含义？', '2', '指示前方可直行或掉头', '指示前方可左转或掉头', '指示前方可直行或向左变道', '指示前方可直行或左转', '其实是一个左转+掉头的综合体 orz', 'https://images.juheapi.com/jztk/c1c2subject1/677.jpg'),
('678', '如图所示，这这种情况下只要后方、对向无来车，可以掉头。', '1', '正确', '错误', '', '', '简单来说：黄线是用来画分来回车道的，黄实线是禁止越线行驶。黄虚线是在对面没车来的情况下，可以在黄虚线越过转弯或者是掉头。白实线是用来规分同方向车道的，实线是表示同方向行驶，不能越线到另一同方向车道行驶。白虚线是虚线同方向车道的，可以越线到另一同方向车道行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/678.jpg'),
('679', '遇前方路段车道减少，车辆行驶缓慢，为保证安全有序应该怎样做？', '1', '依次交替通行', '穿插到前方排队车辆中通过', '加速从前车左右超越', '借对向车道迅速通过', '第五十三条：机动车在车道减少的路口、路段，遇有前方机动车停车排队等候或者缓慢行驶的，应当每车道一辆依次交替驶入车道减少后的路口、路段。', NULL),
('680', '驾驶人的机动车驾驶证被依法扣留、暂扣的情况下不得驾驶机动车。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第二十八条：机动车驾驶人在机动车驾驶证丢失、损毁、超过有效期或者被依法扣留、暂扣期间以及记分达到12分的，不得驾驶机动车。', NULL),
('681', '以下哪种行为处十日以下拘留，并处一千元以上二千元以下罚款，吊销机动车驾驶证？', '4', '醉酒驾驶机动车的', '故意遮挡机动车号牌的', '使用其他车辆保险标志的', '因饮酒后驾驶机动车被处罚，再次饮酒后驾驶机动车的', '依据《中华人民共和国道路交通安全法》：饮酒后驾驶机动车的，处暂扣六个月机动车驾驶证，并处一千元以上二千元以下罚款。<b>因饮酒后驾驶机动车被处罚，再次饮酒后驾驶机动车的，处十日以下拘留，并处一千元以上二千元以下罚款，吊销机动车驾驶证。</b>', NULL),
('682', '如图所示，通过有这个标志的路口时无需减速。', '2', '正确', '错误', '', '', '前方标志为减速让行标志，通过有这个标志的路口时需要减速。', 'https://images.juheapi.com/jztk/c1c2subject1/682.jpg'),
('683', '如图所示，在这种情况下只要后方、对向无来车，可以掉头。', '2', '正确', '错误', '', '', '黄色的实线是不能压的，掉头必须要穿过黄线，所以，有黄色的实线是不能掉头的。', 'https://images.juheapi.com/jztk/c1c2subject1/683.jpg'),
('684', '如图所示，直行车辆遇到前方路口堵塞，以下说法正确的是什么？', '2', '可以直接驶入路口内等待通行', '等前方道路疏通后，且信号灯为绿灯时方可继续行驶', '只要信号灯为绿灯，就可通过', '等有其他机动车进入路口时跟随行驶', '《道路交通安全法》第五十三条规定： 机动车遇有前方交叉路口交通阻塞时，应当依次停在路口以外等候，不得进入路口。因此本题选A', 'https://images.juheapi.com/jztk/c1c2subject1/684.jpg'),
('685', '超过机动车驾驶证有效期一年以上未换证被注销，但未超过2年的，机动车驾驶人应当如何恢复驾驶资格？', '1', '参加道路交通安全法律、法规和相关知识考试合格后', '参加场地考试合格后', '参加道路驾驶技能考试合格后', '参加安全文明驾驶常识考试合格后', '《机动车驾驶证申领和使用规定》：被注销机动车驾驶证未超过两年的，机动车驾驶人考试科目一合格后，可以恢复驾驶资格。', NULL),
('686', '遇前方路段车道减少，车辆行驶缓慢，为保证道路通畅，应借对向车道迅速通过。', '2', '正确', '错误', '', '', '第五十三条机动车遇有前方交叉路口交通阻塞时，应当依次停在路口以外等候，不得进入路口。<b>机动车在遇有前方机动车停车排队等候或者缓慢行驶时，应当依次排队，不得从前方车辆两侧穿插或者超越行驶，不得在人行横道，网状线区域内停车等候。</b>', NULL),
('687', '驾驶证审验内容不包括以下哪一项？', '4', '道路交通安全违法行为、交通事故处理情况', '身体条件情况', '道路交通安全违法行为记分及记满12分后参加学习和考试情况', '机动车检验情况', '驾驶证审验内容包括：道路交通安全违法行为、交通事故处理情况；身体条件情况；道路交通安全违法行为记分及记满12分后参加学习和考试情况。', NULL),
('688', '如图所示，以下哪种情况可以超车?(图50a.50b. 50c. 50d)', '3', '50a', '50b', '50c', '50d', '大家都知道的，实线一侧是不可以跨越的，只有虑线的一侧才可以，所以只有50c具备超车条件。', 'https://images.juheapi.com/jztk/c1c2subject1/688.jpg'),
('689', '持有小型汽车驾驶证的驾驶人，发生交通事故造成人员死亡承担同等以上责任未被吊销机动车驾驶证的，应当在本记分周期结束后三十日内到公安机关交通管理部门接受审验，同时应当申报身体条件情况。', '1', '', '', '', '', '规定以外准驾车型驾驶证的驾驶人，发生交通事故造成人员死亡承担同等以上责任未被吊销机动车驾驶证的，应当在本记分周期结束后三十日内到公安机关交通管理部门接受审验。', NULL),
('690', '遇到前方车辆停车排队或者缓慢行驶时，强行穿插，以下说法正确的是什么？', '3', '允许，因为可以省油', '允许，因为可以快速的通过拥堵区', '禁止，因为这样扰乱车流，加重拥堵', '禁止，因为这样不利于省油', '机动车遇有前方车辆停车排队等候或者缓慢行驶时，不得借道超车或者占用对面车道，不得穿插等候的车辆，应当依次排队。如果强行穿插，会扰乱车流加重拥堵。所以B选项是正确的', NULL),
('691', '驾驶机动车在隧道内行驶时，可以临时停车。', '2', '', '', '', '', '机动车在交叉路口、铁路道口、急弯路、宽度不足4米的窄路、桥梁、陡坡、隧道以及距离上述地点50米以内的路段，不得停车。', NULL),
('692', '路面上导向箭头是何含义？', '3', '提示前方有左弯或需向左绕行', '提示前方有障碍需向左合流', '提示前方有右弯或需向右合流', '提示前方有左弯或需向左合流', '按图箭头意思就是要向右小转变，可能是道路右转，可能是两个不同的车道要汇合', 'https://images.juheapi.com/jztk/c1c2subject1/692.jpg'),
('693', '雾天行车为了提高能见度，应该开启远光灯。', '2', '正确', '错误', '', '', '雾天行驶应该打开雾灯、尾灯、示廓灯和前照灯(近光)，不能使用远光灯。</b>因远光灯光轴偏上，射出的光线被雾气漫反射，在车前形成白茫茫一片，如同隔着磨砂玻璃一样，反而什么都看不见，非常危险。', NULL),
('694', '这个标志的含义是提醒车辆驾驶人前方路段通过村庄或集镇。', '1', '正确', '错误', '', '', '警告标志：注意村庄，注意行车安全。用以提醒车辆驾驶人小心驾驶。设在紧靠村庄、集镇且视线不良的路段以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/694.jpg'),
('695', '这个路面标记是什么标线？', '4', '禁驶区', '网状线', '导流线', '中心圈', '中心圈，设置在交叉路口中心的白色圆形或菱形区域，用以区分车辆大、小转弯，及交叉路口车辆左右转弯的指示，车辆不得压线行驶。机动车向左转弯时，必须紧靠中心圈小转弯。', 'https://images.juheapi.com/jztk/c1c2subject1/695.jpg'),
('696', '驾驶证丢失后,驾驶人可以继续驾驶机动车。', '2', '', '', '', '', '驾驶证丢失后，驾驶人不可继续驾驶机动车，应该向核发地车辆管理所申请补发。', NULL),
('697', '这个仪表是何含义？', '1', '发动机转速表', '行驶速度表', '区间里程表', '百公里油耗表', '此为发动机转速表，跟时速表对比记忆。', 'https://images.juheapi.com/jztk/c1c2subject1/697.jpg'),
('698', '这个标志的含义是提醒车辆驾驶人前方有很强的侧向风。', '1', '正确', '错误', '', '', '注意横风，这种标志会出现在一些风口或是宽阔的地段,提醒驾驶员前方会有较强侧风。', 'https://images.juheapi.com/jztk/c1c2subject1/698.jpg'),
('699', '在狭窄的山路会车，规定不靠山体的一方优先行驶的原因是什么？', '1', '靠山体的一方相对安全', '不靠山体的一方车速较快', '靠山体的一方视野宽阔', 'B和C都正确', '狭窄的山路会车，如果不靠山体一方停车让行，万一发生碰撞会导致车掉下山崖。相对来说，靠山体一方停车让行安全性大一些。', NULL),
('700', '夜间行车，可选择下列哪个地段超车?', '3', '交叉路口', '窄路窄桥', '路宽车少', '弯道陡坡', '超车前，应选择视线良好、平直宽阔、左右均无障碍且前方路段200米范围内没有来车的道路，在保证安全的前提下方能超车。千万不要盲目超车。几个选项中，当然是选路宽车少的路段了。', NULL),
('701', '专用车道规定的专用使用时间之外，其他车辆可以进入专用车道行驶。', '1', '正确', '错误', '', '', '重点看题目中的“专用使用时间之外”，审题要仔细。<br/>在规定时间内，道路划设为专用车道的，在专用车道内，只准许规定的车辆通行，其他车辆不得进入专用车道内行驶。在规定时间之外，其他车辆可以行使。', NULL),
('702', '超车时，如果无法保证与被超车辆的安全间距，应主动放弃超车。', '1', '正确', '错误', '', '', '必须在确保安全的情况下，再实施超车。不具备条件时，应该主动放弃。', NULL),
('703', '申请人在考试过程中有贿赂、舞弊行为的，申请人在多少年内不得再次申领机动车驾驶证？', '1', '1年', '2年', '3年', '4年', '根据123号令第六章法律责任的规定：<b>申请人在考试过程中有贿赂、舞弊行为的，取消考试资格，已经通过考试的其他科目成绩无效；申请人在一年内不得再次申领机动车驾驶证。</b>', NULL),
('704', '如图所示，驾驶机动车遇到这种情况时，以下做法正确的是什么？ ', '1', '应停车察明水情，确认安全后，低速通过', '应停车察明水情，确认安全后，快速通过', '应减速观察水情，然后加速行驶通过', '可随意通行', '图中所示，河水已经漫过路面，驾驶机动车遇到这种情况时，应停车察明水情，确认安全后，低速通过；不可随意通行。', 'https://images.juheapi.com/jztk/c1c2subject1/704.jpg'),
('705', '如图所示，在这种雾天情况下，通过交叉路口时必须开灯、鸣喇叭，加速通过，以免造成交通拥堵。', '2', '正确', '错误', '', '', '施主咱聊聊，不要再做no zuo no die(不作不死)的事情了好不好？雾天亲你就别加速了好不好？', 'https://images.juheapi.com/jztk/c1c2subject1/705.jpg'),
('706', '如图所示，A车具有优先通行权。', '1', '正确', '错误', '', '', '左转让直行！右转让左转！', 'https://images.juheapi.com/jztk/c1c2subject1/706.jpg'),
('707', '在后方无来车的情况下，在隧道中倒车应靠边行驶。', '2', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第五十条规定： 机动车不得在铁路道口、交叉路口、单行路、桥梁、急弯、陡坡或者隧道中倒车。', NULL),
('708', '如图所示，在这种道路上行驶，应在道路中间通行的主要原因是在道路中间通行速度快。', '2', '正确', '错误', '', '', '没有划分车道的，在遵循右侧通行前提下，混合通行。行人在最右侧通行，非机动车在靠右侧，机动车在中间偏右的位置通行。因为对向来车也是如此，所以对整条路而言，就是机动车在中间，非机动车在两边。给两侧的非机动车和行人留有充足的通行空间，相对来讲更加安全。', 'https://images.juheapi.com/jztk/c1c2subject1/708.jpg'),
('709', '如图所示，驾驶机动车接打电话容易导致发生交通事故。', '1', '', '', '', '', '驾驶机动车需要驾驶员集中注意力观察周围的情况，打电话容易分散驾驶员的注意力，会导致驾驶员不注意周围情况从而引发交通事故。', 'https://images.juheapi.com/jztk/c1c2subject1/709.jpg'),
('710', '如图所示，在这种情况下，您应该轻踩制动踏板减速。', '1', '正确', '错误', '', '', '超过了最高时速60公里，应该减速，但是由于只超速一点点，所以只要轻踩制动踏板。', 'https://images.juheapi.com/jztk/c1c2subject1/710.jpg'),
('711', '车辆在通过山区道路弯道时，要做到“减速、鸣喇叭、靠右行”。', '1', '正确', '错误', '', '', '通过弯道时，大家都知道要减速，而在山区道路，由于前方状况很难了解，因此，若要经过弯道，应当鸣号告知其他车辆你要通过弯道了，靠右行是为了避免在弯道时遇到对向来车，若不靠右行驶，很可能会与来车发生碰撞。', NULL),
('712', '初次申领机动车驾驶证的，可以申请下列哪种准驾车型？', '3', '中型客车', '大型客车', '普通三轮摩托车', '牵引车', '初次申领机动车驾驶证的，可以申请准驾车型为城市公交车、大型货车、小型汽车、小型自动挡汽车、低速载货汽车、三轮汽车、残疾人专用小型自动挡载客汽车、普通三轮摩托车、普通二轮摩托车、轻便摩托车、轮式自行机械车、无轨电车、有轨电车的机动车驾驶证。', NULL),
('713', '这个仪表是何含义？', '1', '速度和里程表', '发动机转速表', '最高时速值表', '百公里油耗表', '图为时速表，看到那个KM没？那个是公里的意思，也就是里程表的意思。', 'https://images.juheapi.com/jztk/c1c2subject1/713.jpg'),
('714', '如图所示，在高速公路同方向两条机动车道左侧车道行驶，应保持什么车速？', '2', '110公里/小时～130公里/小时', '100 公里/小时～120公里/小时', '90 公里/小时～110公里/小时', '60 公里/小时～120公里/小时', '高速路同方向有2条车道，左侧车的速度范围为100公里到120公里，右侧车的速度范围为60公里到100公里。', 'https://images.juheapi.com/jztk/c1c2subject1/714.jpg'),
('715', '道路交通标线分为指示标线、警告标线、禁止标线。', '1', '正确', '错误', '', '', '道路交通标志  道路交通标志和标线是用图案、符号、文字传递交通管理信息，用以管制及引导交通的一种安全管理设施。<b>《道路交通标志和标线》规定的交通标志分为七大类：</b>
<br/>  (1)警告标志：警告车辆和行人注意危险地点的标志。
<br/>  (2)禁令标志：禁止或限制车辆、行人交通行为的标志。
<br/>  (3)指示标志：指示车辆、行人行进的标志。
<br/>  (4)指路标志：传递道路方向、地点、距离的标志。
<br/>  (5)旅游区标志：提供旅游景点方向、距离的标志。
<br/>  (6)道路施工安全标志：通告道路施工区通行的标志。
<br/>  (7)辅助标志：附设于主标志下起辅助说明使用的标志。
<br/> <b> 规定的道路交通标线分为三大类：</b>
<br/><b>  (1)指示标线</b>：指示车行道、行车方向、路面边缘、人行道等设施的标线。
<br/>  <b>(2)禁止标线</b>：告示道路交通的遵行、禁止、限制等特殊规定，车辆驾驶人员及行人需要严格遵守的标线。
<br/>  <b>(3)警告标线</b>：促使车辆驾驶人员及行人了解道路上的特殊情况，提高警觉，准备防范应变措施的标线。', NULL),
('716', '同车道行驶的车辆前方遇到下列哪种车辆不得超车？', '2', '大型客货车', '执行任务的消防车', '公共汽车', '出租汽车', '亲，人命关天，您就别超了。', NULL),
('717', '夜间行车，需要超车时，变换远近光灯示意是为了提示前车。', '1', '正确', '错误', '', '', '夜间超车，由于光线差、驾驶员视野变小，仅仅通过打左转向灯有时候很难让前车注意到后车发出的超车信号。为了保证安全，可以在需要超车时，变换远近光灯提示前车注意避让。题目描述无误，本题答案为对。', NULL),
('718', '这个仪表是何含义？', '4', '压力表', '电流表', '水温表', '燃油表', '汽油不够了，看到那个加油站常见的机器没。', 'https://images.juheapi.com/jztk/c1c2subject1/718.jpg'),
('719', '牵引故障车时，牵引与被牵引的机动车，在行驶中都要开启危险报警闪光灯。', '1', '正确', '错误', '', '', '分析：《中华人民共和国道路交通安全法实施条例》第六十一条 牵引故障机动车应当遵守下列规定： 　　<br/>(一)被牵引的机动车除驾驶人外不得载人，不得拖带挂车； 　　<br/>(二)被牵引的机动车宽度不得大于牵引机动车的宽度； 　　<br/>(三)使用软连接牵引装置时，牵引车与被牵引车之间的距离应当大于4米小于10米； 　　<br/>(四)对制动失效的被牵引车，应当使用硬连接牵引装置牵引； 　　<br/>(五)<b>牵引车和被牵引车均应当开启危险报警闪光灯。</b>汽车吊车和轮式专用机械车不得牵引车辆。摩托车不得牵引车辆或者被其他车辆牵引。转向或者照明、信号装置失效的故障机动车，应当使用专用清障车拖曳。>>>因此本题是对的。', NULL),
('720', '这个路面标记是什么标线？', '3', '禁驶区', '网状线', '中心圈', '导流线', '中心圈，设置在交叉路口中心的白色圆形或菱形区域，用以区分车辆大、小转弯，及交叉路口车辆左右转弯的指示，车辆不得压线行驶。机动车向左转弯时，必须紧靠中心圈小转弯。', 'https://images.juheapi.com/jztk/c1c2subject1/720.jpg')
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('721', '已注册登记的机动车达到国家规定的强制报废标准的，应当向登记地车辆管理所申请注销登记。', '1', '', '', '', '', '《中华人民共和国道路交通安全法》第二章第十四条规定：应当报废的机动车必须及时办理注销登记。达到报废标准的机动车不得上道路行驶。报废的大型客、货车及其他营运车辆应当在公安机关交通管理部门的监督下解体。', NULL),
('722', '安全头枕用于在发生追尾事故时保护驾驶人的头部不受伤害。', '2', '', '', '', '', '应该是减轻驾驶人头部伤害。', NULL),
('723', '如图所示，在这种情况下遇右侧车辆变更车道，应减速保持间距，注意避让。', '1', '正确', '错误', '', '', '碰到右侧车辆打了左转灯，前车轮已经向本车道转过来了，需要减速保持车距，如果不避让硬冲上去，极有可能发生事故。', 'https://images.juheapi.com/jztk/c1c2subject1/723.jpg'),
('724', '遇到这种情形怎样行驶？', '1', '停车让对方车辆通过', '开启左转向灯向左行驶', '开前照灯告知对方让行', '加速超越障碍后会车', '《道路交通安全法实施条例》第四十八条： 在没有中心隔离设施或者没有中心线的道路上，在有障碍的路段，<b>无障碍的一方先行；</b>但有障碍的一方已驶入障碍路段而无障碍的一方未驶入时，有障碍的一方先行。', 'https://images.juheapi.com/jztk/c1c2subject1/724.jpg'),
('725', '路中心的双黄实线作用是分隔对向交通流，在保证安全的前提下，可越线超车或转弯。', '2', '正确', '错误', '', '', '黄色虚线是中心线，可以跨越；黄色单实线就已经不能跨越了；黄色双实线是严格禁止压线或者跨越！', 'https://images.juheapi.com/jztk/c1c2subject1/725.jpg'),
('726', '交通信号灯由红灯、绿灯和黄灯组成。', '1', '正确', '错误', '', '', '《公安部令第123号》第二十六条：交通信号灯由红灯、绿灯、黄灯组成。红灯表示禁止通行，绿灯表示准许通行，黄灯表示警示。', NULL),
('727', '机动车上路行驶时，前排乘车人可不系安全带。', '2', '正确', '错误', '', '', '《道路交通安全法》第五十一条：机动车行驶时，驾驶人、乘坐人员应当按规定使用安全带，摩托车驾驶人及乘坐人员应当按规定戴安全头盔。', NULL),
('728', '驾驶机动车发生交通事故后当事人故意破坏、伪造现场、毁灭证据的，应当承担什么责任？', '4', '主要责任', '次要责任', '同等责任', '全部责任', '发生交通事故后当事人逃逸的，故意破坏、伪造现场、毁灭证据的，均承担全部责任。', NULL),
('729', '机动车仪表板上（如图所示）一直亮，表示发动机控制系统故障。', '1', '正确', '错误', '', '', '该标志表示发动机控制系统故障，因此本题正确。', 'https://images.juheapi.com/jztk/c1c2subject1/729.jpeg'),
('730', '年龄在60周岁以上，在一个记分周期结束后一年内未提交身体条件证明的，其机动车驾驶证将会被车辆管理所注销。', '1', '', '', '', '', '根据《机动车驾驶证申领和使用规定》第42条第6项：年龄在60周岁以上，在一个记分周期结束后一年内未提交身体条件证明的；或者持有大型客车、牵引车、城市公交车、中型客车、大型货车、无轨电车、有轨电车准驾车型，在两个记分周期结束后一年内未提交身体条件证明的；或者持有残疾人专用小型自动挡载客汽车准驾车型，在三个记分周期结束后一年内未提交身体条件证明的，车辆管理所应当注销其机动车驾驶证。被注销机动车驾驶证未超过两年的，机动车驾驶人考试科目一合格后，可以恢复驾驶资格。', NULL),
('731', '如图所示，在高速公路同方向三条机动车道中间车道行驶，车速不能低于多少？', '2', '100公里/小时', '90公里/小时', '110公里/小时', '60公里/小时', '《道路交通安全法实施条例》第七十八条：同方向有3条以上车道的，最左侧车道的最低车速为每小时110公里，中间车道的最低车速为每小时90公里。', 'https://images.juheapi.com/jztk/c1c2subject1/731.jpg'),
('732', '这个标志的含义是告示前方道路是单向通行路段。', '2', '正确', '错误', '', '', '警告标志：右侧绕行，注意安全。用以告示前方道路有障碍物，车辆应按标志指示减速慢行。设在道路障碍物前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/732.jpg'),
('733', '夜间在道路上会车时，距离对向来车多远将远光灯改用近光灯？', '2', '不必变换灯光', '150米以外', '100米以内', '50米以内', '《中华人民共和国道路交通安全法》第四十八条：<br/>在没有中心隔离设施或者没有中心线的道路上，机动车遇相对方向来车时应当遵守下列规定：<br/>(一)减速靠右行驶，并与其他车辆、行人保持必要的安全距离；<br/>(二)在有障碍的路段，无障碍的一方先行；但有障碍的一方已驶入障碍路段而无障碍的一方未驶入时，有障碍的一方先行；<br/>(三)在狭窄的坡路，上坡的一方先行；但下坡的一方已行至中途而上坡的一方未上坡时，下坡的一方先行；<br/>(四)在狭窄的山路，不靠山体的一方先行；<br/>(五)<b>夜间会车应当在距相对方向来车150米以外改用近光灯，</b>在窄路、窄桥与非机动车会车时应当使用近光灯。', NULL),
('734', '在这种雨天跟车行驶使用灯光，以下做法正确的是？', '3', '使用远光灯', '不能使用近光灯', '不能使用远光灯', '使用雾灯', '《道路交通安全法实施条例》第五十八条：机动车在夜间没有路灯、照明不良或者遇有雾、<b>雨</b>、雪、沙尘、冰雹等低能见度情况下行驶时，应当开启前照灯、示廓灯和后位灯，<b>但同方向行驶的后车与前车近距离行驶时，不得使用远光灯。</b>机动车雾天行驶应当开启雾灯和危险报警闪光灯。
<br/>图中情况为下雨天，正确的做法应该是打开近光灯，不能使用远光灯。因此本题答案应为C。', 'https://images.juheapi.com/jztk/c1c2subject1/734.jpg'),
('735', '安全头枕在发生追尾事故时，能有效保护驾驶人的什么部位？', '4', '腰部', '胸部', '头部', '颈部', '安全头枕是保护颈椎。', NULL),
('736', '行车中要文明驾驶，礼让行车，做到不开英雄车、冒险车、赌气车和带病车。', '1', '正确', '错误', '', '', '文明驾车，安全行驶。', NULL),
('737', '行车中突遇对方车辆强行超车，占据自己车道，正确的做法是什么？', '3', '挡住其去路', '保持原车速行驶', '尽可能减速避让、直至停车', '加速行驶', '行车要记得安全文明驾驶。后方要超车，尽可能减速避让、直至停车。', NULL),
('738', '机动车仪表板上（如图所示）这个符号表示什么？', '3', '远光灯开关', '近光灯开关', '车灯总开关', '后雾灯开关', '此为车灯总开关。', 'https://images.juheapi.com/jztk/c1c2subject1/738.jpeg'),
('739', '机动车仪表板上（如图所示）亮表示什么？', '4', '洗涤液不足', '制动液不足', '冷却系故障', '冷却液不足', 'A,B,C都巨不靠谱，只有D最合理。', 'https://images.juheapi.com/jztk/c1c2subject1/739.jpeg'),
('740', '（如图所示）这个符号的开关控制什么装置？', '3', '前风窗玻璃除霜或除雾', '后风窗玻璃刮水器及洗涤器', '前风窗玻璃刮水器及洗涤器', '后风窗玻璃除霜或除雾', '此为前风窗玻璃刮水器及洗涤器。关于如何区分前风窗玻璃刮水器及洗涤器和后风窗玻璃刮水器及洗涤器，你只需记住一点半弧形的图标是前风窗，四四方方的图标就是后风窗。', 'https://images.juheapi.com/jztk/c1c2subject1/740.jpeg'),
('741', '机动车仪表板上（如图所示）亮表示什么？', '1', '地板及迎面出风', '空气内循环', '空气外循环', '侧面及地板出风', '亲，这个真的选A。', 'https://images.juheapi.com/jztk/c1c2subject1/741.jpeg'),
('742', '机动车仪表板上（如图所示）亮表示什么？', '3', '发动机舱开启', '燃油箱盖开启', '两侧车门开启', '行李舱开启', '这个毫无疑问俩边门都开了。', 'https://images.juheapi.com/jztk/c1c2subject1/742.jpeg'),
('743', '路中心黄色虚线的含义是分隔对向交通流，在保证安全的前提下，可越线超车或转弯。', '1', '正确', '错误', '', '', '黄色虚线是中心线，可以跨越；黄色单实线就已经不能跨越了；黄色双实线是严格禁止压线或者跨越', 'https://images.juheapi.com/jztk/c1c2subject1/743.jpg'),
('744', '驾驶人要按照驾驶证载明的准驾车型驾驶车辆。', '1', '正确', '错误', '', '', '《公安部令第123号》规定：驾驶与准驾驶车型不符的机动车的违法行为，一次记12分。处罚200以上1000以下的罚款。', NULL),
('745', '在什么情况下不得行车？', '2', '车窗没关闭', '车门没关闭', '音响没关闭', '顶窗没关闭', '《道路交通安全法实施条例》第六十二条：驾驶机动车不得在车门、车厢没有关好时行车。', NULL),
('746', '机动车仪表板上（如图所示）亮表示什么？', '4', '充电电流过大', '蓄电池损坏', '电流表故障', '充电电路故障', '此为充电电路故障，一般没有故障这些都不会亮的，只有出故障了才会亮。', 'https://images.juheapi.com/jztk/c1c2subject1/746.jpeg'),
('747', '进入这个路口应该怎样做？', '3', '交替变换远近光灯提醒路口内车辆让行', '从路口内车辆前迅速插入', '让已在路口内的车辆先行', '鸣喇叭直接进入路口', '前方标志为环岛行驶，应该让已进入环岛内的车辆通行。当前车辆不能压白色网状区域。', 'https://images.juheapi.com/jztk/c1c2subject1/747.jpg'),
('748', '这个开关控制机动车哪个部位？', '2', '风窗玻璃除雾器', '风窗玻璃刮水器', '危险报警闪光灯', '照明、信号装置', '这个控制风窗玻璃刮水器的。风窗玻璃除雾器和危险报警闪光灯都是按钮形式的，照明、信号装置在你的左手边。', 'https://images.juheapi.com/jztk/c1c2subject1/748.jpg'),
('749', '如图所示，驾驶机动车行驶至桥梁涵洞时，以下做法正确的是什么？', '2', '加速，在对向车到达前通过', '减速靠右通过', '保持原速继续正常行驶', '鸣喇叭后加速通过', '如图所示，一辆车已经行至涵洞里了，而涵洞较窄，所以我方车辆应该减速靠右让对向车辆先行。', 'https://images.juheapi.com/jztk/c1c2subject1/749.jpg'),
('750', '在这种天气条件下行车如何使用灯光？', '1', '使用近光灯', '不使用灯光', '使用远光灯', '使用雾灯', '一般雪天能见度低，应该注意灯光的正确使用。一是开启近光灯，帮助驾驶员�望前方情况，使驾驶员对前方情况看得清楚一些。二是开启示廓灯和前后位灯，示意自己车辆的存在，使前后行驶的车辆，能够看到自己的具体位置及通行情况，方便他们采取相应的措施。', 'https://images.juheapi.com/jztk/c1c2subject1/750.jpg'),
('751', '如图所示，驾驶机动车遇前方车流行驶缓慢时，借用公交专用道超车是正确的。', '2', '', '', '', '', '公交车道没有规定时间限制的，其他车辆任何时候都不能占用。', 'https://images.juheapi.com/jztk/c1c2subject1/751.jpg'),
('752', '点火开关在LOCK位置拔出钥匙转向盘会锁住。', '1', '正确', '错误', '', '', 'LOCK-----（锁止），ACC------------ (断电)<br/>ON--------（通电），START--------（起动）。', 'https://images.juheapi.com/jztk/c1c2subject1/752.jpg'),
('753', '在这个路口怎样左转弯？', '2', '靠路口中心点右侧转弯', '靠路口中心点左侧转弯', '骑路口中心点转弯', '不能左转弯', '注意，本题中出现的红绿灯是最普通的三色灯，不具备指示通行方向的作用，在没有限制行进方向的路口，前方绿灯即可视为左右前均为放行状态。所以只要选择正确的左转方式就可以了，规定左转要靠路口中心点左侧转弯。所以应该选B。', 'https://images.juheapi.com/jztk/c1c2subject1/753.jpg'),
('754', '驾驶机动车在道路上发生交通事故，当事人不能自行移动车辆的，应当保护现场并立即报警。', '1', '', '', '', '', '《中华人民共和国道路交通安全法》中第七十条第一款规定，在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场。', NULL),
('755', '在高速公路上驾驶机动车，车辆发生故障后的处置方法，以下说法错误的是什么？', '3', '打开危险报警闪光灯，夜间还应开启示廓灯、后位灯', '在车后150米以外设置安全警告标志', '车内乘员应下车辅助将故障车辆推移到紧急停车带上', '所有人员需离开故障车辆，在紧急停车带或护栏以外安全位置报警并等候救援', '《道路交通安全法》规定：机动车在高速公路上发生故障时，驾驶人应当立即开启危险报警闪光灯，将车辆移至不妨碍交通的地点，并在车后150米设置警告标志。夜间还应当同时开启示廓灯和后位灯。驾驶人和乘车人应当迅速转移到右侧路肩上或者应急车道内。
<br/>如果发生故障无法正常行驶的，应当由救援车、清障车拖曳、牵引。而不是车内乘员将其推到紧急停车带上。', NULL),
('756', '夜间驾驶机动车在没有中心隔离设施或者没有中心线的道路上行驶，以下哪种情况下应当改用近光灯？', '2', '接近没有交通信号灯控制的交叉路口时', '与对向机动车会车时', '接近人行横道时', '城市道路照明条件不良时', '夜间驾驶机动车在没有中心隔离设施或者没有中心线的道路上行驶，在会车时，使用远光灯，会使对方看不清路况从而容易发生事故，应该切换近光灯。', NULL),
('757', '这个标志的含义是警告车辆驾驶人前方是学校区域。', '2', '正确', '错误', '', '', '图中是注意儿童警告标志。用以警告车辆驾驶人减速慢行，注意儿童。设在小学、幼儿园、少年宫等儿童经常出入地点前适当位置。题目描述错误，因此答案为错。
<br/>
<br/>【拓展延伸】
<br/>要注意区分学校标志。学校标志通常是由注意儿童标志和“前方学校，减速慢行”提示语组成，不要混淆。
<br/><p><img src=http://tp.mnks.cn/tp_136.jpg>
<br/>注意儿童
<br/></p>', 'https://images.juheapi.com/jztk/c1c2subject1/757.jpg'),
('758', '年龄在60周岁以上的驾驶人多长时间提交一次身体条件证明？', '4', '每3年', '每2年', '每6个月', '每1年', '记住吧', NULL),
('759', '驾驶这种机动车上路行驶属于什么行为？', '3', '违章行为', '违规行为', '违法行为', '犯罪行为', '《道路交通安全法》第十一条规定：机动车号牌应当按照规定悬挂并保持清晰、完整，不得故意遮挡、污损。
<br/>图中机动车的车号牌被故意遮挡住了，违反了《道路交通安全法》的规定，因此属于违法行为。本题答案应为C。', 'https://images.juheapi.com/jztk/c1c2subject1/759.jpg'),
('760', '持有大型客车、牵引车、城市公交车、中型客车、大型货车驾驶证的驾驶人从业单位等信息发生变化的，应当在信息变更后三十日内，向驾驶证核发地车辆管理所备案。', '1', '', '', '', '', '机动车驾驶人联系电话、联系地址等信息发生变化，以及持有大型客车、牵引车、城市公交车、中型客车、大型货车准驾车型驾驶证的驾驶人从业单位等信息发生变化，应在信息变更后三十日内，向驾驶证<b>核发地</b>车辆管理所备案。', NULL),
('761', '驾驶人的驾驶证损毁后不得驾驶机动车。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第二十八条：机动车驾驶人在机动车驾驶证丢失、损毁、超过有效期或者被依法扣留、暂扣期间以及记分达到12分的，不得驾驶机动车。', NULL),
('762', '持小型汽车驾驶证的驾驶人在下列哪种情况下需要接受审验？', '2', '一个记分周期末', '有效期满换发驾驶证时', '记分周期未满分', '记分周期满12分', '小型汽车、摩托车等车型驾驶人审验的情形有两种：　　
<br/>一是发生交通事故造成人员死亡承担同等以上责任未被吊销驾驶证的，应当在记分周期结束后三十日内到公安交管部门接受审验；
<br/><b>二是驾驶证转到异地或者有效期满换证时，应当到公安交管部门接受审验。</b>　　
<br/>需要提醒的是，驾驶人没有按照规定参加审验仍驾驶机动车的，公安交管部门将处200元以上500元以下罚款。', NULL),
('763', '驾驶机动车应在变更车道的同时开启转向灯。', '2', '', '', '', '', '机动车超车时，应当<b>提前</b>开启左转向灯、变换使用远、近光灯，所以转向灯必须要提前打。', NULL),
('764', '驾驶机动车发生故障或事故不能正常行驶时，应立即打开危险报警闪光灯。', '1', '', '', '', '', '《道路交通安全法》规定：机动车在高速公路上发生故障时，驾驶人应当立即开启危险报警闪光灯，将车辆移至不妨碍交通的地点，并在车后150米设置警告标志。夜间还应当同时开启示廓灯、后位灯和危险报警闪光灯。驾驶人和乘车人应当迅速转移到右侧路肩上或者应急车道内。', NULL),
('765', '酒后驾驶发生重大交通事故被依法追究刑事责任的人不能申请机动车驾驶证。', '1', '正确', '错误', '', '', '饮酒后或者醉酒驾驶机动车发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证，终生不得重新取得机动车驾驶证。', NULL),
('766', '机动车登记证书丢失后应及时补办，避免被不法分子利用。', '1', '', '', '', '', '机动车登记证书丢失后，一旦被他人非法利用很容易造成重大损失。一定要在丢失后及时补办。', NULL),
('767', '在车门、车厢没有关好时不要驾驶机动车起步。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第六十二条：驾驶机动车不得在车门、车厢没有关好时行车。', NULL),
('768', '驾驶人连续驾驶不得超过多长时间？', '4', '6小时', '8小时', '10小时', '4小时', '《道路交通安全法实施条例》第六十二条：连续驾驶机动车超过4小时应停车休息，停车休息时间不少于20分钟。', NULL),
('769', '如图所示，在高速公路同方向三条机动车道右侧车道行驶，车速不能低于多少？', '4', '80公里/小时', '100公里/小时', '110公里/小时', '60 公里/小时', '高速公路如果有三条车道：
<br/>最右侧车道限速范围是60km/h~90km/h
<br/>中间车道限速范围是90km/h~110km/h
<br/>最左边车道是超车道，最低时速要高于110km/h
<br/>因此在最右侧车道上行驶，车速应该不低于60km/h，选择B。', 'https://images.juheapi.com/jztk/c1c2subject1/769.jpg'),
('770', '机动车在道路上变更车道需要注意什么？', '3', '开启转向灯迅速向左转向', '进入左侧车道时适当减速', '不能影响其他车辆正常行驶', '尽快加速进入左侧车道', '《道路交通安全法实施条例》第四十四条：在道路同方向划有2条以上机动车道的，变更车道的机动车不得影响相关车道内行驶的机动车的正常行驶。', NULL),
('771', '点火开关在START位置起动机起动。', '1', '正确', '错误', '', '', 'LOCK-----（锁止），ACC------------ (断电)
<br/>ON--------（通电），START--------（起动）', 'https://images.juheapi.com/jztk/c1c2subject1/771.jpg'),
('772', '违反交通信号灯通行的一次记6分。', '1', '正确', '错误', '', '', '《公安部令第123号》规定，驾驶机动车违反道路交通信号灯通行的，一次记6分 。', NULL),
('773', '行至漫水路时，应当怎样做？', '2', '空挡滑行', '低速通过涉水路段', '高速通过，减少涉水时间', '高挡位低速通过', '《中华人民共和国道路交通安全法实施条例》第六十四条：<b>机动车行经漫水路或者漫水桥时，应当停车察明水情，确认安全后，低速通过。</b>', NULL),
('774', '如图所示，通过有这个标志的路口时应该减速让行。', '2', '正确', '错误', '', '', '图中为停车让行标志。表示车辆必须在停止线以外停车瞭望，确认安全后，才准许通行。题目描述错误，因此本题答案为错。
<br/>
<br/>【拓展延伸】
<br/><p><img src=http://tp.mnks.cn/tp_176.jpg>
<br/>停车让行
<br/><img src=http://tp.mnks.cn/tp_177.jpg>
<br/>减速让行</p>', 'https://images.juheapi.com/jztk/c1c2subject1/774.jpg'),
('775', '机动车仪表板上（如图所示）亮，提示发电机向蓄电池充电。', '2', '正确', '错误', '', '', '是蓄电池坏了不是电量不足，所以不是充电就能解决问题的，所以应该是充电系统出现故障。', 'https://images.juheapi.com/jztk/c1c2subject1/775.jpeg'),
('776', '驾驶机动车向右变更车道前应仔细观察右侧车道车流情况的原因是什么？', '2', '准备抢行', '判断有无变更车道的条件', '迅速变更车道', '准备迅速停车', '仔细观察是为了判断是否可以变道，也就是有无变更车道的条件。如果没有变更车道的条件，应该放弃变道等候合适时机；如果有变更车道的条件，驾驶员打开转向灯后，再伺机变更车道。', NULL),
('777', '如图所示，以下哪种情况可以超车?(图51a.51b. 51c. 51d)', '1', '51a', '51b', '51c', '51d', '如图所示，能够超车的必须满足两个条件：一是必须在虚线的一侧，而是对向没有来车。满足这个两个条件的就只有51a了。', 'https://images.juheapi.com/jztk/c1c2subject1/777.jpg'),
('778', '如图所示，机动车遇行人正在通过人行横道时，要停车让行，是因为行人享有优先通行权。', '1', '正确', '错误', '', '', '《道路交通安全法》第四十七条：<b>机动车行经人行横道时，应当减速行驶；遇行人正在通过人行横道，应当停车让行。</b>机动车行经没有交通信号的道路时，遇行人横过道路，应当避让。', 'https://images.juheapi.com/jztk/c1c2subject1/778.jpg'),
('779', '年龄在50周岁以上的机动车驾驶人，应当每年进行一次身体检查，并向公安机关交通管理部门申报身体条件情况。', '2', '', '', '', '', '修改后的《机动车驾驶证申领和使用规定》(公安部令第139号)中第三十条规定：年龄在70周岁以上的机动车驾驶人，应当每年进行一次身体检查，在记分周期结束后三十日内，提交县级或者部队团级以上医疗机构出具的有关身体条件的证明。', NULL),
('780', '驾驶机动车发生交通事故未造成人身伤亡的，责任明确双方无争议时，应当如何处置？', '4', '保护好现场再协商', '不要移动车辆', '疏导其他车辆绕行', '撤离现场自行协商', '《中华人民共和国道路交通安全法》第七十条：明确规定在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜；不即行撤离现场的，应当迅速报告执勤的交通警察或者公安机关交通管理部门。', NULL),
('781', '行驶过程中发现车门未关好，应及时关闭车门，否则车辆在转弯等激烈运动过程中会造成人员或货物被甩到车外。', '1', '', '', '', '', '行车过程中，车门一定要关紧，否则很容易将车内物品、人甩出。', NULL),
('782', '驾驶机动车超车时，可以鸣喇叭替代开启转向灯。', '2', '', '', '', '', '机动车超车时，应当提前开启左转向灯、变换使用远、近光灯，打转向灯是必要的步骤。', NULL),
('783', '交通肇事致一人以上重伤，负事故全部或者主要责任，并具有下列哪种行为的，构成交通肇事罪?', '3', '未带驾驶证', '未报警', '无驾驶资格驾驶机动车辆的', '未抢救受伤人员', '可能构成交通壁事罪。例如，交通壁事致一人受伤(属于一般事故)，负事故全部或者主要责任，并具有酒后、无证驾驶、严重超载等情形之一的，以交通肇事罪处罚。', NULL),
('784', '这个导向箭头是何含义？', '4', '指示向左变道', '指示前方直行', '指示前方掉头', '指示前方右转弯', '请记住了哦', 'https://images.juheapi.com/jztk/c1c2subject1/784.jpg'),
('785', '在暂住地初次申领机动车驾驶证的，不能直接申领大型货车驾驶证。', '1', '', '', '', '', '在暂住地初次申领机动车驾驶证的，是可以直接申领大型货车驾驶证的。
<br/>根据2016年4月1日起开始实行的驾驶证新规，取消了异地考驾照对A/B证的限制，A/B也可以在暂住地申领了，但是需要有当地的居住证或者暂住证。
<br/>题目描述有误，因此本题答案应为错误。', NULL),
('786', '驾驶人户籍迁出原车辆管理所需要向什么地方的车辆管理所提出申请？', '4', '迁出地', '居住地', '所在地', '迁入地', '《公安部令第123号》第四十九条：机动车驾驶人户籍迁出原车辆管理所管辖区的，应当向迁入地车辆管理所申请换证。', NULL),
('787', '道路上划设这种标线的车道内允许下列哪类车辆通行？', '1', '公交车', '私家车', '出租车', '公务用车', '请注意地面的字，公交专用车道。所以是只有公交车才能行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/787.jpg'),
('788', '驾驶机动车通过未设置交通信号灯的交叉路口时，下列说法错误的是什么？', '4', '转弯的机动车让直行的车辆、行人先行', '没有交通标志、标线控制时，在进入路口前停�望，让右方道路的来车先行', '相对方向行驶的右转弯机动车让左转弯的车辆先行', '相对方向行驶的左转弯机动车让右转弯的车辆先行', '驾驶机动车通过未设置交通信号灯的交叉路口时：<br/>转弯的机动车应当让直行的车辆、行人先行；<br/>没有交通标志、标线控制时，在进入路口前停车瞭望，让右方道路的来车先行；<br/><b>相对方向行驶的右转弯机动车让左转弯的车辆先行。</b><br/>题目问的是错误的，所以选择D要看清题目哦！', NULL),
('789', '如图所示，在这起交通事故中，以下说法正确的是什么？ ', '1', 'A车负全部责任', 'B车负全部责任', '各负一半的责任', 'B车负主要责任', '这起交通事故主要是因为A车绕开障碍物时未提前观察减速为B车让行造成的，所以A车全责。', 'https://images.juheapi.com/jztk/c1c2subject1/789.jpg'),
('790', '如图所示，驾驶机动车遇到这种情况，可以轻按喇叭提醒前方非机动车和行人后方有来车。', '1', '', '', '', '', '前方有行人和自行车，道路较窄，驾驶机动车遇到这种情况，可以轻按喇叭提醒前方非机动车和行人后方有来车，这样更加安全。', 'https://images.juheapi.com/jztk/c1c2subject1/790.jpg'),
('791', '前方路口这种信号灯亮表示什么意思？', '3', '加速左转', '禁止右转', '路口警示', '加速直行', '黄灯为警示灯，所以是路口警示。', 'https://images.juheapi.com/jztk/c1c2subject1/791.jpg'),
('792', '机动车驾驶证被依法扣押、扣留、暂扣期间能否申请补发？', '4', '可以申请', '扣留期间可以临时申请', '暂扣期间可以临时申请', '不得申请补发', '机动车驾驶证被依法扣押、扣留或者暂扣期间，机动车驾驶人不得申请补发。', NULL),
('793', '这个标志的含义是提醒车辆驾驶人前方是桥头跳车较严重的路段。', '2', '正确', '错误', '', '', '此为<b>驼峰桥标志</b>。用以提醒车辆驾驶人谨慎驾驶。设在拱度很大，影响视距的驼峰桥以前适当位置。题目描述错误，因此本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/793.jpg'),
('794', '驾驶机动车行驶过程中，遇道路养护车辆从本车道逆向驶来时，以下做法正确的是什么？', '1', '靠边减速或停车让行', '在原车道继续行驶', '占用非机动车道行驶', '鸣喇叭示意其让道', '《中华人民共和国道路交通安全法》第五十四条条明确规定：<b>道路养护车辆、工程作业车进行作业时，在不影响过往车辆通行的前提下，其行驶路线和方向不受交通标志、标线限制，过往车辆和人员应当注意避让。</b>
<br/>如果道路养护车逆向驶来，一定要靠边减速或停车让行，避免正向相撞。', NULL),
('795', '如图所示，在环岛交叉路口发生的交通事故中，应由A车负全部责任。', '1', '', '', '', '', 'B在环岛内，A要驶进环岛。按照规定，驶入环岛的车辆不能影响环岛内车辆的正常通行。而A车与B车相撞，没有为B车让行，所以A车负全责。', 'https://images.juheapi.com/jztk/c1c2subject1/795.jpg'),
('796', '申请小型汽车汽车驾驶证的，年龄应在18周岁以上70周岁以下。', '1', '', '', '', '', '《公安部令第123号》第十一条：1、申请小型汽车等准驾车型在18周岁以上、70周岁以下；2、申请低速载货汽车、三轮汽车等准驾车型的，在18周岁以上，60周岁以下。此题正确。本题车管所已经修正。', NULL),
('797', '上道路行驶的机动车驾驶人未携带机动车驾驶证、行驶证的，除扣留机动车外，并受到什么处罚？', '2', '警告', '罚款', '拘留', '吊销驾驶证', '未携带驾驶证的，公安机关交通管理部门应当扣留机动车，通知当事人提供驾驶证，并可以依照道路交通法第九十条的规定予以200元的罚款。', NULL),
('798', '车辆进入山区道路后，要特别注意“连续转弯”标志，并主动避让车辆及行人，适时减速和提前鸣喇叭。', '1', '正确', '错误', '', '', '山区本来就是有山的地势，自然就会有坡度，以及拐弯，连续的弯路，容易影响行车的视线，所以要注意“连续转弯”的标志，以防在转弯处突然出现对向来车，为了安全，当然要适时减速和提前鸣喇叭，以提醒车辆与行人。', NULL),
('799', '仪表显示当前车速是20公里/小时。', '2', '正确', '错误', '', '', '图显示的单位是 1/min×1000，意思是每一分钟（注意是分钟）1000转。转速指针为2，即2000转每分钟。<br/>而车速还要根据车轮大小来确定。【2×车轮半径×3.14（圆周率）】车轮周长×转速。<br/>此图，应该是<b>转速标示图</b>。', 'https://images.juheapi.com/jztk/c1c2subject1/799.jpg'),
('800', '如图所示，A车货物掉落，导致B车与掉落货物发生碰撞，以下说法正确的是什么？', '2', 'B车自负责任', 'A车负全部责任', '各负一半责任', '偶然事件，不可避免', '造成该事故的原因是货车上货物固定不牢，货物遗洒导致后面的机动车事故，货车应负全部责任。 
<br/>
<br/>【拓展延伸】 
<br/>很多人认为后车跟车距离过近也要承担事故责任，但后方轿车在事故发生前与货车的距离是未知的，因为货车货物掉落，极有可能是在紧急刹车后，货物固定不牢，在惯性作用下向后洒落，砸到了后方的轿车。货车紧急刹车，但后车躲避不及，本来保持一定车距，但只够避免追尾，却没料到会被货物砸到。大家可以这样考虑。', 'https://images.juheapi.com/jztk/c1c2subject1/800.jpg')
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('801', '如图所示，铁路道口禁止掉头的原因是什么？', '4', '有铁路道口标志', '有铁路道口信号灯', '铁路道口车流量大', '容易引发事故', '铁道路口行车条件比较复杂，掉头容易引发事故。', 'https://images.juheapi.com/jztk/c1c2subject1/801.jpg'),
('802', '为什么规定辅路车让主路车先行？', '1', '主路车流量大、速度快', '辅路车便于观察', '主路车流量小、速度快', '辅路车速度快', '正因为车流量大才成为主路，主路为干线，辅路为支线，支线车让干线车先行。一般主路车道较多，车速较快，所以辅路车要让主路车先行。', NULL),
('803', '发动机起动后仪表板上（如图所示）亮表示什么？', '2', '发动机主油道堵塞', '发动机机油压力过低', '发动机曲轴箱漏气', '发动机机油压力过高', '像茶壶一样的就是机油的标志，各位记住就是啦。 该指示灯用来显示发动机内机油的压力状况。打开钥匙门，车辆开始自检时，指示灯点亮，启动后熄灭。该指示灯常亮，说明该车发动机机油压力低于规定标准，需要维修。', 'https://images.juheapi.com/jztk/c1c2subject1/803.jpeg'),
('804', '如图所示，驾驶机动车遇到这种情况，以下做法正确的是什么？', '1', '减速慢行、鸣喇叭示意', '为拓宽视野，临时占用左侧车道行驶', '加速行驶', '停车观察', '驾驶机动车遇到这种情况，应该：减速慢行、鸣喇叭示意。', 'https://images.juheapi.com/jztk/c1c2subject1/804.jpg'),
('805', '驾驶机动车变更车道时，以下做法正确的是什么？', '2', '开启转向灯的同时变更车道', '在道路同方向划有2条以上机动车道的，不得影响相关车道内行驶的机动车的正常行驶', '在车辆较少路段，可以随意变更车道', '遇前方道路拥堵，可以向应急车道变更', '《道路交通安全法》规定：驾驶机动车变更车道时，在道路同方向划有2条以上机动车道的，不得影响相关车道内行驶的机动车的正常行驶。', NULL),
('806', '驾驶机动车下长坡时，利用惯性滑行可以减少燃油消耗，值得提倡。', '2', '', '', '', '', '下长坡时，如果利用惯性滑行会导致刹车片过热，从而造成刹车失灵，非常危险，绝对不能提倡。', NULL),
('807', '这个标志的含义是提醒车辆驾驶人前方是过水路面或漫水桥路段。', '1', '正确', '错误', '', '', '警告标志：过水路面，应当减速慢行。用以提醒车辆驾驶人谨慎慢行。设在过水路面或漫水桥路段以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/807.jpg'),
('808', '因避让特种车辆而发生违法行为，被电子警察拍到时，可向交管部门复议。', '1', '', '', '', '', '根据规定，路上碰见特种车辆需要避让。因此避让特种车辆是遵守交通法规的行为，如果因此被电子警察拍到，是可以申请复议的。', NULL),
('809', '驾驶机动车上路行驶应当按规定悬挂号牌。', '1', '正确', '错误', '', '', '《道路交通安全法》第十一条：驾驶机动车上道路行驶，<b>应当悬挂机动车号牌</b>，放置检验合格标志、保险标志，并随车携带机动车行驶证。因此本题答案应为正确。', NULL),
('810', '已经达到报废标准的机动车经大修后可以上路行驶。', '2', '正确', '错误', '', '', '《道路交通安全法》第一百条规定：驾驶拼装的机动车或者已达到报废标准的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废，处200元以上2000元以下罚款，并吊销机动车驾驶证。 
<br/>已经达到报废标准的车，无论是否经过大修都不能重新开上路。本题描述有误。因此本题答案应为错误。', NULL),
('811', '打开左转向灯开关，（如图所示）亮起。', '2', '正确', '错误', '', '', '图中朝右的箭头亮起，表示打开的是右转向灯。', 'https://images.juheapi.com/jztk/c1c2subject1/811.jpeg'),
('812', '发生交通事故后，当事人故意破坏、伪造现场、毁灭证据的，承担全部责任。', '1', '', '', '', '', '发生交通事故后，当事人故意破坏、伪造现场、毁灭证据的，导致后期无法采证的，应该负全部责任。', NULL),
('813', '驾驶机动车在没有道路中心线的道路上行驶，应该在道路的左侧通行', '2', '正确', '错误', '', '', '《交通安全法》第三十六条:根据道路条件和通行需要，道路划分为机动车道、非机动车道和人行道的，机动车、非机动车、行人实行分道通行。没有划分机动车道、非机动车道和人行道的，机动车在道路中间通行，非机动车和行人在道路两侧通行。', NULL),
('814', '发动机号码、车辆识别代号因磨损、锈蚀、事故等原因辨认不清或者损坏的，可以向登记地车辆管理所申请备案。', '1', '', '', '', '', '《机动车登记规定》：发动机号码、车辆识别代号因磨损、锈蚀、事故等原因辨认不清或者损坏的，可以向登记地车辆管理所申请备案。', NULL),
('815', '机动车仪表板上（如图所示）亮，表示驻车制动器操纵杆可能没松到底。', '2', '正确', '错误', '', '', '图中标志表示行车制动系统异常或故障，并非驻车制动器操纵杆没松到底。题目描述错误，因此答案为错。
<br/><p><img src=http://tp.mnks.cn/tp_374.jpg>
<br/>行车制动故障
<br/><img src=http://tp.mnks.cn/tp_376.jpg>
<br/>驻车制动没松</p>', 'https://images.juheapi.com/jztk/c1c2subject1/815.jpeg'),
('816', '车辆在山区上坡路驾驶，减挡要及时、准确、迅速，避免拖挡行驶导致发动机动力不足。', '1', '正确', '错误', '', '', '上坡前要减档，避免拖挡行驶导致的发动机动力不足而熄火。', NULL),
('817', '机动车仪表板上（如图所示）亮表示什么？', '1', '没有系好安全带', '安全带出现故障', '安全带系得过松', '已经系好安全带', '此为没有系好安全带。', 'https://images.juheapi.com/jztk/c1c2subject1/817.jpeg'),
('818', '年龄在60周岁以上的机动车驾驶人，应当每年进行一次身体检查的目的是什么？', '4', '体现对老年人的关心', '例行程序仅供参考', '检查是否患有老年常见病', '检查是否患有妨碍安全驾驶的疾病', '根据《机动车驾驶证申领使用规定》第四十八条规定年龄在60周岁以上或者持有大型客车、牵引车、城市公交车、中型客车、大型货车、无轨电车、有轨电车准驾车型的机动车驾驶人，应当每年进行一次身体检查，在记分周期结束后十五日内，提交县级或者部队团级以上医疗机构出具的有关身体条件的证明，检查是否患有妨碍安全驾驶的疾病。', NULL),
('819', '这个标志的含义是提醒车辆驾驶人前方路面颠簸或有桥头跳车现象。', '1', '正确', '错误', '', '', '警告标志：路面不平，提醒车辆驾驶人减速慢行。', 'https://images.juheapi.com/jztk/c1c2subject1/819.jpg'),
('820', '图中圈内的路面标记是什么标线？', '1', '人行横道线', '减速让行线', '停车让行线', '路口示意线', '人行横道线俗称斑马线,是由一条一条的白色线组成的主要是供行人穿越马路之用', 'https://images.juheapi.com/jztk/c1c2subject1/820.jpg'),
('821', '仪表显示油箱内存油量已在警告线以内。', '1', '正确', '错误', '', '', '左边可以看到那个加油的机器，指针到红色区，说明油量不足了。', 'https://images.juheapi.com/jztk/c1c2subject1/821.jpg'),
('822', '遇到这种情况可以优先通行。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第四十八条： 在没有中心隔离设施或者没有中心线的道路上，在有障碍的路段，无障碍的一方先行；但有障碍的一方已驶入障碍路段而无障碍的一方未驶入时，有障碍的一方先行。', 'https://images.juheapi.com/jztk/c1c2subject1/822.jpg'),
('823', '驾驶机动车在高速公路发生故障，需要停车排除故障时，以下做法先后顺序正确的是？ ①放置警告标志，转移乘车人员至安全处，迅速报警②开启危险报警闪光灯③将车辆移至不妨碍交通的位置④等待救援', '4', '④③①②', '①②③④', '③②①④', '②③①④', '驾驶机动车在高速公路发生故障，需要停车排除故障时，应当进行如下顺序的操作：开启危险报警闪光灯；将车辆移至不妨碍交通的位置；放置警告标志，转移乘车人员至安全处，迅速报警；等待救援。', NULL),
('824', '行车中仪表板上（如图所示）亮表示什么？', '1', '发动机温度过高', '发动机冷却系故障', '发动机润滑系故障', '发动机温度过低', '此标志亮起说明发动机水温过高，可能是冷却液不足引起的。', 'https://images.juheapi.com/jztk/c1c2subject1/824.jpeg'),
('825', '如图所示，在高速公路最左侧车道行驶，想驶离高速公路，以下说法正确的是什么？', '3', '立即减速后右变更车道', '找准机会一次变更到最右侧车道', '每次变更一条车道，直到最右侧车道', '为了快速变更车道，可以加速超越右侧车辆后变更车道', '变更车道，每次只能变更一条车道，变更之后需行驶一段距离，再变道。不可以连续变更车道。', 'https://images.juheapi.com/jztk/c1c2subject1/825.jpg'),
('826', '驾驶机动车下陡坡、转弯、掉头时，最高速度不能超过多少？', '3', '50公里/小时', '60公里/小时', '30公里/小时', '40公里/小时', '机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 <br/>（一）进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；　　 <br/>（二）<b>掉头、转弯、下陡坡</b>时；　　 <br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 <br/>（四）在冰雪、泥泞的道路上行驶时；', NULL),
('827', '驾驶机动车行经漫水路或者漫水桥时，应当停车察明水情。', '1', '', '', '', '', '机动车行经漫水路或者漫水桥时，应当停车察明水情，确认安全后，低速通过。', NULL),
('828', '关于机动车灯光的使用，以下说法正确的是什么？', '2', '机动车灯光的作用仅仅是为了在夜间照明', '机动车灯光一个重要的作用是提示其他机动车驾驶人和行人', '夜间驾驶机动车在照明条件良好的路段可以不使用灯光', '夜间驾驶机动车在照明条件良好的路段必须使用远光灯', '车辆的灯光不仅仅是在光线不足的情况下提供照明，而更重要的是起到警示作用，即使在白天，人们也会首先注意到亮着灯的车辆，不管是行人还是其他车辆的司机。', NULL),
('829', '打开右转向灯开关，（如图所示）亮起。', '2', '正确', '错误', '', '', '图中朝左的箭头亮起，表示打开的是左转向灯。', 'https://images.juheapi.com/jztk/c1c2subject1/829.jpeg'),
('830', '在超越前车时，提前开启左转向灯，变换使用远、近光灯或者鸣喇叭是为了什么？', '3', '仅提醒前车', '仅提醒后车', '提醒后车以及前车', '提醒行人', '超车时交替使用远近光灯或者鸣喇叭是为了提醒前车，开启左转向灯是为了提醒后车，所以是为了提醒后车和前车。', NULL),
('831', '机动车仪表板上（如图所示）亮时，提醒驾驶人安全带插头未插入锁扣。', '1', '正确', '错误', '', '', '该指示灯用来显示安全带是否处于锁止状态，当该灯点亮时，说明安全带没有及时的扣紧。有些车型会有相应的提示音。当安全带被及时扣紧后，该指示灯自动熄灭。', 'https://images.juheapi.com/jztk/c1c2subject1/831.jpeg'),
('832', '如图所示，在这种情况下通过路口，交替使用远近光灯的目的是什么？', '1', '提示其他交通参与者注意来车', '检查灯光是否能正常使用', '准备变更车道', '超车前提示前车', '如图所示，在没有交通信号灯控制的路口，应当交替使用远近光灯示意，提示横向车道上的来车注意。', 'https://images.juheapi.com/jztk/c1c2subject1/832.jpg'),
('833', '驾驶机动车下陡坡时不得有哪些危险行为？', '1', '空挡滑行', '低挡行驶', '制动减速', '提前减挡', '《道路交通安全法实施条例》第六十二条规定，驾驶机动车下陡坡时不得熄火或者空挡滑行。', NULL),
('834', '驾驶机动车下长坡时，仅靠行车制动器制动，容易引起行车制动器失灵。', '1', '', '', '', '', '汽车制动分为三种：1、行车制动，就是脚下的制动踏板，控制四轮；2、驻车制动，就是手刹车，停车时防止前滑后溜；3、发动机制动，也就是抢档，用于刹车失灵，在行车制动失灵时用，一级一级减档，从高到底，利用发动机变速箱的原理使车速降下来。<b>下长坡时，驾驶员长时间使用行车制动器，易造成制动器热衰退，汽车的制动效能变差。</b>', NULL),
('835', '驾驶机动车造成重大交通事故后逃逸，构成犯罪的，由公安机关交通管理部门吊销机动车驾驶证，且终生不得重新取得机动车驾驶证。', '1', '', '', '', '', '<b>《道路交通安全法》第一百零一条规定，造成交通事故后逃逸的，由公安机关交通管理部门吊销机动车驾驶证，且终身不得重新取得机动车驾驶证。</b>上述规定泛指各类交通事故，只要是造成交通事故后逃逸的，就应当由公安机关交通管理部门吊销其机动车驾驶证，并且终身不得重新取得驾驶证，而不论其造成交通事故后果的大小。也就是说，法律规定惩罚的交通肇事逃逸行为，与驾驶人造成交通事故后果的轻重无关；构成犯罪的，依法追究刑事责任。', NULL),
('836', '这个标志是何含义？', '1', '向左转弯', '禁止直行', '直行车道', '单行路', '向左转弯：表示只准一切车辆向左转弯。此标志设在车辆必须向左转弯的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/836.jpg'),
('837', '这个标志的含义是警告车辆驾驶人注意前方设有信号灯。', '1', '正确', '错误', '', '', '警告标志警告车辆驾驶人注意前方设有信号灯。用以警告车辆驾驶人注意前方路段设有信号灯，应依信号灯指示行车。', 'https://images.juheapi.com/jztk/c1c2subject1/837.jpg'),
('838', '驾驶人在下列哪种情况下不能驾驶机动车？', '3', '喝咖啡后', '喝牛奶后', '饮酒后', '喝茶后', '2011年2月25日，十一届全国人大常委会第十九次会议表决通过了刑法修正案（八）。首次将醉酒驾车这种严重危害群众利益的行为规定为犯罪，并于5月1日正式实施。具体规定为：在道路上驾驶机动车追逐竞驶，情节恶劣的，或者在道路上醉酒驾驶机动车的，处拘役，并处罚金。
<br/>国家严禁机动车驾驶员酒后驾驶，因此本题应选A。', NULL),
('839', '驾驶人有下列哪种违法行为一次记6分？', '3', '使用其他车辆行驶证', '车速超过规定时速50%以上', '违法占用应急车道行驶', '饮酒后驾驶机动车', '（公安部令123号）机动车驾驶人有下列违法行为之一，一次记6分：<br/>(一)机动车驾驶证被暂扣期间驾驶机动车的;<br/>(二)驾驶机动车违反道路交通信号灯通行的;<br/>(三)驾驶营运客车(不包括公共汽车)、校车载人超过核定人数未达20%的，或者驾驶其他载客汽车载人超过核定人数20%以上的;<br/>(四)驾驶中型以上载客载货汽车、校车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速未达20%的;<br/>(五)驾驶中型以上载客载货汽车、校车、危险物品运输车辆在高速公路、城市快速路以外的道路上行驶或者驾驶其他机动车行驶超过规定时速20%以上未达到50%的;<br/>(六)驾驶货车载物超过核定载质量30%以上或者违反规定载客的;<br/>(七)驾驶营运客车以外的机动车在高速公路车道内停车的;<br/><b>(八)驾驶机动车在高速公路或者城市快速路上违法占用应急车道行驶的;</b><br/>(九)低能见度气象条件下，驾驶机动车在高速公路上不按规定行驶的;<br/>(十)驾驶机动车运载超限的不可解体的物品，未按指定的时间、路线、速度行驶或者未悬挂明显标志的;<br/>(十一)驾驶机动车载运爆炸物品、易燃易爆化学物品以及剧毒、放射性等危险物品，未按指定的时间、路线、速度行驶或者未悬挂警示标志并采取必要的安全措施的;<br/>(十二)以隐瞒、欺骗手段补领机动车驾驶证的;<br/>(十三)连续驾驶中型以上载客汽车、危险物品运输车辆以外的机动车超过4小时未停车休息或者停车休息时间少于20分钟的;<br/>(十四)驾驶机动车不按照规定避让校车的。', NULL),
('840', '这个标志是何含义？', '2', '注意长时鸣喇叭', '无人看守铁路道口', '有人看守铁路道口', '多股铁路与道路相交', '有火车形状的，为无人看守的铁路口，还有一个栅栏形式的图片为有人看守的铁路口。', 'https://images.juheapi.com/jztk/c1c2subject1/840.jpg'),
('841', '机动车仪表板上（如图所示）亮表示发动机可能机油量不足。', '1', '正确', '错误', '', '', '图中的标志是机油的标志。 该指示灯用来显示发动机内机油的压力状况，该指示灯常亮，说明该车发动机机油压力低于规定标准，需要维修。', 'https://images.juheapi.com/jztk/c1c2subject1/841.jpeg'),
('842', '不得驾驶具有安全隐患的机动车上道路行驶。', '1', '正确', '错误', '', '', '《道路交通安全法》第二十一条：驾驶人驾驶机动车上道路行驶前，应当对机动车的安全技术性能进行认真检查；<b>不得驾驶安全设施不全或者机件不符合技术标准等具有安全隐患的机动车。</b>因此本题答案应为正确。', NULL),
('843', '服用国家管制的精神药品可以短途驾驶机动车。', '2', '正确', '错误', '', '', '《道路交通安全法》第二十二条规定：饮酒、<b>服用国家管制的精神药品</b>或者麻醉药品，或者患有妨碍安全驾驶机动车的疾病，或者过度疲劳影响安全驾驶的，不得驾驶机动车。本题题干表述有误，因此本题答案应为错误。', NULL),
('844', '已注册登记的机动车，机动车所有人住所在车辆管理所管辖区域内迁移或者机动车所有人姓名（单位名称）、联系方式变更的，应当向登记地车辆管理所备案。', '1', '', '', '', '', '《机动车登记规定》第十七条规定：已注册登记的机动车，机动车所有人住所在车辆管理所管辖区域内迁移或者机动车所有人姓名(单位名称)、联系方式变更的，应当向登记地车辆管理所备案。', NULL),
('845', '驾驶人违反交通运输管理法规发生重大事故致人死亡的处3年以上有期徒刑。', '2', '正确', '错误', '', '', '据《刑法》第一百三十三条：
<br/>违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；
<br/>交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；
<br/>因逃逸致人死亡的，处七年以上有期徒刑。
<br/>依据法规是3年以下的，所以，本题选择【错误】。', NULL),
('846', '驾驶机动车在高速公路上车辆发生故障时，为获得其他车辆的帮助，可将警告标志放置在其他车道。', '2', '', '', '', '', '应在本车道放置警告标志，且放置距离为：高速公路是150米以外，道路是50--100米；且只能同车道摆放。', NULL),
('847', '如图所示，在这起交通事故中，以下说法正确的是什么？', '2', 'A车负全部责任', 'B车负全部责任', '都无责任，后果自行承担', '各负一半责任', 'A车在车道上正常行驶，B车掉头导致事故发生，因此，B车负全责。', 'https://images.juheapi.com/jztk/c1c2subject1/847.jpg'),
('848', '机动车参加安全技术检验的主要目的是检查车辆各项性能系数，及时消除车辆安全隐患，减少事故发生。', '1', '', '', '', '', '机动车参加安全技术检验的主要目的，是为了降低交通安全隐患，减少交通事故发生的可能性。', NULL),
('849', '如图所示，驾驶机动车时，前风窗玻璃处悬挂放置干扰视线的物品是错误的。', '1', '', '', '', '', '悬挂物品干扰驾驶员的视线，会加大行车危险，所以这种行为是错误的。', 'https://images.juheapi.com/jztk/c1c2subject1/849.jpg'),
('850', '驾驶机动车在路口遇到这种信号灯亮时，不能右转弯。', '2', '正确', '错误', '', '', '只有 红 黄 绿三色且是圆形（如图）交通信号灯的路口，任何情况下都能右转，如果是箭头信号灯的话按箭头方向行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/850.jpg'),
('851', '机动车驾驶人联系电话、联系地址等信息发生变化，应当在信息变更后三十日内，向驾驶证核发地车辆管理所备案。', '1', '', '', '', '', '持有大型客车、牵引车、城市公交车、中型客车、大型货车驾驶证的驾驶人联系电话、从业单位等信息发生变化未及时申报变更信息的，公安机关交通管理部门处二十元以上二百元以下罚款。机动车驾驶人联系电话、联系地址等信息发生变化，应当在信息变更后三十日内，向驾驶证核发地车辆管理所备案。', NULL),
('852', '公安机关交通管理部门对驾驶人的交通违法行为除依法给予行政处罚外,实行下列哪种制度？', '3', '违法登记制度', '奖励里程制度', '累积记分制度', '强制报废制度', '《道路交通安全法》第二十四条：公安机关交通管理部门对机动车驾驶人违反道路交通安全法律、法规的行为，除依法给予行政处罚外，实行累积记分制度。', NULL),
('853', '大雾天行车,多鸣喇叭是为了什么?', '1', '引起对方注意，避免发生危险', '催促前车提速，避免发生追尾', '准备超越前车', '催促前车让行', '都说了是大雾天，肯定能见度很低啦，所以要靠耳朵来听。多响几声喇叭，就是要告诉别人，这里有车，提高注意！', NULL),
('854', '这个标志是何含义？', '2', '学校区域', '注意儿童', '人行横道', '注意行人', '注意儿童：用以警告车辆驾驶人减速慢行，注意儿童。设在小学、幼儿园、少年宫等儿童经常出入地点前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/854.jpg'),
('855', '持有大型客车、牵引车、城市公交车、中型客车、大型货车驾驶证的驾驶人联系电话、从业单位等信息发生变化未及时申报变更信息的，公安机关交通管理部门处二十元以上二百元以下罚款。', '1', '', '', '', '', '持有大型客车、牵引车、城市公交车、中型客车、大型货车驾驶证的驾驶人联系电话、从业单位等信息发生变化未及时申报变更信息的，公安机关交通管理部门处二十元以上二百元以下罚款。机动车驾驶人联系电话、联系地址等信息发生变化，应当在信息变更后三十日内，向驾驶证核发地车辆管理所备案。', NULL),
('856', '路面由白色虚线和三角地带标线组成的是什么标线？', '4', '道路入口标线', '可跨越式分道线', '道路出口减速线', '道路出口标线', '道路出口标线为白色虚线，主要用于高速公路和其他采用立体交叉道路。该标线作用为，高速公路出入口横向标线或三角地带标线是为驶入或驶出匝道车辆提供安全交汇引导，减少与突出部缘石碰撞。', 'https://images.juheapi.com/jztk/c1c2subject1/856.jpg'),
('857', '驾驶机动车在高速公路上行驶，能见度小于200米时，车速不得超过每小时60公里。', '1', '', '', '', '', '《中华人民共和国道路交通安全法实施条例》第八十一条：机动车在高速公路上行驶，遇有雾、雨、雪、沙尘、冰雹等低能见度气象条件时，应当遵守下列规定：<b>能见度小于200米时，开启雾灯、近光灯、示廓灯和前后位灯，车速不得超过每小时60公里，与同车道前车保持100米以上的距离。</b>', NULL),
('858', '这个标志是何含义？', '2', '路面不平', '路面低洼', '路面高突', '有驼峰桥', '路面低洼：用以提醒车辆驾驶人减速慢行。设在路面突然低洼以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/858.jpg'),
('859', '这个标志是何含义？', '2', '预告宽度为3米', '限制宽度为3米', '解除3米限宽', '限制高度为3米', '限制宽度为3米：表示禁止装载宽度超过标志所示数值的车辆通行。此标志设在最大允许宽度受限制的地方。 以图为例：装载宽度不得超过3米', 'https://images.juheapi.com/jztk/c1c2subject1/859.jpg'),
('860', '这个标志是何含义？', '4', '电动自行车行驶', '非机动车停车位', '非机动车停放区', '非机动车行驶', '看到自行车你就想他是非机动车就行了。', 'https://images.juheapi.com/jztk/c1c2subject1/860.jpg'),
('861', '这个标志是何含义？', '1', '解除禁止超车', '准许变道行驶', '解除禁止变道', '解除禁止借道', '解除禁止超车：表示禁止超车路段结束。此标志设在禁止超车的终点。', 'https://images.juheapi.com/jztk/c1c2subject1/861.jpg'),
('862', '这个标志是何含义？', '1', '右转车道', '掉头车道', '左转车道', '分向车道', '表示只准一切车辆向右转弯。此标志设在车辆必须向右转弯的路口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/862.jpg'),
('863', '这个标志是何含义？', '2', '禁止驶入路口', '禁止向右转弯', '禁止变更车道', '禁止车辆掉头', '禁止向右转弯：表示前方路口禁止一切车辆向右转弯。此标志设在禁止向右转弯的路口前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/863.jpg'),
('864', '这个标志是何含义？', '4', '禁止直行和向左变道', '禁止直行和向左转弯', '允许直行和向左变道', '禁止直行和向右转弯', '禁止直行和向右转弯：表示前方路口禁止一切车辆直行和向右转弯。此标志设在禁止直行和向右转弯的路口前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/864.jpg'),
('865', '驾驶机动车由加速车道进入高速公路行驶，以下做法错误的是什么？', '4', '在加速车道上加速，同时要开启左转向灯', '密切注意左侧行车道的车流状态，同时用后视镜观察后方的情况', '充分利用加速车道的长度加速,确认安全后,平顺地进入行车道', '经加速车道充分加速后，可直接驶入最左侧车道', '《中华人民共和国道路交通安全法实施条例》第七十八条：高速公路应当标明车道的行驶速度，最高车速不得超过每小时120公里，最低车速不得低于每小时60公里。在高速公路上行驶的小型载客汽车最高车速不得超过每小时120公里，其他机动车不得超过每小时100公里，摩托车不得超过每小时80公里。同方向有2条车道的，左侧车道的最低车速为每小时100公里；同方向有3条以上车道的，最左侧车道的最低车速为每小时110公里，中间车道的最低车速为每小时90公里。因此，<b>驾车进入高速公路后，不能直接驶入最左车道，要循序渐进。</b>', NULL),
('866', '持有大型客车、牵引车、城市公交车、中型客车、大型货车驾驶证的驾驶人，记分周期内有记分的，应当在记分周期结束后三十日内到公安机关交通管理部门接受审验，同时还应当申报身体条件情况。', '1', '', '', '', '', '《道路交通安全法》规定：持有大型客车、牵引车、城市公交车、中型客车、大型货车驾驶证的驾驶人，应当在每个记分周期结束后三十日内到公安机关交通管理部门接受审验。但在一个记分周期内没有记分记录的，免予本记分周期审验。', NULL),
('867', '申请小型汽车准驾车型驾驶证的人年龄条件是多少？', '2', '18周岁以上60周岁以下', '18周岁以上70周岁以下', '24周岁以上70周岁以下', '21周岁以上50周岁以下', '新交规 公安部123号令
<br/><b>1、申请小型汽车、小型自动挡汽车、残疾人专用小型自动挡载客汽车、轻便摩托车准驾车型的，在18周岁以上、70周岁以下；</b> 　　
<br/>2、申请低速载货汽车、三轮汽车、普通三轮摩托车、普通二轮摩托车或者轮式自行机械车准驾车型的，在18周岁以上，60周岁以下； 
<br/>3、申请城市公交车、大型货车、无轨电车或者有轨电车准驾车型的，在20周岁以上，50周岁以下； 
<br/>4、申请中型客车准驾车型的，在21周岁以上，50周岁以下； 　　
<br/>5、申请牵引车准驾车型的，在24周岁以上，50周岁以下； 　　
<br/>6、申请大型客车准驾车型的，在26周岁以上，50周岁以下。', NULL),
('868', '这个标志是何含义？', '3', '不准让行', '会车让行', '减速让行', '停车让行', '减速让行：表示车辆应减速让行，告示车辆驾驶员必须慢行或停车，观察干路行车情况，在确保干道车辆优先的前提下，认为安全时方可续行。此标志设在视线良好交叉道路的次要路口。', 'https://images.juheapi.com/jztk/c1c2subject1/868.jpg'),
('869', '这个标志是何含义？', '4', '两侧变窄路段', '车速测试路段', '车距确认路段', '注意保持车距', '车距确认标线作为车辆驾驶人保持行车安全距离的参考，视需要设于较长直线段、易发生追尾事故或其他需要的路段，应与车距确认标志配合使用。', 'https://images.juheapi.com/jztk/c1c2subject1/869.jpg'),
('870', '驾驶机动车在高速公路上行驶，能见度小于200米时，与同车车道前车应保持100米以上的距离。', '1', '', '', '', '', '<b>能见度小于200米时，开启雾灯、近光灯、示廓灯和前后位灯，车速不得超过每小时60公里，与同车道前车保持100米以上的距离；</b>能见度小于100米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时40公里，与同车道前车保持50米以上的距离；能见度小于50米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时20公里，并从最近的出口尽快驶离高速公路。', NULL),
('871', '机动车所有人申请转移登记前，应当将涉及该车的道路交通安全违法行为和交通事故处理完毕。', '1', '', '', '', '', '已注册登记的机动车所有权发生转移的，现机动车所有人应当自机动车交付之日起三十日内向登记地车辆管理所申请转移登记。机动车所有人申请转移登记前，应当将涉及该车的道路交通安全违法行为和交通事故处理完毕。', NULL),
('872', '这个标志的含义是提醒车辆驾驶人前方是车辆渡口。', '1', '正确', '错误', '', '', '警告标志：渡口。用以提醒车辆驾驶人谨慎驾驶。设在车辆渡口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/872.jpg'),
('873', '这个标志是何含义？', '3', '最高速度', '限制速度', '建议速度', '最低速度', '常识题，记住。', 'https://images.juheapi.com/jztk/c1c2subject1/873.jpg'),
('874', '这个标志是何含义？', '4', '禁止长时鸣喇叭', '断续鸣喇叭', '减速鸣喇叭', '禁止鸣喇叭', '禁止鸣喇叭：表示禁止鸣喇叭。此标志设在需要禁止鸣喇叭的地方。禁止鸣喇叭的时间和范围可用辅助标志说明。', 'https://images.juheapi.com/jztk/c1c2subject1/874.jpg'),
('875', '如图所示，驾驶机动车经过这种道路时，如果前方没有其他交通参与者，可在道路上随意通行。 ', '2', '', '', '', '', '驾驶机动车经过这种道路时，如果前方没有其他交通参与者，也不可在道路上随意通行，安全第一。', 'https://images.juheapi.com/jztk/c1c2subject1/875.jpg'),
('876', '这个标志是何含义？', '1', '省道编号', '国道编号', '县道编号', '乡道编号', '乡道是白底Y字开头的，县道是白底X开头的，省道是黄底的，国道是红底的。', 'https://images.juheapi.com/jztk/c1c2subject1/876.jpg'),
('877', '这种白色矩形标线框含义是什么？', '2', '长时停车位', '限时停车位', '免费停车位', '专用停车位', '有时限的停车位~~', 'https://images.juheapi.com/jztk/c1c2subject1/877.jpg'),
('878', '这个标志是何含义？', '3', '泥泞道路', '低洼路面', '过水路面', '渡口', '过水路面指的是通过平时无水或流水很少的宽浅河流而修筑的在洪水期间容许水流浸过的路面。', 'https://images.juheapi.com/jztk/c1c2subject1/878.jpg'),
('879', '驾驶机动车在山路行驶时，为了减少油耗，下坡时可以空挡滑行，并使用行车制动器控制速度。', '2', '', '', '', '', '下坡时用空档滑行容易烧坏变速器，非常危险，属于交通陋习。', NULL),
('880', '驾驶机动车在交叉路口前变更车道时，应在进入实线区后，开启转向灯，变更车道。', '2', '', '', '', '', '驾驶机动车在交叉路口前变更车道时，应该在虚线区就要提前开启转向灯，完成车道变更。实线禁止压线，不能在实线区开转向变更车道。', NULL)
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('881', '路中心的黄色斜线填充是何含义？', '2', '单向行驶车道分界线', '禁止跨越对向车行道分界线', '双侧可跨越同向车道分界线', '可跨越对向车道分界线', '图中两侧车道很明显是不同方向的，并且双黄线是禁止跨越的，因此路中心的黄色斜线填充为禁止跨越对向车行道分界线。', 'https://images.juheapi.com/jztk/c1c2subject1/881.jpg'),
('882', '驾驶机动车经过无划分车道的道路时，可以随意通行。', '2', '', '', '', '', '按规定：驾驶机动车经过无划分车道的道路时，机动车在道路中间通行，非机动车和行人在道路两侧通行。', NULL),
('883', '这个标志是何含义？', '3', '距无人看守铁路道口100米', '距有人看守铁路道口100米', '距无人看守铁路道口50米', '距有人看守铁路道口50米', '一道红线是50米，一道50米。', 'https://images.juheapi.com/jztk/c1c2subject1/883.jpg'),
('884', '如图所示，夜间驾驶机动车与同方向行驶的前车距离较近时，以下做法正确的是什么？', '2', '使用远光灯，有利于观察路面情况', '禁止使用远光灯，避免灯光照射至前车后视镜造成前车驾驶人眩目', '使用远光灯，有利于告知前方驾驶人后方有来车', '禁止使用远光灯，避免灯光照射至前车后视镜造成自己眩目', '夜间驾驶机动车与同方向行驶的前车距离较近时，禁止使用远光灯，避免灯光照射至前车后视镜造成前车驾驶人眩目。', 'https://images.juheapi.com/jztk/c1c2subject1/884.jpg'),
('885', '这一组交通警察手势是什么信号？', '3', '右转弯信号', '变道信号', '减速慢行信号', '靠边停车信号', '如果看到别人发火，我们会做由上往下压的动作让他压压火别爆发，同理，由下往下压是让你减速慢行', 'https://images.juheapi.com/jztk/c1c2subject1/885.jpg'),
('886', '如图所示，驾驶机动车在路口遇到这种交通信号时，右转弯的车辆在不妨碍被放行的车辆、行人的情况下，可以通行。', '1', '', '', '', '', '驾驶机动车在路口遇到这种圆形交通信号时，右转弯的车辆在不妨碍被放行的车辆、行人的情况下，可以通行。', 'https://images.juheapi.com/jztk/c1c2subject1/886.jpg'),
('887', '经购买、调拨、赠予等方式获得机动车后尚未注册登记的，向车辆管理所申领临时行驶车号牌后，方可临时上道路行驶。', '1', '', '', '', '', '按规定：经购买、调拨、赠予等方式获得机动车后尚未注册登记的，向车辆管理所申领临时行驶车号牌后，方可临时上道路行驶。', NULL),
('888', '发生交通事故时，下列哪种情况下当事人应当保护现场并立即报警？', '4', '未造成人员伤亡的', '未发生财产损失事故', '未损害公共设施及建筑物的', '驾驶人有酒后驾驶嫌疑的', '酒后驾驶属违法行为，应及时报警。', NULL),
('889', '驾驶机动车遇紧急事务，可以边开车边接打电话。', '2', '', '', '', '', '新修订的《机动车驾驶证申领和使用规定》公布后，2013年1月1日起施行，其中规定：<b>驾驶机动车有拨打、接听手持电话等妨碍安全驾驶的行为的一次记2分。此外，边开车边打电话也会危害人身安全。</b>', NULL),
('890', '如图所示，A车具有优先通行权。', '1', '', '', '', '', '直行先行，但若让A车等待B车，则时间更长，所以都是直行的情况下，A车先行。', 'https://images.juheapi.com/jztk/c1c2subject1/890.jpg'),
('891', '如图所示，驾驶机动车驶出这个路口时应当怎样使用灯光?', '1', '开启右转向灯', '开启危险报警闪光灯', '不用开启转向灯', '开启左转向灯', '图中是环岛，驶入开左转向灯，驶出开右转向灯。', 'https://images.juheapi.com/jztk/c1c2subject1/891.jpg'),
('892', '这个标志是何含义？', '1', '右侧绕行', '单向通行', '注意危险', '左侧绕行', '右侧绕行：用以告示前方道路有障碍物，车辆应按标志指示减速慢行，右侧绕行通过。', 'https://images.juheapi.com/jztk/c1c2subject1/892.jpg'),
('893', '车辆在交叉路口有优先通行权的，遇有车辆抢行时，应怎样做？', '3', '抢行通过', '提前加速通过', '减速避让，必要时停车让行', '按优先权规定正常行驶不予避让', '遇到抢行车辆时，考虑到安全第一，要主动避让。', NULL),
('894', '这个标志是何含义？', '2', '海关检查', '停车检查', '边防检查', '禁止通行', '停车检查：表示机动车必须停车接受检查。此标志设在关卡将近处，以便要求车辆接受检查或缴费等手续。标志中可加注说明检查事项。', 'https://images.juheapi.com/jztk/c1c2subject1/894.jpg'),
('895', '如图所示，驾驶机动车在路口前遇到这种情况时，A车具有优先通行权。', '1', '', '', '', '', '道路上行驶时，右转弯让左转弯，转弯让直行。因此图中的A车具有优先通行权。', 'https://images.juheapi.com/jztk/c1c2subject1/895.jpg'),
('896', '当驾驶人的血液中酒精含量为100毫克/100毫升时，属于醉酒驾驶。', '1', '', '', '', '', '驾驶人的血液中酒精含量在80毫克/100毫升以上，含（80毫克/100毫升）都属于醉酒驾驶。', NULL),
('897', '申请人患有癫痫病的，可以申领机动车驾驶证，但是驾驶时必须有人陪同。', '2', '', '', '', '', '申请人患有癫痫病的，因为不知道发病时间，所以驾驶车辆是存在安全隐患的，所以不能申请。', NULL),
('898', '驾驶机动车下长坡时，空挡滑行会导致再次挂挡困难。', '1', '', '', '', '', '空档滑行时，汽车会失去发动机牵制作用，下坡的过程中，由于重力的作用，汽车速度会越来越快，在没有发动机牵制下的汽车，制动距离要增大很多，也就是说，刹车的作用会大大降低，车辆会处于失控状态，再次挂档也会很难。一旦前方有状况出，驾驶员没法使车辆及时减速或者停下来，造成很大的安全隐患。', NULL),
('899', '驾驶机动车在道路上掉头时，应当提前开启左转向灯。', '1', '', '', '', '', '《中华人民共和国道路交通安全法实施条例》第五十七条机动车应当按照下列规定使用转向灯：（一）向左转弯、向左变更车道、准备超车、驶离停车地点或者掉头时，应当提前开启左转向灯；（二）向右转弯、向右变更车道、超车完毕驶回原车道、靠路边停车时，应当提前开启右转向灯。', NULL),
('900', '机动车驾驶人造成重大交通事故后逃逸，构成犯罪的，十年内不能申请机动车驾驶证。', '2', '', '', '', '', '《交通法》第一百零一条：违反道路交通安全法律、法规的规定，发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证。<b>造成交通事故后逃逸的，由公安机关交通管理部门吊销机动车驾驶证，且终生不得重新取得机动车驾驶证。</b>', NULL),
('901', '警车、消防车、救护车、工程救险车执行紧急任务时，耽误或影响其通行可能会导致严重后果，所以其他车辆和行人应当主动让行。', '1', '', '', '', '', '警车、消防车、救护车、工程救险车都属于特种车，按照规定，应该给特征车让行。', NULL),
('902', '车速超过规定时速达到50%的一次记3分。', '2', '正确', '错误', '', '', '《公安部令第123号》规定，驾驶中型以上载客载货汽车、校车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速20％以上或者在高速公路、城市快速路以外的道路上行驶超过规定时速50％以上，以及驾驶其他机动车行驶超过规定时速50%以上的，一次记12分。', NULL),
('903', '两辆机动车发生轻微碰擦事故后，为保证理赔，必须等保险公司人员到场鉴定后才能撤离现场。', '2', '', '', '', '', '《中华人民共和国道路交通安全法》中第七十条第二、三款规定，在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜;不即行撤离现场的，应当迅速报告执勤的交通警察或者公安机关交通管理部门。在道路上发生交通事故，仅造成轻微财产损失，并且基本事实清楚的，当事人应当先撤离现场再进行协商处理。', NULL),
('904', '补领机动车驾驶证应到以下哪个地方办理？', '2', '所学驾校', '驾驶证核发地车辆管理所', '派出所', '全国任何地方公安机关交通管理部门', '如果出现驾驶证丢失需补办等办理情况，需要到驾驶证核发地车辆管理所补领机动车驾驶证。', NULL),
('905', '机动车驾驶人一次有两个以上违法行为记分的，应当分别计算累加分值。', '1', '', '', '', '', '《机动车驾驶证申领和使用规定》第五十六条 对机动车驾驶人的道路交通安全违法行为，处罚与记分同时执行。<b>机动车驾驶人一次有两个以上违法行为记分的，应当分别计算，累加分值。</b>', NULL),
('906', '隐瞒有关情况或者提供虚假材料申领机动车驾驶证的，申请人在1年内不得再次申领机动车驾驶证。', '1', '', '', '', '', '《机动车驾驶证申领和使用规定》第七十八条：<b>隐瞒有关情况或者提供虚假材料申领机动车驾驶证的，申请人在一年内不得再次申领机动车驾驶证。</b>申请人在考试过程中有贿赂、舞弊行为的，取消考试资格，已经通过考试的其他科目成绩无效；申请人在一年内不得再次申领机动车驾驶证。', NULL),
('907', '道路没有划分机动车道、非机动车道和人行道的，以下说法正确的是什么？', '3', '机动车在道路左侧通行，非机动车和行人随意通行', '机动车在道路左侧通行，非机动车和行人在道路两侧通行', '机动车在道路中间通行，非机动车和行人在道路两侧通行', '机动车、非机动车和行人可随意通行', '按规定：驾驶机动车经过无划分车道的道路时，机动车在道路中间通行，非机动车和行人在道路两侧通行。', NULL),
('908', '驾驶机动车在高速公路上行驶，遇低能见度气象条件时，能见度在200米以下，车速不得超过每小时多少公里，与同车道前车至少保持多少米的距离？', '1', '60，100', '70，100', '40，80', '30，80', '驾驶机动车在高速公路上行驶，遇低能见度气象条件时，能见度在200米以下，车速不得超过60公里/小时，与同车道前车至少保持100米的车距以保证安全。', NULL),
('909', '驾驶机动车遇到前方道路拥堵时，可以借用无人通行的非机动车道行驶。', '2', '', '', '', '', '遇到道路拥堵，应该按顺序排队等待，不得借用非机动车道行驶。', NULL),
('910', '关于醉酒驾驶机动车的处罚，以下说法错误的是什么？', '4', '公安机关交通管理部门约束至酒醒', '吊销驾驶证', '五年内不得重新取得机动车驾驶证', '记6分', '根据规定，醉酒驾驶机动车的，由公安机关交通管理部门约束至酒醒，<b>吊销机动车驾驶证</b>，依法追究刑事责任，五年内不得重新取得机动车驾驶证。
<br/>注意，题目说要选择“说法错误的是什么”，选项D“记6分”与规定的“吊销机动车驾驶证”不符，是错误的。因此本题答案选D。', NULL),
('911', '如图所示，驾驶机动车直行遇前方道路堵塞时，车辆可以在黄色网格线区域临时停车等待，但不得在人行横道停车。', '2', '', '', '', '', '驾驶机动车直行遇前方道路堵塞时，车辆不可在黄色网格线区域临时停车等待，也不可在人行横道停车。即使绿灯亮了，也要在路口外停车等待。', 'https://images.juheapi.com/jztk/c1c2subject1/911.jpg'),
('912', '以下哪种违法行为的机动车驾驶人将被一次记6分？', '3', '驾驶与准驾车型不符的机动车', '车速超过规定时速50%以上', '驾驶机动车违反道路交通信号灯', '未取得校车驾驶资格驾驶校车', '二、机动车驾驶人有下列违法行为之一，一次记6分：<br/>（一）机动车驾驶证被暂扣期间驾驶机动车的；<br/><b>（二）驾驶机动车违反道路交通信号灯通行的；</b><br/>（三）驾驶营运客车（不包括公共汽车）、校车载人超过核定人数未达20％的，或者驾驶其他载客汽车载人超过核定人数20％以上的；<br/>（四）驾驶中型以上载客载货汽车、校车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速未达20％的；<br/>（五）驾驶中型以上载客载货汽车、校车、危险物品运输车辆在高速公路、城市快速路以外的道路上行驶或者驾驶其他机动车行驶超过规定时速20%以上未达到50%的；<br/>（六）驾驶货车载物超过核定载质量30%以上或者违反规定载客的；<br/>（七）驾驶营运客车以外的机动车在高速公路车道内停车的；<br/>（八）驾驶机动车在高速公路或者城市快速路上违法占用应急车道行驶的；<br/>（九）低能见度气象条件下，驾驶机动车在高速公路上不按规定行驶的；<br/>（十）驾驶机动车运载超限的不可解体的物品，未按指定的时间、路线、速度行驶或者未悬挂明显标志的；', NULL),
('913', '驾驶机动车发生以下交通事故，哪种情况适用自行协商解决？', '3', '对方饮酒的', '对事实及成因有争议的', '未造成人身伤亡，对事实及成因无争议的', '造成人身伤亡的', '《中华人民共和国道路交通安全法实施条例》第八十六条规定:“机动车与机动车、机动车与非机动车在道路上发生未造成人身伤亡的交通事故，当事人对事实及成因无争议的，在记录交通事故的时间、地点、对方当事人的姓名和联系方式、机动车牌号、驾驶证号、保险凭证号、碰撞部位，并共同签名后，撤离现场，自行协商损害赔偿事宜。当事人对交通事故事实及成因有争议的，应当迅速报警。”', NULL),
('914', '如图所示，驾驶机动车遇到这种情况时，以下做法正确的是什么？ ', '2', '应减速观察水情，然后加速行驶通过', '应停车察明水情，确认安全后，低速通过', '应停车察明水情，确认安全后，快速通过', '可随意通行', '机动车在有积水较深的桥下通过行车时，应当停车察明水情，确认安全后，低速通过。', 'https://images.juheapi.com/jztk/c1c2subject1/914.jpg'),
('915', '避让特种车辆使其顺利通过后，车辆应有序回到原车道继续行驶，不要尾随特种车辆，以免发生交通事故。', '1', '', '', '', '', '特种车辆本身车速较快，而且由于其特殊性，驾驶路线与常规车辆也不同。如果跟随特种车会十分危险，因此避让特种车后，要有序回到原车道继续行驶。', NULL),
('916', '实习期驾驶人驾驶机动车上高速公路行驶，以下做法正确的是什么？', '3', '任何情况下都不允许上高速', '不需要其他人员陪同', '需要持有相应或者更高准驾车型驾驶证三年以上的驾驶人陪同', '需要持有相应或者更高准驾车型驾驶证、同在实习期内的驾驶人陪同', '《道路交通安全法》规定：实习期驾驶人驾驶机动车上高速公路行驶，应当由持相应或者更高准驾车型驾驶证三年以上的驾驶人陪同。', NULL),
('917', '驾驶机动车行经漫水路或者漫水桥时，应当停车察明水情，快速通过。', '2', '', '', '', '', '《中华人民共和国道路交通管理条例》的第四十六条规定：车辆行经漫水路或漫水桥时,必须停车察明水情,确认安全后,低速通过。', NULL),
('918', '驾驶机动车在路口右转弯时，应提前开启右转向灯，不受信号灯限制，不受车速限制，迅速通过，防止路口堵塞。', '2', '', '', '', '', '驾驶机动车在路口右转弯时，应提前开启右转向灯，不受信号灯限制，必须限制车速，注意观察行人及来往车辆，安全通过。', NULL),
('919', '下列哪种情况可以向机动车驾驶证核发地车辆管理所申请补发?', '3', '驾驶证被扣押', '驾驶证被扣留', '驾驶证遗失', '驾驶证被暂扣', '驾驶证被扣留、扣押及暂扣都可以再次取回，不用补发。机动车驾驶证遗失、损毁无法辨认时，机动车驾驶人应当向机动车驾驶证核发地车辆管理所申请补发。', NULL),
('920', '这个标志是何含义？', '3', '施工路段绕行', '双向交通', '左右绕行', '注意危险', '左右绕行：用以告示前方道路有障碍物，车辆应按标志指示减速慢行，绕行通过。', 'https://images.juheapi.com/jztk/c1c2subject1/920.jpg'),
('921', '自愿降级的驾驶人需要到车辆管理所申请换领驾驶证。', '1', '', '', '', '', '自愿降级的驾驶人，由本人带驾驶证、身份证去车管所提出申请，并换领驾驶证。', NULL),
('922', '发生无人员伤亡的、财产轻微损失的交通事故后，以下做法正确的是什么？', '3', '必须报警，等候警察处理', '开车离开现场', '确保安全的情况下，对现场拍照，然后将车辆移至路边等不妨碍交通的地点', '停在现场保持不动', '《中华人民共和国道路交通安全法实施条例》第八十六条规定:“机动车与机动车、机动车与非机动车在道路上发生未造成人身伤亡的交通事故，当事人对事实及成因无争议的，<b>在记录交通事故的时间、地点、对方当事人的姓名和联系方式、机动车牌号、驾驶证号、保险凭证号、碰撞部位，并共同签名后，撤离现场</b>，自行协商损害赔偿事宜。当事人对交通事故事实及成因有争议的，应当迅速报警。”', NULL),
('923', '驾驶机动车在高速公路上行驶，错过出口时，如果确认后方无来车，可以倒回出口驶离高速公路。', '2', '', '', '', '', '错过出口时，应在下一个出口出去，高速公路上绝对不允许倒车。', NULL),
('924', '路中心双黄实线是何含义？', '1', '禁止跨越对向车行道分界线', '可跨越对向车道分界线', '双侧可跨越同向车道分界线', '单向行驶车道分界线', '双黄实线表示禁止跨越。因此是禁止跨越对向车行道分界线。', 'https://images.juheapi.com/jztk/c1c2subject1/924.jpg'),
('925', '如图所示，驾驶机动车遇到右侧车辆强行变道，应减速慢行，让右前方车辆顺利变道。', '1', '', '', '', '', '驾驶机动车遇到右侧车辆强行变道，应减速慢行，让右前方车辆顺利变道。如都不相让的话，就会造成交通事故了。', 'https://images.juheapi.com/jztk/c1c2subject1/925.jpg'),
('926', '驾驶机动车遇前方交叉路口交通阻塞时，路口内无网状线的，可停在路口内等候。', '2', '', '', '', '', '《中华人民共和国道路交通安全法实施条例》第五十三条：机动车遇有前方交叉路口交通阻塞时，应当依次停在路口以外等候，不得进入路口。
<br/>无论路口内有没有网状线，都不能进入路口等待。', NULL),
('927', '驾驶机动车超车时，被超越车辆未减速让路，应迅速提速超越前方车辆完成超车。', '2', '', '', '', '', '被超车辆未减速让行，说明不具备超车条件，此时应该放弃超车，否则容易撞在一起，非常危险。', NULL),
('928', '隐瞒有关情况或者提供虚假材料申请机动车驾驶证，申请人在多少年内不得再次申领机动车驾驶证？', '1', '1年', '2年', '3年', '4年', '《机动车驾驶证申领和使用规定》第六章第七十八条规定：<b>隐瞒有关情况或者提供虚假材料申领机动车驾驶证的，申请人在一年内不得再次申领机动车驾驶证。</b>', NULL),
('929', '在交叉路口、隧道内均不能倒车。', '1', '', '', '', '', '《道路交通交通法》规定：机动车在交叉路口、隧道内均不能倒车。', NULL),
('930', '以下哪种行为机动车驾驶人将被一次记12分？', '4', '驾驶机动车不按规定避让校车的', '驾驶证被暂扣期间驾驶机动车的', '驾驶机动车违反道路交通信号灯通行的', '驾驶与准驾车型不符的机动车的', '机动车驾驶人有下列违法行为之一，一次记12分：
<br/>1、驾驶营运客车超载20％以上（将校车列入其中）
<br/>2、严重超速（新规定加入校车）
<br/>3、故意遮挡号牌（由扣6分调整为扣12分）
<br/>4、驾驶营运客车在高速公路车道内停车（由扣6分调整为扣12分）
<br/>5、连续驾驶中型以上载客汽车、危险物品运输车辆超过4小时未停车休息或者停车休息时间少于20分钟（由扣6分调整为扣12分）
<br/>6、未取得校车驾驶资格驾驶校车（新增）
<br/>7、饮酒后驾驶机动车
<br/><b>8、驾驶与准驾车型不符</b>
<br/>9、造成交通事故后逃逸
<br/>10、伪造、更改号牌和证件
<br/>11、驾驶机动车在高速公路上倒车、逆行、穿越中央分隔带掉头', NULL),
('931', '驾驶机动车发生交通事故，仅造成财产损失的，但是对交通事故事实及成因有争议的，应当怎么处理？', '1', '迅速报警', '占道继续和对方争辩', '找中间人帮忙解决', '自行协商损害赔偿事宜', '对于事故成因不明的交通事故，应及时报警，交由警察处理。', NULL),
('932', '这个标志是何含义？', '3', '高速公路出口预告', '高速公路入口预告', '高速公路终点预告', '高速公路起点预告', '高速公路终点预告：用于指示高速公路或城市快速路终点，设在高速公路或城市快速路终点处。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/932.jpg'),
('933', '以下不属于机动车驾驶证审验内容的是什么？', '4', '道路交通安全违法行为、交通事故处理情况', '驾驶人身体条件', '记满12分后参加学习和考试情况', '驾驶车辆累计行驶里程', '机动车驾驶证审验内容：（一）道路交通安全违法行为、交通事故处理情况；（二）身体条件情况；（三）道路交通安全违法行为记分及记满12分后参加学习和考试情况。驾驶车辆累计行驶里程不在审验范围内。', NULL),
('934', '如图所示，红圈标注的深色车辆的做法是违法的。', '1', '', '', '', '', '白色实线不允许变道，深色车辆在白色实线上变更车道，属于违法行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/934.jpg'),
('935', '机动车驾驶证有效期超过一年以上未换证的，驾驶证将被注销。', '1', '', '', '', '', '《机动车驾驶证申领和使用规定》第四十二条机动车驾驶人具有下列情形之一的，车辆管理所应当注销其机动车驾驶证:(一)死亡的;(二)身体条件不适合驾驶机动车的;(三)提出注销申请的;(四)丧失民事行为能力，监护人提出注销申请的;(五)<b>超过机动车驾驶证有效期一年以上未换证的。</b>', NULL),
('936', '上道路行驶的机动车未悬挂机动车号牌的一次记几分？', '2', '6分', '12分', '2分', '3分', '《公安部令第123号》规定，上道路行驶的机动车未悬挂机动车号牌的，或者故意遮挡、污损、不按规定安装机动车号牌的，一次记12分 。', NULL),
('937', '机动车驾驶人补领机动车驾驶证后，使用原机动车驾驶证驾驶的，除由公安机关交通管理部门收回原机动车驾驶证外，还应当受到何种处罚？', '4', '吊销驾驶证', '拘留驾驶人', '警告', '罚款', '机动车驾驶人补领机动车驾驶证后，继续使用原机动车驾驶证的,公安机关交通管理部门可处二十元以上二百元以下罚款。', NULL),
('938', '驾驶机动车在高速公路上行驶，遇有雾、雨、雪、沙尘、冰雹等低能见度气象条件下，能见度在100米以下时，车速不得超过每小时多少公里，与同车道前车至少保持多少米的距离？', '1', '40，50', '40，40', '50，40', '50，30', '能见度小于200米时，开启雾灯、近光灯、示廓灯和前后位灯，车速不得超过每小时60公里，与同车道前车保持100米以上的距离；<b>能见度小于100米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时40公里，与同车道前车保持50米以上的距离；</b>能见度小于50米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时20公里，并从最近的出口尽快驶离高速公路。', NULL),
('939', '使用伪造、变造的驾驶证一次记12分。', '1', '正确', '错误', '', '', '机动车驾驶人有下列违法行为之一，一次记12分：使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的。', NULL),
('940', '驾驶拼装的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废，并吊销机动车驾驶证。', '1', '', '', '', '', '<b>驾驶拼装的机动车或者已达到报废标准的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废。</b>对驾驶前款所列机动车上道路行驶的驾驶人，处二百元以上二千元以下罚款，并吊销机动车驾驶证。', NULL),
('941', '如图所示，驾驶机动车遇左侧车道有车辆正在超车时，可以迅速变道，伺机反超。', '2', '', '', '', '', '遇到左侧车辆超车，应当减速慢行，靠右边行，以保障行车安全。', 'https://images.juheapi.com/jztk/c1c2subject1/941.jpg'),
('942', '这辆小型载客汽车驶离高速公路行车道的方法是正确的。', '1', '正确', '错误', '', '', '图中车辆进入减速车道并未压实线，并且开启了转向灯，操作正确，所以是对的。', 'https://images.juheapi.com/jztk/c1c2subject1/942.jpg'),
('943', '道路交通安全违法行为累积记分的周期是多长时间？', '1', '12个月', '24个月', '3个月', '6个月', '123号令第五十五条规定：道路交通安全违法行为<b>累积记分周期（即记分周期）为12个月</b>，满分为12分，从机动车驾驶证初次领取之日起计算。因此本题答案应为C。', NULL),
('944', '如图所示，红圈中标记车辆使用灯光的方法是正确的。', '2', '', '', '', '', '《中华人民共和国道路交通安全法》第四十八条规定：在没有中心隔离设施或者没有中心线的道路上，夜间会车应当在距相对方向来车150米以外改用近光灯。
<br/>途中车辆并没有在150米外切换近光灯，距离这么近仍是远光灯，因此是错误的行为。', 'https://images.juheapi.com/jztk/c1c2subject1/944.jpg'),
('945', '机动车驾驶人驾驶证有效期满换领驾驶证时，须提交县级以上医疗机构出具的身体条件证明。', '1', '', '', '', '', '《道路运输从业人员管理规定》规定：机动车驾驶人驾驶证有效期满换领驾驶证时，须提交县级以上医疗机构出具的身体条件证明。', NULL),
('946', '行人参与道路交通的主要特点除了行走随意性大、方向多变以外，还喜欢聚集、围观。', '1', '', '', '', '', '除了行走随意性大、方向多变以外，喜欢聚集、围观也是行人参与道路交通的特点。', NULL),
('947', '这种黄黑相间的倾斜线条是什么标记？', '3', '实体标记', '突起标记', '立面标记', '减速标记', '《道路交通标志和标线》（GB5768-2009）<br/>第6.6条对于立面标记的规定：“立面标记用以提醒驾驶人注意，在行车道或近旁有高出路面的构造物。可设在跨线桥、渡槽等的墩柱立面、隧道洞口侧墙端面及其他障碍物立面上，一般应涂至2.5m以上的高度。标线为黄黑相间的倾斜线条，倾角为45°，线宽均为15cm。设置时应把向下倾斜的一边朝向车行道。”', 'https://images.juheapi.com/jztk/c1c2subject1/947.jpg'),
('948', '驾驶机动车在道路上发生交通事故造成人身伤亡的，驾驶人必须报警。', '1', '', '', '', '', '《中华人民共和国道路交通安全法》第七十条规定：在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场；造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。', NULL),
('949', '已注册登记的机动车，改变机动车车身颜色的应到公安交通管理部门申请变更登记。', '1', '', '', '', '', '《中华人民共和国道路运输条例》规定：已注册登记的机动车，改变机动车车身颜色的应到公安交通管理部门申请变更登记。', NULL),
('950', '这个标志是何含义？', '4', '高速公路终点地名预告', '高速公路行驶路线预告', '高速公路行驶方向预告', '高速公路地点距离预告', '高速公路地点距离预告：预告高速公路或城市快速路前方所要经过的重要的地点、道路的名称和距离，设置在互通式立体交叉加速车道的渐变段终点以后1 km以上路段的合适位置处。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/950.jpg'),
('951', '如图所示，驾驶机动车行驶至车道减少的路段时，遇前方机动车排队等候或行驶缓慢时，以下做法正确的是什么？', '2', '右侧车让左侧车先行', '每车道一辆依次交替驶入左侧车道', '左侧车让右侧车先行', '右侧车寻找空隙提前进入左侧车道', '驾驶机动车行驶至车道减少的路段时，前方机动车排队等候或行驶缓慢时，应当每车道一辆依次交替驶入左侧车道。', 'https://images.juheapi.com/jztk/c1c2subject1/951.jpg'),
('952', '驾驶机动车在高速公路上行驶，遇有雾、雨、雪、沙尘、冰雹等低能见度气象条件时，能见度在50米以下时，以下做法正确的是什么？', '4', '加速驶离高速公路', '在应急车道上停车等待', '可以继续行驶，但车速不得超过每小时40公里', '以不超过每小时20公里的车速从最近的出口尽快驶离高速公路', '《道路交通安全法》规定：机动车在高速公路上行驶，遇有雾、雨、雪、沙尘、冰雹等低能见度气象条件时，能见度小于50米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时20公里，并从最近的出口尽快驶离高速公路。', NULL),
('953', '以下哪项行为可构成危险驾驶罪？', '4', '闯红灯', '无证驾驶', '疲劳驾驶', '醉驾', '危险驾驶罪是指在道路上醉酒驾驶机动车或者在道路上驾驶机动车追逐竞驶，情节恶劣的行为。其他三个选项不符合要求。', NULL),
('954', '将机动车交由未取得机动车驾驶证的人驾驶的，由公安交通管理部门处二百元以上二千元以下罚款，可以并处以下哪种处罚？', '2', '15日以下拘留', '吊销驾驶证', '扣留车辆', '5年不得重新取得新驾驶证', '将机动车交由未取得机动车驾驶证的人驾驶的，由公安交通管理部门处二百元以上二千元以下罚款，并处以吊销驾驶证的处罚。', NULL),
('955', '机动车发生轻微财产损失的交通事故，对应当自行撤离现场而未撤离的，交通警察有权责令当事人撤离现场。', '1', '', '', '', '', '《中华人民共和国道路交通安全法》中第七十条第二、三款规定：
<br/>在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜；不即行撤离现场的，应当迅速报告执勤的交通警察或者公安机关交通管理部门。
<br/>机动车发生轻微财产损失的交通事故，对应当自行撤离现场而未撤离的，交通警察有权责令当事人撤离现场。', NULL),
('956', '机动车在抵押登记、质押备案期间不可以办理转移登记。', '1', '', '', '', '', '第二十条有下列情形之一的，不予办理转移登记：(一)机动车与该车档案记载内容不一致的；(二)属于海关监管的机动车，海关未解除监管或者批准转让的；(三)机动车在抵押登记、质押备案期间的；(四)有本规定第九条第(一)项、第(二)项、第(七)项、第(八)项、第(九)项规定情形的。', NULL),
('957', '如图所示，夜间驾驶机动车遇对方使用远光灯，无法看清前方路况时，以下做法正确的是什么？ ', '3', '保持行驶方向和车速不变', '自己也打开远光灯行驶', '降低车速，谨慎会车', '加速通过，尽快摆脱眩目光线', '夜间驾驶机动车遇对方使用远光灯，无法看清前方路况时，降低车速，谨慎会车，以免发生车祸、危险。', 'https://images.juheapi.com/jztk/c1c2subject1/957.jpg'),
('958', '如图所示，驾驶机动车经过这种道路时，应降低车速在道路中间通行。', '1', '', '', '', '', '图中道路两侧都有行人，驾驶机动车经过这种道路时，为了保障行人安全，需要降低车速在道路中间通行。', 'https://images.juheapi.com/jztk/c1c2subject1/958.jpg'),
('959', '如图所示，驾驶机动车遇到这种情况，以下做法正确的是什么？', '3', '长鸣喇叭催促行人快速通过', '开启远光灯警示行人有车辆驶近', '降低行驶速度，避让行人', '适当加速从行人前方绕行', '驾驶机动车遇到图中这种情况，应当降低行驶速度，避让行人。', 'https://images.juheapi.com/jztk/c1c2subject1/959.jpg'),
('960', '年龄在60周岁以上的机动车驾驶人，应当每年进行一次身体检查。', '1', '', '', '', '', '年龄在60周岁以上的机动车驾驶人，应当每年进行一次身体检查，以保证行车安全。', NULL)
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('961', '如图所示，驾驶机动车行驶至此位置时，以下做法正确的是什么？', '3', '观察左侧无车后，可以左转', '从该处直接左转', '不得左转，应当直行', '倒车退到虚线处换到左转车道', '驾驶机动车行驶至此位置时，已经在直行车道上，只能直行。而且已经驶过虚线位置到达实线位置，就更不能压线左转。', 'https://images.juheapi.com/jztk/c1c2subject1/961.jpg'),
('962', '如图所示，驾驶机动车在这种情况下，当C车减速让超车时，A车应该如何行驶？', '1', '放弃超越C车', '加速超越C车', '鸣喇叭示意B车让行后超车', '直接向左变更车道，迫使B车让行', '因为C车减速让超车的同时又与来向B车进行会车，此时继续超车容易造成危险，所以应当放弃超越C车。', 'https://images.juheapi.com/jztk/c1c2subject1/962.jpg'),
('963', '使用伪造、变造的行驶证一次记几分？', '4', '6分', '3分', '2分', '12分', '《公安部令第123号》规定，使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的，一次记12分 。', NULL),
('964', '申请人以不正当手段取得机动车驾驶证的，公安机关交通管理部门收缴机动车驾驶证，撤销机动车驾驶许可，申请人在3年内不得再次申领机动车驾驶证。', '1', '', '', '', '', '《中华人民共和国道路运输条例》说明，申请人以不正当手段取得机动车驾驶证的，公安机关交通管理部门收缴机动车驾驶证，撤销机动车驾驶许可，申请人在3年内不得再次申领机动车驾驶证。', NULL),
('965', '驾驶机动车时接打电话容易引发事故，以下原因错误的是什么?', '3', '单手握方向盘，对机动车控制力下降', '驾驶人注意力不集中，不能及时判断危险', '电话的信号会对汽车电子设备的运行造成干扰', '驾驶人对路况观察不到位，容易导致操作失误', '驾驶机动车时接打电话容易引发事故，主要是因为接电话时单手握方向盘，对机动车控制力下降。而且驾驶人注意力不集中，不能及时判断危险。同时驾驶人对路况观察不到位，容易导致操作失误。电话信号并不会对汽车电子设备的运行造成干扰。', NULL),
('966', '机动车驾驶证遗失的，机动车驾驶人应当向哪里的车辆管理所申请补发？', '1', '核发地', '暂住地', '居住地', '户籍地', '驾驶证遗失、损毁无法辨认时驾驶员应当向驾驶证核发地车辆管理所申请补发。', NULL),
('967', '驾驶人在驾驶证有效期满前多长时间申请换证？', '3', '60日内', '30日内', '90日内', '6个月内', '《公安部令第123号》第四十八条：机动车驾驶人应当于机动车驾驶证有效期满前九十日内，向机动车驾驶证核发地车辆管理所申请换证。', NULL),
('968', '已注册登记的机动车，改变车身颜色，机动车所有人不需要向登记地车辆管理所申请变更登记。', '2', '', '', '', '', '《中华人民共和国道路运输条例》说明，已注册登记的机动车，改变机动车车身颜色的应到公安交通管理部门申请变更登记。', NULL),
('969', '造成交通事故后逃逸，尚不构成犯罪的一次记12分。', '1', '正确', '错误', '', '', '《公安部令第123号》规定，造成交通事故后逃逸，尚不构成犯罪的，一次记12分。凡是逃逸的均为12分。', NULL),
('970', '驾驶人将机动车交给驾驶证被暂扣的人驾驶的，交通警察给予口头警告。', '2', '正确', '错误', '', '', '《道路交通安全法》第九十九条：将机动车交由未取得机动车驾驶证或者机动车驾驶证被吊销、暂扣的人驾驶的，由公安机关交通管理部门处二百元以上二千元以下罚款，可以并处吊销机动车驾驶证。
<br/>并不是口头警告这么简单。', NULL),
('971', '驾驶机动车与行人之间发生交通事故造成人身伤亡、财产损失的，机动车一方没有过错的，不承担赔偿责任。', '2', '', '', '', '', '《道路交通事故》第七十六条 机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿。超过责任限额的部分，按照下列方式承担赔偿责任：　（一）机动车之间发生交通事故的，由有过错的一方承担责任；双方都有过错的，按照各自过错的比例分担责任。<b>（二）机动车与非机动车驾驶人、行人之间发生交通事故的，由机动车一方承担责任；但是，有证据证明非机动车驾驶人、行人违反道路交通安全法律、法规，机动车驾驶人已经采取必要处置措施的，减轻机动车一方的责任。</b>
<br/>交通事故的损失是由非机动车驾驶人、行人造成的，机动车一方分担责任；损失是由非机动车驾驶人、行人故意造成的，机动车一方才不承担责任。', NULL),
('972', '这个标志是何含义？', '3', '向左绕行', '连续弯路', '向左急转弯', '向右急转弯', '向左急转弯：向左急弯路标志设在左急转弯的道路前方适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/972.jpg'),
('973', '机动车驾驶人有以下哪种违法行为的，暂扣六个月机动车驾驶证？', '3', '醉酒后驾驶机动车的', '伪造、变造机动车驾驶证的', '饮酒后驾驶机动车的', '使用伪造、变造机动车驾驶证的', '<b>饮酒驾驶机动车辆，罚款1000元—2000元、记12分并暂扣驾照6个月；</b>饮酒驾驶营运机动车，罚款5000元，记12分，处以15日以下拘留，并且5年内不得重新获得驾照。醉酒驾驶机动车辆，吊销驾照，5年内不得重新获取驾照，经过判决后处以拘役，并处罚金；醉酒驾驶营运机动车辆，吊销驾照，10年内不得重新获取驾照，终生不得驾驶营运车辆，经过判决后处以拘役，并处罚金。', NULL),
('974', '以下哪种身体条件，不可以申请机动车驾驶证?', '2', '糖尿病', '红绿色盲', '高血压', '怀孕', '红绿色盲会影响观察红绿灯，而我们在路上开车一般都是根据交通信号灯行驶的，所以不能申请驾照。', NULL),
('975', '这个标志是何含义？', '3', '靠右侧行驶', '不允许直行', '直行单行路', '直行车让行', '表示一切车辆单向行驶。此标志设在单行路的路口和入口处的适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/975.jpg'),
('976', '饮酒后或者醉酒驾驶机动车发生重大交通事故构成犯罪的，依法追究刑事责任，吊销机动车驾驶证，将多少年内不得申请机动车驾驶证？', '4', '五年', '十年', '二十年', '终生', '饮酒驾驶机动车辆，罚款1000元—2000元、记12分并暂扣驾照6个月；饮酒驾驶营运机动车，罚款5000元，记12分，处以15日以下拘留，并且5年内不得重新获得驾照。醉酒驾驶机动车辆，吊销驾照，5年内不得重新获取驾照，经过判决后处以拘役，并处罚金；醉酒驾驶营运机动车辆，吊销驾照，10年内不得重新获取驾照，终生不得驾驶营运车辆，经过判决后处以拘役，并处罚金。<br/><b>饮酒后或者醉酒驾驶机动车发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证，终生不得重新取得机动车驾驶证。</b>', NULL),
('977', '机动车驾驶人血液中酒精含量大于或者等于多少可认定为醉驾？', '3', '20毫克/100毫升', '60毫克/100毫升', '80毫克/100毫升', '50毫克/100毫升', '驾驶人的血液中酒精含量在80毫克/100毫升以上，含（80毫克/100毫升）都属于醉酒驾驶', NULL),
('978', '机动车驾驶人初次申请机动车驾驶证和增加准驾车型后的多长时间为实习期？', '2', '6个月', '12个月', '2年', '3个月', '《公安部令第123号》第六十四条：机动车驾驶人初次申请机动车驾驶证和增加准驾车型后的12个月为实习期。', NULL),
('979', '驾驶机动车碰撞建筑物、公共设施后可即行撤离现场。', '2', '正确', '错误', '', '', '《道路交通事故处理程序规定》 第八条 道路交通事故有下列情形之一的，当事人应当保护现场并立即报警： 　　<br/>（一）造成人员死亡、受伤的； 　　<br/>（二）发生财产损失事故，当事人对事实或者成因有争议的，以及虽然对事实或者成因无争议，但协商损害赔偿未达成协议的； 　　<br/>（三）机动车无号牌、无检验合格标志、无保险标志的； 　　<br/>（四）载运爆炸物品、易燃易爆化学物品以及毒害性、放射性、腐蚀性、传染病病源体等危险物品车辆的； 　　<br/><b>（五）碰撞建筑物、公共设施或者其他设施的；</b>　　<br/>（六）驾驶人无有效机动车驾驶证的； 　　<br/>（七）驾驶人有饮酒、服用国家管制的精神药品或者麻醉药品嫌疑的； 　　<br/>（八）当事人不能自行移动车辆的。 　　<br/>发生财产损失事故，并具有前款第二项至第五项情形之一，车辆可以移动的，当事人可以在报警后，在确保安全的原则下对现场拍照或者标划停车位置，将车辆移至不妨碍交通的地点等候处理。', NULL),
('980', '如图所示，驾驶机动车行经该路段时，应减速慢行，避免因眩目导致的交通事故。', '1', '', '', '', '', '驾驶员在驶出隧道口时，因为此处光线发生变化，驾驶员会有炫目感。安全起见，还是要减速慢行。', 'https://images.juheapi.com/jztk/c1c2subject1/980.jpg'),
('981', '如图所示，驾驶机动车遇到这种情况，不仅要控制车辆留出会车空间，而且要注意与右侧的儿童保持足够的安全距离。', '1', '', '', '', '', '窄路路边有儿童，这种情况应该控制车速为会车留出足够的空间，同时注意与右侧的儿童保持足够的安全距离。', 'https://images.juheapi.com/jztk/c1c2subject1/981.jpg'),
('982', '机动车在高速公路上发生故障时，将车上人员迅速转移到右侧路肩上或者应急车道内，并且迅速报警。', '1', '正确', '错误', '', '', '《道路交通安全法》第五十二条： 
<br/>机动车在道路上发生故障，需要停车排除故障时，驾驶人应当立即开启危险报警闪光灯，将机动车移至不妨碍交通的地方停放；难以移动的，应当持续开启危险报警闪光灯，并在来车方向设置警告标志等措施扩大示警距离，必要时迅速报警。 
<br/>第六十八条： 
<br/>机动车在高速公路上发生故障时，应当依照本法第五十二条的有关规定办理；警告标志应当设置在故障车来车方向一百五十米以外，<b>车上人员应当迅速转移到右侧路肩上或者应急车道内，并且迅速报警。 </b>
<br/>根据规定，题目描述无误，因此本题答案为对。', NULL),
('983', '驾驶人有下列哪种违法行为一次记12分？', '2', '违反交通信号灯', '使用伪造机动车号牌', '拨打、接听手机的', '违反禁令标志指示', '机动车驾驶人有下列违法行为之一，一次记12分：<br/>（一）驾驶与准驾车型不符的机动车的；<br/>（二）饮酒后驾驶机动车的；<br/>（三）驾驶营运客车（不包括公共汽车）、校车载人超过核定人数20％以上的；<br/>（四）造成交通事故后逃逸，尚不构成犯罪的；<br/>（五）上道路行驶的机动车未悬挂机动车号牌的，或者故意遮挡、污损、不按规定安装机动车号牌的；<br/><b>（六）使用伪造、变造的机动车号牌、行驶证、驾驶证、校车标牌或者使用其他机动车号牌、行驶证的；</b><br/>（七）驾驶机动车在高速公路上倒车、逆行、穿越中央分隔带掉头的；<br/>（八）驾驶营运客车在高速公路车道内停车的；<br/>（九）驾驶中型以上载客载货汽车、校车、危险物品运输车辆在高速公路、城市快速路上行驶超过规定时速20％以上或者在高速公路、城市快速路以外的道路上行驶超过规定时速50％以上，以及驾驶其他机动车行驶超过规定时速50%以上的；<br/>（十）连续驾驶中型以上载客汽车、危险物品运输车辆超过4小时未停车休息或者停车休息时间少于20分钟的；<br/>（十一）未取得校车驾驶资格驾驶校车的。', NULL),
('984', '道路交通事故中，驾驶人有饮酒、醉酒嫌疑时，要保护现场并立即报警。', '1', '正确', '错误', '', '', '《道路交通事故处理程序规定》 第八条 道路交通事故有下列情形之一的，当事人应当保护现场并立即报警： 　　<br/>（一）造成人员死亡、受伤的； 　　<br/>（二）发生财产损失事故，当事人对事实或者成因有争议的，以及虽然对事实或者成因无争议，但协商损害赔偿未达成协议的； 　　<br/>（三）机动车无号牌、无检验合格标志、无保险标志的； 　　<br/>（四）载运爆炸物品、易燃易爆化学物品以及毒害性、放射性、腐蚀性、传染病病源体等危险物品车辆的； 　　<br/>（五）碰撞建筑物、公共设施或者其他设施的；　　<br/>（六）驾驶人无有效机动车驾驶证的； 　　<br/><b>（七）驾驶人有饮酒、服用国家管制的精神药品或者麻醉药品嫌疑的； </b>　　<br/>（八）当事人不能自行移动车辆的。 　　<br/>发生财产损失事故，并具有前款第二项至第五项情形之一，车辆可以移动的，当事人可以在报警后，在确保安全的原则下对现场拍照或者标划停车位置，将车辆移至不妨碍交通的地点等候处理。', NULL),
('985', '驾驶机动车造成交通事故后逃逸，尚不构成犯罪的，由公安机关交通管理部门处二百元以上二千元以下罚款，可以并处15日以下拘留。', '1', '', '', '', '', '根据规定，造成交通事故后逃逸，尚不构成犯罪的，处二百元以上二千元以下罚款，并处十五日以下拘留。由公安机关交通管理部门吊销机动车驾驶证，且终生不得重新取得机动车驾驶证。
<br/>题目描述正确，因此答案为对。', NULL),
('986', '驾驶机动车遇到这种信号灯，可在对面直行车前直接向左转弯。', '2', '正确', '错误', '', '', '通过有交通标志标线的路口，右转弯让左转弯，转弯车让直行车。对面车辆是直行车，不能在它面前直接左转，要让行。', 'https://images.juheapi.com/jztk/c1c2subject1/986.jpg'),
('987', '机动车达到国家规定的强制报废标准的不能办理注册登记。', '1', '正确', '错误', '', '', '《机动车登记规定》有下列情形之一的，不予办理注册登记：机动车达到国家规定的强制报废标准的。', NULL),
('988', '驾驶机动车在高速公路上车辆发生故障时，若车辆可以移动至应急车道内，只需开启危险报警闪光灯，警告标志可根据交通流情况选择是否放置。', '2', '', '', '', '', '驾驶机动车在高速公路发生故障，需要停车排除故障时，应当进行如下顺序的操作：开启危险报警闪光灯；将车辆移至不妨碍交通的位置；放置警告标志，转移乘车人员至安全处，迅速报警；等待救援。', NULL),
('989', '这个标志是何含义？', '2', '左侧变窄', '窄桥', '窄路', '右侧变窄', '窄桥：用以警告车辆驾驶人注意前方桥面宽度变窄，应谨慎驾驶。设在桥面净宽较两端路面宽度变窄，且桥的净宽小于6 m的桥梁以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/989.jpg'),
('990', '这个标志是何含义？', '4', '高速公路缴费车道', '高速公路检查车道', '高速公路领卡车道', '高速公路ETC车道', '高速公路ETC车道：用于指示电子不停车收费车道，设在收费广场渐变段起点前300 m处。表示单向3个收费车道时ETC车道指示标志。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/990.jpg'),
('991', '这个标志的含义是提醒车辆驾驶人前方是单向行驶并且照明不好的涵洞。', '2', '正确', '错误', '', '', '图中是注意隧道警告标志。用以提醒车辆驾驶人注意慢行。设在双向行驶并且照明不好的隧道口前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/991.jpg'),
('992', '有吸食、注射毒品后驾驶驾车行为的机动车驾驶人，不会被注销驾驶证。', '2', '正确', '错误', '', '', '被查获有吸食、注射毒品后驾驶机动车行为，正在执行社区戒毒、强制隔离戒毒、社区康复措施，或者长期服用依赖性精神药品成瘾尚未戒除的，车辆管理所应当注销其机动车驾驶证。三年内有吸食、注射毒品行为，或者解除强制隔离戒毒措施未满三年，或者长期服用依赖性精神药品成瘾尚未戒除的，不得申请机动车驾驶证。', NULL),
('993', '这个标志是何含义？', '3', '高速公路客车站', '高速公路休息区', '高速公路加油站', '高速公路服务区', '高速公路加油站：用于指示加油站的位置，设在通往加油站的入口附近。查看高速公路标志大全：http://www.jszks.com/onepage/16721.html', 'https://images.juheapi.com/jztk/c1c2subject1/993.jpg'),
('994', '这种停车标线含义是什么？', '4', '专用待客停车位', '专用上下客停车位', '机动车限时停车位', '固定停车方向停车位', '这是固定停车方向停车位，车头要按箭头方向停放。', 'https://images.juheapi.com/jztk/c1c2subject1/994.jpg'),
('995', '路中心的双黄实线属于哪一类标线？', '3', '辅助标线', '警告标志', '禁止标线', '指示标线', '1.指示标线：道路上用黄色虚线、白色虚线划分的标线。2.禁止标线：道路上用黄色双实、单实线、白色的双实和单实划分的标线。3.警告标线：道路上用黄线划成的各种图形或线段以警告车通行的标线。', 'https://images.juheapi.com/jztk/c1c2subject1/995.jpg'),
('996', '驾驶机动车在上道路行驶前驾驶人要按规定系好安全带。', '1', '正确', '错误', '', '', '《道路交通安全法》第五十一条：机动车行驶时，驾驶人、乘坐人员应当按规定使用安全带，摩托车驾驶人及乘坐人员应当按规定戴安全头盔。', NULL),
('997', '《道路交通安全法实施条例》规定，高速公路上最高时速不得超过120公里。因此在高速公路上行驶只要时速不超过120公里就不违法。', '2', '正确', '错误', '', '', '不同车型的限速不同，不同车道的限速也不同。而且高速上不仅有最高限速，还有最低限速，并不是不高于120公里/小时就可以了的。', NULL),
('998', '在这段高速公路上行驶的最高车速是多少？', '4', '60公里/小时', '90公里/小时', '100公里/小时', '120公里/小时', '红圈白底限制最高速度，此路段最高车速是120公里每小时。', 'https://images.juheapi.com/jztk/c1c2subject1/998.jpg'),
('999', '车辆在主干道上行驶，驶近主支干道交汇处时，为防止与从支路突然驶入的车辆相撞，应怎样做？', '2', '保持正常速度行驶', '提前减速、观察，谨慎驾驶', '鸣喇叭，迅速通过', '提前加速通过', '最好的做法就是提前减速、观察，谨慎驾驶。这样才能避免与支路驶来的车相撞。', NULL),
('1000', '这种白色矩形标线框含义是什么？', '2', '出租车专用上下客停车位', '平行式停车位', '倾斜式停车位', '垂直式停车位', '路边的平行的停车位，亲 侧方停车以后要好好学哦~', 'https://images.juheapi.com/jztk/c1c2subject1/1000.jpg'),
('1001', '车辆不得在高速公路匝道上掉头。', '1', '正确', '错误', '', '', '按照规定：驶入确定匝道后，迅速提高车速，但不得超过规定速度，在匝道上，不准超车、掉头、停车、和倒车。', NULL),
('1002', '机动车在高速公路上遇前方交通受阻时，应当跟随前车顺序排队，并立即开启危险报警闪光灯，防止追尾。', '1', '正确', '错误', '', '', '开启危险警报闪光灯是为了提醒后车：前方有故障，请减速慢行，谨防追尾。', NULL),
('1003', '机动车在道路上发生故障，难以移动时下列做法正确的是什么？', '1', '开启危险报警闪光灯', '开启车上所有灯光', '禁止车上人员下车', '在车前方设置警告标志', '《道路交通安全法实施条例》第六十条：机动车在道路上发生故障或者发生交通事故，妨碍交通又难以移动的，应当按照规定开启危险报警闪光灯并在车后50米至100米处设置警告标志，夜间还应当同时开启示廓灯和后位灯。', NULL),
('1004', '车辆在交叉路口绿灯亮后，遇非机动车抢道行驶时，可以不让行。', '2', '正确', '错误', '', '', '安全第一，文明驾驶，礼貌让行。无论何时都应该主动让行，确保其安全。', NULL),
('1005', '遇到这种情况时，中间车道不允许车辆通行。', '1', '正确', '错误', '', '', '中间车道是红灯，故不允许车辆通行，两边是绿灯，所以应该在两边通行。', 'https://images.juheapi.com/jztk/c1c2subject1/1005.jpg'),
('1006', '车辆在高速公路以每小时100公里的速度行驶时，距同车道前车100米以上为安全距离。', '1', '正确', '错误', '', '', '根据《中华人民共和国道路交通安全法实施条例》第八十条 机动车在高速公路上行驶，车速超过每小时100公里时，应当与同车道前车保持100米以上的距离，车速低于每小时100公里时，与同车道前车距离可以适当缩短，但最小距离不得少于50米。', NULL),
('1007', '驾驶机动车在高速公路上倒车、逆行、穿越中央分隔带掉头的一次记6分。', '2', '正确', '错误', '', '', '《公安部令第123号》规定，驾驶机动车在高速公路上倒车、逆行、穿越中央分隔带掉头的，一次记12分 。', NULL),
('1008', '驾驶人在实习期内驾驶机动车时，应当在车身后部粘贴或者悬挂统一式样的实习标志。', '1', '正确', '错误', '', '', '《公安部令第123号》第六十四条：在实习期内驾驶机动车的，应当在车身后部粘贴或者悬挂统一式样的实习标志。', NULL),
('1009', '这样停放机动车什么违法行为？', '3', '在非机动车道停车', '在有禁停标志路段停车', '在公共汽车站停车', '停车占用人行道', '图为公共汽车站。公共汽车站、急救站、加油站、消防栓或者消防队（站）门前以及距离上述地点３０米以内的路段，除使用上述设施的以外，不得停车。', 'https://images.juheapi.com/jztk/c1c2subject1/1009.jpg'),
('1010', '机动车停稳前不能开车门和上下人员。', '1', '正确', '错误', '', '', '安全第一，一定要在车子停稳之后再上下车！', NULL),
('1011', '驾驶机动车在高速公路遇到能见度低于200米的气象条件时，最高车速是多少？', '3', '不得超过100公里/小时', '不得超过90公里/小时', '不得超过60公里/小时', '不得超过80公里/小时', '高速公路行车限速：（1）最低限速60公里/小时（2）特殊情况限速：能见度小于200米限速60公里/小时、能见度小于100米限速40公里/小时、能见度小于50米限速20公里/小时。', NULL),
('1012', '在这种情形中前车怎样行驶？', '2', '正常行驶', '及时让行', '开启危险报警闪光灯行驶', '不得变更车道', '《道路法》第五十三条第1款　警车、消防车、救护车、工程救险车执行紧急任务时，其他车辆和行人应当让行。', 'https://images.juheapi.com/jztk/c1c2subject1/1012.jpg'),
('1013', '遇后车发出超车信号后，只要具备让超条件应怎样做？', '2', '靠道路右侧加速行驶', '主动减速并靠右侧行驶', '让出适当空间加速行驶', '迅速减速或紧急制动', '文明礼让，和谐驾驶。如果遇到后车发出超车信号，我们应该主动减速并靠右侧行驶。', NULL),
('1014', '机动车驾驶人在实习期内有记满12分记录的，注销其实习的准驾车型驾驶资格。', '1', '正确', '错误', '', '', '公安部123号令规定：<br/>第六十四条 机动车驾驶人初次申请机动车驾驶证和增加准驾车型后的12个月为实习期。<br/>第六十九条 <b>机动车驾驶人在实习期内有记满12分记录的，注销其实习的准驾车型驾驶资格。</b>', NULL),
('1015', '驾驶机动车在高速公路违法占用应急车道行驶的一次记6分。', '1', '正确', '错误', '', '', '《公安部令第123号》规定，驾驶机动车在高速公路或者城市快速路上违法占用应急车道行驶的，一次记6分 。', NULL),
('1016', '驾驶机动车在这种信号灯亮的路口，可以右转弯。', '1', '正确', '错误', '', '', '要看路口的信号灯。如果路口只有红、黄、绿圆形三色的信号灯时，就可以直接右转弯。如果路口信号灯有箭头指示灯时，需要根据箭头灯的指示。', 'https://images.juheapi.com/jztk/c1c2subject1/1016.jpg'),
('1017', '夜间驾驶机动车在窄路、窄桥会车怎样使用灯光？', '2', '关闭所有灯光', '开启近光灯', '关闭前照灯', '开启远光灯', '《道路交通安全法实施条例》第四十八条： 在没有中心隔离设施或者没有中心线的道路上，夜间会车应当在距相对方向来车150米以外改用近光灯，<b>在窄路、窄桥与非机动车会车时应当使用近光灯。</b>', NULL),
('1018', '驾驶车辆进入交叉路口前，应降低行驶速度，注意观察，确认安全。', '1', '正确', '错误', '', '', '进入交叉路口时，要安全驾驶，减速前行。', NULL),
('1019', '行车中前方遇自行车影响通行时，可鸣喇叭提示，加速绕行。', '2', '正确', '错误', '', '', '本题错在加速绕行，鸣喇叭提示是对的。应当减速与其保持安全距离，道路宽度允许通过时谨慎通过。因此本题错了。', NULL),
('1020', '驾驶机动车通过窄路、窄桥时，最高速度不能超过多少？', '3', '50公里/小时', '40公里/小时', '30公里/小时', '60公里/小时', '机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 <br/>（一）进出非机动车道，通过铁路道口、急弯路、<b>窄路、窄桥时；</b>　　 <br/>（二）掉头、转弯、下陡坡时；　　 <br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 <br/>（四）在冰雪、泥泞的道路上行驶时；', NULL),
('1021', '在这个路口可以掉头。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第四十九条：机动车在有禁止掉头或者禁止左转弯标志、标线的地点以及在铁路道口、人行横道、桥梁、急弯、陡坡、隧道或者容易发生危险的路段，不得掉头。', 'https://images.juheapi.com/jztk/c1c2subject1/1021.jpg'),
('1022', '夜间起步前，应当先开启近光灯。', '1', '正确', '错误', '', '', '夜间起步，先开启近光灯观察路况，确认周围情况后，在开启左转向灯，起步。', NULL),
('1023', '在山区道路超车时，应怎样超越？', '2', '抓住任何机会尽量', '选择宽阔的缓上坡路段', '选择较长的下坡路', '选择较缓的下坡路', '下坡不允许超车，超车选择宽阔的缓上坡路段比较安全。上坡有阻力，不宜滑车，也不宜撞车，所以上坡宽阔地可以超车。', NULL),
('1024', '在高速公路变更车道时，应提前开启转向灯，观察情况，确认安全后，驶入需要变更的车道。', '1', '正确', '错误', '', '', '变更车道时，需先开启转向灯提示后车，其次要观察路况，确认安全后再变更车道。', NULL),
('1025', '驾驶车辆时，长时间左臂搭在车门窗上，或者长时间右手抓住变速器操纵杆，是一种驾驶陋习。', '1', '正确', '错误', '', '', '长时间左臂搭在车门窗上，或者长时间右手抓住变速器操纵杆，如果出现紧急情况，驾驶员很难做出良好及时的应对，属于驾驶陋习。', NULL),
('1026', '驾驶机动车找不到停车位时可以借人行道停放。', '2', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》第五十六条“机动车应当在规定地点停放，禁止在人行道上停放机动车。”', NULL),
('1027', '在道路上发生未造成人员伤亡且无争议的轻微交通事故如何处置？', '3', '不要移动车辆', '疏导其他车辆绕行', '撤离现场自行协商', '保护好现场再协商', '《道路交通安全法》第七十条：<b>在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜；</b>不立即撤离现场的，应当迅速报告执勤的交通警察或者公安机关交通管理部门。 在道路上发生交通事故，仅造成轻微财产损失，并且基本事实清楚的，当事人应当先撤离现场再进行协商处理。', NULL),
('1028', '机动车在高速公路上发生故障或交通事故无法正常行驶时由什么车拖曳或牵引？', '4', '过路车', '大客车', '同行车', '清障车', '《道路交通安全法》第六十八条：机动车在高速公路上发生故障时，应当依照本法第五十二条的有关规定办理；但是，警告标志应当设置在故障车来车方向一百五十米以外，车上人员应当迅速转移到右侧路肩上或者应急车道内，并且迅速报警。<b>机动车在高速公路上发生故障或者交通事故，无法正常行驶的，应当由救援车、清障车拖曳、牵引。</b>', NULL),
('1029', '驾驶人一边驾车，一边吸烟对安全行车无影响。', '2', '正确', '错误', '', '', '驾驶车辆吸烟不仅对车上乘客有害，也会让驾驶员分心，对安全行车是有影响的。', NULL),
('1030', '驾驶人有使用其他车辆保险标志嫌疑的，交通警察可依法扣留车辆。', '1', '正确', '错误', '', '', '《道路交通安全违法行为处理程序规定》第二十五条规定，有下列情形之一的，依法扣留车辆：有伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、检验合格标志、 保险标志、驾驶证或者使用其他车辆的机动车登记证书、号牌、行驶证、检验合格标志、保险标志嫌疑的。', NULL),
('1031', '这辆红色轿车变更车道的方法和路线是正确的。', '2', '正确', '错误', '', '', '红车在变道的时候没有打转向灯，并且红车明显没留出足够安全的行车距离强行并线，这是错误的变更车道方式。
<br/>题目描述有误，本题答案应为错误。', 'https://images.juheapi.com/jztk/c1c2subject1/1031.jpg'),
('1032', '机动车在高速公路上发生故障时错误的做法是什么？', '3', '按规定设置警告标志', '迅速报警', '车上人员不能下车', '开启危险报警闪光灯', '《道路交通安全法》第五十二条：
<br/>机动车在道路上发生故障，需要停车排除故障时，驾驶人应当立即<b>开启危险报警闪光灯</b>，将机动车移至不妨碍交通的地方停放；难以移动的，应当<b>持续开启危险报警闪光灯</b>，并在来车方向设置警告标志等措施扩大示警距离，必要时迅速报警。
<br/>第六十八条：
<br/>机动车在高速公路上发生故障时，应当依照本法第五十二条的有关规定办理；警告标志应当设置在故障车来车方向一百五十米以外，<b>车上人员应当迅速转移到右侧路肩上或者应急车道内，并且迅速报警。</b>
<br/>题目要求是发生故障时的错误做法是什么，选项中ABD都是正确的，C项错误（车上人应应当迅速转移到右侧路肩上或者应急车道内，不应该不下车）。因此本题答案选C。', NULL),
('1033', '行车中遇残疾人影响通行时，应主动减速礼让。', '1', '正确', '错误', '', '', '残疾人行动不便，遇到残疾人一定要减速让行，必要时还需停车让行。', NULL),
('1034', '夜间驾驶机动车在窄路、窄桥会车时正确的做法是使用远光灯。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第四十八条： 在没有中心隔离设施或者没有中心线的道路上，夜间会车应当在距相对方向来车150米以外改用近光灯，<b>在窄路、窄桥与非机动车会车时应当使用近光灯。</b>', NULL),
('1035', '在这段道路上不能掉头。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第四十九条：机动车在有禁止掉头或者禁止左转弯标志、标线的地点以及在铁路道口、人行横道、桥梁、急弯、陡坡、隧道或者容易发生危险的路段，不得掉头。', 'https://images.juheapi.com/jztk/c1c2subject1/1035.jpg'),
('1036', '将点火开关转到ACC位置起动机工作。', '2', '正确', '错误', '', '', 'LOCK-----（锁止），ACC------------ (断电)
<br/>ON--------（通电），START--------（起动）', 'https://images.juheapi.com/jztk/c1c2subject1/1036.jpg'),
('1037', '行车中当驾驶人意识到车辆爆胎时，应在控制住方向的情况下采取紧急制动，迫使车辆迅速停住。', '2', '正确', '错误', '', '', '车辆爆胎后，应先控制方向，保持直线行驶，然后利用发动机制动，缓慢减速停车。不能采取紧急制动，容易翻车。', NULL),
('1038', '驶入高速公路的收费口时，应选择怎样的入口？', '3', '车辆多', '红灯亮', '绿灯亮', '暂停服务', '绿灯是表示收费站正常运行的，所以应该选择绿灯亮的入口。', NULL),
('1039', '通过急转弯路段时，在车辆较少的情况下可以超车。', '2', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》 第四十三条 同车道行驶的机动车，……有下列情形之一的，不得超车： 
<br/>（一）前车正在左转弯、掉头、超车的； 
<br/>（二）与对面来车有会车可能的； 
<br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的； 
<br/>（四）行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。
<br/> <b>通过隧道，铁路道口，急转弯路段，窄路，窄桥或遇前方道路上有车辆掉头时，不得超车。</b>', NULL),
('1040', '在这段道路上，只要不影响其他车辆通行的前提下可以掉头。', '1', '正确', '错误', '', '', '黄线用来区分不同方向的车道，一般画在马路正中，好像一条隔离带，把马路隔成两个方向： 1、无论单黄线还是双黄线，只要是实线，就严禁跨越的，比如超车、转弯、掉头等。行车时没有特别情况就不应该越线。 <b>2、无论单黄线还是双黄线，只要是虚线，就可以在保证安全的情况下超车或掉头。</b>', 'https://images.juheapi.com/jztk/c1c2subject1/1040.jpg')
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('1041', '驾驶机动车超车后立即开启右转向灯驶回原车道。', '2', '正确', '错误', '', '', '错，不能立即，应在与被超车辆拉开必要的安全距离后，开启右转向灯驶回原车道。', NULL),
('1042', '行车中，发现行人突然横过道路时，应迅速减速避让。', '1', '正确', '错误', '', '', '发现行人突然横过道路时，应迅速减速避让，确保行人安全。', NULL),
('1043', '驾驶机动车行经下列哪种路段时不得超车？', '2', '高架路', '交叉路口', '中心街道', '环城高速', '《中华人民共和国道路交通安全法》第四十三条：
<br/>同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：
<br/>（一）前车正在左转弯、掉头、超车的；
<br/>（二）与对面来车有会车可能的；
<br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的；
<br/>（四）行经铁路道口、<b>交叉路口、</b>窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。', NULL),
('1044', '遇到这种情况下可以从右侧超车。', '2', '正确', '错误', '', '', '超车只能从左侧超车，任何情况下都是不能从右边超车的。', 'https://images.juheapi.com/jztk/c1c2subject1/1044.jpg'),
('1045', '通过山区危险路段，尤其是通过经常发生塌方、泥石流的山区地段，应谨慎驾驶，避免停车。', '1', '正确', '错误', '', '', '经常发生塌方、泥石流的都属于危险地段，所以能尽快离开就尽快离开，避免停车。', NULL),
('1046', '机动车仪表板上（如图所示）亮，提示发动机舱开启。', '2', '正确', '错误', '', '', '此为行李舱开启指示灯。当机动车仪表板上该符号亮起，表示行李舱开启。题目描述错误，因此本题答案为错。
<br/>
<br/>【拓展延伸】
<br/><p><img src=http://tp.mnks.cn/tp_423.jpg>
<br/>行李舱开启</p><p><img src=http://tp.mnks.cn/tp_404.jpg>
<br/>发动机舱开启</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1046.jpeg'),
('1047', '下长坡时，控制车速除了刹车制动以外还有什么有效的辅助方法？', '2', '挂入空挡滑行', '利用发动机制动', '关闭发动机熄火滑行', '踏下离合器滑行', '<b>发动机制动就是挂低档，让车利用低档位的惯性制动。</b>下长坡时，可以通过这种方式有效控制车速。', NULL),
('1048', '如何通过这种交叉路口？', '3', '保持速度通过', '鸣笛催促', '减速慢行', '加速通过', '路旁有多名行人马上要横穿马路，一定要减速慢行，保证行人安全。', 'https://images.juheapi.com/jztk/c1c2subject1/1048.jpg'),
('1049', '驾驶机动车超车应该提前开启左转向灯、变换使用远近光灯或鸣喇叭。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第四十七条：<br/>机动车超车时，应当提前开启左转向灯、变换使用远、近光灯或者鸣喇叭。', NULL),
('1050', '在这种环境里行车使用近光灯。', '1', '正确', '错误', '', '', '注意观察题目图片，夜间驾驶机动车，机动车前方有人行横道，<b>路边有行人</b>。在这种情况下行车应该使用近光灯，不妨碍行人正常通行。题目描述正确，因此本题答案为对。', 'https://images.juheapi.com/jztk/c1c2subject1/1050.jpg'),
('1051', '驾驶机动车在沙尘天气条件下行车不用开启前照灯、示廓灯和后位灯。', '2', '正确', '错误', '', '', '《道路交通安全法实施条例》第五十八条： 机动车在夜间没有路灯、照明不良或者<b>遇有雾、雨、雪、沙尘、冰雹等低能见度情况下行驶时，应当开启前照灯、示廓灯和后位灯，</b>但同方向行驶的后车与前车近距离行驶时，不得使用远光灯。机动车雾天行驶应当开启雾灯和危险报警闪光灯。
<br/>题目描述有误，本题答案应为错误。', NULL),
('1052', '在这个路口左转弯选择哪条车道？', '1', '最左侧车道', '中间车道', '不用变道', '最右侧车道', '只有最左侧车道有左转的标志，而且目前所处位置是虚线位置，是可以变道的。', 'https://images.juheapi.com/jztk/c1c2subject1/1052.jpg'),
('1053', '倒车过程中要缓慢行驶，注意观察车辆两侧和后方的情况，随时做好停车准备。', '1', '正确', '错误', '', '', '倒车时主要观察车后面和车两侧的情况，整个过程要缓慢谨慎，安全第一。', NULL),
('1054', '行车中遇到后方车辆要求超车时，应怎样做？', '2', '保持原有车速行驶', '及时减速、观察后靠右行驶让行', '靠右侧加速行驶', '不让行', '基于安全和和谐的因素，所以要及时减速让行。', NULL),
('1055', '驾驶机动车在没有交通信号的路口遇到前方车辆缓慢行驶时要依次交替通行。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》第四十五条明确规定：在车道减少的路段、路口，或者在没有交通信号灯、交通标志、交通标线或者交通警察指挥的交叉路口遇到停车排队等候或者缓慢行驶时，机动车应当依次交替通行。', NULL),
('1056', '同车道行驶的车辆遇前车有下列哪种情形时不得超车？', '3', '减速让行', '正常行驶', '正在超车', '正在停车', '同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：  ①《《前车正在左转弯、掉头、超车的》》;  ②与对面来车有会车可能的;  ③前车为执行紧急任务的警车、消防车、救护车、工程救险车的;  ④行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。', NULL),
('1057', '（如图所示）这个符号的开关控制什么装置？', '3', '前风窗玻璃刮水器及洗涤器', '后风窗玻璃除霜或除雾', '后风窗玻璃刮水器及洗涤器', '前风窗玻璃除霜或除雾', '此为后风窗玻璃刮水器及洗涤器。关于如何区分前风窗玻璃刮水器及洗涤器和后风窗玻璃刮水器及洗涤器，你只需记住一点半弧形的图标是前风窗，四四方方的图标就是后风窗。', 'https://images.juheapi.com/jztk/c1c2subject1/1057.jpeg'),
('1058', '通过铁路道口时，不得超车。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》 第四十三条 同车道行驶的机动车，……有下列情形之一的，不得超车： <br/>（一）前车正在左转弯、掉头、超车的； <br/>（二）与对面来车有会车可能的； <br/>（三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的； <br/>（四）<b>行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。</b>', NULL),
('1059', '车辆在下坡行驶时，可充分利用空挡滑行。', '2', '正确', '错误', '', '', '下坡时，绝对不能熄火或空档滑行。<b>如果下坡空档滑行，只靠刹车来控制车速，遇到连续下坡的时候可能会造成刹车负担过重，刹车片过热而失灵。</b>', NULL),
('1060', '机动车仪表板上（如图所示）一直亮，表示安全气囊处于工作状态。', '2', '正确', '错误', '', '', '圆圈表示安全气囊，此标志亮，说明安全气囊处于故障状态。', 'https://images.juheapi.com/jztk/c1c2subject1/1060.jpeg'),
('1061', '机动车驾驶人在实习期内驾驶机动车不得牵引挂车。', '1', '正确', '错误', '', '', '《公安部令第123号》第六十五条规定：机动车驾驶人在<b>实习期内</b>不得驾驶公共汽车、营运客车或者执行任务的警车、消防车、救护车、工程救险车以及载有爆炸物品、易燃易爆化学物品、剧毒或者放射性等危险物品的机动车；<b>驾驶的机动车不得牵引挂车。</b>', NULL),
('1062', '驾驶机动车在道路上靠路边停车过程中如何使用灯光？', '2', '开启危险报警闪光灯', '提前开启右转向灯', '变换使用远近光灯', '不用指示灯提示', '《道路交通安全法实施条例》第五十七条 机动车应当按照下列规定使用转向灯： (一)向左转弯、向左变更车道、准备超车、驶离停车地点或者掉头时，应当提前开启左转向灯； <b>(二)向右转弯、向右变更车道、超车完毕驶回原车道、靠路边停车时，应当提前开启右转向灯。</b>
<br/>注意题干所说的是“靠边停车过程中”，而非已经靠边停车了。所以应该提前开启右转向灯，本题答案应为D。', NULL),
('1063', '车辆在高速公路匝道提速到每小时60公里以上时，可直接驶入行车道。', '2', '正确', '错误', '', '', '高速公路匝道是高速公路出口或入口靠右侧的一条道路（一般在150－200米）。入口处匝道过后是加速车道，出口处匝道紧接在减速道之后。匝道内车速一般要求低于40km/h，加速车道内应迅速加速至60km/h以上。　 <br/>驾驶车辆从匝道进入高速公路加速车道后，打开左转向灯或者不打开均可，尽快将车速提高到每小时60公里以上，<b>并仔细观察车道上车辆行驶的情况，选择驶入行车道的时机。</b>不准在加速车道紧急制动或停车。行车道车辆稀少时，可以正常行驶车辆后驶入行车道；遇高速公路正常行驶车辆尾随相距较近时，应控制好车速，在所有车辆通过后再驶入行车道。<br/><b>本题错在直接两字，没有一个观察的动作。</b>', NULL),
('1064', '遇到路口情况复杂时，应做到“宁停三分，不抢一秒”。', '1', '正确', '错误', '', '', '文明驾车，安全行驶。', NULL),
('1065', '驾驶机动车在道路上超车完毕驶回原车道时开启右转向灯。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例实施条例》第五十七条：机动车应当按照下列规定使用转向灯：
<br/>（一）向左转弯、向左变更车道、准备超车、驶离停车地点或者掉头时，应当提前开启左转向灯；
<br/><b>（二）向右转弯、向右变更车道、超车完毕驶回原车道、靠路边停车时，应当提前开启右转向灯。</b>
<br/>题目描述无误，本题答案为对。', NULL),
('1066', '（如图所示）这个符号的开关控制什么装置？', '1', '儿童安全锁', '两侧车窗玻璃', '电动车门', '车门锁住开锁', '你看里边长的多像一个小孩，故选A最靠谱。', 'https://images.juheapi.com/jztk/c1c2subject1/1066.jpeg'),
('1067', '通过窄路、窄桥时，不得超车。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法》第四十三条 同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：（四）行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。 <b>通过隧道，铁路道口，急转弯路段，窄路，窄桥或遇前方道路上有车辆掉头时，不得超车。</b>', NULL),
('1068', '在这种天气条件下行车如何使用灯光？', '2', '使用远光灯', '使用雾灯', '不使用灯光', '开启右转向灯', '能见度这么低一定要开启雾灯。', 'https://images.juheapi.com/jztk/c1c2subject1/1068.jpg'),
('1069', '车辆驶入双向行驶隧道前，应开启什么灯？', '1', '示廓灯或近光灯', '雾灯', '远光灯', '危险报警闪光灯', '<b>凡是车辆进入双向行驶隧道，都应该开启近光灯或示廓灯，</b>提醒其他车辆，避免发生事故。', NULL),
('1070', '在这段路的最高时速为每小时50公里。', '2', '正确', '错误', '', '', '白底红圈表示最高限速，蓝色牌子表示最低限速。所以最高时速应该为80公里/小时。
<br/>题目描述有误，因此本题答案应为错误。', 'https://images.juheapi.com/jztk/c1c2subject1/1070.jpg'),
('1071', '当驾驶车辆行经两侧有非机动车行驶且有积水的路面时，应怎样做？', '1', '减速慢行', '正常行驶', '加速通过', '连续鸣喇叭', '文明驾驶。减速行驶能够防止水溅到行人身上。', NULL),
('1072', '行驶车道绿灯亮时，但车辆前方人行横道仍有行人行走，应怎样做？', '3', '直接起步通过', '起步后从行人后方绕过', '等行人通过后再起步', '起步后从行人前方绕过', '从前方绕、后方绕、直接通过都会惊扰到行人，有可能造成事故。正确做法是等行人通过后再起步。', NULL),
('1073', '这个标志的含义是提醒车辆驾驶人前方是堤坝路段。', '2', '正确', '错误', '', '', '<p><img src=http://tp.mnks.cn/tp_144.jpg>
<br/>堤坝路
<br/><img src=http://tp.mnks.cn/tp_143.jpg>
<br/>傍山险路</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1073.jpg'),
('1074', '机动车仪表板上（如图所示）亮，提示右侧车门未关闭。', '2', '正确', '错误', '', '', '从图而知，是左侧车门是开启状态，因此该标志是指左侧车门未关闭。', 'https://images.juheapi.com/jztk/c1c2subject1/1074.jpeg'),
('1075', '驾驶机动车通过没有交通信号和管理人员的铁路道口怎样通过？', '3', '适当减速通过', '空挡滑行通过', '停车确认安全后通过', '加速尽快通过', '《道路交通安全法》第四十六条：机动车通过铁路道口时，应当按照交通信号或者管理人员的指挥通行；<b>没有交通信号或者管理人员的，应当减速或者停车，在确认安全后通过。</b>', NULL),
('1076', '雨天行车，遇撑雨伞和穿雨衣的行人在公路上行走时，应怎样做？', '3', '持续鸣喇叭示意其让道', '加速绕行', '提前鸣喇叭，并适当降低车速', '以正常速度行驶', '安全驾驶，减速慢行。遇到撑雨伞和穿雨衣会使视线受阻碍，所以要鸣喇叭，雨天路滑所以要减速。', NULL),
('1077', '驾驶机动车在高速公路遇到能见度低于100米的气象条件时，最高车速是多少？', '1', '不得超过40公里/小时', '不得超过60公里/小时', '不得超过80公里/小时', '不得超过90公里/小时', '《道路交通安全法实施条例》第八十一条：机动车在高速公路上行驶，遇有雾、雨、雪、沙尘、冰雹等低能见度气象条件时，应当遵守下列规定：(一)能见度小于200米时，开启雾灯、近光灯、示廓灯和前后位灯，车速不得超过每小时60公里，与同车道前车保持100米以上的距离；<b>(二)能见度小于100米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时40公里，与同车道前车保持50米以上的距离；</b>(三)能见度小于50米时，开启雾灯、近光灯、示廓灯、前后位灯和危险报警闪光灯，车速不得超过每小时20公里，并从最近的出口尽快驶离高速公路。', NULL),
('1078', '在这种情况的交叉路口转弯要让直行车先行。', '1', '正确', '错误', '', '', '三个先行原则：转弯的机动车让直行的车辆先行，右方道路来车先行，右转弯车让左转弯车先行。', 'https://images.juheapi.com/jztk/c1c2subject1/1078.jpg'),
('1079', '设有安全带装置的车辆，应要求车内乘员系安全带。', '1', '正确', '错误', '', '', '行车过程中，即使是设有安全装置的车内，驾驶员与非驾驶员都要系安全带，安全第一!', NULL),
('1080', '行车中从其他道路汇入车流前，应注意观察侧后方车辆的动态。', '1', '正确', '错误', '', '', '行车中从其他道路线汇入车流前，应注意观察侧后方车辆的动态，确保行车安全。', NULL),
('1081', '夜间会车时，若对方车辆不关闭远光灯，可变换灯光提示对向车辆，同时减速靠右侧行驶或停车。', '1', '正确', '错误', '', '', '夜间安全驾驶知识中第三条就有：“夜间会车应当在距对方来车150米以外改用近光灯，若对方车辆不关闭远光灯，可连续变换灯光提示对向车辆。当遇对面来车仍不关闭远光灯时，应及时减速靠右侧行驶或停车让行。”', NULL),
('1082', '驾驶机动车在道路上掉头时提前开启左转向灯。', '1', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第五十七条 机动车应当按照下列规定使用转向灯： 
<br/><b>（一）向左转弯、向左变更车道、准备超车、驶离停车地点或者掉头时，应当提前开启左转向灯。</b>
<br/>（二）向右转弯、向右变更车道、超车完毕驶回原车道、靠路边停车时，应当提前开启右转向灯。
<br/>因此，本题答案应为正确。', NULL),
('1083', '机动车仪表板上（如图所示）亮时，表示驻车制动器处于制动状态。', '1', '正确', '错误', '', '', '圆圈里面是“P” 表示驻车制动器处于制动状态，即手刹没松开，但是车辆没有发生故障。
<br/>里面是“！” 表示制动系统异常或故障。', 'https://images.juheapi.com/jztk/c1c2subject1/1083.jpeg'),
('1084', '驾驶人发现轮胎漏气，将车辆驶离主车道时，不要采用紧急制动，以免造成翻车或后车采取制动不及时导致追尾事故。', '1', '正确', '错误', '', '', '轮胎漏气时不能采取紧急制动，容易造成翻车。应控制住方向，慢慢停车。', NULL),
('1085', '车辆行至泥泞或翻浆路段时，应停车观察，选择平整、坚实的路段缓慢通过。', '1', '正确', '错误', '', '', '泥泞翻浆路段行车容易发生侧滑，应该停车仔细观察后，降低车速，选择平整、坚实的路段缓慢通过。', NULL),
('1086', '车辆下长坡时要减挡行驶，以充分利用发动机的制动作用。', '1', '正确', '错误', '', '', '变速箱高档位高速持续运转中，迅速降低变速箱的档位转速，使变速箱的低档位转速对车辆本身的惯性高速产生抑制，从而产生短时间内的所谓发动机制动(变速箱制动)。', NULL),
('1087', '驾驶机动车掉头、转弯、下陡坡时的最高速度不能超过每小时40公里。', '2', '正确', '错误', '', '', '机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 <br/>（一）进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；　　 <br/><b>（二）掉头、转弯、下陡坡时；</b>　　 <br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 <br/>（四）在冰雪、泥泞的道路上行驶时。', NULL),
('1088', '预计在超车过程中与对面来车有会车可能时，应提前加速超越。', '2', '正确', '错误', '', '', '预计在超车过程中与对面来车有会车可能时，应当放弃超车。若加速超越，有可能会引起不必要的事故。', NULL),
('1089', '下列哪种行为会受到200元以上2000元以下罚款，并处吊销机动车驾驶证？', '2', '违反道路通行规定', '超过规定时速50%', '造成交通事故后逃逸', '驾车没带驾驶证', '第九十九条　有下列行为之一的，由公安机关交通管理部门处二百元以上二千元以下罚款：
<br/>（一）未取得机动车驾驶证、机动车驾驶证被吊销或者机动车驾驶证被暂扣期间驾驶机动车的；
<br/>（二）将机动车交由未取得机动车驾驶证或者机动车驾驶证被吊销、暂扣的人驾驶的；
<br/>（三）造成交通事故后逃逸，尚不构成犯罪的；
<br/><b>（四）机动车行驶超过规定时速百分之五十的；（超过规定时速50%）</b>
<br/>（五）强迫机动车驾驶人违反道路交通安全法律、法规和机动车安全驾驶要求驾驶机动车，造成交通事故，尚不构成犯罪的；
<br/>（六）违反交通管制的规定强行通行，不听劝阻的；
<br/>（七）故意损毁、移动、涂改交通设施，造成危害后果，尚不构成犯罪的；
<br/>（八）非法拦截、扣留机动车辆，不听劝阻，造成交通严重阻塞或者较大财产损失的。
<br/><b>行为人有前款第二项、第四项情形之一的，可以并处吊销机动车驾驶证</b>；有第一项、第三项、第五项至第八项情形之一的，可以并处十五日以下拘留。
<br/>
<br/>A选项中，违反道路通行规定的说法太宽泛了，不适用于具体的处罚标准。
<br/>C选项中，造成交通事故逃逸的处罚是：吊销机动车驾驶证，且终生不得重新取得机动车驾驶证。如果造成交通事故逃逸，不构成犯罪的，处罚款200以上2000以下。但选项中没有说明是否构成犯罪，因此不能判断罚款金额。
<br/>D选项中，驾车没带驾驶证的处罚是：扣留机动车，通知驾驶人提供驾驶证。
<br/>
<br/>综上，本题应该选B。', NULL),
('1090', '轮胎气压过低时，高速行驶轮胎会出现波浪变形温度升高而导致什么？', '3', '气压更低', '行驶阻力增大', '爆胎', '气压不稳', '轮胎气不足，会造成轮胎与地面的摩擦范围增大，温度升高从而爆胎。压力过低和过高都会导致爆胎。', NULL),
('1091', '驾驶机动车在路口遇到这种情况如何行驶？', '1', '停车等待', '遵守交通信号灯', '靠右侧直行', '可以向右转弯', '<p><img src=http://nimg.cysq.com/yxlimg/8298e043.gif>
<br/>停止</p>
<br/>1、首先，在有交警指挥的路口，应首先按照交警指挥进行通行。
<br/>2、其次，图中交警的手势为停止信号，驾驶员应该按照交警手势停车等待。
<br/>因此本题答案应为D。', 'https://images.juheapi.com/jztk/c1c2subject1/1091.jpg'),
('1092', '行车中当驾驶人意识到爆胎时，应在控制住方向的情况下，轻踏制动踏板，使车辆缓慢减速，逐渐平稳地停靠于路边。', '1', '正确', '错误', '', '', '这种情况下为了保障安全，驾驶员首先要做的就是控制住方向，然后缓慢减速，平稳停车。', NULL),
('1093', '在这条公路上行驶的最高速度不能超过多少？', '3', '70公里/小时', '50公里/小时', '40公里/小时', '30公里/小时', '根据《中华人民共和国道路交通安全法实施条例》第四十五条：……在没有限速标志、标线的道路上，机动车不得超过下列最高行驶速度：　　(一)没有道路中心线的道路，城市道路为每小时30公里，公路为每小时40公里；　　(二)同方向只有1条机动车道的道路，城市道路为每小时50公里，公路为每小时70公里。图为没有道路中心线的公路，所以最高时速为40公里每小时。', 'https://images.juheapi.com/jztk/c1c2subject1/1093.jpg'),
('1094', '机动车 仪表板上（如图所示）亮表示发动机可能机油压力过高。', '2', '正确', '错误', '', '', '图片表示发动机可能机油压力不足。', 'https://images.juheapi.com/jztk/c1c2subject1/1094.jpeg'),
('1095', '开启前照灯远光时仪表板上（如图所示）亮起。', '2', '正确', '错误', '', '', '<p><img src=http://tp.mnks.cn/tp_387.jpg>
<br/>前照远光灯</p>
<br/><p><img src=http://tp.mnks.cn/tp_388.jpg>
<br/>前照近光灯</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1095.jpeg'),
('1096', '驾驶车辆汇入车流时，应提前开启转向灯，保持直线行驶，通过后视镜观察左右情况，确认安全后汇入合流。', '1', '正确', '错误', '', '', '在汇入车流是先开转向灯的，是为了提示后面的车避让留下进入车流的空隙，保持直行一段，因为是汇入合流，要确认好车与车横向空隙就要用后视镜看左右了。', NULL),
('1097', '红色圆圈内标线含义是什么？', '2', '临时停靠站', '港湾式停靠站', '应急停车带', '公交车停靠站', '请记住', 'https://images.juheapi.com/jztk/c1c2subject1/1097.jpg'),
('1098', '驾驶机动车通过交叉路口要遵守交通信号。', '1', '正确', '错误', '', '', '《道路交通安全法》第四十四条：机动车通过交叉路口，应当按照交通信号灯、交通标志、交通标线或者交通警察的指挥通过；通过没有交通信号灯、交通标志、交通标线或者交通警察指挥的交叉路口时，应当减速慢行，并让行人和优先通行的车辆先行。', NULL),
('1099', '在这种情况的铁路道口要加速通过。', '2', '正确', '错误', '', '', '前面是火车道，道口红灯已经亮起，表明即将有火车通过。这个时候应当停车等待，等火车过去了再通过。', 'https://images.juheapi.com/jztk/c1c2subject1/1099.jpg'),
('1100', '遇到这种情况的路口怎样通过？', '1', '确认安全后通过', '右转弯加速通过', '加速直行通过', '左转弯加速通过', '这个路口只有一个信号灯，也就说只有黄灯，而且一直在闪烁，表示警示，提醒过往车辆注意瞭望。并且当前路口有其他车辆转弯，有行人接近，必须确认安全后通过。', 'https://images.juheapi.com/jztk/c1c2subject1/1100.jpg'),
('1101', '这个仪表是何含义？', '1', '水温表', '燃油表', '电流表', '压力表', '看到那个温度计没说明他是管温度的。', 'https://images.juheapi.com/jztk/c1c2subject1/1101.jpg'),
('1102', '在这个路口右转弯如何通行？', '4', '直接向右转弯', '抢在对面车前右转弯', '鸣喇叭催促', '先让对面车左转弯', '对面左转车辆已到路口中间，本车先让对面左转弯车转弯再右转。', 'https://images.juheapi.com/jztk/c1c2subject1/1102.jpg'),
('1103', '在交叉路口遇到这种情况享有优先通行权。', '1', '正确', '错误', '', '', '右转让左转，没有问题。', 'https://images.juheapi.com/jztk/c1c2subject1/1103.jpg'),
('1104', '在这条高速公路上行驶时的最高速度不能超过多少？', '1', '110公里/小时', '120公里/小时', '90公里 /小时', '100公里/小时', '《道路交通安全法实施条例》第七十八条：道路限速标志标明的车速与上述车道行驶车速的规定不一致的，按照道路限速标志标明的车速行驶。
<br/>图中的红圈白底图标，是限速标志。表示最高行驶速度不得超过110公里/小时，因此本题应该选B。', 'https://images.juheapi.com/jztk/c1c2subject1/1104.jpg'),
('1105', '在这条公路上行驶的最高速度不能超过多少？', '4', '30公里/小时', '40公里/小时', '50公里/小时', '70公里/小时', '根据《中华人民共和国道路交通安全法实施条例》第四十五条：……在没有限速标志、标线的道路上，机动车不得超过下列最高行驶速度：　　(一)没有道路中心线的道路，城市道路为每小时30公里，公路为每小时40公里；　　(二)同方向只有1条机动车道的道路，城市道路为每小时50公里，公路为每小时70公里。图为公路，所以最高时速为70公里/每小时。', 'https://images.juheapi.com/jztk/c1c2subject1/1105.jpg'),
('1106', '交通标志和交通标线不属于交通信号。', '2', '正确', '错误', '', '', '《公安部令第123号》第二十五条规定：交通信号包括交通信号灯、交通标志、交通标线和交通警察的指挥。
<br/>题目描述有误，因此本题答案应为错误。', NULL),
('1107', '前方路口这种信号灯亮表示什么意思？', '4', '准许通行', '提醒注意', '路口警示', '禁止通行', '红灯停。', 'https://images.juheapi.com/jztk/c1c2subject1/1107.jpg'),
('1108', '机动车仪表板上（如图所示）亮表示什么？', '2', '前后雾灯开启', '前后位置灯开启', '前照灯开启', '危险报警闪光灯开启', '位置灯就是车辆示宽灯，也就是当你开启双跳灯后，前后左右四个闪的灯 宽灯就是转向信号灯同时闪烁，用于警告作用。', 'https://images.juheapi.com/jztk/c1c2subject1/1108.jpeg'),
('1109', '机动车仪表板上（如图所示）亮表示什么？', '4', '后雾灯打开', '前照灯近光打开', '前照灯远光打开', '前雾灯打开', '前雾灯朝左，后雾灯朝右。', 'https://images.juheapi.com/jztk/c1c2subject1/1109.jpeg'),
('1110', '前方路口这种信号灯亮表示什么意思？', '4', '路口警示', '禁止通行', '提醒注意', '准许通行', '绿灯行。', 'https://images.juheapi.com/jztk/c1c2subject1/1110.jpg'),
('1111', '打开后雾灯开关，（如图所示）亮起。', '2', '正确', '错误', '', '', '图中是前雾灯亮起。
<br/><p><img src=http://tp.mnks.cn/tp_365.jpg>
<br/>前雾灯
<br/><img src=http://tp.mnks.cn/tp_366.jpg>
<br/>后雾灯</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1111.jpeg'),
('1112', '车辆发生爆胎后，驾驶人在尚未控制住车速前，不要冒险使用行车制动器停车，以避免车辆横甩发生更大的险情。', '1', '正确', '错误', '', '', '爆胎后，驾驶人在尚未控制住车速的时候，是不能急踩刹车的，此举极易导致翻车，甚至与后面来车追尾。正确的做法应该是紧握方向盘，控制方向，极力保持直线行驶，利用发动机制动，减档或抢档减速度，轻踏制动踏板缓慢减速，平稳靠边停车。', NULL),
('1113', '夜间驾驶机动车通过人行横道时需要交替使用远近光灯。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第五十九条：机动车在夜间通过急弯、坡路、拱桥、人行横道或者没有交通信号灯控制的路口时，应当交替使用远近光灯示意。
<br/>题目描述正确，因此本题答案应为正确。', NULL),
('1114', '打开前雾灯开关，（如图所示）亮起。', '2', '正确', '错误', '', '', '图中是后雾灯亮起。
<br/><p><img src=http://tp.mnks.cn/tp_365.jpg>
<br/>前雾灯
<br/><img src=http://tp.mnks.cn/tp_366.jpg>
<br/>后雾灯</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1114.jpeg'),
('1115', '机动车仪表板上（如图所示）这个符号表示什么？', '1', '行李舱开启', '一侧车门开启', '发动机舱开启', '燃油箱盖开启', '后边为行李舱，前边为发动机舱。', 'https://images.juheapi.com/jztk/c1c2subject1/1115.jpeg'),
('1116', '驾驶机动车在道路上向右变更车道可以不使用转向灯。', '2', '正确', '错误', '', '', '只要是变更车道，就要使用相应的转向灯。
<br/>《中华人民共和国道路交通安全法实施条例》第五十七条 机动车应当按照下列规定使用转向灯： 
<br/>（一）向左转弯、向左变更车道、准备超车、驶离停车地点或者掉头时，应当提前开启左转向灯。 
<br/><b>（二）向右转弯、向右变更车道、超车完毕驶回原车道、靠路边停车时，应当提前开启右转向灯。</b>
<br/>无论是向左变道还是向右变道，都应该打开转向灯。题目描述有误，因此本题答案应为错误。', NULL),
('1117', '机动车发生故障时，（如图所示）闪烁。', '2', '正确', '错误', '', '', '图片中是危险报警闪光灯。当机动车发生故障时，该灯并不会闪烁。只有人为开启时，该该灯才会闪烁。题目描述有误，因此本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/1117.jpeg'),
('1118', '在这种急弯道路上行车应交替使用远近光灯。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第五十九条：机动车在夜间通过急弯、坡路、拱桥、人行横道或者没有交通信号灯控制的路口时，应当交替使用远近光灯示意。
<br/>题目描述正确，因此本题答案应为正确。', 'https://images.juheapi.com/jztk/c1c2subject1/1118.jpg'),
('1119', '在这条城市道路上行驶的最高速度不能超过多少？', '3', '30公里/小时', '40公里/小时', '50公里/小时', '70公里/小时', '《中华人民共和国道路交通安全法实施条例》第四十五条：在没有限速标志、标线的道路上，机动车不得超过下列最高行驶速度：
<br/>(一)没有道路中心线的道路，城市道路为每小时30公里，公路为每小时40公里；
<br/><b>(二)同方向只有1条机动车道的道路，城市道路为每小时50公里，公路为每小时70公里。</b>
<br/>图中道路，是同方向有1条车道的城市道路，所以最高速度为50公里/小时，本题答案应为C。', 'https://images.juheapi.com/jztk/c1c2subject1/1119.jpg'),
('1120', '机动车仪表板上（如图所示）亮时，防抱死制动系统处于打开状态。', '2', '正确', '错误', '', '', '此标志为防抱死制动系统出现故障，应该停车进行全面检查。', 'https://images.juheapi.com/jztk/c1c2subject1/1120.jpeg')
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('1121', '小型客车行驶在平坦的高速公路上，突然有颠簸感觉时，应迅速降低车速，防止爆胎。', '1', '正确', '错误', '', '', '如果突然有颠簸的感觉，应该是压到了不小的障碍物。这时候为了确保轮胎不爆胎，一定要迅速减速，然后开到安全的路边检查。
<br/>
<br/>【拓展延伸】
<br/>迅速降低车速≠紧急制动。爆胎后虽然严禁紧急制动，但题目所说的是突然有颠簸感觉时，要采取迅速降低车速来避免爆胎，而迅速降低车速可以采用收油减挡等方式，并非紧急制动。注意审题。', NULL),
('1122', '机动车仪表板上（如图所示）亮表示什么？', '1', '防抱死制动系统故障', '驻车制动器处于解除状态', '行车制动系统故障', '安全气囊处于故障状态', 'ABS就是防抱死制动系统', 'https://images.juheapi.com/jztk/c1c2subject1/1122.jpeg'),
('1123', '机动车在环形路口内行驶，遇有其他车辆强行驶入时，只要有优先权就可以不避让', '2', '正确', '错误', '', '', '当然错拉，有优先权就了不起呀?有优先权也要考虑到安全啊，不然容易发生两车相撞。', NULL),
('1124', '交通信号包括交通信号灯、交通标志、交通标线和交通警察的指挥。', '1', '正确', '错误', '', '', '全国统一的交通信号分为：交通信号灯、交通标志、交通标线和交通警察的指挥。', NULL),
('1125', '在路口遇到这种情形时怎样做？', '2', '停在网状线区域内等待', '停在路口以外等待', '跟随前车通过路口', '停在路口内等待', '《道路交通安全法实施条例》第五十三条：机动车在遇有前方机动车停车排队等候或者缓慢行驶时，应当依次排队，不得从前方车辆两侧穿插或者超越行驶，<b>不得在人行横道、网状线区域内停车等候。</b>
<br/>根据规定，题目中情形为了不加重拥堵，机动车应该停在路口以外等待。B项符合要求，因此本题答案为B。', 'https://images.juheapi.com/jztk/c1c2subject1/1125.jpg'),
('1126', '行至这种情况的铁路道口要停车观察。', '1', '正确', '错误', '', '', '在无人看守的铁道路口，要停车观察，确定安全后，才可以通过！', 'https://images.juheapi.com/jztk/c1c2subject1/1126.jpg'),
('1127', '驾驶机动车上坡时,在将要到达坡道顶端时要加速并鸣喇叭。', '2', '正确', '错误', '', '', '肯定是错的，鸣喇叭对，但是加速是错误的。', NULL),
('1128', '行车中当车辆突然爆胎时，驾驶人切忌慌乱中急踏制动踏板，尽量采用“抢挡”的方法，利用发动机制动使车辆减速。', '1', '正确', '错误', '', '', '车胎爆胎时紧急制动极易导致车辆侧翻。应该利用抢档的方式，用发动机制动减速停车。', NULL),
('1129', '机动车仪表板上（如图所示）亮，提示左侧车门未关闭。', '2', '正确', '错误', '', '', '从图而知，图标中右侧车门显示开启状态，因此该标志是提示右侧车门未关闭，并非提示左侧车门未关闭。题目描述错误，因此本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/1129.jpeg'),
('1130', '在这个弯道上行驶时的最高速度不能超过多少？', '2', '40公里/小时', '30公里/小时', '50公里/小时', '70公里/小时', '机动车行驶中遇有下列情形之一的，<b>最高行驶速度不得超过每小时30公里，</b>其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 <br/>（一）进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；　　 <br/>（二）<b>掉头、转弯、下陡坡时；</b>　　 <br/>（三）遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时；　　 <br/>（四）在冰雪、泥泞的道路上行驶时；', 'https://images.juheapi.com/jztk/c1c2subject1/1130.jpg'),
('1131', '车辆前轮胎爆裂，危险较大，方向会立刻向爆胎车轮一侧跑偏，直接影响驾驶人对转向盘的控制。', '1', '正确', '错误', '', '', '爆胎后，车辆整体平衡会受到影响，会向爆胎的一边跑偏，直接影响到驾驶人对转向盘的控制。', NULL),
('1132', '这个地面标记的含义是预告前方设有交叉路口。', '2', '正确', '错误', '', '', '指示标线，人行横道预警棱形图标。', 'https://images.juheapi.com/jztk/c1c2subject1/1132.jpg'),
('1133', '驾驶机动车遇雾、雨、雪等能见度在50米以内时，最高速度不能超过多少？', '4', '70公里/小时', '50公里/小时', '40公里/小时', '30公里/小时', '机动车行驶中遇有下列情形之一的，最高行驶速度不得超过每小时30公里，其中拖拉机、电瓶车、轮式专用机械车不得超过每小时15公里：　　 
<br/>（一）进出非机动车道，通过铁路道口、急弯路、窄路、窄桥时；　　 
<br/>（二）掉头、转弯、下陡坡时；　　 
<br/>（三）<b>遇雾、雨、雪、沙尘、冰雹，能见度在50米以内时</b>；
<br/>（四）在冰雪、泥泞的道路上行驶时；', NULL),
('1134', '在同向4车道高速公路上行车，车速高于每小时110公里的车辆应在哪条车道上行驶？', '1', '最左侧', '第二条', '最右侧', '第三条', '交通安全法实施条例第七十八条规定了同向两车道、三车道的限速规范：二车道左侧车道最低限速100，三车道左到右依次110、90、60。 <b>同向四车道记着培训老师讲的：左到右最低限速依次110、90、90、60。</b>因此本题选A。', NULL),
('1135', '按下这个开关，后风窗玻璃除霜器开始工作。', '2', '正确', '错误', '', '', '这题表述的意思是：当前按下的这个图标即亮灯的这个表示的是前窗玻璃除霜器开始工作。<br/>核心的意思是这两个图标，一个表示前窗玻璃除霜器，一个表示后窗玻璃除霜器。<br/>带扇形的那个是前窗标识，下面那个长方形的是后窗标识。', 'https://images.juheapi.com/jztk/c1c2subject1/1135.jpg'),
('1136', '驾驶机动车遇到漫水桥时要察明水情确认安全后再低速通过。', '1', '正确', '错误', '', '', '《道路交通安全法实施条例》第六十四条：机动车行经漫水路或者漫水桥时，应当停车察明水情，确认安全后，低速通过。', NULL),
('1137', '在大雨天行车，为避免发生“水滑”而造成危险，要控制速度行驶。', '1', '正确', '错误', '', '', '雨天路面积水，摩擦变小轮胎很容易打滑。安全起见，雨天要减速行驶。', NULL),
('1138', '这是什么操纵装置？', '4', '节气门操纵杆', '变速器操纵杆', '离合器操纵杆', '驻车制动器操纵杆', '驻车制动器操纵杆俗称手刹，能使汽车本体固定在地面或某平面上而不出现相对移动的总成的操纵装置。', 'https://images.juheapi.com/jztk/c1c2subject1/1138.jpg'),
('1139', '驾驶机动车遇到前方车辆停车排队等候或缓慢行驶时怎么办？', '3', '可借道超车', '占用对面车道', '依次行驶', '穿插等候的车辆', '《道路交通安全法》第四十五条：<br/>机动车遇有前方车辆停车排队等候或者缓慢行驶时，不得借道超车或者占用对面车道，不得穿插等候的车辆。', NULL),
('1140', '驾驶机动车在没有中心线的道路上遇相对方向来车时怎样行驶？', '3', '紧靠路边行驶', '靠路中心行驶', '减速靠右行驶', '借非机动车道行驶', '《道路交通安全法实施条例》第四十八条： 在没有中心隔离设施或者没有中心线的道路上，减速靠右行驶，并与其他车辆、行人保持必要的安全距离。', NULL),
('1141', '车辆因故障必须在高速公路停车时，应在车后方多少米以外设置故障警告标志？', '2', '25', '150', '100', '50', '<b>车辆因故障必须在高速公路停车时，应在车后方（150米）处设置故障警告标志，夜间还需开启示廓灯和后位灯。</b>', NULL),
('1142', '同车道行驶的车辆前方遇到下列哪种车辆不得超车？', '3', '大型客货车', '出租汽车', '执行任务的救护车', '公共汽车', '亲，人命关天，您就别超了。', NULL),
('1143', '如图所示，在高速公路同方向三条机动车道最左侧车道行驶，应保持什么车速？', '1', '110 公里/小时～120公里/小时', '100 公里/小时～120公里/小时', '90 公里/小时～110公里/小时', '60 公里/小时～120公里 /小时', '《中华人民共和国道路交通安全法实施条例》第七十八条：同方向有2条车道的，左侧车道的最低车速为每小时100公里；同方向有3条以上车道的，最左侧车道的最低车速为每小时110公里，中间车道的最低车速为每小时90公里。道路限速标志标明的车速与上述车道行驶车速的规定不一致的，技照道路限速标志标明的车速行驶。', 'https://images.juheapi.com/jztk/c1c2subject1/1143.jpg'),
('1144', '车辆通过铁道路口时，应用低速挡安全通过，中途不得换挡，以避免发动机熄火。', '1', '正确', '错误', '', '', '通过铁路道口，安全第一。换挡容易熄火，中途换挡如果发生熄火，很容易产生危险。', NULL),
('1145', '下长坡连续使用行车制动会导致什么？', '4', '会缩短发动机寿命', '增加驾驶人的劳动强度', '容易造成车辆倾翻', '会使制动器温度升高而使制动效果急剧下降', '持续用刹车，会造成刹车片发热，从而制动力减小，严重的会丧失制动能力，所以长下坡要用低挡，用发动机制动。', NULL),
('1146', '行人参与道路交通的主要特点是什么？', '3', '行动迟缓', '喜欢聚集、围观', '行走随意性大，方向多变', '以上都是', '不同的人行动速度不同，因此A不准确。而B中并不是行人参与交通的特点。行人由于主观能动性强，想法更改自由随意，并不十分受信号灯约束，因此C才是行人参与交通的主要特点。', NULL),
('1147', '超车时应从前车的左侧超越，是因为左侧超车便于观察，有利于安全。', '1', '正确', '错误', '', '', '驾驶人的座位在左侧，所以不管是对于超车的驾驶人还是被超车的驾驶人而言都比右侧利于观察。也更加有利于安全。', NULL),
('1148', '这属于哪一种标志？', '1', '警告标志', '指路标志', '指示标志', '禁令标志', '交叉路口：用以警告车辆驾驶人谨慎慢行，注意横向来车。设在平面交叉路口驶入路段的适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/1148.jpg'),
('1149', '这个标志的含义是警告前方出现向左的急转弯路。', '1', '正确', '错误', '', '', '向左急弯路：用以警告车辆驾驶人减速慢行。', 'https://images.juheapi.com/jztk/c1c2subject1/1149.jpg'),
('1150', '机动车驾驶证遗失、损毁无法辨认时，机动车驾驶人应当向机动车驾驶证核发地车辆管理所申请补发。', '1', '正确', '错误', '', '', '具有下列情形之一的，机动车驾驶人应当在三十日内到机动车驾驶证核发地车辆管理所申请换证：<br/>(一)在车辆管理所管辖区域内，机动车驾驶证记载的机动车驾驶人信息发生变化的;<br/>(二)<b>机动车驾驶证损毁无法辨认的。</b><br/>根据123号令第五十四条:<b>机动车驾驶证遗失的，机动车驾驶人应当向机动车驾驶证核发地车辆管理所申请补发。</b>', NULL),
('1151', '这个导向箭头是何含义？', '1', '提示前方有左弯或需向左合流', '提示前方有右弯或需向右合流', '提示前方右侧有障碍需向左合流', '提示前方有左弯或或许向左绕行', '导向箭头：提示前方道路有左弯或需向左合流。', 'https://images.juheapi.com/jztk/c1c2subject1/1151.jpg'),
('1152', '科目三道路驾驶技能和安全文明驾驶常识考试满分分别为100分，成绩分别达到80和90分的为合格。', '2', '正确', '错误', '', '', '各科目考试的合格标准为： （一）科目一考试满分为100分，成绩达到90分的为合格；<b>（二）科目三道路驾驶技能和安全文明驾驶常识考试满分分别为100分，成绩分别达到90分的为合格。</b>', NULL),
('1153', '驾驶机动车遇到这种信号灯不断闪烁时怎样行驶？', '3', '尽快加速通过', '靠边停车等待', '注意观望安全通过', '紧急制动', '路口黄灯持续闪烁，警示驾驶人要注意瞭望，确认安全通过。', 'https://images.juheapi.com/jztk/c1c2subject1/1153.jpg'),
('1154', '这属于哪一种标志？', '3', '警告标志', '禁令标志', '指示标志', '指路标志', '指示标志是交通标志中主要标志的一种，，用以指示车辆和行人按规定方向、地点行驶。 指示标志的颜色为蓝底、白图案；形状分为圆形、长方形和正方形。', 'https://images.juheapi.com/jztk/c1c2subject1/1154.jpg'),
('1155', '机动车仪表板上（如图所示）亮，提示行李舱开启。', '2', '正确', '错误', '', '', '后边为行李舱，前边为发动机舱。当机动车仪表板上该符号亮起，表示发动机舱开启。', 'https://images.juheapi.com/jztk/c1c2subject1/1155.jpeg'),
('1156', '这个标志的含义是指示此处设有室内停车场。', '1', '正确', '错误', '', '', '你看那个P字上边还有个遮挡，说明是室内的，如果没有上边那个遮挡就是露天停车场。', 'https://images.juheapi.com/jztk/c1c2subject1/1156.jpg'),
('1157', '驾驶机动车跨越双实线行驶属于什么行为？', '2', '违章行为', '违法行为', '过失行为', '违规行为', '《道路交通安全法》规定双实线是不能跨越的，违反道路交通安全法，就是违法行为。', NULL),
('1158', '这属于哪一种标志？', '1', '旅游区标志', '作业区标志', '告示标志', '高速公路标志', '旅游区方向：设在通往旅游区各连接道路的交叉口处。', 'https://images.juheapi.com/jztk/c1c2subject1/1158.jpg'),
('1159', '这个标志是何含义？', '3', '提醒车辆驾驶人前方道路沿水库、湖泊、河流', '提醒车辆驾驶人前方有向上的陡坡路段', '提醒车辆驾驶人前方有向下的陡坡路段', '提醒车辆驾驶人前方有两个及以上的连续上坡路段', '下陡坡：用以提醒车辆驾驶人小心驾驶。', 'https://images.juheapi.com/jztk/c1c2subject1/1159.jpg'),
('1160', '这个标志的含义是警告前方道路有障碍物，车辆减速绕行。', '2', '正确', '错误', '', '', '这个警告标志是向右急转弯。', 'https://images.juheapi.com/jztk/c1c2subject1/1160.jpg'),
('1161', '这个标志的含义是警告前方道路易滑，注意慢行。', '2', '正确', '错误', '', '', '<p><img src=http://tp.mnks.cn/tp_125.jpg>
<br/>反向弯路
<br/><img src=http://tp.mnks.cn/tp_142.jpg>
<br/>易滑路段</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1161.jpg'),
('1162', '机动车登记证书、号牌、行驶证灭失、丢失或者损毁的，机动车所有人应当向居住地车辆管理所申请补领、换领。', '2', '正确', '错误', '', '', '根据《机动车登记规定》第四十四条的规定：机动车号牌、行驶证灭失、丢失或者损毁的，机动车所有人应当向<b>登记地车</b>辆管理所申请补领、换领。申请时，机动车所有人应当填写申请表并提交身份证明。
<br/>本题题干说的是“居住地车辆管理所”，是不正确的，本题答案应为错误。', NULL),
('1163', '这是什么交通标志？', '3', '易滑路段', '急转弯路', '反向弯路', '连续弯路', '反向弯路：用以警告车辆驾驶人减速慢行。设置位置为两反向圆曲线起点的外面，但不应进入相邻的圆曲线内。', 'https://images.juheapi.com/jztk/c1c2subject1/1163.jpg'),
('1164', '这个标志的含义是提醒前方道路变为不分离双向行驶路段。', '1', '正确', '错误', '', '', '警告标志注意双向交通。用以提醒车辆驾驶人注意会车。设在由双向分离行驶，因某种原因出现临时性或永久性的不分离双向行驶的路段，或由单向行驶进人双向行驶的路段以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/1164.jpg'),
('1165', '这种标志的作用是警告车辆驾驶人前方有危险，谨慎通行。', '1', '正确', '错误', '', '', '黄色标志都是表示警告，第一张图警告前方T字路口，第二张图片表示急转弯，第三张图片表示前方道路变窄，要小心驾驶。', 'https://images.juheapi.com/jztk/c1c2subject1/1165.jpg'),
('1166', '这个标志的含义是警告前方有两个相邻的反向转弯道路。', '2', '正确', '错误', '', '', '<p><img src=http://tp.mnks.cn/tp_125.jpg>
<br/>反向弯路
<br/><img src=http://tp.mnks.cn/tp_126.jpg>
<br/>连续弯路</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1166.jpg'),
('1167', '这个标志的含义是前方即将行驶至Y型交叉路口？', '2', '正确', '错误', '', '', '交叉路口：用以警告车辆驾驶人谨慎慢行，注意横向来车。设在平面交叉路口驶入路段的适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/1167.jpg'),
('1168', '这是什么交通标志？', '3', '两侧变窄', '右侧变窄', '左侧变窄', '桥面变窄', '左侧变窄：用以警告车辆驾驶人注意前方车行道或路面狭窄情况，遇有来车应予减速避让。设在双车道路面宽度缩减为6 m以下的路段起点前方。', 'https://images.juheapi.com/jztk/c1c2subject1/1168.jpg'),
('1169', '这个标志是何含义？', '2', '提醒车辆驾驶人前方道路沿水库、湖泊、河流', '提醒车辆驾驶人前方有向上的陡坡路段', '.提醒车辆驾驶人前方有两个及以上的连续上坡路段', '提醒车辆驾驶人前方有向下的陡坡路段', '上陡坡：用以提醒车辆驾驶人小心驾驶。', 'https://images.juheapi.com/jztk/c1c2subject1/1169.jpg'),
('1170', '这个标志的含义是提醒前方桥面宽度变窄。', '2', '正确', '错误', '', '', '此为<b>两侧变窄标志</b>。常设在两侧变窄道路，提示司机看到此标志时应请提前减速，前方道路即将变窄，车辆密集度增加，行使空间降低，易发生车祸，所以请一定要提前减速。题目描述错误，因此本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/1170.jpg'),
('1171', '这是什么交通标志？', '4', '易滑路段', '急转弯路', '反向弯路', '连续弯路', '连续弯路：用以警告车辆驾驶人减速慢行。设置位置为连续弯路起点的外面，当连续弯路总长度大于500m时，应重复设置。', 'https://images.juheapi.com/jztk/c1c2subject1/1171.jpg'),
('1172', '在驾驶技能准考证明的有效期内，科目二和科目三道路驾驶技能考试预约次数不得超过多少次？', '3', '3次', '4次', '5次', '6次', '在驾驶技能准考证明有效期内，科目二和科目三道路驾驶技能考试预约考试的次数不得超过五次。第五次预约考试仍不合格的，已考试合格的其他科目成绩作废。', NULL),
('1173', '机动车发生正面碰撞时，安全气囊加上安全带的双重保护才能充分发挥作用。', '1', '正确', '错误', '', '', '研究表明，假设气囊加安全带是100%安全的话，安全带的作用是70%，气囊的作用是30%。', NULL),
('1174', '这是什么交通标志？', '1', '两侧变窄', '右侧变窄', '左侧变窄', '桥面变窄', '两侧变窄：用以警告车辆驾驶人注意前方车行道或路面狭窄情况，遇有来车应予减速避让。设在双车道路面宽度缩减为6 m以下的路段起点前方。', 'https://images.juheapi.com/jztk/c1c2subject1/1174.jpg'),
('1175', '驾驶机动车在人行横道上临时停车属于违法行为。', '1', '正确', '错误', '', '', '《道路交通安全法》规定人行横道上不允许停车。违反安全法就是违法行为。', NULL),
('1176', '科目三考试分为道路驾驶技能考试和安全文明驾驶常识考试两部分。', '1', '正确', '错误', '', '', '机动车驾驶人考试内容分为道路交通安全法律、法规和相关知识考试科目（以下简称“科目一”）、场地驾驶技能考试科目（以下简称“科目二”）、<b>道路驾驶技能和安全文明驾驶常识考试科目（以下简称“科目三”）。</b>', NULL),
('1177', '这个标志的作用是用以警告车辆驾驶人谨慎慢行，注意横向来车。', '1', '正确', '错误', '', '', '图中是“十字交叉”标志，用以警告车辆驾驶人谨慎慢行，注意横向来车相交，设在视线不良的平面交叉路口驶入路段的适当位置的标志。', 'https://images.juheapi.com/jztk/c1c2subject1/1177.jpg'),
('1178', '这属于哪一种标志？', '2', '警告标志', '禁令标志', '指示标志', '指路标志', '禁令标志是交通标志中主要标志的一种，对车辆加以禁止或限制的标志，如禁止通行、禁止停车、禁止左转弯、禁止鸣喇叭、限制速度、限制重量等。 禁令标志的颜色，除个别标志外，为白底，红圈，红杠，黑图案。图案压杠。', 'https://images.juheapi.com/jztk/c1c2subject1/1178.jpg'),
('1179', '小型汽车科目二考试内容包括倒车入库、坡道定点停车和起步、侧方停车、曲线行驶、直角转弯。', '1', '正确', '错误', '', '', '《公安部令第123号》第二十五条:科目二考试内容包括小型汽车、小型自动挡汽车、残疾人专用小型自动挡载客汽车和低速载货汽车考试倒车入库、坡道定点停车和起步、侧方停车、曲线行驶、直角转弯。省级公安机关交通管理部门可以根据实际增加考试内容。', NULL),
('1180', '驾驶技能准考证明的有效期是多久？', '3', '1年', '2年', '3年', '4年', '驾驶技能准考证明的有效期为三年，申请人应当在有效期内完成科目二和科目三考试。未在有效期内完成考试的，已考试合格的科目成绩作废。', NULL),
('1181', '这个标志是何含义？', '4', '禁止左转', '此路不通', '禁止通行', '超高绕行', '4M高度，因为超过所以只能绕行。', 'https://images.juheapi.com/jztk/c1c2subject1/1181.jpg'),
('1182', '这个标志的含义是提醒前方两侧行车道或路面变窄。', '2', '正确', '错误', '', '', '<p><img src=http://tp.mnks.cn/tp_130.jpg>
<br/>两侧变窄
<br/><img src=http://tp.mnks.cn/tp_133.jpg>
<br/>窄桥</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1182.jpg'),
('1183', '申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的（被撤销的），申请人在多长时间内不得再次申领机动车驾驶证。', '4', '6个月', '1年', '2年', '3年', '申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的，公安机关交通管理部门收缴机动车驾驶证，撤销机动车驾驶许可；申请人在三年内不得再次申领机动车驾驶证。', NULL),
('1184', '机动车购买后尚未注册登记，需要临时上道路行驶的，可以凭什么临时上道路行驶？', '2', '合法来源凭证', '临时行驶车号牌', '借用的机动车号牌', '法人单位证明', '《道路交通安全法》第八条：国家对机动车实行登记制度。机动车经公安机关交通管理部门登记后，方可上道路行驶。尚未登记的机动车，需要临时上道路行驶的，应当取得临时通行牌证。', NULL),
('1185', '正在执行社区戒毒、强制隔离戒毒、社区康复措施，车辆管理所将注销其驾驶证。', '1', '正确', '错误', '', '', '机动车驾驶人具有下列情形之一的，车辆管理所应当注销其机动车驾驶证：<br/>（一）死亡的；<br/>（二）提出注销申请的；<br/>（三）丧失民事行为能力，监护人提出注销申请的；<br/>（四）身体条件不适合驾驶机动车的；<br/>（五）有器质性心脏病、癫痫病、美尼尔氏症、眩晕症、癔病、震颤麻痹、精神病、痴呆以及影响肢体活动的神经系统疾病等妨碍安全驾驶疾病的；<br/>（六）<b>被查获有吸食、注射毒品后驾驶机动车行为，正在执行社区戒毒、强制隔离戒毒、社区康复措施，或者长期服用依赖性精神药品成瘾尚未戒除的。</b>', NULL),
('1186', '这个标志的含义是提醒前方左侧行车道或路面变窄。', '1', '正确', '错误', '', '', '左侧变窄：用以警告车辆驾驶人注意前方车行道或路面狭窄情况，遇有来车应予减速避让。设在双车道路面宽度缩减为6 m以下的路段起点前方。', 'https://images.juheapi.com/jztk/c1c2subject1/1186.jpg'),
('1187', '这个标志是何含义？', '4', '提醒车辆驾驶人前方有两个及以上的连续上坡路段', '提醒车辆驾驶人前方有向上的陡坡路段', '提醒车辆驾驶人前方有向下的陡坡路段', '提醒车辆驾驶人前方有两个及以上的连续下坡路段', '连续下坡：用以提醒车辆驾驶人小心驾驶。当连续下坡总长大于3 km后，应重复设置。', 'https://images.juheapi.com/jztk/c1c2subject1/1187.jpg'),
('1188', '这个标志的含义是提醒车辆驾驶人前方是无人看守铁路道口。', '2', '正确', '错误', '', '', '有人看守铁路道口：用以警告车辆驾驶人注意慢行或及时停车。设在车辆驾驶人不易发现的道口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/1188.jpg'),
('1189', '夜间通过没有路灯或路灯照明不良时，应将近光灯转换为远光灯，但同向行驶的后车不得使用远光灯。', '1', '正确', '错误', '', '', '通过没有路灯或路灯照明不良的路段（非路口）时可以开启远光灯，但是前方有车或行人时，为了不影响他人视线，应关闭远光，改用近光。', NULL),
('1190', '这个标志的含义是告示前方是拥堵路段，注意减速慢行。', '2', '正确', '错误', '', '', '图中是事故多发地段标志。用以告示前方道路为事故易发路段，谨慎驾驶。设在交通事故易发路段以前适当位置。题目描述错误，本题答案为错。', 'https://images.juheapi.com/jztk/c1c2subject1/1190.jpg'),
('1191', '这个标志的含义是提醒车辆驾驶人前方是傍山险路路段。', '2', '正确', '错误', '', '', '<p><img src=http://tp.mnks.cn/tp_143.jpg>
<br/>注意傍山险路
<br/><img src=http://tp.mnks.cn/tp_140.jpg>
<br/>注意落石</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1191.jpg'),
('1192', '这个标志的含义是提醒前方右侧行车道或路面变窄。', '1', '正确', '错误', '', '', '右侧变窄：用以警告车辆驾驶人注意前方车行道或路面狭窄情况，遇有来车应予减速避让。设在双车道路面宽度缩减为6 m以下的路段起点前方。', 'https://images.juheapi.com/jztk/c1c2subject1/1192.jpg'),
('1193', '申请人在考试过程中有贿赂、舞弊行为的，取消考试资格，已经通过考试的其他科目成绩无效。', '1', '正确', '错误', '', '', '申请人在考试过程中有贿赂、舞弊行为的，取消考试资格，已经通过考试的其他科目成绩无效；申请人在一年内不得再次申领机动车驾驶证。', NULL),
('1194', '这个标志的含义是提醒车辆驾驶人前方是非机动车道。', '2', '正确', '错误', '', '', '<p><img src=http://tp.mnks.cn/tp_232.jpg>
<br/>非机动车道</p><p><img src=http://tp.mnks.cn/tp_159.jpg>
<br/>注意非机动车</p>
<br/>图中标志是注意非机动车，并非提醒前方是非机动车车道。题目描述有误，因此本题答案应为错误。', 'https://images.juheapi.com/jztk/c1c2subject1/1194.jpg'),
('1195', '申请人因故不能按照预约时间参加考试的，应当提前一日申请取消预约，对申请人未按照预约考试时间参加考试的，判定该次考试不合格。', '1', '正确', '错误', '', '', '申请人因故不能按照预约时间参加考试的，应当提前一日申请取消预约。对申请人未按照预约考试时间参加考试的，判定该次考试不合格。', NULL),
('1196', '机动车登记证书、号牌、行驶证灭失、丢失或者损毁的，机动车所有人应当向哪个部门申请补领、换领。', '3', '住地交警支队车辆管理所', '驾驶证核发地车辆管理所', '登记地车辆管理所', '当地公安局', '根据《机动车登记规定》第四十四条的规定：机动车号牌、行驶证灭失、丢失或者损毁的，机动车所有人应当向登记地车辆管理所申请补领、换领。申请时，机动车所有人应当填写申请表并提交身份证明。', NULL),
('1197', '这个标志的含义是提醒车辆驾驶人前方是无人看守铁路道口。', '1', '正确', '错误', '', '', '无人看守铁路道口：用以警告车辆驾驶人注意慢行或及时停车。设在无人看守铁路道口以前适当位置。', 'https://images.juheapi.com/jztk/c1c2subject1/1197.jpg'),
('1198', '这个标志的含义是告示前方道路施工，车辆左右绕行。', '2', '正确', '错误', '', '', '<b>图中是 [左右绕行] 标志。</b>用以告示前方道路有障碍物，车辆应按标志指示减速慢行。设在道路障碍物前适当位置。并非道路施工，题目描述有误，因此本题答案为错。
<br/><p><img src=http://tp.mnks.cn/tp_163.jpg>
<br/>左右绕行标志</p><p><img src=http://tp.mnks.cn/tp_167.jpg>
<br/>前方施工标志</p>', 'https://images.juheapi.com/jztk/c1c2subject1/1198.jpg'),
('1199', '这是什么交通标志？', '2', '两侧变窄', '右侧变窄', '左侧变窄', '桥面变窄', '右侧变窄：用以警告车辆驾驶人注意前方车行道或路面狭窄情况，遇有来车应予减速避让。设在双车道路面宽度缩减为6 m以下的路段起点前方。', 'https://images.juheapi.com/jztk/c1c2subject1/1199.jpg'),
('1200', '打开位置灯开关，（如图所示）亮起。', '1', '正确', '错误', '', '', '该指示灯是用来显示车辆示宽灯（也叫示廓灯、位置灯）的工作状态，平时为熄灭状态，当示宽灯打开时，该指示灯随即点亮。当示宽灯关闭或者关闭示宽灯打开大灯时，该指示灯自动熄灭。', 'https://images.juheapi.com/jztk/c1c2subject1/1200.jpg')
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
  answer = VALUES(answer),
  item1 = VALUES(item1),
  item2 = VALUES(item2),
  item3 = VALUES(item3),
  item4 = VALUES(item4),
  explains = VALUES(explains),
  image_url = VALUES(image_url);


INSERT INTO jztk_question (question_id, question_text, answer, item1, item2, item3, item4, explains, image_url) VALUES
('1201', '机动车仪表板上（如图所示）亮表示什么？', '3', '侧面出风', '空气外循环', '迎面出风', '空气内循环', '直吹人脸表示迎面出风，垂直向下表示吹地板。', 'https://images.juheapi.com/jztk/c1c2subject1/1201.jpeg'),
('1202', '驾驶的车辆正在被其他车辆超越时，若此时后方有跟随行驶的车辆，应怎样做？', '2', '继续加速行驶', '稍向右侧行驶，保证横向安全距离', '靠道路中心行驶', '加速向右侧让路', '稍向右侧减速慢行，和前车、超车的车辆保持一定的安全距离。', NULL),
('1203', '机动车仪表板上（如图所示）这个符号表示什么？', '4', '雪地起步模式', '空气循环', '空调制冷', '冷风暖气风扇', '看它长的多像风扇。', 'https://images.juheapi.com/jztk/c1c2subject1/1203.jpeg'),
('1204', '驾驶机动车应当随身携带哪种证件？', '3', '职业资格证', '身份证', '驾驶证', '工作证', '《道路交通安全法》第十九条：驾驶人应当按照驾驶证载明的准驾车型驾驶机动车；驾驶机动车时，应当随身携带机动车驾驶证。', NULL),
('1205', '发动机起动后仪表板上（如图所示）亮表示什么？', '4', '燃油泵出现异常或者故障', '发动机点火系统出现故障', '发动机供油系统出现异常', '油箱内燃油已到最低液面', '这个是汽油不足了，多像加油站加油的那个机器，记住机油和汽油是不一样的。', 'https://images.juheapi.com/jztk/c1c2subject1/1205.jpeg'),
('1206', '机动车仪表板上（如图所示）亮时提醒发动机需要加注机油。', '2', '正确', '错误', '', '', '图示灯亮了是提醒发动机温度过高，不是需要加注机油。', 'https://images.juheapi.com/jztk/c1c2subject1/1206.jpeg'),
('1207', '这是什么操纵装置？', '1', '刮水器开关', '前照灯开关', '转向灯开关', '除雾器开关', '左手边转向灯开关，右手边刮水器开关。', 'https://images.juheapi.com/jztk/c1c2subject1/1207.jpg'),
('1208', '在实习期内驾驶机动车的，应当在车身后部粘贴或者悬挂哪种标志？', '3', '注意避让标志', '注意新手标志', '统一式样的实习标志', '注意车距标志', '《公安部令第123号》第六十四条规定：在实习期内驾驶机动车的，应当在车身后部粘贴或者悬挂<b>统一式样的实习标志</b>。', NULL),
('1209', '将转向灯开关向下拉，右转向灯亮。', '2', '正确', '错误', '', '', '向上提：右转向灯亮，（顺时针方向，向右打方向盘的方向） 
<br/>向下拉：左转向灯亮，（逆时针方向，向左打方向盘的方向）', 'https://images.juheapi.com/jztk/c1c2subject1/1209.jpg'),
('1210', '以欺骗、贿赂等不正当手段取得驾驶证被依法撤销驾驶许可的，多长时间不得重新申请驾驶许可？', '1', '3年内', '终身', '1年内', '5年内', '吊二撤三醉五逃终身。
<br/>根据公安部令第123号规定：申请人在考试过程中有贿赂、舞弊行为的，取消考试资格，已经通过考试的其他科目成绩无效；申请人在一年内不得再次申领机动车驾驶证。
<br/><b>申请人以欺骗、贿赂等不正当手段取得机动车驾驶证的，公安机关交通管理部门收缴机动车驾驶证，撤销机动车驾驶许可；申请人在三年内不得再次申领机动车驾驶证。</b>', NULL),
('1211', '准驾车型为小型汽车的，可以驾驶下列哪种车辆？', '1', '低速载货汽车', '中型客车', '三轮摩托车', '轮式自行机械', '小型汽车（C1）准驾车型：小型、微型载客汽车以及轻型、微型载货汽车；轻型、微型专项作业车，小型、微型自动挡载客汽车以及轻型、微型自动挡载货汽车，低速载货汽车，三轮汽车。', NULL),
('1212', '驾驶机动车上路前应当检查车辆安全技术性能。', '1', '正确', '错误', '', '', '《道路交通安全法》第二十一条规定：驾驶人驾驶机动车上道路行驶前，应当对机动车的安全技术性能进行认真检查；不得驾驶安全设施不全或者机件不符合技术标准等具有安全隐患的机动车。', NULL),
('1213', '同车道行驶的车辆前方遇到下列哪种车辆不得超车？', '1', '执行任务的警车', '大型客货车', '出租汽车', '城市公交车', '如果是真的执行任务的警车（此处不好判断），一定要让行。', NULL),
('1214', '雪天行车中，在有车辙的路段应循车辙行驶。', '1', '正确', '错误', '', '', '冰雪覆盖下，司机没法观察到路面情况是否安全。如果有车辙的路段证明有车通行过，说明是可以通行的安全路段，应循车辙行驶。', NULL),
('1215', '在路口遇这种情形要减速让行。', '1', '正确', '错误', '', '', '当驾车在路口遇到图中减速让行标志时，机动车应主动减速让行。
<br/><p><img src=http://tp.mnks.cn/tp_177.jpg>
<br/>减速让行
<br/><img src=http://tp.mnks.cn/tp_176.jpg>
<br/>停车让行
<br/></p>', 'https://images.juheapi.com/jztk/c1c2subject1/1215.jpg'),
('1216', '机动车驾驶证有效期分为6年、10年、20年。', '2', '正确', '错误', '', '', '《中华人民共和国道路交通安全法实施条例》第二十六条明确规定： 机动车驾驶人在机动车驾驶证的6年有效期内，每个记分周期均未达到12分的，换发10年有效期的机动车驾驶证；在机动车驾驶证的10年有效期内，每个记分周期均未达到12分的，换发长期有效的机动车驾驶证。
<br/>有效期为6年，10年，长期。', NULL),
('1217', '机动车仪表板上（如图所示）亮表示什么？', '4', '车前后位置灯亮起', '车前后示宽灯亮起', '左转向指示灯闪烁', '右转向指示灯闪烁', '这个没有问题吧。。。老衲也不知如何解释这个题。', 'https://images.juheapi.com/jztk/c1c2subject1/1217.jpeg'),
('1218', '机动车仪表板上（如图所示）亮表示什么？', '1', '危险报警闪光灯闪烁', '右转向指示灯闪烁', '左转向指示灯闪烁', '车前后位置灯闪烁', '危险报警闪光灯，通常称为“双蹦”（红三角里有个！的标志按扭开关，俗称双闪灯 或双跳灯），是一种提醒其他车辆与行人注意本车发生了特殊情况的信号灯。', 'https://images.juheapi.com/jztk/c1c2subject1/1218.jpeg'),
('1219', '准驾车型为小型汽车的，可以驾驶小型自动挡载客汽车。', '1', '正确', '错误', '', '', '小型汽车（C1）准驾车型：小型、微型载客汽车以及轻型、微型载货汽车；轻型、微型专项作业车，小型、微型自动挡载客汽车以及轻型、微型自动挡载货汽车，低速载货汽车，三轮汽车。', NULL),
('1220', '驾驶机动车违反道路交通安全法律法规发生交通事故属于交通违章行为。', '2', '正确', '错误', '', '', '题干中有明确表述“违反道路交通安全法”，因此属于违法行为，并非违章行为。', NULL),
('1221', '在这种情况下可以加速通过人行横道。', '2', '正确', '错误', '', '', '图中可以看出，人行横道上正在有老人过马路，所以应该是停车等待，等待行人通过后，再驶离人行横道。', 'https://images.juheapi.com/jztk/c1c2subject1/1221.jpg'),
('1222', '驾驶人在驾驶证核发地车辆管理所管辖区以外居住的，可以向居住地车辆管理所申请换证。', '1', '正确', '错误', '', '', '《机动车驾驶证申领和使用规定》第四十九条：机动车驾驶人户籍迁出原车辆管理所管辖区的，应当向迁入地车辆管理所申请换证。机动车驾驶人在核发地车辆管理所管辖区以外居住的，可以向居住地车辆管理所申请换证。', NULL),
('1223', '提拉这个开关控制机动车哪个部位？', '1', '左右转向灯', '倒车灯', '示廓灯', '报警闪光灯', '向上提：右转向灯亮，（顺时针方向，向右打方向盘的方向） 
<br/>向下拉：左转向灯亮，（逆时针方向，向左打方向盘的方向）', 'https://images.juheapi.com/jztk/c1c2subject1/1223.jpg'),
('1224', '驾驶机动车超车时，前方车辆不减速让路，应停止超车并适当减速，与前方车辆保持安全距离。', '1', '', '', '', '', '不具备超车条件时，应该主动放弃超车，并与前车保持安全距离，避免发生碰撞。', NULL),
('1225', '闪光警告信号灯为持续闪烁的黄灯，其作用是提示车辆、行人需要快速通过。', '2', '', '', '', '', '持续闪烁的黄灯是为了警告车辆和行人在此处应该注意观察，确认安全后再通过，而非快速通过。', NULL),
('1226', '如图所示，驾驶机动车遇到这种情况时，A车应当注意避让。', '1', '', '', '', '', '《中华人民共和国道路交通安全法》第五十四条条明确规定：<b>道路养护车辆、工程作业车进行作业时，在不影响过往车辆通行的前提下，其行驶路线和方向不受交通标志、标线限制，过往车辆和人员应当注意避让。</b>', 'https://images.juheapi.com/jztk/c1c2subject1/1226.jpg'),
('1227', '如图所示，驾驶过程中遇到这种情况时，A车可以长鸣喇叭提醒道路养护车辆暂停喷水。', '2', '', '', '', '', '《中华人民共和国道路交通安全法》第五十四条条明确规定：道路养护车辆、工程作业车进行作业时，在不影响过往车辆通行的前提下，其行驶路线和方向不受交通标志、标线限制，过往车辆和人员应当注意避让。不能鸣喇叭让其停止喷水。', 'https://images.juheapi.com/jztk/c1c2subject1/1227.jpg'),
('1228', '驾驶机动车在道路上违反交通安全法规的行为属于违法行为。', '1', '正确', '错误', '', '', '题干中明确表述“违反道路交通安全法规”，违反法律法规即视为违法行为。', NULL),
('1229', '驾驶人连续驾驶4小时以上，停车休息的时间不得少于多少？', '3', '10分钟', '15分钟', '20分钟', '5分钟', '《道路交通安全法实施条例》第六十二条：连续驾驶机动车超过4小时应停车休息，停车休息时间不少于20分钟。', NULL)
ON DUPLICATE KEY UPDATE
  question_text = VALUES(question_text),
